-- Questions batch 7 (250 rows)
INSERT INTO questions (idx, dataset, example_id, prompt_id, source, subject, question_number, prompt, question, choice_a, choice_b, choice_c, choice_d, answer, gold_passage, gold_idx, generated, subtopic)
VALUES
('mbe_665', 'mbe', '665', '453', '1991-Feb', 'CONST. LAW', '114', '', 'Insurance is provided in the state of Shoshone only by private companies. Although the state insurance commissioner inspects insurance companies for solvency, the state does not regulate their rates or policies. An insurance company charges higher rates for burglary insurance to residents of one part of a county in Shoshone than to residents of another section of the same county because of the different crime rates in those areas. Foster is a resident of that county who was charged the higher rate by the insurance company because of the location of her residence. Foster sues the insurance company, alleging that the differential in insurance rates unconstitutionally denies her the equal protection of the laws. Will Foster''s suit succeed?', 'Yes, because the higher crime rate in Foster''s neighborhood demonstrates that the county police are not giving persons who reside there the equal protection of the laws.', 'Yes, because the insurance rate differential is inherently discriminatory.', 'No, because the constitutional guarantee of equal protection of the laws is not applicable to the actions of these insurance companies.', 'No, because there is a rational basis for the differential in insurance rates.', 'C', 'The Equal Protection Clause of the Fourteenth Amendment protects citizens from conduct by the government—generally not from conduct by private actors. See Nat''l Collegiate Athletic Ass''n v. Tarkanian, 488 U.S. 179, 191, 109 S.Ct. 454, 102 L.Ed.2d 469 (1988) (acknowledging that “[a]s a general matter the protections of the Fourteenth Amendment do not extend to ‘private conduct abridging individual rights’ ”) (quoting Burton v. Wilmington Parking Auth., 365 U.S. 715, 722, 81 S.Ct. 856, 6 L.Ed.2d 45 (1961)).', 'mbe_518', 0, '114'),
('mbe_666', 'mbe', '666', '454', '1991-Feb', 'CRIM. LAW', '115', 'Jack, a bank teller, was fired by Morgan, the president of the bank. Jack decided to take revenge against Morgan, but decided against attempting it personally, because he knew Morgan was protected around the clock by bank security guards. Jack knew that Chip had a violent temper and was very jealous. Jack falsely told Chip that Chip''s wife, Elsie, was having an affair with Morgan. Enraged, Chip said, "What am I going to do?" Jack said, "If it were my wife, I''d just march into his office and blow his brains out." Chip grabbed a revolver and rushed to the bank. He walked into the bank, carrying the gun in his hand. One of the security guards, believing a holdup was about to occur, shot and killed Chip.', 'If charged with murder of Chip, Jack should be found', 'guilty, based upon extreme recklessness.', 'guilty, based upon transferred intent.', 'not guilty, because he did not intend for Chip to be shot by the security guard.', 'not guilty, because he did not shoot Chip and he was not acting in concert with the security guard.', 'A', 'If the defendant intended to kill one person and, in attempting to do so, accidentally killed another, he or she can be held liable for the intentional killing of the deceased through the law of transferred intent. 

[R]eckless murder, which is defined as murder committed “[u]nder circumstances manifesting extreme indifference to human life” by “recklessly engag[ing] in conduct which creates a grave risk of death to a person other than himself or herself,” and “thereby caus[ing] the death of another person.” § 13A–6–2(a)(2).', 'mbe_519', 0, '115'),
('mbe_667', 'mbe', '667', '454', '1991-Feb', 'CRIM. LAW', '116', 'Jack, a bank teller, was fired by Morgan, the president of the bank. Jack decided to take revenge against Morgan, but decided against attempting it personally, because he knew Morgan was protected around the clock by bank security guards. Jack knew that Chip had a violent temper and was very jealous. Jack falsely told Chip that Chip''s wife, Elsie, was having an affair with Morgan. Enraged, Chip said, "What am I going to do?" Jack said, "If it were my wife, I''d just march into his office and blow his brains out." Chip grabbed a revolver and rushed to the bank. He walked into the bank, carrying the gun in his hand. One of the security guards, believing a holdup was about to occur, shot and killed Chip.', 'If charged with attempted murder of Morgan, Jack should be found', 'guilty, because he intended to kill Morgan and used Chip to carry out his plan.', 'guilty, because he was extremely reckless as to Morgan.', 'not guilty, because Morgan was never in imminent danger of being killed.', 'not guilty, because Chip, if successful, would be guilty of no more than manslaughter and an accessory cannot be guilty of a higher crime than the principal.', 'A', 'The doctrine of transferred intent is a theory of imputed liability. It was developed to address situations where a defendant, intending to kill A, misses A and instead accidentally kills B. Without the doctrine, the individual responsible for B''s death could not be charged with murder because there was never an intent to kill B.
Rather than allow an individual who intended to commit murder to escape full responsibility for his conduct simply because he killed the wrong person, the doctrine of transferred intent was established.  The intent to kill A would be transferred or imputed *198 to victim B. “The doctrine of transferred intent was created to avoid the specific intent requirement and thus hold the defendant accountable for the consequences of his behavior when he injures an unintended victim.” State v. Wilson, 71 Wash.App. 880, 863 P.2d 116, 121 (1993), rev''d in part on other grounds, 125 Wash.2d 212, 883 P.2d 320 (1994).', 'mbe_520', 0, '116'),
('mbe_668', 'mbe', '668', '455', '1991-Feb', 'CONST. LAW', '117', '', 'The National AIDS Prevention and Control Act is a new, comprehensive federal statute that was enacted to deal with the public health crisis caused by the AIDS virus. Congress and the President were concerned that inconsistent lower court rulings with respect to the constitutionality, interpretation, and application of the statute might adversely affect or delay its enforcement and, thereby, jeopardize the public health. As a result, they included a provision in the statute providing that all legal challenges concerning those matters may be initiated only by filing suit directly in the United States Supreme Court. The provision authorizing direct review of the constitutionality, interpretation, or application of this statute only in the United States Supreme Court is', 'constitutional, because it is authorized by the Article I power of Congress to enact all laws that are "necessary and proper" to implement the general welfare.', 'constitutional, because Article III provides that the jurisdiction of the United States Supreme Court is subject to such exceptions and such regulations as Congress shall make.', 'unconstitutional, because it denies persons who wish to challenge this statute the equal protection of the laws by requiring them to file suit in a court different from that in which persons who wish to challenge other statutes may file suit.', 'unconstitutional, because it is inconsistent with the specification in Article III of the original jurisdiction of the United States Supreme Court.', 'D', 'Article III, Section 1 of the Constitution states: "In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make."', 'mbe_521', 0, '117'),
('mbe_669', 'mbe', '669', '456', '1991-Feb', 'CRIM. LAW', '118', '', 'Miller was indicted in a state court in January 1985 for a robbery and murder that occurred in December 1982. He retained counsel, who filed a motion to dismiss on the ground that Miller had been prejudiced by a 25-month delay in obtaining the indictment. Thereafter, Miller, with his counsel, appeared in court for arraignment and stated that he wished to plead guilty. The presiding judge asked Miller whether he understood the nature of the charges, possible defenses, and maximum allowable sentences. Miller replied that he did, and the judge reviewed all of those matters with him. He then asked Miller whether he understood that he did not have to plead guilty. When Miller responded that he knew that, the judge accepted the plea and sentenced Miller to 25 years. Six months later, Miller filed a motion to set aside his guilty plea on each of the following grounds. Which of these grounds provides a constitutional basis for relief?', 'The judge did not rule on his motion to dismiss before accepting the guilty plea.', 'The judge did not determine that Miller had robbed and killed the victim.', 'The judge did not determine whether Miller understood that he had a right to jury trial.', 'The judge did not determine whether the prosecutor''s file contained any undisclosed exculpatory material.', 'C', 'This court has noted “[t]here is no more fundamental right in the United States than the right to a jury trial.” State v. Larraco, 32 Kan.App.2d 996, 999, 93 P.3d 725 (2004). There can be little doubt, therefore, that the consideration of the denial of a right to a jury trial is necessary to prevent the denial of a fundamental right.
A criminal defendant''s right to a jury trial is guaranteed by constitution and statute. U.S. Const. Amend. VI; Kan. Const. Bill of Rights §§ 5, 10. K.S.A. 22–3403(1) requires all felony cases be tried to a jury unless the defendant and prosecuting attorney, with the consent of the court, submit the matter to a bench trial.
The right to a jury trial may be waived if it is done so voluntarily and knowingly. State v. Irving, 216 Kan. 588, 589, 533 P.2d 1225 (1975). “Whether this test is satisfied in any given case will depend on the particular facts and circumstances of that case, but a waiver of the right to a jury trial will not be presumed from a silent record. [Citations omitted.]” 216 Kan. at 589, 533 P.2d 1225. Rather, a court may not accept a waiver unless the defendant, after being advised by the court of his or her right to a jury trial, personally waives that right, either in writing or in open court on the record. 216 Kan. at 590, 533 P.2d 1225.', 'mbe_2669', 0, '118'),
('mbe_67', 'mbe', '67', '41', 'MBE-1972-78-part3', '', '18', '', 'Congressional legislation authorizing marriages and divorces as a matter of federal law on prescribed terms and conditions could most easily be upheld if it', 'applied only to marriages and divorces in which at least one of the parties is a member of the armed forces', 'applied only to marriages performed by federal judges and to divorces granted by federal courts', 'implemented an executive agreement seeking to define basic human rights', 'applied only to marriages and divorces in the District of Columbia', 'D', 'This brings us to the principal issue. The authority of the President to settle claims of American nationals through executive agreements is clear. See Am. Ins. Ass''n v. Garamendi, 539 U.S. 396, 123 S.Ct. 2374, ––––, 156 L.Ed.2d 376, 2003 WL 21433477, at *11 (U.S. June 23, 2003); id. at ––––, at *23 (Ginsburg, J., dissenting). There is no doubt that laws passed after the President enters into an executive agreement may abrogate the agreement. The question here is whether legislation enacted while the case was pending abrogated the Algiers Accords.', 'mbe_57', 0, '18'),
('mbe_670', 'mbe', '670', '457', '1991-Feb', 'CRIM. LAW', '119', '', 'Sally told Michael she would like to have sexual intercourse with him and that he should come to her apartment that night at 7 p.m. After Michael arrived, he and Sally went into the bedroom. As Michael started to remove Sally''s blouse, Sally said she had changed her mind. Michael tried to convince her to have intercourse with him, but after ten minutes of her sustained refusals, Michael left the apartment. Unknown to Michael, Sally was 15 years old. Because she appeared to be older, Michael believed her to be about 18 years old. A statute in the jurisdiction provides: "A person commits rape in the second degree if he has sexual intercourse with a girl, not his wife, who is under the age of 16 years." If Michael is charged with attempting to violate this statute, he is', 'guilty, because no mental state is required as to the element of age.', 'guilty, because he persisted after she told him she had changed her mind.', 'not guilty, because he reasonably believed she had consented and voluntarily withdrew after she told him she had changed her mind.', 'not guilty, because he did not intend to have intercourse with a girl under the age of 16.', 'D', 'It is a defense to a prosecution that an actor through mistake formed a reasonable belief about a matter of fact if his or her mistaken belief negated the kind of culpability required for commission of the offense.', 'mbe_2670', 0, '119'),
('mbe_671', 'mbe', '671', '458', '1991-Feb', 'CONTRACTS', '120', 'Alice entered into a contract with Paul by the terms of which Paul was to paint Alice''s office for $1,000 and was required to do all of the work over the following weekend so as to avoid disruption of Alice''s business.', 'For this question only, assume the following facts. If Paul had started to paint on the following Saturday morning, he could have finished before Sunday evening. However, he stayed home that Saturday morning to watch the final game of the World Series on TV, and did not start to paint until Saturday afternoon. By late Saturday afternoon, Paul realized that he had underestimated the time it would take to finish the job if he continued to work alone. Paul phoned Alice at her home and accurately informed her that it was impossible to finish the work over the weekend unless he hired a helper. He also stated that to do so would require an additional charge of $200 for the work. Alice told Paul that she apparently had no choice but to pay "whatever it takes" to get the work done as scheduled. Paul hired Ted to help finish the painting and paid Ted $200. Alice has offered to pay Paul $1,000. Paul is demanding $1,200. How much is Paul likely to recover?', '$1,000 only, because Alice received no consideration for her promise to pay the additional sum.', '$1,000 only, because Alice''s promise to pay "whatever it takes" is too uncertain to be enforceable.', '$1,200, in order to prevent Alice''s unjust enrichment.', '$1,200, because the impossibility of Paul''s completing the work alone discharged the original contract and a new contract was formed.', 'A', 'but where the promise to the one is simply a repetition of a subsisting legal promise there can be no consideration for the promise of the other party, and there is no warrant for inferring that the parties have voluntarily rescinded or modified their contract.  But where the party refusing to complete his contract does so by reason of some unforeseen and substantial difficulties in the performance of the contract, which were not known or anticipated by the parties when the contract was entered into, and which cast upon him an additional burden not contemplated by the parties, and the opposite party promises him extra pay or benefits if he will complete his contract, and he so promises, the promise to pay is supported by a valid consideration. In such a case the natural inference arising from the transaction, if unmodified by any equitable considerations, is rebutted, and the presumption arises that by the voluntary and mutual promises of the parties their respective rights and obligations under the original contract are waived, and those of the new or modified contract substituted for them. Cases of this character form an exception to the general rule that a promise to do that which a party is already legally bound to do is not a sufficient consideration to support a promise *488 by the other party to the contract to give the former an additional compensation or benefit. 1 Whart. Cont. § 500.', 'mbe_522', 0, '120'),
('mbe_672', 'mbe', '672', '458', '1991-Feb', 'CONTRACTS', '121', 'Alice entered into a contract with Paul by the terms of which Paul was to paint Alice''s office for $1,000 and was required to do all of the work over the following weekend so as to avoid disruption of Alice''s business.', 'For this question only, assume the following facts. Paul commenced work on Saturday morning, and had finished half the painting by the time he quit work for the day. That night, without the fault of either party, the office building was destroyed by fire. Which of the following is an accurate statement?', 'Both parties'' contractual duties are discharged, and Paul can recover nothing from Alice.', 'Both parties'' contractual duties are discharged, but Paul can recover in quasi-contract from Alice.', 'Only Paul''s contractual duty is discharged, because Alice''s performance (payment of the agreed price) is not impossible.', 'Only Paul''s contractual duty is discharged, and Paul can recover his reliance damages from Alice.', 'B', 'A cause of action for quasi-contract invokes consideration of equitable principles, rather than of contract. “ ‘... [It] is an obligation ... created by the law without regard to the intention of the parties, and is designed to restore the aggrieved party to [its] former position by return of the thing or its equivalent in money. [Citations.]’ ” (Unilab Corp. v. Angeles-IPA (2016) 244 Cal.App.4th 622, 639, 198 Cal.Rptr.3d 211; 1 Witkin, Summary of Cal. Law (11th ed. 2017) Contracts, § 1050; Rest.2d Contracts, § 4, com. b, p. 56.) The doctrine focuses on equitable principles; its key phrase is “ ‘unjust enrichment,’ ” which is used to identify the “transfer of money or other valuable assets to an individual or a company that is not entitled to them.” (Rest.3d Restitution and Unjust Enrichment, Foreword, vol. 1, p. XIII.)', 'mbe_523', 0, '121'),
('mbe_673', 'mbe', '673', '459', '1991-Feb', 'CONST. LAW', '122', '', 'The state of Erehwon has a statute providing that an unsuccessful candidate in a primary election for a party''s nomination for elected public office may not become a candidate for the same office at the following general election by nominating petition or by write-in votes. Sabel sought her party''s nomination for governor in the May primary election. After losing in the primary, Sabel filed nominating petitions containing the requisite number of signatures to become a candidate for the office of governor in the following general election. The chief elections officer of Erehwon refused to certify Sabel''s petitions solely because of the above statute. Sabel then filed suit in federal district court challenging the constitutionality of this Erehwon statute. As a matter of constitutional law, which of the following is the proper burden of persuasion in this suit?', 'Sabel must demonstrate that the statute is not necessary to achieve a compelling state interest.', 'Sabel must demonstrate that the statute is not rationally related to a legitimate state interest.', 'The state must demonstrate that the statute is the least restrictive means of achieving a compelling state interest.', 'The state must demonstrate that the statute is rationally related to a legitimate state interest.', 'C', 'Regulations imposing severe burdens on plaintiffs'' rights are subject to strict scrutiny and must be narrowly tailored to advance a compelling State interest. Id. at 358–59, 117 S.Ct. 1364; see also Yes On Term Limits, Inc. v. Savage, 550 F.3d 1023, 1028 (10th Cir.2008) (noting that, to survive strict scrutiny, the State “has the burden *1274 of proving that its [regulation] is narrowly tailored to serve a compelling state interest”) (citation omitted).To survive strict scrutiny, the Secretary has the burden of proving that the hybrid scheme is narrowly tailored to serve a compelling State interest. Yes on Term Limits, 550 F.3d at 1028 (citation omitted).', 'mbe_524', 0, '122'),
('mbe_674', 'mbe', '674', '460', '1991-Feb', 'REAL PROP.', '123', '', 'Rohan executed and delivered a promissory note and a mortgage securing the note to Acme Mortgage Company, which was named as payee in the note and as mortgagee in the mortgage. The note included a statement that the indebtedness evidenced by the note was "subject to the terms of a contract between the maker and the payee of the note executed on the same day" and that the note was "secured by a mortgage of even date." The mortgage was promptly and properly recorded. Subsequently, Acme sold the Rohan note and mortgage to XYZ Bank and delivered to XYZ Bank a written assignment of the Rohan note and mortgage. The assignment was promptly and properly recorded. Acme retained possession of both the note and the mortgage in order to act as collecting agent. Later, being short of funds, Acme sold the note and mortgage to Peterson at a substantial discount. Acme executed a written assignment of the note and mortgage to Peterson and delivered to him the note, the mortgage, and the assignment. Peterson paid value for the assignment without actual knowledge of the prior assignment to XYZ Bank and promptly and properly recorded his assignment. The principal of the note was not then due, and there had been no default in payment of either interest or principal. If the issue of ownership of the Rohan note and mortgage is subsequently raised in an appropriate action by XYZ Bank to foreclose, the court should hold that', 'Peterson owns both the note and the mortgage.', 'XYZ Bank owns both the note and the mortgage.', 'Peterson owns the note and XYZ Bank owns the mortgage.', 'XYZ Bank owns the note and Peterson owns the mortgage.', 'B', 'the legal owner of a promissory note may maintain a cause of action even though actual or beneficial ownership of the note lies in another. The beneficial owner of a promissory note is not even a necessary party to a suit on the note. Importantly, it is legal ownership that must be proved to enforce a note.', 'mbe_525', 0, '123'),
('mbe_675', 'mbe', '675', '461', '1991-Feb', 'CONST. LAW', '124', '', 'In order to provide funds for a system of new major airports near the ten largest cities in the United States, Congress levies a tax of $25 on each airline ticket issued in the United States. The tax applies to every airline ticket, even those for travel that does not originate in, terminate at, or pass through any of those ten large cities. As applied to the issuance in the United States of an airline ticket for travel between two cities that will not be served by any of the new airports, this tax is', 'constitutional, because Congress has broad discretion in choosing the subjects of its taxation and may impose taxes on subjects that have no relation to the purpose for which those tax funds will be expended.', 'constitutional, because an exemption for the issuance of tickets for travel between cities that will not be served by the new airports would deny the purchasers of all other tickets the equal protection of the laws.', 'unconstitutional, because the burden of the tax outweighs its benefits for passengers whose travel does not originate in, terminate at, or pass through any of the ten largest cities.', 'unconstitutional, because the tax adversely affects the fundamental right to travel.', 'A', 'The only limitation upon the power of Congress to levy excise taxes of the character now under consideration is geographical uniformity throughout the United States. This court has often declared it cannot add others. Subject to such limitation Congress may select the subjects of taxation, and may exercise the power conferred at its discretion. License Tax Cases, 5 Wall. 462, 471, 18 L. Ed. 497. Of course Congress may not in the exercise of federal power exert authority wholly reserved to the states. Many decisions of this court have so declared. And from an early day the court has held that the fact that other motives may impel the exercise of federal taxing power does not authorize the courts to inquire into that subject. If the legislation enacted has some reasonable relation to the exercise of the taxing authority conferred by the Constitution, it cannot be invalidated because of the supposed motives which induced it. Veazie Bank v. Fenno, 8 Wall. 533, 541, 19 L. Ed. 482, in which case this court sustained a tax on a state bank issue of circulating notes. McCray v. United States, 195 U. S. 27, 24 Sup. Ct. 769, 49 L. Ed. 78, 1 Ann. Cas. 561, where the power was thoroughly considered, and an act levying a special tax upon oleomargarine artificially colored was sustained. And see Flint v. Stone Tracy Co., 220 U. S. 107, 147, 153, 156, 31 Sup. Ct. 342, 55 L. Ed. 389, Ann. Cas. 1912B, 1312, and cases cited.', 'mbe_2384', 0, '124'),
('mbe_676', 'mbe', '676', '462', '1991-Feb', 'REAL PROP.', '125', '', 'Stoven, who owned Craigmont in fee simple, mortgaged Craigmont to Ulrich to secure a loan of $100,000. The mortgage was promptly and properly recorded. Stoven later mortgaged Craigmont to Martin to secure a loan of $50,000. The mortgage was promptly and properly recorded. Subsequently, Stoven conveyed Craigmont to Fritsch. About a year later, Fritsch borrowed $100,000 from Zom, an elderly widow, and gave her a mortgage on Craigmont to secure repayment of the loan. Zorn did not know about the mortgage held by Martin. The understanding between Fritsch and Zorn was that Fritsch would use the $100,000 to pay off the mortgage held by Ulrich and that Zom would, therefore, have a first mortgage on Craigmont. Zorn''s mortgage was promptly and properly recorded. Fritsch paid the $100,000 received from Zom to Ulrich and obtained and recorded a release of the Ulrich mortgage. The $50,000 debt secured by the Martin mortgage was not paid when it was due, and Martin brought an appropriate action to foreclose, joining Stoven, Fritsch, and Zom as defendants and alleging that Martin''s mortgage was senior to Zorn''s mortgage on Craigmont. If the court rules that Zom''s mortgage is entitled to priority over Martin''s mortgage, which of the following determinations are necessary to support that ruling? I. Ulrich''s mortgage was originally senior to Martin''s mortgage. II. Zorn is entitled to have Ulrich''s mortgage revived for her benefit, and Zorn is entitled to be subrogated to Ulrich''s original position as senior mortgagee. III. There are no countervailing equities in favor of Martin.', 'I and II only.', 'I and III only.', 'II and III only.', 'I, II, and III.', 'D', 'Recording a deed perfects delivery. See Candlewood Lake Assn. v. Scott, 10th Dist. Franklin App. No. 01AP–631, 2001-Ohio-8873 [2001 WL 1654288].  However, “a deed does not have to be recorded to pass title. Whether or not recorded, a deed in Ohio passes title upon its proper execution and delivery, so far as the grantor is able to convey it.” Wayne Bldg. & Loan of Wooster v. *873 Yarborough, 11 Ohio St.2d 195, 212, 228 N.E.2d 841 (1967).', 'mbe_2671', 0, '125'),
('mbe_677', 'mbe', '677', '463', '1991-Feb', 'EVIDENCE', '126', '', 'Paul sued Dyer for personal injuries sustained when Dyer''s car hit Paul, a pedestrian. Immediately after the accident, Dyer got out of his car, raced over to Paul, and said, "Don''t worry, I''ll pay your hospital bill." Paul''s testimony concerning Dyer''s statement is', 'admissible, because it is an admission of liability by a party opponent.', 'admissible, because it is within the excited utterance exception to the hearsay rule.', 'inadmissible to prove liability, because it is an offer to pay medical expenses.', 'inadmissible, provided that Dyer kept his promise to pay Paul''s medical expenses.', 'C', 'Admissions of a party opponent are admissible as exceptions to the hearsay rule. Tennyson v. State, 282 Ga. 92, 93(3), 646 S.E.2d 219 (2007).', 'mbe_526', 0, '126'),
('mbe_678', 'mbe', '678', '464', '1991-Feb', 'CRIM. LAW', '127', '', 'One evening, Parnell had several drinks and then started to drive home. As he was proceeding down Main Boulevard, an automobile pulled out of a side street to his right. Parnell''s car struck this automobile broadside. The driver of the other car was killed as a result of the collision. A breath analysis test administered after the accident showed that Parnell satisfied the legal definition of intoxication. If Parnell is prosecuted for manslaughter, his best chance for acquittal would be based on an argument that', 'the other driver was contributorily negligent.', 'the collision would have occurred even if Parnell had not been intoxicated.', 'because of his intoxication he lacked the mens rea needed for manslaughter.', 'driving while intoxicated requires no mens rea and so cannot be the basis for misdemeanor manslaughter.', 'B', 'The elements of involuntary manslaughter are as follows: (i) the unlawful killing: (ii) of a human being; (iii) without malice; (iv) through either: (a) the commission of an unlawful act not amounting to a felony; or (b) while committing a lawful act in an unlawful manner, or without due caution and circumspection, which act might produce death. See 18 U.S.C. § 1112(a); Tenth Circuit Pattern Jury Instructions Criminal § 2.54.1, at 185 (2011)(Involuntary Manslaughter). When the killing occurs outside of a situation involving the commission of an unlawful act not amount to a felony, the United States must prove to secure a conviction under 18 U.S.C. § 1112(a) for involuntary manslaughter that defendant acted with “gross negligence amounting to wanton and reckless disregard for human life.” Tenth Circuit Pattern Jury Instructions Criminal § 2.54.1, at 185. This mens rea requirement is equivalent to “ ‘gross'' or ‘criminal’ negligence,” and thus contains a similar mens rea requirement to an offense committed under N.M.S.A.1978, § 30–6–1(D)(1). United States v. Browner, 889 F.2d 549, 553 (5th Cir.1989).', 'mbe_2672', 0, '127'),
('mbe_679', 'mbe', '679', '465', '1991-Feb', 'CONTRACTS', '128', '', 'Seisin and Vendee, standing on Greenacre, orally agreed to its sale and purchase for $5,000, and orally marked its bounds as "that line of trees down there, the ditch that intersects them, the fence on the other side, and that street on the fourth side." In which of the following is the remedy of reformation most appropriate?', 'As later reduced to writing, the agreement by clerical mistake included two acres that are actually beyond the fence.', 'Vendee reasonably thought that two acres beyond the fence were included in the oral agreement but Seisin did not. As later reduced to writing, the agreement included the two acres.', 'Vendee reasonably thought that the price orally agreed upon was $4,500, but Seisin did not. As later reduced to writing, the agreement said $5,000.', 'Vendee reasonably thought that a dilapidated shed backed up against the fence was to be torn down and removed as part of the agreement, but Seisin did not. As later reduced to writing, the agreement said nothing about the shed.', 'A', '[T]he distinction between clerical error and judicial error does not turn on whether the correction of the error results in a substantive change in the judgment. Rather, the distinction turns on whether the error “was the deliberate result of judicial reasoning and determination, regardless of whether it was made by the clerk, by counsel, or by the judge.” Buchanan v. West Kentucky Coal Company, Ky., 218 Ky. 259, 291 S.W. 32, 35 (1927). “A clerical error involves an error or mistake made by a clerk or other judicial or ministerial officer in writing or keeping records....” 46 Am.Jur.2d, Judgments § 167. The omission ... was not the product of judicial reasoning and determination. It was a clerical error.', 'mbe_527', 0, '128'),
('mbe_68', 'mbe', '68', '42', 'MBE-1972-78-part3', '', '19', 'Assume for the purposes of these questions that you are counsel to the state legislative committee that is responsible for real estate laws in your state.', 'The committee wants you to draft a statute governing the recording of deeds that fixes priorities of title, as reflected on the public record, as definitely as possible. Which of the following, divorced from other policy considerations, would best accomplish this particular result?', 'Eliminate the requirement of witnesses to deeds.', 'Make time of recording the controlling factor.', 'Make irrebuttable the declarations in the deeds that valuable consideration was paid.', 'Make the protection of bona fide purchasers the controlling factor.', 'B', 'A deed to personalty needs no attesting witness to make it valid; in other respects, the principles applicable to deeds to lands are applicable to deeds to personalty. However, generally a deed is not necessary to convey title to personalty.', 'mbe_2323', 0, '19'),
('mbe_680', 'mbe', '680', '466', '1991-Feb', 'TORTS', '129', '', 'Airco operates an aircraft maintenance and repair business serving the needs of owners of private airplanes. Flyer contracted with Airco to replace the engine in his plane with a more powerful engine of foreign manufacture. Airco purchased the replacement engine through a representative of the manufacturer and installed it in Flyer''s plane. A short time after it was put into use, the new engine failed, and the plane crashed into a warehouse owned by Landers, destroying the warehouse and its contents. Airco was guilty of no negligence in the procurement, inspection, or installation of the engine. The failure of the engine was caused by a defect that would not be disclosed by inspection and testing procedures available to an installer. There was no negligence on the part of Flyer, who escaped the disabled plane by parachute. Landers recovered a judgment for damages from Flyer for the destruction of his warehouse and its contents, and Flyer has asserted a claim against Airco to recover compensation on account of that liability. In that action, Flyer will recover', 'full compensation, because the engine was defective.', 'no compensation, because Airco was not negligent.', 'contribution only, because Airco and Flyer were equally innocent.', 'no compensation, because Landers''s judgment established Flyer''s responsibility to Landers.', 'A', 'Stated generally, a “defective product” is one which is “not reasonably safe” or is “unreasonably dangerous” to the user or consumer. Campbell, 970 P.2d at 392, quoting McLaughlin, 778 P.2d at 64. In contrast, “[i]f a product is safe for normal handling and consumption, it is not defective.” Campbell, 970 P.2d at 392. It is not enough to show that an injury occurred during use of the product to establish it was defective. Id. at 394. Instead, a plaintiff must show a defect in the product, which he may do either by presenting evidence of a specific defect or by inference. Sims, 751 P.2d at 360–61.', 'mbe_528', 0, '129'),
('mbe_681', 'mbe', '681', '467', '1991-Feb', 'CONST. LAW', '130', '', 'To encourage the growth of its population, the state of Axbridge established a program that awarded $1,000 to the parents of each child born within the state, provided that at the time of the child''s birth the mother and father of the newborn were citizens of the United States. The Lills are aliens who are permanent residents of the United States and have resided in Axbridge for three years. When their first child was born two months ago, they applied for and were denied the $1,000 award by Axbridge officials on the sole ground that they are not citizens of the United States. The Lills filed suit in federal court contending that their exclusion from the award program was unconstitutional. Assume no federal statute addresses this question. In this case, the court should hold that the exclusion of aliens from the Axbridge award program is', 'constitutional, because the Tenth Amendment reserves to the states plenary authority over the spending of state funds.', 'constitutional, because Axbridge has a legitimate interest in encouraging the growth of its population, and a rational legislature could believe that families in which both parents are United States citizens are more likely to stay in Axbridge and contribute to its future prosperity than those in which one or both of the parents are aliens.', 'unconstitutional, because strict scrutiny governs judicial review of such state classifications based on alienage, and Axbridge cannot demonstrate that this classification is necessary to advance a compelling state interest.', 'unconstitutional, because state classifications based on alienage are impermissible unless explicitly authorized by an act of Congress.', 'C', 'The Court has ruled that classifications by a State that are based on alienage are “inherently suspect and subject to close judicial scrutiny.” Graham v. Richardson, 403 U.S. 365, 372, 91 S.Ct. 1848, 1852, 29 L.Ed.2d 534 (1971). See Examining Board v. Flores de Otero, 426 U.S. 572, 601-602, 96 S.Ct. 2264, 2281, 49 L.Ed.2d 65 (1976); In re Griffiths, 413 U.S., at 721, 93 S.Ct. at 2854, 37 L.Ed.2d 910; Sugarman v. Dougall, 413 U.S. 634, 642, 93 S.Ct. 2842, 2847, 37 L.Ed.2d 853 (1973). In undertaking this scrutiny, “the governmental interest claimed to justify the discrimination is to be carefully examined in order to determine whether that interest is legitimate and substantial, and inquiry must be made whether the means adopted to achieve the goal are necessary and precisely drawn.” Examining Board v. Flores de Otero, 426 U.S., at 605, 96 S.Ct., at 2283. See In re Griffths, 413 U.S., at 721-722, 93 S.Ct., at 2854-2855. Alienage classifications by a State that do not withstand this stringent examination cannot stand.', 'mbe_529', 0, '130'),
('mbe_682', 'mbe', '682', '468', '1991-Feb', 'TORTS', '131', '', 'While driving at a speed in excess of the statutory limit, Dant negligently collided with another car, and the disabled vehicles blocked two of the highway''s three northbound lanes. When Page approached the scene two minutes later, he slowed his car to see if he could help those involved in the collision. As he slowed, he was rear-ended by a vehicle driven by Thomas. Page, who sustained damage to his car and was seriously injured, brought an action against Dant to recover damages. The jurisdiction adheres to the traditional common-law rules pertaining to contributory negligence. If Dant moves to dismiss the action for failure to state a claim upon which relief may be granted, should the motion be granted?', 'Yes, because it was Thomas, not Dant, who collided with Page''s car and caused Page''s injuries.', 'Yes, if Page could have safely passed the disabled vehicles in the traffic lane that remained open.', 'No, because a jury could find that Page''s injury arose from a risk that was a continuing consequence of Dant''s negligence.', 'No, because Dant was driving in excess of the statutory limit when he negligently caused the first accident.', 'C', 'Proximate cause has two elements: cause in fact and foreseeability. Travis v. City of Mesquite, 830 S.W.2d 94, 98 (Tex.1992). “These elements cannot be established by mere conjecture, guess, or speculation.” Doe, 907 S.W.2d at 477. The test for cause in fact is whether the act or omission was a substantial factor in causing the injury without which the harm would not have occurred. Marathon Corp. v. Pitzner, 106 S.W.3d 724, 727 (Tex.2003). If the defendant''s negligence merely furnished a condition that made the injuries possible, there can be no cause in fact. See IHS Cedars Treatment Ctr. of Desoto, Tex., Inc. v. Mason, 143 S.W.3d 794, 799 (Tex.2004).', 'mbe_530', 0, '131'),
('mbe_683', 'mbe', '683', '469', '1991-Feb', 'REAL PROP.', '132', '', 'Olin owned Blueacre, a valuable tract of land located in York County. Olin executed a document in the form of a warranty deed of Blueacre, which was regular in all respects except that the only language designating the grantees in each of the granting and habendum clauses was: "The leaders of all the Protestant Churches in York County." The instrument was acknowledged as required by statute and promptly and properly recorded. Olin told his lawyer, but no one else, that he had made the conveyance as he did because he abhorred sectarianism in the Protestant movement and because he thought that the leaders would devote the asset to lessening sectarianism. Olin died suddenly and unexpectedly a week later, leaving a will that bequeathed and devised his entire estate to Plum. After probate of the will became final and the administration on Olin''s estate was closed, Plum instituted an appropriate action to quiet title to Blueacre and properly served as defendant each Protestant church situated in the county. The only evidence introduced consisted of the chain of title under which Olin held, the probated will, the recorded deed, the fact that no person knew about the deed except Olin and his lawyer, and the conversation Olin had with his lawyer described above. In such action, judgment should be for', 'Plum, because there is inadequate identification of grantees in the deed.', 'Plum, because the state of the evidence would not support a finding of delivery of the deed.', 'the defendants, because a deed is prima facie valid until rebutted.', 'the defendants, because recording established delivery prima facie until rebutted.', 'A', 'The overwhelming weight of authority is that once a bona fide purchaser or lender for value acquires title by way of execution of contract for sale or valid mortgage, the purchaser or mortgagee takes title free and clear of any subsequent lien.9 In the *504 case sub judice, it is beyond cavil that appellee acquired its interest as a mortgagee of the property well before the filing of the petition for a mechanics'' lien; thus, it did not take its interest subject to appellant''s mechanics'' lien and appellant''s mechanics'' lien did not acquire priority over appellee''s interest.', 'mbe_531', 0, '132'),
('mbe_684', 'mbe', '684', '470', '1991-Feb', 'CONST. LAW', '133', '', 'Old City police officers shot and killed Jones''s friend as he attempted to escape arrest for an armed robbery he had committed. Jones brought suit in federal district court against the Old City Police Department and the city police officers involved, seeking only a judgment declaring unconstitutional the state statute under which the police acted. That newly enacted statute authorized the police to use deadly force when necessary to apprehend a person who has committed a felony. In his suit, Jones alleged that the police would not have killed his friend if the use of deadly force had not been authorized by the statute. The federal district court should', 'decide the case on its merits, because it raises a substantial federal question.', 'dismiss the action, because it involves a nonjusticiable political question.', 'dismiss the action, because it does not present a case or controversy.', 'dismiss the action, because the Eleventh Amendment prohibits federal courts from deciding cases of this type.', 'C', '"No federal court, whether this Court or a district court, has ‘jurisdiction to pronounce any statute, either of a state or of the United States, void, because irreconcilable with the constitution, except as it is called upon to adjudge the legal rights of litigants in actual controversies.’"', 'mbe_532', 0, '133'),
('mbe_685', 'mbe', '685', '471', '1991-Feb', 'EVIDENCE', '134', '', 'Dooley and Melville were charged with conspiracy to dispose of a stolen diamond necklace. Melville jumped bail and cannot be found. Proceeding to trial against Dooley alone, the prosecutor calls Wixon, Melville''s girlfriend, to testify that Melville confided to her that "Dooley said I still owe him some of the money from selling that necklace." Wixon''s testimony is', 'admissible as evidence of a statement by party-opponent Dooley.', 'admissible as evidence of a statement against interest by Melville.', 'inadmissible, because Melville''s statement was not in furtherance of the conspiracy.', 'inadmissible, because Melville is not shown to have firsthand knowledge that the necklace was stolen.', 'B', 'For Rule 804(b)(3) to apply, the proponent of an inculpatory hearsay statement must show: (1) that the declarant is unavailable to testify at trial; (2) that the statement was against the declarant''s penal interest when made; and (3) that corroborating circumstances clearly suggest that the statement is trustworthy. United States v. Loggins, 486 F.3d 977, 981 (7th Cir.2007). At trial, Volpendesto invoked his right against self-incrimination; there is no dispute that, with respect to the first requirement, he was unavailable to testify.', 'mbe_2673', 0, '134'),
('mbe_686', 'mbe', '686', '472', '1991-Feb', 'TORTS', '135', '', 'Pocket, a bank vice president, took substantial kickbacks to approve certain loans that later proved worthless. Upon learning of the kickbacks, Dudd, the bank''s president, fired Pocket, telling him, "If you are not out of this bank in ten minutes, I will have the guards throw you out bodily." Pocket left at once. If Pocket asserts a claim against Dudd based on assault, will Pocket prevail?', 'No, because the guards never touched Pocket.', 'No, because Dudd gave Pocket ten minutes to leave.', 'Yes, if Dudd intended to cause Pocket severe emotional distress.', 'Yes, because Dudd threatened Pocket with a harmful or offensive bodily contact.', 'B', '“Under California law, to prevail on the tort of assault, the plaintiff must establish that: (1) the defendant threatened to touch the plaintiff in a harmful or offensive manner; (2) it reasonably appeared to the plaintiff that the defendant was about to carry out the threat; (3) the plaintiff did not consent to the defendant''s conduct; (4) the plaintiff was harmed; and (5) the defendant''s conduct was a substantial factor in causing the plaintiff''s harm.” Avina, 681 F.3d at 1130. As with battery, “[p]hysical injury is not a required element” of assault. Kiseskey v. Carpenters'' Trust for S. Cal., 144 Cal.App.3d 222, 232, 192 Cal.Rptr. 492 (1983).', 'mbe_533', 0, '135'),
('mbe_687', 'mbe', '687', '473', '1991-Feb', 'CONST. LAW', '136', '', 'Lee contracted with Mover, an interstate carrier, to ship household goods from the state of Green to his new home in the state of Pink. A federal statute provides that all liability of an interstate mover to a shipper for loss of or damage to the shipper''s goods in transit is governed exclusively by the contract between them. The statute also requires the mover to offer a shipper at least two contracts with different levels of liability. In full compliance with that federal statute, Mover offered Lee a choice between two shipping agreements that provided different levels of liability on the part of Mover. The more expensive contract provided that Mover was fully liable in case of loss or damage. The less expensive contract limited Mover''s liability in case of loss or damage to less than full value. Lee voluntarily signed the less expensive contract with Mover, fixing Mover''s liability at less than the full value of the shipment. Mover''s truck was involved in an accident in the state of Pink. The accident was entirely a product of the negligence of Mover''s driver. Lee''s household goods were totally destroyed. In accordance with the contract, Mover reimbursed Lee for less than the full value of the goods. Lee then brought suit against Mover under the tort law of the state of Pink claiming that he was entitled to be reimbursed for the full value of the goods. Mover filed a motion to dismiss. In this suit, the court should', 'dismiss the case, because the federal statute governing liability of interstate carriers is the supreme law of the land and preempts state tort law.', 'dismiss the case, because the contractual relationship between Lee and Mover is governed by the obligation of contracts clause of the Constitution.', 'deny the motion to dismiss, because the full faith and credit clause of the Constitution requires that state tort law be given effect.', 'deny the motion to dismiss, because it is unconstitutional for a federal statute to authorize Mover to contract out of any degree of liability for its own negligence.', 'A', 'Conflict preemption arises when there is an actual conflict between state and federal law, such as when compliance with both federal and state law is impossible or when the state law stands as an obstacle to the full purposes and objectives of the federal law (see, for example, Walker v. People''s United Bank, 305 F. Supp. 3d 365, 377 (D. Conn. 2018); Walkup v. Santander Bank, N.A., 147 F. Supp. 3d 349, 356 (E.D. Pa. 2015)).', 'mbe_534', 0, '136'),
('mbe_688', 'mbe', '688', '474', '1991-Feb', 'CRIM. LAW', '137', '', 'John asked Doris to spend a weekend with him at his apartment and promised her they would get married on the following Monday. Doris agreed and also promised John that she would not tell anyone of their plans. Unknown to Doris, John had no intention of marrying her. After Doris came to his apartment, John told Doris he was going for cigarettes. He called Doris''s father and told him that he had his daughter and would kill her if he did not receive $100,000. John was arrested on Sunday afternoon when he went to pick up the $100,000. Doris was still at the apartment and knew nothing of John''s attempt to get the money. John is guilty of', 'kidnapping.', 'attempted kidnapping.', 'kidnapping or attempted kidnapping but not both.', 'neither kidnapping nor attempted kidnapping.', 'D', '“[A] person commits the offense of kidnapping when he abducts or steals away any person without lawful authority or warrant and holds such person against his will.” Therefore, the elements of kidnapping are “(1) an illegal holding, (2) an overmastering of the victim''s will, and (3) an asportation of the victim.”1', 'mbe_535', 0, '137'),
('mbe_689', 'mbe', '689', '475', '1991-Feb', 'CONST. LAW', '138', '', 'Metro City operates a cemetery pursuant to a city ordinance. The ordinance requires the operation of the city cemetery to be supported primarily by revenues derived from the sale of cemetery lots to individuals. The ordinance further provides that the purchase of a cemetery lot entitles the owner to perpetual care of the lot, and entitles the owner to erect on the lot, at the owner''s expense, a memorial monument or marker of the owner''s choice, subject to certain size restrictions. The Metro City ordinance requires the city to maintain the cemetery, including mowing the grass, watering flowers, and plowing snow, and provides for the expenditure of city tax funds for such maintenance if revenues from the sale of cemetery lots are insufficient. Although cemetery lots are sold at full fair market value, which includes the current value of perpetual care, the revenue from the sale of such lots has been insufficient in recent years to maintain the cemetery. As a result, a small amount of city tax funds has also been used for that purpose. A group of Metro City taxpayers brings suit against Metro City challenging the constitutionality of the city ordinance insofar as it permits the owner of a cemetery lot to erect a religious memorial monument or marker on his or her lot. Is this suit likely to be successful?', 'No, because only a small amount of city tax funds has been used to maintain the cemetery.', 'No, because the purpose of the ordinance is entirely secular, its primary effect neither advances nor inhibits religion, and it does not foster an excessive government entanglement with religion.', 'Yes, because city maintenance of any religious object is a violation of the establishment clause of the First Amendment as incorporated into the Fourteenth Amendment.', 'Yes, because no compelling governmental interest justifies authorizing private persons to erect religious monuments or markers in a city-operated cemetery.', 'B', 'Three such tests may be gleaned from our cases. First, the statute must have a secular legislative purpose; second, its principal or primary effect must be one that neither advances nor inhibits religion, Board of Education v. Allen, 392 U.S. 236, 243, 88 S.Ct. 1923, 1926, 20 L.Ed.2d 1060 (1968); *613 finally, the statute must not foster ‘an excessive government entanglement with religion.’ Walz, supra, at 674, 90 S.Ct., at 1414.', 'mbe_536', 0, '138'),
('mbe_69', 'mbe', '69', '43', 'MBE-1972-78-part3', '', '20', 'Assume for the purposes of these questions that you are counsel to the state legislative committee that is responsible for real estate laws in your state.', 'The committee wants you to draft legislation to make all restrictions on land use imposed by deeds (now or hereafter recorded) unenforceable in the future so that public land-use planning through zoning will have exclusive control in matters of land use. Which of the following is LEAST likely to be a consideration in the drafting of such legislation?', 'Compensation for property rights taken by public authority', 'Impairment of contract', 'Sovereign immunity', 'Police power', 'C', 'Sovereign immunity means that the United States may not be sued without its consent and the existence of consent is a prerequisite for jurisdiction. United States v. Mitchell, 463 U.S. 206, 212, 103 S.Ct. 2961, 77 L.Ed.2d 580 (1983).', 'mbe_2609', 0, '20'),
('mbe_690', 'mbe', '690', '476', '1991-Feb', 'EVIDENCE', '139', '', 'In a civil action for personal injury, Payne alleges that he was beaten up by Dabney during an altercation in a crowded bar. Dabney''s defense is that he was not the person who hit Payne. To corroborate his testimony about the cause of his injuries, Payne seeks to introduce, through the hospital records custodian, a notation in a regular medical record made by an emergency room doctor at the hospital where Payne was treated for his injuries. The notation is: "Patient says he was attacked by Dabney." The notation is', 'inadmissible, unless the doctor who made the record is present at trial and available for cross-examination.', 'inadmissible as hearsay not within any exception.', 'admissible as hearsay within the exception for records of regularly conducted activity.', 'admissible as a statement made for the purpose of medical diagnosis or treatment.', 'B', '“Hearsay” is an assertion of fact or belief made out of court and offered to prove the truth of the matter asserted.', 'mbe_537', 0, '139'),
('mbe_691', 'mbe', '691', '477', '1991-Feb', 'EVIDENCE', '140', '', 'Dexter was tried for the homicide of a girl whose strangled body was found beside a remote logging road with her hands taped together. After Dexter offered evidence of alibi, the state calls Wilma to testify that Dexter had taped her hands and tried to strangle her in the same location two days before the homicide but that she escaped. The evidence is', 'admissible, as tending to show Dexter is the killer.', 'admissible, as tending to show Dexter''s violent nature.', 'inadmissible, because it is improper character evidence.', 'inadmissible, because it is unfairly prejudicial.', 'A', '“Unfair prejudice supporting exclusion of relevant evidence means a tendency to suggest decision on an improper basis or divert the jury''s attention away from its duty of weighing the evidence impartially.” Klein, 85 A.3d at 498. “A witness can be contradicted only on matters germane to the issue trying. There is no rule more firmly established than this: ‘No contradiction shall be permitted on collateral matters.’ ” Id. at 500 (quoting Hammel v. Christian, 416 Pa.Super. 78, 610 A.2d 979, 984 (1992), appeal denied, 533 Pa. 652, 624 A.2d 111 (1993)).', 'mbe_538', 0, '140'),
('mbe_692', 'mbe', '692', '478', '1991-Feb', 'CONTRACTS', '141', '', 'Fruitko, Inc., ordered from Orchard, Inc., 500 bushels of No. 1 Royal Fuzz peaches, at a specified price, "for prompt shipment." Orchard promptly shipped 500 bushels, but by mistake shipped No. 2 Royal Fuzz peaches instead of No. 1. The error in shipment was caused by the negligence of Orchard''s shipping clerk. Which of the following best states Fruitko''s rights and duties upon delivery of the peaches?', 'Orchard''s shipment of the peaches was a counteroffer and Fruitko can refuse to accept them.', 'Orchard''s shipment of the peaches was a counteroffer but, since peaches are perishable, Fruitko, if it does not want to accept them, must reship the peaches to Orchard in order to mitigate Orchard''s losses.', 'Fruitko must accept the peaches because a contract was formed when Orchard shipped them.', 'Although a contract was formed when Orchard shipped the peaches, Fruitko does not have to accept them.', 'D', 'A contract is formed when an offer is made and accepted, and the agreement is supported by consideration. Marquardt v. Perry, 200 P.3d 1126, 1129 (Colo.App.2008).  Acceptance of an offer is generally defined as words or conduct that, when objectively viewed, manifests an intent to accept an offer. Id. A person who, with knowledge of an offer''s terms, voluntarily takes the benefits of the offered services without objection is deemed to have accepted the offer and formed a contract. Restatement (Second), Contracts § 69.', 'mbe_343', 0, '141'),
('mbe_693', 'mbe', '693', '479', '1991-Feb', 'REAL PROP.', '142', '', 'Blackacre was a tract of 100 acres retained by Byron, the owner, after he had developed the adjoining 400 acres as a residential subdivision. Byron had effectively imposed restrictive covenants on each lot in the 400 acres. Chaney offered Byron a good price for a five-acre tract located in a corner of Blackacre far away from the existing 400-acre residential subdivision. Byron conveyed the fiveacre tract to Chaney and imposed the same restrictive covenants on the five-acre tract as he had imposed on the lots in the adjoining 400 acres. Byron further covenanted that when he sold the remaining 95 acres of Blackacre he would impose the same restrictive covenants in the deed or deeds for the 95 acres. Byron''s conveyance to Chaney was promptly and properly recorded. However, shortly thereafter, Byron conveyed the remaining 95 acres to Dart for $100,000 by a deed that made no mention of any restrictive covenants. Dart had no actual knowledge of the restrictive covenants in Chaney''s deed. Dart now proposes to build an industrial park which would violate such restrictive covenants if they are applicable. The recording act of the jurisdiction provides: "No conveyance or mortgage of real property shall be good against subsequent purchasers for value and without notice unless the same be recorded according to law." In an appropriate action by Chaney to enforce the restrictive covenants against Dart''s 95-acre tract, if Dart wins it will be because', 'the deed imposing the restrictions was not in the chain of title for the 95 acres when Dart bought.', 'the disparity in acreage means that the covenant can only be personal to Byron.', 'negative reciprocal covenants are not generally recognized.', 'a covenant to impose restrictions is an illegal restraint on alienation.', 'A', 'A purchaser is bound by every recital, reference, and reservation contained in or fairly disclosed by an instrument that forms an essential link in the chain of title under which he claims. Westland Oil Dev. Corp. v. Gulf Oil Corp., 637 S.W.2d 903, 908 (Tex.1982).', 'mbe_539', 0, '142'),
('mbe_694', 'mbe', '694', '480', '1991-Feb', 'CRIM. LAW', '143', '', 'A grand jury indicted Alice on a charge of arson, and a valid warrant was issued for her arrest. Paul, a police officer, arrested Alice and informed her of what the warrant stated. However, hoping that Alice might say something incriminating, he did not give her Miranda warnings. He placed her in the back seat of his patrol car and was driving her to the police station when she said, "Look, I didn''t mean to bum the building; it was an accident. I was just burning some papers in a wastebasket." At the station, after being given Miranda warnings, Alice stated she wished to remain silent and made no other statements. Alice moved to suppress the use of her statement to Paul as evidence on two grounds: first, that the statement was acquired without giving Miranda warnings, and second, that the police officer had deliberately elicited her incriminating statement after she was in custody. As to Alice''s motion to suppress, the court should', 'deny the motion.', 'grant the motion only on the basis of the first ground stated.', 'grant the motion only on the basis of the second ground stated.', 'grant the motion on either ground.', 'A', 'As we previously explained, “Miranda warnings are required only when there is a custodial interrogation.” State v. Wright, 2009 S.D. 51, ¶ 19, 768 N.W.2d 512, 520 (citing State v. Aesoph, 2002 S.D. 71, ¶ 17, 647 N.W.2d 743, 751).', 'mbe_540', 0, '143'),
('mbe_695', 'mbe', '695', '481', '1991-Feb', 'CONTRACTS', '144', '', 'Debtor''s $1,000 contractual obligation to Aunt was due on July 1. On the preceding June 15, Aunt called Niece and said, "As my birthday gift to you, you may collect on July 1 the $1,000 Debtor owes me." Aunt also called Debtor and told him to pay the $1,000 to Niece on July 1. On July 1, Debtor, saying that he did not like Niece and wouldn''t pay anything to her, paid the $1,000 to Aunt, who accepted it without objection. Will Niece succeed in an action for $1,000 against Debtor?', 'Yes, because Aunt had effectively assigned the $1,000 debt to her.', 'Yes, because Aunt''s calls to Niece and Debtor effected a novation.', 'No, because Aunt''s acceptance of the $1,000, without objection, was in effect the revocation of a gratuitous assignment.', 'No, because Debtor cannot be compelled to render performance to an assignee whom he finds personally objectionable.', 'C', 'It is true that, in general, payments voluntarily made are not recoverable.', 'mbe_541', 0, '144'),
('mbe_696', 'mbe', '696', '482', '1991-Feb', 'TORTS', '145', 'Dooley was a pitcher for the City Robins, a professional baseball team. While Dooley was throwing warm-up pitches on the sidelines during a game, he was continuously heckled by some spectators seated in the stands above the dugout behind a wire mesh fence. On several occasions, Dooley turned and looked directly at the hecklers with a scowl on his face, but the heckling continued. Dooley wound up as though he was preparing to pitch in the direction of his catcher; however the ball traveled from his hand at high speed, at a 90-degree angle from the line to the catcher and directly toward the hecklers in the stands. The ball passed through the wire mesh fence and struck Patricia, one of the hecklers. Patricia brought an action for damages against Dooley and the City Robins, based upon negligence and battery. The trial court directed a verdict for the defendants on the battery count. The jury found for the defendants on the negligence count because the jury determined that Dooley could not foresee that the ball would pass through the wire mesh fence. Patricia has appealed the judgments on the battery counts, contending that the trial court erred in directing verdicts for Dooley and the City Robins.', 'On appeal, the judgment entered on the directed verdict in Dooley''s favor on the battery claim should be', 'affirmed, because the jury found on the evidence that Dooley could not foresee that the ball would pass through the fence.', 'affirmed, if there was evidence that Dooley was mentally ill and that his act was the product of his mental illness.', 'reversed and the case remanded, if a jury could find on the evidence that Dooley intended to cause the hecklers to fear being hit.', 'reversed and the case remanded, because a jury could find that Dooley''s conduct was extreme and outrageous, and the cause of physical harm to Patricia.', 'C', 'The elements of a civil battery claim in California are: “(1) defendant intentionally performed an act that resulted in a harmful or offensive contact with the plaintiff''s person; (2) plaintiff did not consent to the contact; and (3) the harmful or offensive contact caused injury, damage, loss or harm to plaintiff.” Brown v. Ransweiler, 171 Cal. App. 4th 516, 526–27 (2009). “Plaintiff must prove unreasonable force as an element of the tort” of civil battery. Edson v. City of Anaheim, 63 Cal. App. 4th 1269, 1272 (1998).', 'mbe_542', 0, '145'),
('mbe_697', 'mbe', '697', '482', '1991-Feb', 'TORTS', '146', 'Dooley was a pitcher for the City Robins, a professional baseball team. While Dooley was throwing warm-up pitches on the sidelines during a game, he was continuously heckled by some spectators seated in the stands above the dugout behind a wire mesh fence. On several occasions, Dooley turned and looked directly at the hecklers with a scowl on his face, but the heckling continued. Dooley wound up as though he was preparing to pitch in the direction of his catcher; however the ball traveled from his hand at high speed, at a 90-degree angle from the line to the catcher and directly toward the hecklers in the stands. The ball passed through the wire mesh fence and struck Patricia, one of the hecklers. Patricia brought an action for damages against Dooley and the City Robins, based upon negligence and battery. The trial court directed a verdict for the defendants on the battery count. The jury found for the defendants on the negligence count because the jury determined that Dooley could not foresee that the ball would pass through the wire mesh fence. Patricia has appealed the judgments on the battery counts, contending that the trial court erred in directing verdicts for Dooley and the City Robins.', 'For this question only, assume that, on appeal, the court holds that the question of whether Dooley committed a battery is a jury issue. The judgment entered on the directed verdict in favor of the City Robins should then be', 'reversed and the case remanded, because a jury could find the City Robins vicariously liable for a battery committed by Dooley in the course of his employment.', 'reversed and the case remanded, only if a jury could find negligence on the part of the Robins'' management.', 'affirmed, because an employer is not vicariously liable for a servant''s battery.', 'affirmed, if Dooley''s act was a knowing violation of team rules.', 'A', '“Vicarious liability ‘means that the act or omission of one person ... is imputed by operation of law to another,’ ” without regard to fault. (Srithong v. Total Investment Co. (1994) 23 Cal.App.4th 721, 726, 28 Cal.Rptr.2d 672, italics added.) For example, vicarious liability for torts is imposed by operation of law upon employers for acts of their employees within the course and scope of employment, or upon principals for the acts of their agents. Kiymaz was neither Brown''s employee nor agent. Plaintiff''s suggestion that Brown is vicariously liable for his tenant''s negligence is contrary to established law that the negligence of a tenant “cannot be imputed to the landlord.” (Mundt v. Nowlin, supra, 44 Cal.App.2d at p. 415, 112 P.2d 782; see also O''Leary v. Herbert (1936) 5 Cal.2d 416, 418, 55 P.2d 834, Anderson v. Souza, supra, 38 Cal.2d at p. 831, 243 P.2d 497.)', 'mbe_543', 0, '146'),
('mbe_698', 'mbe', '698', '483', '1991-Feb', 'CONST. LAW', '147', '', 'The School Board of the city of Rulb issued a rule authorizing public school principals to punish, after a hearing, students who engage in violations of the board''s student behavior code. According to the rule, violators of the behavior code may be punished in a variety of ways including being required to sit in designated school confinement rooms during all school hours, with their hands clasped in front of them, for a period of up to 15 school days. Teddy, a fifth grade student in Rulb Elementary School, was charged with placing chewed bubble gum on a classmate''s chair, a violation of the student behavior code. He had never violated the code before and was otherwise an attentive and well-behaved student. After a hearing on the charges, Teddy''s principal determined that Teddy had violated the behavior code in the manner charged, and ordered Teddy to spend the next 15 school days in the school confinement room with his hands clasped in front of him. Teddy''s parents file suit in federal court challenging, solely on constitutional grounds, the principal''s action in ordering Teddy to spend the next 15 school days in the school confinement room with his hands clasped in front of him. Which of the following arguments would be most helpful to Teddy''s parents in this suit?', 'Because the school board rule limits the freedom of movement of students and subjects them to bodily restraint, it denies them a privilege and immunity of citizenship guaranteed them by Article IV, Section 2.', 'Because the school board rule is substantially overbroad in relation to any legitimate purpose, it constitutes a facial violation of the equal protection clause of the Fourteenth Amendment.', 'Because application of the school board rule in this case denies the student freedom of movement and subjects him to bodily restraint in a manner grossly disproportionate to his offense and circumstances, it violates the due process clause of the Fourteenth Amendment.', 'Because the school board rule is enforced initially by administrative rather than judicial proceedings, it constitutes a prohibited bill of attainder.', 'C', '“(T)he range of interests protected by procedural due process is not infinite.” Board of Regents v. Roth, supra, at 570, 92 S.Ct., at 2705. We have repeatedly rejected “the notion that any grievous loss visited upon a person by the State is sufficient to invoke the procedural protections of the Due Process Clause.” Meachum v. Fano, 427 U.S. at 224, 96 S.Ct., at 2538. Due process is required only when a decision of the State implicates an interest within the protection of the Fourteenth Amendment. And “to determine whether due process requirements apply in the first place, we must look not to the ‘weight’ but to the nature of the interest at stake.” Roth, supra, 408 U.S., at 570-571, 92 S.Ct., at 2705.
 The Due Process Clause of the Fifth Amendment, later incorporated into the Fourteenth, was intended to give Americans *673 at least the protection against governmental power that they had enjoyed as Englishmen against the power of the Crown. The liberty preserved from deprivation without due process included the right “generally to enjoy those privileges long recognized at common law as essential to the orderly pursuit of happiness by free men.” Meyer v. Nebraska, 262 U.S. 390, 399, 43 S.Ct. 625, 626, 67 L.Ed. 1042 (1923); see Dent v. West Virginia, 129 U.S. 114, 123-124, 9 S.Ct. 231, 233-234, 32 L.Ed. 623 (1889). Among the historic liberties so protected was a right to be free from and to obtain judicial relief, for unjustified intrusions on personal security.41
While the contours of this historic liberty interest in the context of our federal system of government have not been defined precisely,42 they always have been thought **1414 to encompass *674 freedom from bodily restraint and punishment. See Rochin v. California, 342 U.S. 165, 72 S.Ct. 205, 96 L.Ed. 183 (1952). It is fundamental that the state cannot hold and physically punish an individual except in accordance with due process of law.
This constitutionally protected liberty interest is at stake in this case. There is, of course a de minimis level of imposition with which the Constitution is not concerned. But at least where school authorities, acting under color of state law, deliberately decide to punish a child for misconduct by restraining the child and inflicting appreciable physical pain, we hold that Fourteenth Amendment liberty interests are implicated.', 'mbe_544', 0, '147'),
('mbe_699', 'mbe', '699', '484', '1991-Feb', 'EVIDENCE', '148', '', 'Davidson and Smythe were charged with burglary of a warehouse. They were tried separately. At Davidson''s trial, Smythe testified that he saw Davidson commit the burglary. While Smythe is still subject to recall as a witness, Davidson calls Smythe''s cellmate, Walton, to testify that Smythe said, "I broke into the warehouse alone because Davidson was too drunk to help." This evidence of Smythe''s statement is', 'admissible as a declaration against penal interest.', 'admissible as a prior inconsistent statement.', 'inadmissible, because it is hearsay not within any exception.', 'inadmissible, because the statement is not clearly corroborated.', 'B', 'Each element of a criminal offense “must be proven by sufficient evidence.” Spottedbear, ¶ 23. Prior inconsistent statements may be admitted as substantive evidence and may be considered in “determining whether the evidence is sufficient to sustain the conviction.” State v. Torres, 2013 MT 101, ¶ 27, 369 Mont. 516, 299 P.3d 804. A prior inconsistent statement is a statement made by a declarant that the declarant later contradicts during testimony at trial. M. R. Evid. 801(d)(1)(A). While such a statement may be admitted as substantive evidence, it is insufficient, standing alone, to prove a necessary element of a criminal offense. Torres, ¶ 27 (citing State v. White Water, 194 Mont. 85, 88-89, 634 P.2d 636, 638 (1981)). Instead, prior inconsistent statements must be corroborated by other evidence in order to sustain a conviction. State v. Giant, 2001 MT 245, ¶ 34, 307 Mont. 74, 37 P.3d 49; State v. Charlo, 226 Mont. 213, 217, 735 P.2d 278, 280 (1987).
**924 ¶ 12 We established in White Water that “[a]n unreliable prior inconsistent statement should not be the sole, substantive evidence upon which a jury should be allowed to base guilt.” White Water, 194 Mont. at 88, 634 P.2d at 638. We relied on White Water to conclude in Giant that prior inconsistent statements admitted as substantive evidence of guilt must be corroborated in order to sustain a conviction. Giant, ¶ 34. We held that evidence of the husband’s flight did not corroborate the wife’s prior inconsistent statement identifying him as her attacker, because neither the prior statement nor the evidence of flight independently constituted reliable evidence of guilt. Giant, ¶¶ 39, 41. We noted that evidence of flight, standing alone, “cannot be the sole basis of guilt,” as flight could be “as consistent with innocence as it is with guilt.” Giant, ¶ 38. We explained that to hold that “two forms of evidence, each unreliable in its own right, nonetheless, when taken together, are sufficient to prove guilt beyond a reasonable doubt, accords the sum of the evidence a characteristic trustworthiness that neither of its constituent parts possesses.” Giant, ¶ 39.', 'mbe_545', 0, '148'),
('mbe_7', 'mbe', '7', '3', 'MBE-1972-78-part2', '', '8', 'A water pipe burst in the basement of Supermart, a grocery store, flooding the basement and damaging cases of canned goods on the floor. The Plumbing contractor''s workmen, in repairing the leak, knocked over several stacks of canned goods in cases, denting the cans. After settling its claims against the landlord for the water leak and against the plumbing contractor for the damage done by his workmen, Supermart put the goods on special sale. Four weeks later Dotty was shopping in Supermart. Several tables in the market were covered with assorted canned foods, all of which were dirty and dented. A sign on each of the tables read: "Damaged Cans-Half Price." Dotty was having Guest for dinner that evening and purchased two dented cans of tuna, packed by Canco, from one of the tables displaying the damaged cans. Before Guest arrived, Dotty prepared a tuna casserole which she and Guest ate. Both became ill and the medical testimony established that the illness was caused by the tuna''s being unfit for consumption. The tuna consumed by Dotty and Guest came from the case that was at the top of one of the stacks knocked over by the workmen. The tuna in undamaged cans from the same Canco shipment was fit for consumption.', 'If Dotty asserts a claim against Canco based on negligence, the doctrine of res ipsa loquitur is', 'applicable, because the tuna was packed in a sealed can', 'applicable, because Canco as the packer is strictly liable', 'not applicable, because the case of tuna had been knocked over by the workmen', 'not applicable, because of the sign on the table from which Dotty purchased the tuna', 'C', 'The res ipsa loquitur doctrine “enables a jury presented only with circumstantial evidence to infer negligence simply from the fact that an event happened.” St. Paul Fire & Marine Ins. Co. v. City of New York, 907 F.2d 299, 302 (2d Cir.1990).  The criteria for applying res ipsa loquitur include
 “(1) the event must be of a kind which ordinarily does not occur in the absence of someone''s negligence; (2) it must be caused by an agency or instrumentality within the exclusive control of the defendant; (3) it must not have been due to any voluntary action or contribution on the part of the plaintiff.”
Morejon v. Rais Construction Company, 7 N.Y.3d 203, 818 N.Y.S.2d 792, 851 N.E.2d 1143, 1147 (2006) (quoting Corcoran v. Banner Super Mkt., 19 N.Y.2d 425, 280 N.Y.S.2d 385, 227 N.E.2d 304 (1967)).', 'mbe_4', 0, '8'),
('mbe_70', 'mbe', '70', '44', 'MBE-1972-78-part3', '', '21', '', 'Vetter and Prue each signed a memorandum which stated that Vetter agreed to sell and Prue agreed to purchase a tract of land and that the contract should be closed and conveyance made and accepted "by tender of general warranty deed conveying a good and marketable title" on a date specified. The memorandum signed by the parties contains all of the elements deemed essential and necessary to satisfy the Statute of Frauds applicable to the transaction except that there was omission of a recitation of the purchase price agreed upon. Vetter has refused to perform the contract, and in an action by Prue for specific performance, Vetter relies upon the Statute of Frauds as a defense. If Prue offers evidence, in addition to the written memorandum, that the parties discussed and agreed upon a purchase price of $35,000 just prior to signing, Prue should', 'succeed, because Vetter is estopped to deny that such agreed price is a fair and equitable one. which will be implied by law as a term of the written memorandum', 'succeed, because the law implies that the parties contracted for the reasonable market value of the land, although the price to be paid may not necessarily be that orally agreed upon', 'fail, because the price agreed upon is an essential element of the contract and must be in writing', 'fail, because the evidence does not show that the price agreed upon is in fact the reasonable market value of the land', 'C', 'Under the California statute of frauds,52 a promise or agreement to answer for the debt, default, or miscarriage of another person, such as a guaranty or surety, must be in writing and signed by the party to be charged. An oral modification of a contract subject to the statute of frauds is never permitted when it would materially alter the parties'' written agreement.53 “Were it possible to make an oral modification of a contract which by the statute of frauds is required to be in writing and enforce such oral modification, the door would be open for the perpetration of such frauds as the statute seeks to prevent.”54', 'mbe_2610', 0, '21'),
('mbe_700', 'mbe', '700', '485', '1991-Feb', 'CONTRACTS', '149', '', 'On March 1, Hotz Apartments, Inc., received from Koolair, Inc., a letter offering to sell Hotz 1,200 window air conditioners suitable for the apartments in Hotz''s buildings. The Koolair offer stated that it would remain open until March 20, but that Hotz''s acceptance must be received on or before that date. On March 16, Hotz posted a letter of acceptance. On March 17, Koolair telegraphed Hotz to advise that it was revoking the offer. The telegram reached Hotz on March 17, but Hotz''s letter did not arrive at Koolair''s address until March 21. As of March 22, which of the following is a correct statement?', 'The telegram revoking the offer was effective upon receipt.', 'The offer was revocable at any time for lack of consideration.', 'The mail was the only authorized means of revocation.', 'Under the terms of Koolair''s offer, Hotz''s attempted acceptance was ineffective.', 'D', 'Moreover, when negotiating the terms, the acceptance of the final offer must be substantially as made; if the purported acceptance includes conditions or differing terms, it is not a valid acceptance—it is a counteroffer and will not bind the parties. See Harper Bldg. Co. v. Kaplan, 332 Mich. 651, 655–656, 52 N.W.2d 536 (1952).', 'mbe_2674', 0, '149'),
('mbe_701', 'mbe', '701', '486', '1991-Feb', 'TORTS', '150', '', 'Dieter parked her car in violation of a city ordinance that prohibits parking within ten feet of a fire hydrant. Because Grove was driving negligently, his car sideswiped Dieter''s parked car. Plaintiff, a passenger in Grove''s car, was injured in the collision. If Plaintiff asserts a claim against Dieter to recover damages for his injuries, basing his claim on Dieter''s violation of the parking ordinance, will Plaintiff prevail?', 'Yes, because Dieter was guilty of negligence per se.', 'Yes, if Plaintiff would not have been injured had Dieter''s car not been parked where it was.', 'No, because Dieter''s parked car was not an active or efficient cause of Plaintiff''s injury.', 'No, if prevention of traffic accidents was not a purpose of the ordinance.', 'D', 'Instead, they argue that a South Bend ordinance required Radman to maintain the handrail and that Radman therefore owed them a duty under the doctrine of negligence per se. Under that doctrine, the unexcused violation of a statute or ordinance constitutes negligence per se if the provision (1) “protect[s] the class of persons in which the plaintiff is included” and (2) “protect[s] against the type of harm which has occurred as a result of the violation.” City of Fort Wayne v. Parrish, 32 N.E.3d 275, 277 (Ind. Ct. App. 2015), trans. denied.', 'mbe_2675', 0, '150'),
('mbe_702', 'mbe', '702', '487', '1991-Feb', 'REAL PROP.', '151', '', 'Owen owned Greenacre, a tract of land, in fee simple. By warranty deed he conveyed Greenacre to Lafe for life "and from and after the death of Lafe to Rem, her heirs and assigns." Subsequently Rem died, devising all of her estate to Dan. Rem was survived by Hannah, her sole heir-at-law. Shortly thereafter Lafe died, survived by Owen, Dan, and Hannah. Title to Greenacre now is in', 'Owen, because the contingent remainder never vested and Owen''s reversion was entitled to possession immediately upon Lafe''s death.', 'Dan, because the vested remainder in Rem was transmitted by her will.', 'Hannah, because she is Rem''s heir.', 'either Owen or Hannah, depending upon whether the destructibility of contingent remainders is recognized in the applicable jurisdiction.', 'B', 'A vested remainder is a present fixed right in the remainderman to take possession upon the natural termination of the preceding estate with no conditions precedent imposed on the time for the remainder to vest in interest.” Id. (citing Chas. W. Priddy & Co. v. Sanderford, 221 N.C. 422, 424, 20 S.E.2d 341, 343 (1942) (stating that a “remainder is vested, when, throughout its continuance, the remainderman and his heirs have the right to the immediate possession whenever and however the preceding estate is determined; or, in other words, a remainder is vested if, so long as it lasts, the only obstacle to the right of immediate possession by the remainderman is the existence of the preceding estate; or, again, a remainder is vested if it is subject to no condition precedent save the determination of the preceding estate.”)).', 'mbe_546', 0, '151'),
('mbe_703', 'mbe', '703', '488', '1991-Feb', 'CONST. LAW', '152', '', 'A statute of the state of Illitron declares that after five years of continuous service in their positions all state employees, including faculty members at the state university, are entitled to retain their positions during "good behavior." The statute also contains a number of procedural provisions. Any state employee who is dismissed after that five-year period must be given reasons for the dismissal before it takes effect. In addition, such an employee must, upon request, be granted a postdismissal hearing before an administrative board to seek reinstatement and back pay. The statute precludes any other hearing or opportunity to respond to the charges. That post-dismissal hearing must occur within six months after the dismissal takes effect. The burden of proof at such a hearing is on the state, and the board may uphold the dismissal only if it is supported by a preponderance of the evidence. An employee who is dissatisfied with a decision of the board after a hearing may appeal its decision to the state courts. The provisions of this statute are inseverable. A teacher who had been employed continuously for seven years as a faculty member at the state university was dismissed. A week before the dismissal took effect, she was informed that she was being dismissed because of a charge that she accepted a bribe from a student in return for raising the student''s final grade in her course. At that time she requested an immediate hearing to contest the propriety of her dismissal. Three months after her dismissal, she was granted a hearing before the state administrative board. The board upheld her dismissal, finding that the charge against her was supported by a preponderance of the evidence presented at the hearing. The faculty member did not appeal the decision of the state administrative board to the Illitron state courts. Instead, she sought a declaratory judgment in federal district court to the effect that the state statute prescribing the procedures for her dismissal is unconstitutional. In this case, the federal district court should', 'dismiss the suit, because a claim that a state statute is unconstitutional is not ripe for adjudication by a federal court until all judicial remedies in state courts provided for by state law have been exhausted.', 'hold the statute unconstitutional, because the due process clause of the Fourteenth Amendment requires a state to demonstrate beyond a reasonable doubt the facts constituting good cause for termination of a state employee.', 'hold the statute unconstitutional, because a state may not ordinarily deprive an employee of a property interest in a job without giving the employee an opportunity for some kind of a predismissal hearing to respond to the charges against that employee.', 'hold the statute constitutional, because the due process clause of the Fourteenth Amendment entitles state employees who have a right to their jobs during good behavior only to a statement of reasons for their dismissal and an opportunity for a post-dismissal hearing.', 'C', 'Respondents'' federal constitutional claim depends on their having had a property right in continued employment. Board of Regents v. Roth, 408 U.S. 564, 576–578, 92 S.Ct. 2701, 2708–2709, 33 L.Ed.2d 548 (1972); Reagan v. United States, 182 U.S. 419, 425, 21 S.Ct. 842, 845, 45 L.Ed. 1162 (1901). If they did, the State could not deprive them of this property without due process. See Memphis Light, Gas & Water Div. v. Craft, 436 U.S. 1, 11–12, 98 S.Ct. 1554, 1561–1562, 56 L.Ed.2d 30 (1978); Goss v. Lopez, 419 U.S. 565, 573–574, 95 S.Ct. 729, 735–736, 42 L.Ed.2d 725 (1975).

An essential principle of due process is that a deprivation of life, liberty, or property “be preceded by notice and opportunity for hearing appropriate to the nature of the case.” Mullane v. Central Hanover Bank & Trust Co., 339 U.S. 306, 313, 70 S.Ct. 652, 656, 94 L.Ed. 865 (1950). We have described “the root requirement” of the Due Process Clause as being “that an individual be given an opportunity for a hearing before he is deprived of any significant property interest.” Boddie v. Connecticut, 401 U.S. 371, 379, 91 S.Ct. 780, 786, 28 L.Ed.2d 113 (1971) (emphasis in original); see Bell v. Burson, 402 U.S. 535, 542, 91 S.Ct. 1586, 1591, 29 L.Ed.2d 90 (1971). This principle requires “some kind of a hearing” prior to the discharge of an employee who has a constitutionally protected property interest in his employment. Board of Regents v. Roth, 408 U.S., at 569–570, 92 S.Ct., at 2705; Perry v. Sindermann, 408 U.S. 593, 599, 92 S.Ct. 2694, 2698, 33 L.Ed.2d 570 (1972).', 'mbe_547', 0, '152'),
('mbe_704', 'mbe', '704', '489', '1991-Feb', 'TORTS', '153', '', 'Dorfman''s dog ran into the street in front of Dorfman''s home and began chasing cars. Peterson, who was driving a car on the street, swerved to avoid hitting the dog, struck a telephone pole, and was injured. If Peterson asserts a claim against Dorfman, will Peterson prevail?', 'Yes, because Dorfman''s dog was a cause in fact of Peterson''s injury.', 'Yes, if Dorfman knew his dog had a propensity to chase cars and did not restrain it.', 'No, because a dog is a domestic animal.', 'No, unless a statute or ordinance made it unlawful for the owner to allow a dog to be unleashed on a public street.', 'B', '“[N]egligence is the failure to use due care,” i.e., “that degree of care which a person of ordinary prudence and reason would exercise under the same circumstances.” Hart v. Doe, 261 S.C. 116, 122, 198 S.E.2d 526, 529 (1973). It is often referred to as either ordinary negligence or simple negligence.', 'mbe_548', 0, '153'),
('mbe_705', 'mbe', '705', '490', '1991-Feb', 'TORTS', '154', '', 'Dower, an inexperienced driver, borrowed a car from Puder, a casual acquaintance, for the express purpose of driving it several blocks to the local drug store. Instead, Dower drove the car, which then was worth $12,000, 100 miles to Other City. While Dower was driving in Other City the next day, the car was hit by a negligently driven truck and sustained damage that will cost $3,000 to repair. If repaired, the car will be fully restored to its former condition. If Puder asserts a claim against Dower based on conversion, Puder should recover a judgment for', '$12,000.00', '$3,000.00', '$3,000 plus damages for the loss of the use of the car during its repair.', 'nothing, unless Dower was negligent and his negligence was a substantial cause of the collision.', 'A', '“The measure of damages for the conversion of a chattel is the market value of the chattel at the time and place of conversion plus interest to the date of judgment.” Staub v. Staub, 37 Md.App. 141, 145, 376 A.2d 1129 (1977).', 'mbe_549', 0, '154'),
('mbe_706', 'mbe', '706', '491', '1991-Feb', 'CRIM. LAW', '155', '', 'Miller''s, a department store, had experienced a growing incidence of shoplifting. At the store''s request, the police concealed Best, a woman who was a detective, at a vantage point above the women''s apparel fitting rooms where she could see into these rooms, where customers tried on clothes. Detective Best saw Davis enter a fitting room, stuff a dress into her pocketbook, leave the fitting room, and start for the street door. By prearranged signal, Best notified another police officer near the door, who detained Davis as Davis started to go out into the street. Davis was placed under arrest, and the dress was retrieved from her purse. Davis is charged with shoplifting. Her motion to prevent the introduction of the dress into evidence will be', 'granted, because the police should have secured a search warrant to search her bag.', 'granted, because a customer has a reasonable expectation of privacy while using a department store fitting room.', 'denied, because the search and seizure were made incident to a valid arrest based on probable cause.', 'denied, because Detective Best could see into the room and thus Davis''s activities were legitimately in plain view.', 'B', '“A ‘reasonable’ expectation of privacy is an objective entitlement founded on broadly based and widely accepted community norms.” (Hill, supra, 7 Cal.4th at p. 37, 26 Cal.Rptr.2d 834, 865 P.2d 633.) The reasonableness of a privacy expectation depends on the surrounding context. The Supreme Court has “stressed that ‘customs, practices, and physical settings surrounding particular activities may create or inhibit reasonable expectations of privacy.’ [Citation.]” (County of Los Angeles, supra, 56 Cal.4th at p. 927, 157 Cal.Rptr.3d 481, 301 P.3d 1102.)', 'mbe_550', 0, '155'),
('mbe_707', 'mbe', '707', '492', '1991-Feb', 'REAL PROP.', '156', 'Pam and Dora own adjoining lots in the central portion of a city. Each of their lots had an office building. Dora decided to raze the existing building on her lot and to erect a building of greater height. Dora has received all governmental approvals required to pursue her project. There is no applicable statute or ordinance (other than those dealing with various approvals for zoning, building, etc.).', 'After Dora had torn down the existing building, she proceeded to excavate deeper. Dora used shoring that met all local, state, and federal safety regulations, and the shoring was placed in accordance with those standards. Pam notified Dora that cracks were developing in the building situated on Pam''s lot. Dora took the view that any subsidence suffered by Pam was due to the weight of Pam''s building, and correctly asserted that none would have occurred had Pam''s soil been in its natural state. Dora continued to excavate. The building on Pam''s lot did suffer extensive damage, requiring the expenditure of $750,000 to remedy the defects. Which of the following is the best comment concerning Pam''s action to recover damages from Dora?', 'Dora is liable, because she removed necessary support for Pam''s lot.', 'Dora cannot be held liable simply upon proof that support was removed, but may be held liable if negligence is proved.', 'Once land is improved with a building, the owner cannot invoke the commonlaw right of lateral support.', 'Dora''s only obligation was to satisfy all local, state, and federal safety regulations.', 'B', 'Liability under the doctrine arises only if the removal of lateral support causes the soil to subside.14 See id. at 1040–41 (noting that limitations for a claim based on the removal of lateral support runs from when the injury occurs, that is when the land begins to slough off); see also Braxton, 2011 WL 4031171, at *6 (upholding summary judgment against plaintiff suing for loss of lateral support when his evidence showed that no injury to his soil had yet occurred); Wingfield v. Bryant, 614 S.W.2d 643, 645 (Tex. Civ. App.—Austin 1981, writ ref''d n.r.e.) (“Before a party may recover for the loss of lateral support, he must show that his land has been injured.”); Restatement (Second) of Torts § 817 cmt. h (Am. Law Inst. 1979) (defining subsidence as the movement of soil from its natural position). Thus, a person removing lateral support from adjoining land may avoid future liability by installing sufficient artificial lateral support, such as a retaining wall. Restatement (Second) of Torts § 817 cmt. i, k; see, e.g., Gerhard v. Fichter, 12 N.J.Super. 265, 79 A.2d 502, 503 (N.J. Super. Ct. Ch. Div. 1951) (holding landowner not liable for removing lateral support from neighbor''s land when he replaced the natural support with adequate artificial support). However, even when a plaintiff is entitled to artificial support, the plaintiff cannot necessarily dictate or mandate the type of support provided. See 23 James E. Lockhart, Causes of Action 681 § 31 Practice Guide (1990), Westlaw (database updated May 2019); see also Vennard v. Morrison, 3 Conn.Cir.Ct. 120, 209 A.2d 202, 208–09 (1964).', 'mbe_551', 0, '156'),
('mbe_708', 'mbe', '708', '492', '1991-Feb', 'REAL PROP.', '157', 'Pam and Dora own adjoining lots in the central portion of a city. Each of their lots had an office building. Dora decided to raze the existing building on her lot and to erect a building of greater height. Dora has received all governmental approvals required to pursue her project. There is no applicable statute or ordinance (other than those dealing with various approvals for zoning, building, etc.).', 'Assume that no problems with subsidence or other misadventures occurred during construction of Dora''s new building. However, when it was completed, Pam discovered that the shadow created by the new higher building placed her building in such deep shade that her ability to lease space was diminished and that the rent she could charge and the occupancy rate were substantially lower. Assume that these facts are proved in an appropriate action Pam instituted against Dora for all and any relief available. Which of the following is the most appropriate comment concerning this lawsuit?', 'Pam is entitled to a mandatory injunction requiring Dora to restore conditions to those existing with the prior building insofar as the shadow is concerned.', 'The court should award permanent damages, in lieu of an injunction, equal to the present value of all rents lost and loss on rents for the reasonable life of the building.', 'The court should award damages for losses suffered to the date of trial and leave open recovery of future damages.', 'Judgment should be for Dora, because Pam has no cause of action.', 'D', 'The general rule may be admitted that every land-owner has a right to have his land preserved unbroken, and that an adjoining owner excavating on his own land is subject to this restriction, that he must not remove the earth so near to the land of his neighbor that his neighbor''s soil will crumble away under its own weight and fall upon his land. But this right of lateral support extends only to the soil in its natural condition. It does not protect whatever is placed upon the soil increasing the downward and lateral pressure. If it did, it would put it in the power of a lot-owner, by erecting heavy buildings on his lot, to greatly abridge the right of his neighbor to use his lot. It would make the rights of the prior occupant greatly superior to those of the latter. Wyatt v. Harrison, 3 Barn. & Adol. 871; Lasala v. Holbrook, 4 Paige (N. Y.), 169; Washburn, Easements, c. 4, sect. 1.', 'mbe_552', 0, '157'),
('mbe_709', 'mbe', '709', '493', '1991-Feb', 'TORTS', '158', '', 'Deland operates a bank courier service that uses armored trucks to transport money and securities. One of Deland''s armored trucks was parked illegally, too close to a street intersection. Pilcher, driving his car at an excessive speed, skidded into the armored truck while trying to make a turn. The truck was not damaged, but Pilcher was injured. Pilcher has brought an action against Deland to recover damages for his loss resulting from the accident. The jurisdiction follows a pure comparative negligence rule. In this action, Pilcher should recover', 'nothing, because Deland was not an active or efficient cause of Pilcher''s loss.', 'nothing, if Deland was less negligent than Pilcher.', 'his entire loss, reduced by a percentage that reflects the negligence attributed to Pilcher.', 'his entire loss, because Deland''s truck suffered no damage.', 'C', 'Comparative negligence
When any person suffers death or damage as a result partly of that person''s own fault and partly of the fault of any other person or persons, a claim in respect of that death or damage may not be defeated by reason of the fault of the person suffering the damage, but the damages recoverable in respect thereof must be reduced to such extent as the jury thinks just and equitable having regard to the claimant''s share in the responsibility for the damage.
When damages are recoverable by any person by virtue of this section, subject to such reduction as is mentioned, the court shall instruct the jury to find and record the total damages that would have been recoverable if the claimant had not been at fault, and further instruct the jury to reduce the total damages by dollars and cents, and not by percentage, to the extent considered just and equitable, having regard to the claimant''s share in the responsibility for the damages, and instruct the jury to return both amounts with the knowledge that the lesser figure is the final verdict in the case.', 'mbe_2385', 0, '158'),
('mbe_71', 'mbe', '71', '45', 'MBE-1972-78-part3', '', '22', 'Price sued Derrick for injuries Price received in an automobile accident. Price claimed Derrick was negligent in (a) exceeding the posted speed limit of 35 m.p.h., (b) failing to keep a lookout, and (c) crossing the center line.', 'Bystander, Price''s eyewitness, testified on cross-examination that Derrick was wearing a green sweater at the time of the accident. Derrick''s counsel calls Wilson to testify that Derrick''s sweater was blue. Wilson''s testimony is', 'admissible as substantive evidence of a material fact', 'admissible as bearing on Bystander''s truthfulness and veracity', 'inadmissible, because it has no bearing on the capacity of Bystander to observe', 'inadmissible, because it is extrinsic evidence of a collateral matter', 'D', 'The collateral evidence doctrine forbids the introduction of extrinsic evidence to contradict a witness on a collateral matter. Frederick C. Moss, The Sweeping-Claims Exception and the Federal Rules of Evidence, 1982 Duke Law Journal 61-112 (1982). Its purpose is to “limit the scope of impeachment to the introduction of evidence that is relevant to the important issues in dispute.” Id. Therefore, it functions as a corollary to the relevancy requirement; it excludes evidence that is logically relevant to the credibility of witnesses. Id.', 'mbe_2611', 0, '22'),
('mbe_710', 'mbe', '710', '494', '1991-Feb', 'CONST. LAW', '159', '', 'Roberts, a professional motorcycle rider, put on a performance in a privately owned stadium during which he leaped his motorcycle over 21 automobiles. Spectators were charged $5 each to view the jump and were prohibited from using cameras. However, the local television station filmed the whole event from within the stadium without the knowledge or consent of Roberts and showed the film in its entirety on the evening newscast that day. Roberts thereafter brought suit to recover damages from the station for the admittedly unauthorized filming and broadcasting of the act. The television station raised only constitutional defenses. The court should', 'hold against Roberts, because the First and Fourteenth Amendments authorize press coverage of newsworthy entertainment events.', 'hold against Roberts, because under the First and Fourteenth Amendments news broadcasts are absolutely privileged.', 'find the station liable, because its action deprives Roberts of his property without due process.', 'find the station liable, because the First and Fourteenth Amendments do not deprive an entertainer of the commercial value of his or her performances.', 'D', 'First and Fourteenth Amendments did not immunize television broadcasting company when it broadcast “human cannonball” performer''s entire act without his consent, although state could, as matter of its own law, privilege the press in such circumstances. U.S.C.A.Const. Amends. 1, 14; Civil Rights Law N.Y. §§ 50, 51; 17 U.S.C.A. App. § 101 et seq.', 'mbe_553', 0, '159'),
('mbe_711', 'mbe', '711', '495', '1991-Feb', 'CONTRACTS', '160', '', 'Stirrup, a rancher, and Equinox, a fancier of horses, signed the following writing: "For $5,000, Stirrup will sell to Equinox a gray horse that Equinox may choose from among the grays on Stirrup''s ranch." Equinox refused to accept delivery of a gray horse timely tendered by Stirrup or to choose among those remaining, on the ground that during their negotiations Stirrup had orally agreed to include a saddle, worth $100, and also to give Equinox the option to choose a gray or a brown horse. Equinox insisted on one of Stirrup''s brown horses, but Stirrup refused to part with any of his browns or with the saddle as demanded by Equinox. If Equinox sues Stirrup for damages and seeks to introduce evidence of the alleged oral agreement, the court probably will', 'admit the evidence as to both the saddle and the option to choose a brown horse.', 'admit the evidence as to the saddle but not the option to choose a brown horse.', 'admit the evidence as to the option to choose a brown horse but not the promise to include the saddle.', 'not admit any of the evidence.', 'B', 'the parol evidence rule precludes admission of prior or contemporaneous oral statements that vary or contradict the terms of a written contract which is clear, unambiguous and fully integrated. Ungerleider v. Gordon, 214 F.3d 1279 (11th Cir. 2000)(Emphasis added).9 Course of performance is not parol evidence because although extrinsic to the contract “it identifies the parties'' post-agreement conduct rather than their actions prior or contemporaneous to contract formation.” Kinesoft Dev. Corp. v. Softbank Holdings Inc., 139 F.Supp.2d 869, 890 n.9 (N.D. Ill. 2001) (citing E. Allen Farnsworth, Farnsworth on Contracts, § 7.3, at 228 (2d ed.1998)).', 'mbe_554', 0, '160'),
('mbe_712', 'mbe', '712', '496', '1991-Feb', 'CONTRACTS', '161', '', 'Testator, whose nephew Bypast was his only heir, died leaving a will that gave his entire estate to charity. Bypast, knowing full well that Testator was of sound mind all of his life, and having no evidence to the contrary, nevertheless filed a suit contesting Testator''s will on the ground that Testator was incompetent when the will was signed. Craven, Testator''s executor, offered Bypast $5,000 to settle the suit, and Bypast agreed. If Craven then repudiates the agreement and the foregoing facts are proved or admitted in Bypast''s suit against Craven for breach of contract, is Bypast entitled to recover under the prevailing view?', 'Yes, because the Bypast-Craven agreement was a bargained-for exchange.', 'Yes, because the law encourages the settlement of disputed claims.', 'No, because Bypast did not bring the will contest in good faith.', 'No, because an agreement to oust the court of its jurisdiction to decide a will contest is contrary to public policy.', 'C', '"In the context of a will caveat, [u]ndue influence is a fraudulent influence over the mind and will of another to the extent that the professed action is not freely done but is in truth the act of the one who procures the result.
In re Estate of Loftin, 285 N.C. 717, 722, 208 S.E.2d 670, 674–75 (1974)."', 'mbe_555', 0, '161'),
('mbe_713', 'mbe', '713', '497', '1991-Feb', 'EVIDENCE', '162', '', 'Parker sues Dix for breach of a promise made in a letter allegedly written by Dix to Parker. Dix denies writing the letter. Which of the following would NOT be a sufficient basis for admitting the letter into evidence?', 'Testimony by Parker that she is familiar with Dix''s signature and recognizes it on the letter.', 'Comparison by the trier of fact of the letter with an admitted signature of Dix.', 'Opinion testimony of a nonexpert witness based upon familiarity acquired in order to authenticate the signature.', 'Evidence that the letter was written in response to one written by Parker to Dix.', 'C', '“It is undisputed that where an issue is raised regarding the authenticity of a writing, proof of authenticity may be made by a comparison of the disputed writing with another writing, an exemplar, the authenticity of which has been established ... The authenticity of the exemplar may be proved by circumstantial evidence ... In general, a writing may be authenticated by a number of methods, including direct testimony, circumstantial evidence or proof of custody.” (Citations omitted; internal quotation marks omitted.) American Heritage Agency, Inc. v. Gelinas, 62 Conn.App. 711, 720, 774 A.2d 220, cert. denied, 257 Conn. 903, 777 A.2d 192 (2001); Tyler v. Todd, 36 Conn. 218, 222 (1869) (“[I]n this state we allow the disputed signature to be compared with signatures admitted or proved to be genuine. The triers may compare and judge for themselves, and experts may, upon comparison, give their opinions. But the signature used as a standard of comparison must not only be genuine, but must be admitted or proved to be such before it can be used”). “[A]nyone familiar with the signature in question may testify as to its authenticity.” Webster Bank v. Flanagan, 51 Conn.App. 733, 738, 725 A.2d 975 (1999).  “A writing may be authenticated by identifying the signature contained in the document ... A signature can be authenticated by a signatory to the document by acknowledgment. A signature can additionally be proved by a witness to the execution of the document or by a witness who is familiar with the signature in question and attests that it is genuine.” (Citations omitted.) Id., at 737. Therefore, while an expert may offer her opinion as to the authenticity of a signature at issue, an expert is not required for the trier of fact to determine whether a signature is forged.', 'mbe_556', 0, '162'),
('mbe_714', 'mbe', '714', '498', '1991-Feb', 'CONTRACTS', '163', 'Green contracted in a signed writing to sell Greenacre, a 500-acre tract of farmland, to Farmer. The contract provided for exchange of the deed and purchase price of $500,000 in cash on January 15. Possession was to be given to Farmer on the same date. On January 15, Green notified Farmer that because the tenant on Greenacre wrongfully refused to quit the premises until January 30, Green would be unable to deliver possession of Greenacre until then, but he assured Farmer that he would tender the deed and possession on that date. When Green tendered the deed and possession on January 30, Farmer refused to accept either, and refused to pay the $500,000. Throughout the month of January, the market value of Greenacre was $510,000, and its fair monthly rental value was $5,000.', 'Will Green probably succeed in an action against Farmer for specific performance?', 'Yes, because the court will excuse the delay in tender on the ground that there was a temporary impossibility caused by the tenant''s holding over.', 'Yes, because time is ordinarily not of the essence in a land-sale contract.', 'No, because Green breached by failing to tender the deed and possession on January 15.', 'No, because Green''s remedy at law for monetary relief is adequate.', 'B', 'Unless a contract expressly states so, or unless there is otherwise shown to be a clear indication of intent, time is not ordinarily considered to be of the essence in the performance of a contract. Gault v. Branton, 222 Miss. 111, 75 So.2d 439, 445 (1954); Lee v. Schneider, 822 So.2d 311, 314 (Miss.Ct.App.2002). We note that in order for equity to regard contracts as “of the essence,” one of two conditions must be satisfied.  In the absence of either condition, time will not ordinarily be considered of the essence in contract performance.', 'mbe_2676', 0, '163'),
('mbe_715', 'mbe', '715', '498', '1991-Feb', 'CONTRACTS', '164', 'Green contracted in a signed writing to sell Greenacre, a 500-acre tract of farmland, to Farmer. The contract provided for exchange of the deed and purchase price of $500,000 in cash on January 15. Possession was to be given to Farmer on the same date. On January 15, Green notified Farmer that because the tenant on Greenacre wrongfully refused to quit the premises until January 30, Green would be unable to deliver possession of Greenacre until then, but he assured Farmer that he would tender the deed and possession on that date. When Green tendered the deed and possession on January 30, Farmer refused to accept either, and refused to pay the $500,000. Throughout the month of January, the market value of Greenacre was $510,000, and its fair monthly rental value was $5,000.', 'For this question only, make the following assumptions. On January 30, Farmer accepted a conveyance and possession of Greenacre and paid the $500,000 purchase price, but notified Green that he was reserving any rights he might have to damages caused by Green''s breach. Farmer intended to use the land for raising cattle and had entered into a contract for the purchase of 500 head of cattle to be delivered to Greenacre on January 15. Because he did not have possession of Greenacre on that date, he had to rent another pasture at a cost of $2,000 to graze the cattle for 15 days. Green had no reason to know that Farmer intended to use Greenacre for raising cattle or that he was purchasing cattle to be grazed on Greenacre. In an action by Farmer against Green for damages, Farmer is entitled to recover', 'nothing, because by paying the purchase price on January 30, he waived whatever cause of action he may have had.', 'nominal damages only, because the market value of the land exceeded the contract price.', '$2,500 only (the fair rental value of Greenacre for 15 days).', '$2,500 (the fair rental value of Greenacre for 15 days), plus $2,000 (the cost of grazing the cattle elsewhere for 15 days).', 'C', 'The ideal would be for us to forge a hard and fast rule alerting litigants that, in all situations in which a settlement agreement is silent as to the date of performance, a “reasonable time” for the completion of one''s settlement obligations is “x” number of days. However, it is not that simple. If the terms of the settlement at hand are fairly routine, it may be that only 7 to 10 days are needed for all terms of the agreement to be accomplished. If the details of the agreement are more complex, more time may be required. Unfortunately, there is no way we can fashion a one-size-fits-all “reasonable time” period that takes into account every variable or contingency a settlement agreement may incorporate. As this Court stated in Walters v. Getter (1988), 232 Mont. 196, 200, 755 P.2d 574, 576–77 (citing Henderson v. Daniels (1922), 62 Mont. 363, 373–74, 205 P. 964, 967): “ ‘Reasonable time’ is defined to be so much time as is necessary, under the circumstances, to do conveniently what the contract or duty requires should be done in a particular case.” Further, “When the facts are clearly established or are admitted or undisputed, the question of what is a reasonable time is one of law.” Walters, 232 Mont. at 200, 755 P.2d at 577. Such is the case here.', 'mbe_2677', 0, '164'),
('mbe_716', 'mbe', '716', '499', '1991-Feb', 'REAL PROP.', '165', '', 'Able, owner of Blackacre and Whiteacre, two adjoining parcels, conveyed Whiteacre to Baker and covenanted in the deed to Baker that when he, Able, sold Blackacre he would impose restrictive covenants to prohibit uses that would compete with the filling station that Baker intended to construct and operate on Whiteacre. The deed was not recorded. Baker constructed and operated a filling station on Whiteacre and then conveyed Whiteacre to Dodd, who continued the filling station use. The deed did not refer to the restrictive covenant and was promptly and properly recorded. Able then conveyed Blackacre to Egan, who knew about Able''s covenant with Baker to impose a covenant prohibiting the filling station use but nonetheless completed the transaction when he noted that no such covenant was contained in Able''s deed to him. Egan began to construct a filling station on Blackacre. Dodd brought an appropriate action to enjoin Egan from using Blackacre for filling station purposes. If Dodd prevails, it will be because', 'Egan had actual knowledge of the covenant to impose restrictions.', 'Egan is bound by the covenant because of the doctrine of negative reciprocal covenants.', 'business-related restrictive covenants are favored in the law.', 'Egan has constructive notice of the possibility of the covenant resulting from the circumstances.', 'A', 'Applying the above analyses to the case at bar, we conclude that both the trial court and the appeals court used a constructive notice rather than an actual knowledge test in denying Multicon the protection afforded by the provisions of R.C. 5301.25(A). Therefore, we remand this case to the trial court to apply an actual knowledge test.
An unrecorded land use restriction is not enforceable against a bona fide purchaser for value unless the purchaser has actual knowledge of the restriction. Although actual knowledge in some instances may be inferred, it may not be imputed to the purchaser on the basis of mere familiarity with the land use restriction recorded in another county, or on the basis of awareness of the bare existence of the document containing the restrictions.', 'mbe_557', 0, '165'),
('mbe_717', 'mbe', '717', '500', '1991-Feb', 'TORTS', '166', '', 'While walking on a public sidewalk, Anson was struck by a piece of lumber that fell from the roof of Bruce''s house. Bruce had hired Chase to make repairs to his roof, and the lumber fell through negligence on Chase''s part. If Anson brings an action against Bruce to recover damages for the injury caused to him by Chase''s negligence, will Anson prevail?', 'Yes, under the res ipsa loquitur doctrine.', 'Yes, if Chase''s act was a breach of a nondelegable duty owed by Bruce to Anson.', 'No, if Chase was an independent contractor rather than Bruce''s servant.', 'No, if Bruce exercised reasonable care in hiring Chase to do the repair work.', 'B', 'A principal can be held vicariously liable for the acts of an independent contractor if “[it] is negligent in selecting, instructing or supervising the independent contractor; where the independent contractor is hired to do work which is ‘inherently dangerous''; and where the [principal] bears a specific, non-delegable duty” (Saini, 299 A.D.2d at 245, 750 N.Y.S.2d 55). None of these exceptions is applicable to this case.', 'mbe_558', 0, '166'),
('mbe_718', 'mbe', '718', '501', '1991-Feb', 'REAL PROP.', '167', '', 'Owen contracted to sell Vacantacre to Perry. The written contract required Owen to provide evidence of marketable title of record, specified a closing date, stated that "time is of the essence," and provided that at closing, Owen would convey by warranty deed. Perry paid Owen $2,000 earnest money toward the $40,000 purchase price. The title evidence showed that an undivided one-eighth interest in Vacantacre was owned by Alice. Perry immediately objected to title and said he would not close on Owen''s title. Owen responded, accurately, that Alice was his daughter who would be trekking in Nepal until two weeks after the specified closing date. He said that she would gladly deed her interest upon her return, and that meanwhile his deed warranting title to all of Vacantacre would fully protect Perry. Owen duly tendered his deed but Perry refused to close. Perry brought an appropriate action to recover the $2,000 earnest money promptly after the specified closing date. Owen counterclaimed for specific performance, tendering a deed from himself and Alice, who had by then returned. The court will hold for', 'Owen, because Alice''s deed completing the transfer was given within a reasonable time.', 'Owen, because his warranty deed would have given Perry adequate interim protection.', 'Perry, because Owen''s title was not marketable and time was of the essence.', 'Perry, because under the circumstances the earnest money amount was excessive.', 'C', 'Or stated another way, “marketable title” is a title which is free from encumbrances and any reasonable doubt as to its validity, and such as a reasonably intelligent person, who is well informed as to the facts and their legal bearings, and ready and willing to perform his contract, would be willing to accept in the exercise of ordinary business prudence. Accordingly[,] a marketable title must be so far free from defects as to enable the purchaser not only to hold the land in peace but also, if he wishes to sell it, to be reasonably sure that no flaw will appear to disturb its market value. However, a title, in order to be marketable, need not be free from every conceivable technical criticism, but only from those possibilities of defect which are sufficient to raise a reasonable doubt. Sinclair v. Weber, 204 Md. 324, 334, 104 A.2d 561 (1954).', 'mbe_559', 0, '167'),
('mbe_719', 'mbe', '719', '502', '1991-Feb', 'CRIM. LAW', '168', '', 'A statute provides: A person commits the crime of rape if he has sexual intercourse with a female, not his wife, without her consent. Dunbar is charged with the rape of Sally. At trial, Sally testifies to facts sufficient for a jury to find that Dunbar had sexual intercourse with her, that she did not consent, and that the two were not married. Dunbar testifies in his own defense that he believed that Sally had consented to sexual intercourse and that she was his common-law wife. At the conclusion of the case, the court instructed the jury that in order to find Dunbar guilty of rape, it must find beyond a reasonable doubt that he had sexual intercourse with Sally without her consent. The court also instructed the jury that it should find the defendant not guilty if it found either that Sally was Dunbar''s wife or that Dunbar reasonably believed that Sally had consented to the sexual intercourse, but that the burden of persuasion as to these issues was on the defendant. The jury found Dunbar guilty, and Dunbar appealed, contending that the court''s instructions on the issues of whether Sally was his wife and whether he reasonably believed she had consented violated his constitutional rights. Dunbar''s constitutional rights were', 'violated by the instructions as to both issues.', 'violated by the instruction as to whether Sally was his wife, but not violated by the instruction on belief as to consent.', 'violated by the instruction on belief as to consent, but not violated by the instruction as to whether Sally was his wife.', 'not violated by either part of the instructions.', 'B', 'The due process clause of the fourteenth amendment to the United States Constitution requires the prosecution to prove beyond a reasonable doubt every fact necessary to constitute the crime charged. Sandstrom v. Montana, supra 442 U.S. at 520, 99 S.Ct. at 2457; Patterson v. New York, supra 432 U.S. at 206–07, 97 S.Ct. at 2324–25; In re Winship, supra, 397 U.S. at 364, 90 S.Ct. at 1072.', 'mbe_560', 0, '168'),
('mbe_72', 'mbe', '72', '45', 'MBE-1972-78-part3', '', '23', 'Price sued Derrick for injuries Price received in an automobile accident. Price claimed Derrick was negligent in (a) exceeding the posted speed limit of 35 m.p.h., (b) failing to keep a lookout, and (c) crossing the center line.', 'Derrick testified in his own behalf that he was going 30 m.p.h. On cross-examination, Price''s counsel did not question Derrick with regard to his speed. Subsequently, Price''s counsel calls Officer to testify that, in his investigation following the accident, Derrick told him he was driving 40 m.p.h. Officer''s testimony is', 'admissible as a prior inconsistent statement', 'admissible as an admission', 'inadmissible, because it lacks a foundation', 'inadmissible, because it is hearsay not within any exception', 'B', 'A statement by a party-opponent is an admission and admissible as an exception to the hearsay rule if it meets the following requirements: (1) a conscious or voluntary acknowledgment by a party-opponent of the existence of certain facts; (2) the matter acknowledged must be relevant to the cause of the party offering the admission; and (3) the matter acknowledged must be unfavorable to, or inconsistent with, the position now taken by the party-opponent. Nettie''s Flower Garden, Inc. v. SIS, Inc., 869 S.W.2d 226, 229 (Mo.App. E.D.1993).', 'mbe_169', 0, '23'),
('mbe_720', 'mbe', '720', '503', '1991-Feb', 'TORTS', '169', '', 'Star, who played the lead role in a television soap opera, was seriously injured in an automobile accident caused by Danton''s negligent driving. As a consequence of Star''s injury, the television series was canceled, and Penn, a supporting actor, was laid off. In an action against Danton, can Penn recover for his loss of income attributable to the accident?', 'Yes, because Danton''s negligence was the cause in fact of Penn''s loss.', 'Yes, unless Penn failed to take reasonable measures to mitigate his loss.', 'No, unless Danton should have foreseen that by injuring Star he would cause harm to Penn.', 'No, because Danton''s liability does not extend to economic loss to Penn that arises solely from physical harm to Star.', 'D', 'The drafters of the Restatement (Third) explain that the “legal cause” test articulated in the second Restatement included both the “substantial factor” prong and the “rule of law” prong because it was intended to address both factual and proximate cause. Id. ch. 6 Special Note on Proximate Cause, at 574. Although the “substantial factor” requirement has frequently been understood to apply to proximate cause determinations, see Gerst, 549 N.W.2d at 815–16, the drafters contend it was never intended to do so. Restatement (Third) § 29 cmt. a, at 576.3 Accordingly, to eliminate the resulting confusion of factual and policy determinations resulting from the Restatement (Second) formulation of legal cause, the drafters have opted to address factual cause and scope of liability (proximate cause) separately. Restatement (Third) ch. 6 Special Note on Proximate Cause, at 575. The assessment of scope of liability under the Restatement (Third) no longer includes a determination of whether the actor''s conduct was a substantial factor in causing the harm at issue, a question properly addressed under the *838 factual cause rubric. See id. § 27 cmt. j, at 427–29.4
Most importantly, the drafters of the Restatement (Third) have clarified the essential role of policy considerations in the determination of the scope of liability. “An actor''s liability is limited to those physical harms that result from the risks that made the actor''s conduct tortious.” Id. § 29, at 575.  This principle, referred to as the “risk standard,” is intended to prevent the unjustified imposition of liability by “confining liability''s scope to the reasons for holding the actor liable in the first place.” Id. § 29 cmt. d, at 579–80. As an example of the standard''s application, the drafters provide an illustration of a hunter returning from the field and handing his loaded shotgun to a child as he enters the house. Id. cmt. d, illus. 3, at 581. The child drops the gun (an object assumed for the purposes of the illustration to be neither too heavy nor unwieldy for a child of that age and size to handle) which lands on her foot and breaks her toe. Id. Applying the risk standard described above, the hunter would not be liable for the broken toe because the risk that made his action negligent was the risk that the child would shoot someone, not that she would drop the gun and sustain an injury to her foot. Id.
The scope-of-liability issue is fact-intensive as it requires consideration of the risks that made the actor''s conduct tortious and a determination of whether the harm at issue is a result of any of those risks. Id. § 29 cmt. d, at 580, 584. When, as in this case, the court considers in advance of trial whether the plaintiff''s harm is beyond the scope of liability as a matter of law, courts must initially consider all of the range of harms risked by the defendant''s conduct that the jury could find as the basis for determining [the defendant''s] conduct tortious. Then, the court can compare the plaintiff''s harm with the range of harms risked by the defendant to determine whether a reasonable jury might find the former among the latter.
Id. at 580.', 'mbe_561', 0, '169'),
('mbe_721', 'mbe', '721', '504', '1991-Feb', 'CONTRACTS', '170', '', 'On December 1, Broker contracted with Collecta to sell her one of a certain type of rare coin for $12,000, delivery and payment to occur on the next March 1. To fulfill that contract, and without Collecta''s knowledge, Broker contracted on January 1 to purchase for $10,000 a specimen of that type coin from Hoarder, delivery and payment to occur on February 1. The market price of such coins had unexpectedly fallen to $8,000 by February 1, when Hoarder tendered the coin and Broker repudiated. On February 25, the market in such coins suddenly reversed and had stabilized at $12,000 on March 1. Broker, however, had failed to obtain a specimen of the coin and repudiated his agreement with Collecta when she tendered the $12,000 agreed price on March 1. Later that day, after learning by chance of Broker''s dealing with Collecta, Hoarder telephoned Collecta and said: "Listen, Broker probably owes me at least $2,000 in damages for refusing wrongfully to buy my coin for $10,000 on February 1 when the market was down to $8,000. But I''m in good shape in view of the market''s recovery since then, and I think you ought to get after the so-and-so." If Collecta immediately sues Broker for his breach of the Broker-Hoarder contract, which of the following will the court probably decide?', 'Broker wins, because Collecta, if a beneficiary at all of the Broker-Hoarder contract, was only an incidental beneficiary.', 'Broker wins, because as of March 1 neither Hoarder nor Collecta had sustained any damage from Broker''s repudiation of both contracts.', 'Collecta wins, because she was an intended beneficiary of the BrokerHoarder contract, under which damages for Broker''s repudiation became fixed on February 1.', 'Collecta wins, because she took an effective assignment of Hoarder''s claim for damages against Broker when Hoarder suggested that Collecta "get after the so-and-so."', 'A', 'An incidental beneficiary is one “who will be benefited by performance *931 of a promise but who is neither a promisee nor an intended beneficiary.” Only donee and creditor beneficiaries have enforceable rights under a contract.', 'mbe_562', 0, '170'),
('mbe_722', 'mbe', '722', '505', '1991-Feb', 'EVIDENCE', '171', '', 'In a prosecution of Dale for murdering Vera, Dale testified that the killing had occurred in self defense when Vera tried to shoot him. In rebuttal, the prosecution seeks to call Walter, Vera''s father, to testify that the day before the killing, Vera told Walter that she loved Dale so much she could never hurt him. Walter''s testimony is', 'admissible within the hearsay exception for statements of the declarant''s then existing state of mind.', 'admissible, because Vera is unavailable as a witness.', 'inadmissible as hearsay not within any exception.', 'inadmissible, because Vera''s character is not an issue.', 'A', 'A statement of the declarant''s then-existing state of mind (such as motive, intent or plan) or emotional, sensory, or physical condition (such as mental feeling, pain, or bodily health), but not including a statement of memory or belief to prove the fact remembered or believed unless it relates to the validity or terms of the declarant''s will.
Pa.R.E. 803(3). “Pursuant to the state of mind hearsay exception, where a declarant''s out-of-court statements demonstrate her state of mind, are made in a natural manner, and are material and relevant, they are admissible pursuant to the exception.” Laich, 777 A.2d at 1060-61. Axiomatically, and by its unambiguous terms, the exception renders admissible only those statements that reflect the “declarant''s then-existing state of mind ... or condition,” Pa.R.E. 803(3), not someone else''s state of mind or condition. Nothing in the plain terms of the exception would allow, for instance, a party to introduce an out-of-court statement of one person to prove the intent, motive, feelings, pain, or health of another person. The bounds of the exception are limited to the then-existing state of mind of the declarant only.', 'mbe_2386', 0, '171'),
('mbe_723', 'mbe', '723', '506', '1991-Feb', 'CONTRACTS', '172', '', 'For an agreed price of $20 million, Bildko, Inc., contracted with Venture to design and build on Venture''s commercial plot a 15-story office building. In excavating for the foundation and underground utilities, Bildko encountered a massive layer of granite at a depth of 15 feet. By reasonable safety criteria, the building''s foundation required a minimum excavation of 25 feet. When the contract was made, neither Venture nor Bildko was aware of the subsurface granite, for the presence of which neither party had hired a qualified expert to test. Claiming accurately that removal of enough granite to permit the construction as planned would cost him an additional $3 million and a probable net loss on the contract of $2 million, Bildko refused to proceed with the work unless Venture would promise to pay an additional $2.5 million for the completed building. If Venture refuses and sues Bildko for breach of contract, which of the following will the court probably decide?', 'Bildko is excused under the modem doctrine of supervening impossibility, which includes severe impracticability.', 'Bildko is excused, because the contract is voidable on account of the parties'' mutual mistake concerning an essential underlying fact.', 'Venture prevails, because Bildko assumed the risk of encountering subsurface granite that was unknown to Venture.', 'Venture prevails, unless subsurface granite was previously unknown anywhere in the vicinity of Venture''s construction site.', 'C', 'To prove assumption of risk, a defendant must show “1) that the plaintiff had actual or constructive knowledge of the existence of the specific risk involved; 2) that the plaintiff appreciated the risk''s character; and 3) that the plaintiff voluntarily *776 accepted the risk, having had the time, knowledge, and experience to make an intelligent choice.” Carpenter v. City of Belle Fourche, 609 N.W.2d 751, 764 (S.D.2000) (quoting S.D. Pattern Jury Instruction 13–01).', 'mbe_2678', 0, '172'),
('mbe_724', 'mbe', '724', '507', '1991-Feb', 'REAL PROP.', '173', '', 'Owen owned Greenacre in fee simple. The small house on Greenacre was occupied, with Owen''s oral permission, rent-free, by Able, Owen''s son, and Baker, a college classmate of Able. Able was then 21 years old. Owen, by properly executed instrument, conveyed Greenacre to "my beloved son, Able, his heirs and assigns, upon the condition precedent that he earn a college degree by the time he reaches the age of 30. If, for any reason, he does not meet this condition, then Greenacre shall become the sole property of my beloved daughter, Anna, her heirs and assigns." At the time of the conveyance, Able and Baker attended a college located several blocks from Greenacre. Neither had earned a college degree. One week after the delivery of the deed to Able, Able recorded the deed and immediately told Baker that he, Able, was going to begin charging Baker rent since "I am now your landlord." There is no applicable statute. Able and Baker did not reach agreement, and Able served the appropriate notice to terminate whatever tenancy Baker had. Able then sought, in an appropriate action, to oust Baker. Who should prevail?', 'Able, because the conveyance created a fee simple subject to divestment in Able.', 'Able, because Owen''s conveyance terminated Baker''s tenancy.', 'Baker, because Owen''s permission to occupy preceded Owen''s conveyance to Able.', 'Baker, because Baker is a tenant of Owen, not of Able.', 'D', 'A joint tenancy is an estate that two or more individuals hold jointly with equal rights. In re Estate of Alpert, 95 Ill.2d 377, 381, 69 Ill.Dec. 361, 447 N.E.2d 796 (1983). With joint tenancy comes the right of survivorship, which entitles the last surviving joint tenant to take the entire estate. Harms v. Sprague, 105 Ill.2d 215, 224, 85 Ill.Dec. 331, 473 N.E.2d 930 (1984). A joint tenancy can be severed when one tenant voluntarily or involuntarily destroys one of the four unities (interest, time, title, and possession) that are crucial to the creation and continuance of a joint tenancy. Harms, 105 Ill.2d at 220, 85 Ill.Dec. 331, 473 N.E.2d 930.', 'mbe_563', 0, '173'),
('mbe_725', 'mbe', '725', '508', '1991-Feb', 'REAL PROP.', '174', '', 'Owens owned Whiteacre, a dwelling house situated on a two-acre lot in an area zoned for single-family residential uses only. Although it was not discernible from the outside, Whiteacre had been converted by Owens from a single-family house to a structure that contained three separate apartments, in violation of the zoning ordinance. Further, the conversion was in violation of the building code. Owens and Peters entered into a valid written contract for the purchase and sale of Whiteacre. The contract provided that Owens was to convey to Peters a marketable title. The contract was silent as to zoning. Peters had fully inspected Whiteacre. Prior to the closing, Peters learned that Whiteacre did not conform to the zoning ordinance and refused to close although Owens was ready, willing, and able to perform his contract obligations. Owens brought an appropriate action for specific performance against Peters. In that action, Owens should', 'win, because Owens was able to convey a marketable title.', 'win, because Peters was charged with knowledge of the zoning ordinance prior to entering the contract.', 'lose, because the illegal conversion of Whiteacre creates the risk of litigation.', 'lose, because the illegal conversion of Whiteacre was done by Owens rather than by a predecessor.', 'C', 'Unrefuted evidence in the record establishes the long-standing acquiescence and involvement of plaintiff landlord and its predecessors-in-interest in the illegal conversion of the commercial loft space in the subject building, including defendant tenant''s leasehold space. The building''s certificate of occupancy did not permit residential use, and the local zoning laws restricted area property development to commercial and light manufacturing uses. While there was an exception in the zoning laws that permitted combined living-working arrangements for qualified artists, the record is devoid of evidence or substantive argument indicating that such artists resided in the building. Under the circumstances obtaining, the landlord had no claim *488 against defendant tenant for use and occupancy (see e.g. Hornfeld v. Gaare, 130 A.D.2d 398, 515 N.Y.S.2d 258 [1987] ); its sole recourse was to eject the tenant (see id.; and see 99 Commercial St., Inc. v. Llewellyn, 240 A.D.2d 481, 483, 658 N.Y.S.2d 130 [1997], lv. denied 90 N.Y.2d 809, 664 N.Y.S.2d 271, 686 N.E.2d 1366 [1997] ). Here, however, the tenant had voluntarily vacated, rendering the landlord''s causes of action seeking possession of the leased space moot. While plaintiff contends that it may recover use and occupancy to the extent that the leased space was used for commercial purposes, there is **32 no evidence that the space was used for other than residential purposes.', 'mbe_564', 0, '174'),
('mbe_726', 'mbe', '726', '509', '1991-Feb', 'CRIM. LAW', '175', 'Morten was the general manager and chief executive officer of the Woolen Company, a knitting mill. Morten delegated all operational decision making to Crouse, the supervising manager of the mill. The child labor laws in the jurisdiction provide, "It is a violation of the law for one to employ a person under the age of 17 years for full-time labor." Without Morten''s knowledge, Crouse hired a number of 15- and 16-year-olds to work at the mill full time. He did not ask their ages and they did not disclose them. Crouse could have discovered their ages easily by asking for identification, but he did not do so because he was not aware of the law and believed that company policy was to hire young people.', 'If the statute is interpreted to create strict liability and Crouse is charged with violating it, Crouse is', 'guilty, because he should have inquired as to the ages of the children.', 'guilty, because he hired the children.', 'not guilty, because in law the Woolen Company, not Crouse, is the employer of the children.', 'not guilty, because he believed he was following company policy and was not aware of the violation.', 'B', 'A strict liability crime is “[a]n offense for which the action alone is enough to warrant a conviction, with no need to prove a mental state; specif[ically] a crime that does not require a mens rea element, such as traffic offenses....” Crime, Strict-Liability Crime, Black''s Law Dictionary (10th ed. 2014).', 'mbe_2679', 0, '175'),
('mbe_727', 'mbe', '727', '509', '1991-Feb', 'CRIM. LAW', '176', 'Morten was the general manager and chief executive officer of the Woolen Company, a knitting mill. Morten delegated all operational decision making to Crouse, the supervising manager of the mill. The child labor laws in the jurisdiction provide, "It is a violation of the law for one to employ a person under the age of 17 years for full-time labor." Without Morten''s knowledge, Crouse hired a number of 15- and 16-year-olds to work at the mill full time. He did not ask their ages and they did not disclose them. Crouse could have discovered their ages easily by asking for identification, but he did not do so because he was not aware of the law and believed that company policy was to hire young people.', 'If the statute is interpreted to create strict liability and Morten is convicted of violating it, his contention that his conviction would violate the federal Constitution is', 'correct, because it is a violation of due process to punish without a voluntary act.', 'correct, because criminal liability is personal and the Woolen Company is the employer of the children, not Morten.', 'incorrect, because regulatory offenses are not subject to due process limitations.', 'incorrect, because he was in a position to exercise control over the hiring of employees for Woolen Company.', 'D', 'Principals are strictly liable for their agents'' acts—even if the agents are not employees—if the principals authorize or ratify the acts or even just create an appearance that the acts are authorized.', 'mbe_2680', 0, '176'),
('mbe_728', 'mbe', '728', '510', '1991-Feb', 'TORTS', '177', '', 'Ann''s three-year-old daughter, Janet, was killed in an automobile accident. At Ann''s direction, Janet''s body was taken to a mausoleum for interment. Normally, the mausoleum''s vaults are permanently sealed with marble plates secured by "tamper-proof'' screws. After Janet''s body was placed in the mausoleum, however, only a fiberglass panel secured by caulking compound covered her vault. About a month later, Janet''s body was discovered in a cemetery located near the mausoleum. It had apparently been left there by vandals who had taken it from the mausoleum. As a result of this experience, Ann suffered great emotional distress. If Ann sues the mausoleum for the damages arising from her emotional distress, will she prevail?', 'No, because Ann experienced no threat to her own safety.', 'No, unless the mausoleum''s behavior was extreme and outrageous.', 'Yes, if the mausoleum failed to use reasonable care to safeguard the body.', 'Yes, unless Ann suffered no physical harm as a consequence of her emotional distress.', 'C', 'Ordinarily, there is no duty to control the conduct of a third person by preventing him or her from causing harm to another, except in cases where there exists a special relationship between the actor and the third person which gives rise to a duty to control, or between the actor and another which gives the other the right to protection.1 See Littleton v. Good Samaritan Hospital & Health Center (1988), 39 Ohio St.3d 86, 92, 529 N.E.2d 449, 455; Gelbman v. Second Natl. Bank of Warren (1984), 9 Ohio St.3d 77, 78, 9 OBR 280, 281, 458 N.E.2d 1262, 1263; Cleveland, Cincinnati, Chicago & St. Louis Ry. Co. v. Potter (1925), 113 Ohio St. 591, 150 N.E. 44; Restatement of the Law 2d, Torts (1965) 122, Section 315. Thus, liability in negligence will not lie in the absence of a special duty owed by a particular defendant. Hill v. Sonitrol of Southwestern *174 Ohio, Inc. (1988), 36 Ohio St.3d 36, 38, 521 N.E.2d 780, 782; Gelbman, supra; see, also, Feldman v. Howard, supra, at 193, 39 O.O.2d at 230, 226 N.E.2d at 567; Kauffman v. First–Central Trust Co. (1949), 151 Ohio St. 298, 306, 39 O.O. 137, 141, 85 N.E.2d 796, 800; Baier v. Cleveland Ry. Co. (1937), 132 Ohio St. 388, 391, 8 O.O. 208, 209, 8 N.E.2d 1, 2.
We have found that “[t]he existence of a duty depends on the foreseeability of the injury. * * * ” Menifee v. Ohio Welding Products, Inc., supra, at 77, 15 OBR at 180, 472 N.E.2d at 710, citing Ford Motor Co. v. Tomlinson (C.A. 6, 1956), 229 F.2d 873, 59 O.O. 345; Gedeon v. East Ohio Gas Co. (1934), 128 Ohio St. 335, 190 N.E. 924; **773 see, also, Hill v. Sonitrol of Southwestern Ohio, Inc., supra. The court in Menifee, supra, set forth the following test to be used in order to determine foreseeability: “[W]hether a reasonably prudent person would have anticipated that an injury was likely to result from the performance or nonperformance of an act.” Menifee, supra, at 77, 15 OBR at 180, 472 N.E.2d at 710, citing Freeman v. United States (C.A. 6, 1975), 509 F.2d 626; Thompson v. Ohio Fuel Gas Co. (1967), 9 Ohio St.2d 116, 38 O.O.2d 294, 224 N.E.2d 131; Mudrich v. Standard Oil Co. (1950), 153 Ohio St. 31, 41 O.O. 117, 90 N.E.2d 859. We recognize that there is no common-law duty to anticipate or foresee criminal activity.2 Prosser & Keeton, Law of Torts (5 Ed.1979) 201–203, Section 33; see, also, Tarasoff v. Regents of the Univ. of Cal. (1976), 17 Cal.3d 425, 131 Cal.Rptr. 14, 551 P.2d 334 (explaining the role of special relationships, and that, absent such special relationship, a defendant has no duty to control the conduct of third persons for the benefit of others). Thus, the law usually does not require the prudent person to expect the criminal activity of others. As a result, the duty to protect against injury caused by third parties, which may be imposed where a special relationship exists, is expressed as an exception to the general rule of no liability. See Note, Negligence Liability for the Criminal Acts of Another (1982), 15 J. Mar. L.Rev. 459, 465.', 'mbe_565', 0, '177'),
('mbe_729', 'mbe', '729', '511', '1991-Feb', 'CONTRACTS', '178', '', 'Wastrel, a notorious spendthrift who was usually broke for that reason, received the following letter from his Uncle Bullion, a wealthy and prudent man: "I understand you''re in financial difficulties again. I promise to give you $5,000 on your birthday next month, but you''d better use it wisely or you''ll never get another dime from me." Wastrel thereupon signed a contract with a car dealer to purchase a $40,000 automobile and to make a $5,000 down payment on the day after his birthday. If Wastrel sues Bullion for $5,000 after the latter learned of the car-purchase contract and then repudiated his promise, which of the following is Bullion''s best defense?', 'A promise to make a gift in the future is not enforceable.', 'Reliance by the promisee on a promise to make a future gift does not make the promise enforceable unless the value of the promised gift is substantially equivalent to the promisee''s loss by reliance.', 'Reliance by the promisee on a promise to make a future gift does not make the promise enforceable unless that reliance also results in an economic benefit to the promisor.', 'Reliance by the promisee on a promise to make a future gift does not make the promise enforceable unless injustice can be avoided only by such enforcement.', 'D', 'Plaintiffs have claims of fraud and promissory estoppel remaining in this action. To prove fraud under Idaho law, Plaintiffs must prove the following nine elements:
(1) A representation; (2) its falsity; (3) its materiality; (4) the speaker''s knowledge about its falsity or ignorance of its truth; (5) his intent that it should be acted upon by the person and in the manner reasonably contemplated; (6) the hearer''s ignorance of its falsity; (7) his reliance on the [representation]; (8) his right to rely thereon; (9) his consequent and proximate injury.
MWI Veterinary Supply Co. v. Wotton, 2012 WL 2576205, at *2 (D. Idaho July 3, 2012). To prove promissory estoppel, Plaintiffs must prove that “(1) one party''s reliance on a promise [created] a substantial economic detriment, (2) the reliance was or should have been foreseeable, and (3) the reliance was reasonable and justified.” Profits Plus Capital Mgmt. LLC v. Podesta, 156 Idaho 873, 891, 332 P.3d 785, 803 (2014) (citation and quotation marks omitted).', 'mbe_566', 0, '178'),
('mbe_73', 'mbe', '73', '46', 'MBE-1972-78-part3', '', '24', 'In City of State Y, Maple Street is a local public thoroughfare, designated as a one-way street for northbound traffic. Pine Street is a public thoroughfare, designated is a One-way street for eastbound traffic. Maple and Pine Streets intersect at right angles. The intersection is controlled by traffic lights. There are two sets of lights, one at the northeast corner and one at the northwest corner, for traffic on Maple Street. There are two sets of lights, one at the northeast corner and one at the southeast corner, for traffic on Pine Street. Trucker was making a delivery to a market on the east side of Maple Street, just north of its intersection with Pine Street. There being insufficient space for his truck and enclosed trailer, he parked it with the rear of the trailer extending entirely across the crosswalk on the north side of the intersection. The height of the trailer was such that it entirely obscured the traffic light on the northeast corner from the vie" of traffic moving east on Pine Street. Unknown to Trucker, the traffic light at the southeast corner was not functioning, because a collision seventy-two hours earlier had knocked down the pole from which the light was suspended. Visitor, on his first trip to City, w as driving east on Pine Street. Not seeing any traffic light or pole, he entered the intersection at a time when the light was red for eastbound traffic and green for northbound traffic. Driver, proceeding north on Maple Street and seeing the green light, entered the intersection without looking for any cross traffic and struck Visitor''s car. Driver received personal injuries, and Visitor''s car was damaged severely as a result of the impact. Statutes of State Y make it a misdemeanor (1) to park a motor vehicle so that any part projects into a crosswalk and (2) to enter an intersection contrary to a traffic signal.', 'If Driver asserts a claim against Trucker and establishes that Trucker was negligent, the likely result is that Trucker'',s negligence is', 'a legal but not actual cause of Driver''s injuries', 'an actual but not a legal cause of Driver''s nju e e', 'both an actual and a legal cause of Driver''s injuries', 'neither an actual nor a legal cause of Driver''s injuries', 'C', '“Legal cause is established if an injury was foreseeable as the type of harm that a reasonable person would expect to see as a likely result of his or her conduct. [Citation.] Although the foreseeability of an injury will establish legal cause, the extent of the injury or the exact way in which it occurs need not be foreseeable.” Hooper v. County of Cook, 366 Ill.App.3d 1, 7, 303 Ill.Dec. 476, 851 N.E.2d 663, 669 (2006).', 'mbe_58', 0, '24'),
('mbe_730', 'mbe', '730', '512', '1991-Feb', 'CONST. LAW', '179', '', 'Congress passed a bill prohibiting the President from granting a pardon to any person who had not served at least one-third of the sentence imposed by the court which convicted that person. The President vetoed the bill, claiming that it was unconstitutional. Nevertheless, Congress passed it over his veto by a two-thirds vote of each house. This act of Congress is', 'constitutional, because it was enacted over the President''s veto by a two-thirds vote of each house.', 'constitutional, because it is a necessary and proper means of carrying out the powers of Congress.', 'unconstitutional, because it interferes with the plenary power of the President to grant pardons.', 'unconstitutional, because a Presidential veto based upon constitutional grounds may be overridden only with the concurrence of three-fourths of the state legislatures.', 'C', 'A fair reading of the history of the English pardoning power, from which our Art. II, s 2, cl. 1, derives, of the language of that clause itself, and of the unbroken practice since 1790 compels the conclusion that the power flows from the Constitution alone, not from any legislative enactments, and that it cannot be modified, abridged, or diminished by the Congress.', 'mbe_567', 0, '179'),
('mbe_731', 'mbe', '731', '513', '1991-Feb', 'EVIDENCE', '180', '', 'Defendant is on trial for the crime of obstructing justice by concealing records subpoenaed May 1, in a government investigation. The government calls Attorney to testify that on May 3, Defendant asked him how to comply with the regulations regarding the transfer of records to a safe-deposit box in Mexico. The testimony of Attorney is', 'privileged, because it relates to conduct outside the jurisdiction of the United States.', 'privileged, because an attorney is required to keep the confidences of his clients.', 'not privileged, provided Attorney knew of the concededly illegal purpose for which the advice was sought.', 'not privileged, whether or not Attorney knew of the concededly illegal purpose for which the advice was sought.', 'D', 'This “necessary witness” test allows the attorney to be called as a witness only if the attorney''s testimony is material, unobtainable elsewhere, and the testimony is or may be prejudicial to the testifying attorney''s client.10 PUD, 124 Wash.2d at 812, 881 P.2d 1020; Schmitt, 124 Wash.App. at 666-67, 102 P.3d 856. If the State sought Aralica''s testimony here, the necessary witness test would be directly applicable.', 'mbe_568', 0, '180'),
('mbe_732', 'mbe', '732', '514', '1991-Feb', 'TORTS', '181', '', 'Prad entered Drug Store to make some purchases. As he was searching the aisles for various items, he noticed a display card containing automatic pencils. The display card was on a high shelf behind a cashier''s counter. Prad saw a sign on the counter that read, "No Admittance, Employees Only." Seeing no clerks in the vicinity to help him, Prad went behind the counter to get a pencil. A clerk then appeared behind the counter and asked whether she could help him. He said he just wanted a pencil and that he could reach the display card himself. The clerk said nothing further. While reaching for the display card, Prad stepped sideways into an open shaft and fell to the basement, ten feet below. The clerk knew of the presence of the open shaft, but assumed incorrectly that Prad had noticed it. Prad sued Drug Store to recover damages for the injuries he sustained in the fall. The jurisdiction has adopted a rule of pure comparative negligence, and it follows traditional common-law rules governing the duties of a land possessor. Will Prad recover a judgment against Drug Store?', 'No, because Prad was a trespasser.', 'No, unless Prad''s injuries resulted from the defendant''s willful or wanton misconduct.', 'Yes, because the premises were defective with respect to a public invitee.', 'Yes, if the clerk had reason to believe that Prad was unaware of the open shaft.', 'D', 'In Virginia, a store owner owes its customers a duty to exercise ordinary care towards them when they are visiting the premises.1 Winn–Dixie Stores, Inc. v. Parker, 240 Va. 180, 182, 396 S.E.2d 649, 650 (1990) (citing Colonial Stores v. Pulley, 203 Va. 535, 537, 125 S.E.2d 188, 190 (1962)); see generally Atrium Unit Owners Ass''n v. King, 266 Va. 288, 293, 585 S.E.2d 545, 548 (2003) (stating that in order to establish actionable negligence, Virginia law requires a plaintiff to show “the existence of a legal duty, a breach of the duty, and proximate causation resulting in damage”). Discharging this duty requires a store owner: to have the premises in a reasonably safe condition for [a customer''s] visit; to remove, within a reasonable time, foreign objects from its floors which it may have placed there or which it knew, or should have known, that other persons had placed there; to warn the plaintiff of the unsafe condition if it was unknown to her, but was, or should have been, known to the defendant.
Colonial Stores, 203 Va. at 537, 125 S.E.2d at 190; see also Winn–Dixie, 240 Va. at 182, 396 S.E.2d at 650.', 'mbe_569', 0, '181'),
('mbe_733', 'mbe', '733', '515', '1991-Feb', 'CRIM. LAW', '182', '', 'A statute in the jurisdiction defines murder in the first degree as knowingly killing another person after deliberation. Deliberation is defined as "cool reflection for any length of time no matter how brief." Murder in the second degree is defined as "all other murder at common law except felony-murder." Felony-murder is murder in the third degree. Manslaughter is defined by the common law. At 2 a.m., Duncan held up an all-night liquor store using an assault rifle. During the holdup, two police cars with flashing lights drove up in front of the store. In order to create a situation where the police would hesitate to come into the store (and thus give Duncan a chance to escape out the back) Duncan fired several rounds through the front window of the store. Duncan then ran out the back but upon discovering another police car there, surrendered quietly. One of the shots he fired while in the store struck and killed a burglar who was stealing items from a closed store across the street. The most serious degree of criminal homicide Duncan is guilty of is', 'murder in the first degree.', 'murder in the second degree.', 'murder in the third degree.', 'manslaughter.', 'B', 'Murder, at common law, is “the unlawful killing of a human being by a person with ‘malice aforethought.’ ” Schad v. Arizona, 501 U.S. 624, 640, 111 S.Ct. 2491, 115 L.Ed.2d 555 (1991). In United States v. Marrero, the Third Circuit Court of Appeals reviewed the Model Penal Code, Black''s Law Dictionary, and state laws, and adopted the following contemporary definition of generic murder as “causing the death of another person either intentionally, during the commission of a *393 dangerous felony, or through conduct evincing reckless and depraved indifference to serious dangers posed to human life.” 743 F.3d 389, 401 (3d Cir. 2014), cert. denied, ––– U.S. ––––, 135 S.Ct. 950, 190 L.Ed.2d 843 (2015) abrogation on other grounds recognized by United States v. Calabretta, 831 F.3d 128 (3d Cir. 2016); see also United States v. Castro–Gomez, 792 F.3d 1216, 1216–17 (10th Cir.), cert. denied, ––– U.S. ––––, 136 S.Ct. 492, 193 L.Ed.2d 359 (2015) (citing Marrero''s definition of generic murder). The definition of generic murder adopted by the Third Circuit does not change the elements of common law murder; it identifies theories that supply the mens rea for “malice aforethought.” See e.g. Schad, 501 U.S. at 648, 111 S.Ct. 2491 (Scalia, J., concurring in part and concurring in the judgment) (noting that different theories can supply the mens rea of “malice aforethought,” including “an intention to kill or grievously injure, knowledge that an act or omission would probably cause death or grievous injury, an intention to commit a felony, or an intention to resist lawful arrest”).', 'mbe_570', 0, '182'),
('mbe_734', 'mbe', '734', '516', '1991-Feb', 'EVIDENCE', '183', '', 'Denn is on trial for arson. In its case in chief, the prosecution offers evidence that Denn had secretly obtained duplicate insurance from two companies on the property that burned and that Denn had threatened to kill his ex-wife if she testified for the prosecution. The court should admit evidence of', 'Denn''s obtaining duplicate insurance only.', 'Denn''s threatening to kill his ex-wife only.', 'both Denn''s obtaining duplicate insurance and threatening to kill his ex-wife.', 'neither Denn''s obtaining duplicate insurance nor threatening to kill his ex-wife.', 'C', '“Generally, all relevant evidence is admissible.” Layton v. State, 280 S.W.3d 235, 240 (Tex.Crim.App.2009) (citing Tex. R. Evid. 402). Evidence is relevant if it has “any tendency to make the existence of any fact that is of consequence to the determination of the action more probable or less probable than it would be without the evidence.” Tex. R. Evid. 401 (1998, repealed 2015). This definition is “necessarily a broad one.” Montgomery v. State, 810 S.W.2d 372, 391 (Tex.Crim.App.1990) (op. on reh''g). Even “marginally probative” evidence should be admitted if “it has any tendency at all, even potentially, to make a fact of consequence more or less likely.” Fuller v. State, 829 S.W.2d 191, 198 (Tex.Crim.App.1992).', 'mbe_2387', 0, '183'),
('mbe_735', 'mbe', '735', '517', '1991-Feb', 'TORTS', '184', '', 'In the course of a bank holdup, Robber fired a gun at Guard. Guard drew his revolver and returned the fire. One of the bullets fired by Guard ricocheted, striking Plaintiff. If Plaintiff asserts a claim against Guard based upon battery, will Plaintiff prevail?', 'Yes, unless Plaintiff was Robber''s accomplice.', 'Yes, under the doctrine of transferred intent.', 'No, if Guard fired reasonably in his own defense.', 'No, if Guard did not intend to shoot Plaintiff.', 'C', 'The rule is there stated thus: “A battery is the unlawful touching or striking of a person of another by the aggressor himself or by any substance put in motion by him, done with the intention of bringing about a harmful or offensive contact or apprehension thereof which is not legally consented to by the other and not otherwise privileged.” 4 Am.Jur.Assault and Battery, § 2. (Italics inserted.)', 'mbe_571', 0, '184'),
('mbe_736', 'mbe', '736', '518', '1991-Feb', 'CONTRACTS', '185', 'Mural, a wallpaper hanger, sent Gennybelle, a general contractor, this telegram: Will do all paperhanging on new Doctors'' Building, per owner''s specs, for $14,000 if you accept within reasonable time after main contract awarded. /s/ Mural Three other competing hangers sent Gennybelle similar bids in the respective amounts of $18,000, $19,000, and $20,000. Gennybelle used Mural''s $14,000 figure in preparing and submitting her own sealed bid on Doctors'' Building. Before the bids were opened, Mural truthfully advised Gennybelle that the former''s telegraphic sub-bid had been based on a $4,000 computational error and was therefore revoked. Shortly thereafter, Gennybelle was awarded the Doctors'' Building construction contract and subsequently contracted with another paperhanger for a price of $18,000. Gennybelle now sues Mural to recover $4,000.', 'Which of the following, if proved, would most strengthen Gennybelle''s prospect of recovery?', 'After Mural''s notice of revocation, Gennybelle made a reasonable effort to subcontract with another paperhanger at the lowest possible price.', 'Gennybelle had been required by the owner to submit a bid bond and could not have withdrawn or amended her bid on the main contract without forfeiting that bond.', 'Mural was negligent in erroneously calculating the amount of his sub-bid.', 'Gennybelle dealt with all of her subcontractors in good faith and without seeking to renegotiate (lower) the prices they had bid.', 'B', 'A bid is the equivalent of an offer to buy the property, and no contract is formed until the auctioneer manifests final acceptance of the bid.', 'mbe_2681', 0, '185'),
('mbe_737', 'mbe', '737', '518', '1991-Feb', 'CONTRACTS', '186', 'Mural, a wallpaper hanger, sent Gennybelle, a general contractor, this telegram: Will do all paperhanging on new Doctors'' Building, per owner''s specs, for $14,000 if you accept within reasonable time after main contract awarded. /s/ Mural Three other competing hangers sent Gennybelle similar bids in the respective amounts of $18,000, $19,000, and $20,000. Gennybelle used Mural''s $14,000 figure in preparing and submitting her own sealed bid on Doctors'' Building. Before the bids were opened, Mural truthfully advised Gennybelle that the former''s telegraphic sub-bid had been based on a $4,000 computational error and was therefore revoked. Shortly thereafter, Gennybelle was awarded the Doctors'' Building construction contract and subsequently contracted with another paperhanger for a price of $18,000. Gennybelle now sues Mural to recover $4,000.', 'Which of the following, if proved, would best support Mural''s defense?', 'Gennybelle gave Mural no consideration for an irrevocable sub-bid.', 'Mural''s sub-bid expressly requested Gennybelle''s acceptance after awarding of the main contract.', 'Even after paying $18,000 for the paperhanging, Gennybelle would make a net profit of $100,000 on the Doctors'' Building contract.', 'Before submitting her own bid, Gennybelle had reason to suspect that Mural had made a computational mistake in figuring his sub-bid.', 'D', 'It may be pointed out that, in repudiating its sub-bid by its letter of September 14, 1955, Ahern did not rely upon any alleged infirmity in the school district''s action on the heating and ventilating sub-bids. If this contention, never made until 1957 after the school building was completed, had been advanced in 1955, the school district could perhaps have avoided any risk of improper procedure. Instead, Ahern in its letter merely asserted that it had made an error in computation. The practical effect of Ahern''s repudiation of its bid has been to increase, in an amount exceeding Ahern''s deposit, the school district''s costs in performing a contract which no person entitled to do so has questioned, by forcing employment of the next lowest painting sub-bidder.', 'mbe_2682', 0, '186'),
('mbe_738', 'mbe', '738', '519', '1991-Feb', 'EVIDENCE', '187', '', 'Roberta Monk, a famous author, had a life insurance policy with Drummond Life Insurance Company. Her son, Peter, was beneficiary. Roberta disappeared from her residence in the city of Metropolis two years ago and has not been seen since. On the day that Roberta disappeared, Sky Airlines Flight 22 left Metropolis for Rio de Janeiro and vanished; the plane''s passenger list included a Roberta Rector. Peter is now suing Drummond Life Insurance Company for the proceeds of his mother''s policy. At trial, Peter offers to testify that his mother told him that she planned to write her next novel under the pen name of Roberta Rector. Peter''s testimony is', 'admissible as circumstantial evidence that Roberta Monk was on the plane.', 'admissible as a party admission, because Roberta and Peter Monk are in privity with each other.', 'inadmissible, because Roberta Monk has not been missing more than seven years.', 'inadmissible, because it is hearsay not within any exception.', 'A', 'Circumstantial evidence is evidence that relies on an inference to connect it to a conclusion of fact. Direct evidence, by contrast, supports the truth of a fact without the need for additional evidence or inference. Circumstantial evidence is legal evidence and the jury must consider it when it is sufficient to sustain or negate a party''s burden of proof.1 Circumstantial evidence has probative value equal to that of testimonial direct evidence.
Many forms of circumstantial evidence have a logical tendency to prove or disprove some fact in issue. They may or may not be admissible depending upon considerations of public policy, as well as the relevancy and materiality of the testimony. In the absence of a statute or a valid and binding contractual provision to the contrary, circumstantial evidence is regarded by law as competent to prove any given fact in issue in a civil case and is sometimes as cogent and valuable as direct and positive testimony. Upon the issue of reasonableness of conduct, all the surrounding circumstances become facts material to the case. Circumstantial evidence may be used to establish liability where it negates other reasonable causes for injury.
Tort claims may be established entirely by circumstantial evidence. Similarly, proximate cause may be proved by circumstantial evidence even though there is no eyewitness evidence. The law does not require every fact and circumstance which make up a case of negligence to be proved by direct and positive testimony or by the testimony of eyewitnesses. Negligence and freedom from contributory negligence may be shown by circumstantial, as well as the conditions and circumstances leading up to and surrounding the incident causing the plaintiff''s injury. Similarly, the terms of an oral contract, and the assent of the parties to it, may be shown by the actions of the parties and attending circumstances, as well as by the words they use. In accordance with the rules for the construction of contracts, where a contract is ambiguous on its face, evidence of the surrounding circumstances and the subsequent conduct of the parties in the execution of the contract is admissible to interpret the contract; and the circumstances in which the parties to a contract are placed are generally admissible where such evidence will shed light upon issues in the case. In many instances, facts can be proved only by circumstantial evidence. Such evidence may in fact be the only means of proving intent, knowledge, fraud, or illicit sexual relations.
Circumstantial evidence must do more than raise a suspicion. It must amount to proof. There must be some reasonable connection between the facts proved and the fact at issue. A fact cannot be established by circumstantial evidence where there is direct, uncontradicted, reasonable, and unimpeached evidence that the fact does not exist. In some instances, circumstantial evidence may outweigh or be more satisfactory or convincing than direct or positive testimony. Circumstantial evidence cannot be based on mere speculation, guess, or conjecture; it must justify an inference of probability as distinguished from possibility.
The court is given the discretion to determine when circumstantial evidence should be admitted. This may require the court to evaluate the evidence under Federal Rule of Evidence 403 to determine whether its prejudicial effect substantially outweighs its probative value. One court provided this observation about a court''s discretion to allow circumstantial evidence:
As has been frequently said, great latitude is allowed in the reception of circumstantial evidence, the aid of which is constantly required, and therefore, where direct evidence of the fact is wanting, the more the jury can see of the surrounding facts and circumstances, the more correct their judgment is likely to be. The competency of a collateral fact to be used as the basis of legitimate argument is not to be determined by the conclusiveness of the inferences it may afford in reference to the litigated fact. It is enough if these may tend, even in a slight degree, to elucidate the inquiry, or to assist, though remotely, to a determination probably founded in truth. The modern tendency, both of legislation and of the decision of courts, is to give as wide a scope as possible to the investigation of facts.', 'mbe_2388', 0, '187'),
('mbe_739', 'mbe', '739', '520', '1991-Feb', 'TORTS', '188', '', 'Jones and Smith, who were professional rivals, were attending a computer industry dinner where each was to receive an award for achievement in the field of data processing. Smith engaged Jones in conversation and expressed the opinion that if they joined forces, they could do even better. Jones replied that she would not consider Smith as a business partner and when Smith demanded to know why, told him that he, Smith, was incompetent. The exchange was overheard by Brown, who attended the dinner. Smith suffered emotional distress but no pecuniary loss. If Smith asserts a claim against Jones based on defamation, will Smith prevail?', 'No, because Smith suffered no pecuniary loss.', 'No, because Jones''s statement was made to Smith and not to Brown.', 'No, unless Jones should have foreseen that her statement would be overheard by another person.', 'No, unless Jones intended to cause Smith emotional distress.', 'C', '“To establish a prima facie case of defamation, the plaintiff must demonstrate that: (1) the defendant published a defamatory statement; (2) the defamatory statement identified the plaintiff to a third person; (3) the defamatory statement was published to a third person; and (4) the plaintiff’s reputation suffered injury as a result of the statement.” Gambardella v. Apple Health Care, Inc., 291 Conn. 620, 627 (2009).', 'mbe_572', 0, '188'),
('mbe_74', 'mbe', '74', '46', 'MBE-1972-78-part3', '', '25', 'In City of State Y, Maple Street is a local public thoroughfare, designated as a one-way street for northbound traffic. Pine Street is a public thoroughfare, designated is a One-way street for eastbound traffic. Maple and Pine Streets intersect at right angles. The intersection is controlled by traffic lights. There are two sets of lights, one at the northeast corner and one at the northwest corner, for traffic on Maple Street. There are two sets of lights, one at the northeast corner and one at the southeast corner, for traffic on Pine Street. Trucker was making a delivery to a market on the east side of Maple Street, just north of its intersection with Pine Street. There being insufficient space for his truck and enclosed trailer, he parked it with the rear of the trailer extending entirely across the crosswalk on the north side of the intersection. The height of the trailer was such that it entirely obscured the traffic light on the northeast corner from the vie" of traffic moving east on Pine Street. Unknown to Trucker, the traffic light at the southeast corner was not functioning, because a collision seventy-two hours earlier had knocked down the pole from which the light was suspended. Visitor, on his first trip to City, w as driving east on Pine Street. Not seeing any traffic light or pole, he entered the intersection at a time when the light was red for eastbound traffic and green for northbound traffic. Driver, proceeding north on Maple Street and seeing the green light, entered the intersection without looking for any cross traffic and struck Visitor''s car. Driver received personal injuries, and Visitor''s car was damaged severely as a result of the impact. Statutes of State Y make it a misdemeanor (1) to park a motor vehicle so that any part projects into a crosswalk and (2) to enter an intersection contrary to a traffic signal.', 'If Driver asserts a claim against City, the theory on which he has the best chance of prevailing is that City', 'is strictly liable for harm caused by a defective traffic signal', 'was negligent in not replacing the broken pole within seventy-two hours', 'had an absolute duty to maintain installed traffic signals in good operating order', 'created a dangerous trap by not promptly replacing the broken pole', 'B', 'What is a "Failure to Repair" Lawsuit?
Failure to repair lawsuits involves situation where a person has disregarded their duty to repair or fix dangerous conditions, resulting in injury to another person. These types of lawsuits often involve premises liability issues, where the owner of land or property has failed to repair issues with the property.
However, failure to repair can apply to many different situations, including:
Landlords who have a duty to make repairs for tenants
Operators of business ensuring that the premises are safe for patrons
Operators of rental services (for instance, car rentals, go-kart venues, commercial vehicles, etc.)
A failure to repair dangerous conditions or broken items can result in a variety of different injuries, including:
Slip and fall related injuries
Injuries due to burns, fires, explosions, etc.
Injuries from falling objects
Injuries relating to chemical or toxic exposure
Accidents and collisions in vehicles
Various other injures
Failure to repair dangerous conditions can also result in property damage (for instance, if an object falls on someone’s personal belongings).', 'mbe_59', 0, '25'),
('mbe_740', 'mbe', '740', '521', '1991-Feb', 'REAL PROP.', '189', '', 'Ozzie owned and occupied Blackacre, which was a tract of land improved with a onefamily house. His friend, Victor, orally offered Ozzie $50,000 for Blackacre, the fair market value, and Ozzie accepted. Because they were friends, they saw no need for attorneys or written contracts and shook hands on the deal. Victor paid Ozzie $5,000 down in cash and agreed to pay the balance of $45,000 at an agreed closing time and place. Before the closing, Victor inherited another home and asked Ozzie to return his $5,000. Ozzie refused, and, at the time set for the closing, Ozzie tendered a good deed to Victor and declared his intention to vacate Blackacre the next day. Ozzie demanded that Victor complete the purchase. Victor refused. The fair market value of Blackacre has remained $50,000. In an appropriate action brought by Ozzie against Victor for specific performance, if Ozzie loses, the most likely reason will be that', 'the agreement was oral.', 'keeping the $5,000 is Ozzie''s exclusive remedy.', 'Victor had a valid reason for not closing.', 'Ozzie remained in possession on the day set for the closing.', 'A', 'The subsequent land contract omits the zoning ordinance exception contained in the preliminary purchase agreement.6 The preliminary purchase agreement was merged into, and superseded by, the land contract.7 Even if this were not so, such an exception ought not extend to a situation where as a result of the conveyance called for in the contract of purchase and sale the title would be unmarketable as a result of a zoning law violation which the purchaser would be powerless to remedy. Pomeroy, Specific Performance of Contracts (3d ed.), sec. 450, states that equity will not compel specific performance where a defect in title is substantial and material. Similarily, 4 Pomeroy, Equity Jurisprudence (5th ed.), p. 1051, sec. 1407, states:
‘It is therefore a familiar rule that the vendor cannot force performance upon the purchaser unless he is able to give a good title to the subject matter.’
 Also in 49 Am.Jur., Specific Performance, p. 11, 112, sec. 95, it is said:
‘If the vendor is unable to convey a clear and marketable title * * * specific performance will not be granted.’', 'mbe_2683', 0, '189'),
('mbe_741', 'mbe', '741', '522', '1991-Feb', 'CONST. LAW', '190', '', 'Small retailers located in the state of Yellow are concerned about the loss of business to certain large retailers located nearby in bordering states. In an effort to deal with this concern, the legislature of Yellow enacted a statute requiring all manufacturers and wholesalers who sell goods to retailers in Yellow to do so at prices that are no higher than the lowest prices at which they sell them to retailers in any of the states that border Yellow. Several manufacturers and wholesalers who are located in states bordering Yellow and who sell their goods to retailers in those states and in Yellow bring an action in federal court to challenge the constitutionality of this statute. Which of the following arguments offered by these plaintiffs is likely to be most persuasive in light of applicable precedent? The state statute', 'deprives them of their property or liberty without due process of law.', 'imposes an unreasonable burden on interstate commerce.', 'deprives them of a privilege or immunity of national citizenship.', 'denies them the equal protection of the laws.', 'B', 'Although the criteria for determining the validity of state statutes affecting interstate commerce have been variously stated, the general rule that emerges can be phrased as follows: Where the statute regulates even-handedly to effectuate a legitimate local public interest, and its effects on interstate commerce are only incidental, it will be upheld unless the burden imposed on such commerce is clearly excessive in relation to the putative local benefits. Huron Portland Cement Co. v. City of Detroit, 362 U.S. 440, 443, 80 S.Ct. 813, 816, 4 L.Ed.2d 852.', 'mbe_573', 0, '190'),
('mbe_742', 'mbe', '742', '523', '1991-Feb', 'TORTS', '191', '', 'The Pinners, a retired couple, had lived in their home in a residential neighborhood for 20 years when the Darleys moved into the house next door and built a swimming pool in the back yard. The four young Darley children frequently played in the pool after school. They often were joined by other neighborhood children. The Pinners were in the habit of reading and listening to classical music in the afternoons. Sometimes they took naps. The boisterous sounds of the children playing in the pool disturbed the Pinners'' customary enjoyment of quiet afternoons. In the Pinners'' nuisance action for damages against the Darleys, the Pinners should', 'prevail, if the children''s noise constituted a substantial interference with the Pinners'' use and enjoyment of their home.', 'prevail, because the Pinners'' interest in the quiet enjoyment of their home takes precedence in time over the Darleys'' interests.', 'not prevail, unless the noise constituted a substantial and unreasonable disturbance to persons of normal sensibilities.', 'not prevail, because the children''s interest in healthy play has priority over the Pinners'' interest in peace and quiet.', 'C', 'Nuisance requires an interference with the use and enjoyment of land. See Williams v. Monsanto Corp., 856 S.W.2d 338, 340 (Mo.App.1993).  To prove a nuisance,3 a plaintiff must show that the defendant unreasonably uses his or her property such that it substantially impairs the plaintiff''s right to peacefully use his or her property. Id. at 341. “Whether a use is unreasonable to the point of a nuisance depends on factors such as the locality, character of the neighborhood, nature of use, extent of injury, and effect upon enjoyment of life.” Id. Nuisance law recognizes the inherent conflict between the rights of neighboring property owners, and the unreasonable use element seeks to balance *810 those rights. Peters v. ContiGroup, 292 S.W.3d 380, 385 (Mo.App.2009).', 'mbe_574', 0, '191'),
('mbe_743', 'mbe', '743', '524', '1991-Feb', 'EVIDENCE', '192', '', 'Which of the following items of evidence is LEAST likely to be admitted without a supporting witness?', 'In a libel action, a copy of a newspaper purporting to be published by Defendant Newspaper Publishing Company.', 'In a case involving contaminated food, a can label purporting to identify the canner as Defendant Company.', 'In a defamation case, a document purporting to be a memorandum from the Defendant Company president to "All Personnel," printed on Defendant''s letterhead.', 'In a case involving injury to a pedestrian, a pamphlet on stopping distances issued by the State Highway Department.', 'C', 'In order to be admissible at trial, a document must be authenticated. Generally, authentication requires competent testimony concerning the document. See Fed.R.Evid. 901(b)(1). Certain categories of documents are self-authenticating under Fed.R.Evid. 902, and require no extrinsic testimony. Each document submitted in support of summary judgment must either be properly authenticated, or must be self-authenticating under the Federal Rules. Carmona v. Toledo, 215 F.3d 124, 131 (1st Cir.2000); 10A CHARLES ALAN WRIGHT, ARTHUR R. MILLER & MARY KAY KANE, FEDERAL PRACTICE AND PROCEDURE § 2722 at 382 (3d ed.1998). The *17 authentication requirement is rarely onerous; in many instances, a single sentence will suffice, indicating that the document is what it appears to be.', 'mbe_575', 0, '192'),
('mbe_744', 'mbe', '744', '525', '1991-Feb', 'CONTRACTS', '193', 'For several weeks Mater, a wealthy, unemployed widow, and Nirvana Motors, Inc., negotiated unsuccessfully over the purchase price of a new Mark XX Rolls-Royce sedan, which, as Nirvana knew, Mater wanted her son Dilbert to have as a wedding gift. On April 27, Nirvana sent Mater a signed, dated memo saying, "If we can arrive at the same price within the next week, do we have a deal?" Mater wrote "Yes" and her signature at the bottom of this memo and delivered it back to Nirvana on April 29. On May 1, Mater wrote Nirvana a signed letter offering to buy "one new Mark XX Rolls-Royce sedan, with all available equipment, for $180,000 cash on delivery not later than June 1." By coincidence, Nirvana wrote Mater a signed letter on May 1 offering to sell her "one new Mark XX Rolls-Royce sedan, with all available equipment, for $180,000 cash on delivery not later than June 1." These letters crossed in the mails and were respectively received and read by Mater and Nirvana on May 2.', 'If Mater subsequently asserts and Nirvana denies that the parties had a binding contract on May 3, which of the following most persuasively supports Mater''s position?', 'A sale-of-goods contract may be made in any manner sufficient to show agreement, even though the moment of its making is undetermined.', 'A sale-of-goods contract does not require that an acceptance be a mirror image of the offer.', 'With respect both to the making of an agreement and the requirement of consideration, identical cross-offers are functionally the same as an offer followed by a responsive acceptance.', 'Since Nirvana was a merchant in the transaction and Mater was not, Nirvana is estopped to deny that the parties'' correspondence created a binding contract.', 'A', 'In many cases, as where goods are shipped, accepted and paid for before any dispute arises, there is no question whether a contract has been made. In such cases, where the writings of the parties do not establish a contract, it is not necessary to determine which act or document constituted the offer and which the acceptance.', 'mbe_576', 0, '193'),
('mbe_745', 'mbe', '745', '525', '1991-Feb', 'CONTRACTS', '194', 'For several weeks Mater, a wealthy, unemployed widow, and Nirvana Motors, Inc., negotiated unsuccessfully over the purchase price of a new Mark XX Rolls-Royce sedan, which, as Nirvana knew, Mater wanted her son Dilbert to have as a wedding gift. On April 27, Nirvana sent Mater a signed, dated memo saying, "If we can arrive at the same price within the next week, do we have a deal?" Mater wrote "Yes" and her signature at the bottom of this memo and delivered it back to Nirvana on April 29. On May 1, Mater wrote Nirvana a signed letter offering to buy "one new Mark XX Rolls-Royce sedan, with all available equipment, for $180,000 cash on delivery not later than June 1." By coincidence, Nirvana wrote Mater a signed letter on May 1 offering to sell her "one new Mark XX Rolls-Royce sedan, with all available equipment, for $180,000 cash on delivery not later than June 1." These letters crossed in the mails and were respectively received and read by Mater and Nirvana on May 2.', 'For this question only, assume the following facts. On May 4, Mater and Nirvana Motors both signed a single document evidencing a contract for the sale by Nirvana to Mater, "as a wedding gift for Mater''s son Dilbert," a new Mark XX Rolls-Royce sedan, under the same terms as previously stated in their correspondence. On May 5, Mater handed Dilbert a carbon copy of this document. In reliance on the prospective gift, Dilbert on May 20 sold his nearly new Cheetah (an expensive sports car) to a dealer at a "bargain" price of $50,000 and immediately informed Mater and Nirvana that he had done so. On May 25, however, Mater and Nirvana Motors by mutual agreement rescinded in a signed writing "any and all agreements heretofore made between the undersigned parties for the sale-and-purchase of a new Mark XX Rolls-Royce sedan." Later that day, Nirvana sold for $190,000 cash to another buyer the only new Mark XX Rolls-Royce that it had in stock or could readily obtain elsewhere. On June 1, Dilbert tendered $180,000 in cash to Nirvana Motors and demanded delivery to him "within a reasonable time" of a new Mark XX RollsRoyce sedan with all available equipment. Nirvana rejected the tender and denied any obligation. If Dilbert sues Nirvana for breach of contract, which of the following will the court probably decide?', 'Dilbert wins, because his rights as an assignee for value of the May 4 MaterNirvana contract cannot be cut off by agreement between the original parties.', 'Dilbert wins, because his rights as a third-party intended beneficiary became vested by his prejudicial reliance in selling his Cheetah on May 20.', 'Nirvana wins, because Dilbert, if an intended beneficiary at all of the MaterNirvana contract, was only a donee beneficiary.', 'Nirvana wins, because it reasonably and prejudicially relied on its contract of mutual rescission with Mater by selling the only readily available new Mark XX Rolls-Royce sedan to another buyer.', 'B', 'With respect to the merits of Seneca''s assertion, “[a third] party asserting rights as a third-party beneficiary must establish ‘(1) the existence of a valid and binding contract between other parties, (2) that the contract was intended for [the third party''s] benefit and (3) that the benefit to [the third party] is sufficiently immediate, rather than incidental, to indicate the assumption by the contracting parties of a duty to compensate [the third party] if the benefit is lost’ ” (State of Cal. Pub. Employees’ Retirement Sys. v. Shearman & Sterling, 95 N.Y.2d 427, 434-435, 718 N.Y.S.2d 256, 741 N.E.2d 101 [2000], quoting Burns Jackson Miller Summit & Spitzer v. Lindner, 59 N.Y.2d 314, 336, 464 N.Y.S.2d 712, 451 N.E.2d 459 [1983]; see DeLine v. CitiCapital Commercial Corp., 24 A.D.3d 1309, 1311, 807 N.Y.S.2d 247 [4th Dept. 2005]). A third party is “an intended beneficiary, rather than merely an incidental beneficiary, when the circumstances indicate that the promisee intends to give the beneficiary the benefit of the promised performance” (DeLine, 24 A.D.3d at 1311, 807 N.Y.S.2d 247 [internal quotation marks omitted]).', 'mbe_577', 0, '194'),
('mbe_746', 'mbe', '746', '526', '1991-Feb', 'CONST. LAW', '195', '', 'A federally owned and operated office building in the state of West Dakota is heated with a new, pollution-free heating system. However, in the coldest season of the year, this new system is sometimes insufficient to supply adequate heat to the building. The appropriation statute providing the money for construction of the new heating system permitted use of the old, pollution-generating system when necessary to supply additional heat. When the old heating system operates (only about two days in any year), the smokestack of the building emits smoke that exceeds the state of West Dakota''s pollutioncontrol standards. May the operators of the federal office building be prosecuted successfully by West Dakota authorities for violating that state''s pollution control standards?', 'Yes, because the regulation of pollution is a legitimate state police power concern.', 'Yes, because the regulation of pollution is a joint concern of the federal government and the state and, therefore, both of them may regulate conduct causing pollution.', 'No, because the operations of the federal government are immune from state regulation in the absence of federal consent.', 'No, because the violations of the state pollution-control standards involved here are so de minimis that they are beyond the legitimate reach of state law.', 'C', 'Under the Supremacy Clause, “the activities of the Federal Government are free from regulation by any state.”13 Accordingly, state laws are invalid if they “regulate[ ] the United States directly or discriminate [ ] against the Federal Government or those with whom it deals.”', 'mbe_578', 0, '195'),
('mbe_747', 'mbe', '747', '527', '1991-Feb', 'TORTS', '196', '', 'Jones, who was driving his car at night, stopped the car and went into a nearby tavern for a drink. He left the car standing at the side of the road, projecting three feet into the traffic lane. The lights were on and his friend, Peters, was asleep in the back seat. Peters awoke, discovered the situation, and went back to sleep. Before Jones returned, his car was hit by an automobile approaching from the rear and driven by Davis. Peters was injured. Peters sued Davis and Jones jointly to recover the damages he suffered resulting from the accident. The jurisdiction has a pure comparative negligence rule and has abolished the defense of assumption of risk. In respect to other issues, the rules of the common law remain in effect. Peters should recover', 'nothing, if Peters was more negligent than either Davis or Jones.', 'nothing, unless the total of Davis''s and Jones''s negligence was greater than Peters''s.', 'from Davis and Jones, jointly and severally, the amount of damages Peters suffered reduced by the percentage of the total negligence that is attributed to Peters.', 'from Davis and Jones, severally, a percentage of Peters''s damages equal to the percentage of fault attributed to each of the defendants.', 'C', 'Mississippi follows the “comparative negligence doctrine,” which measures negligence “in terms of percentage, and any damages allowed shall be diminished in proportion to amount of negligence attributable to the person for whose injury, damage or death recovery is sought.” Meka, 67 So.3d at 23 (¶ 15) (citations omitted).', 'mbe_2684', 0, '196'),
('mbe_748', 'mbe', '748', '528', '1991-Feb', 'EVIDENCE', '197', '', 'Under the rule allowing exclusion of relevant evidence because its probative value is substantially outweighed by other considerations, which of the following is NOT to be considered?', 'The jury may be confused about the appropriate application of the evidence to the issues of the case.', 'The evidence is likely to arouse unfair prejudice on the part of the jury.', 'The opponent is surprised by the evidence and not fairly prepared to meet it.', 'The trial will be extended and made cumbersome by hearing evidence of relatively trivial consequence.', 'C', 'The court may exclude relevant evidence if its probative value is substantially outweighed by a danger of one or more of the following: unfair prejudice, confusing the issues, misleading the jury, undue delay, wasting time, or needlessly presenting cumulative evidence.', 'mbe_579', 0, '197'),
('mbe_749', 'mbe', '749', '529', '1991-Feb', 'CONTRACTS', '198', '', 'On June 1, Buyem, Inc., a widget manufacturer, entered into a written agreement with Mako, Inc., a tool maker, in which Mako agreed to produce and sell to Buyem 12 sets of newly designed dies to be delivered August 1 for the price of $50,000, payable ten days after delivery. Encountering unexpected expenses in the purchase of special alloy steel required for the dies, Mako advised Buyem that production costs would exceed the contract price; and on July 1 Buyem and Mako signed a modification to the June 1 agreement increasing the contract price to $60,000. After timely receipt of 12 sets of dies conforming to the contract specifications, Buyem paid Mako $50,000 but refused to pay more. Which of the following concepts of the Uniform Commercial Code, dealing expressly with the sale of goods, best supports an action by Mako to recover $10,000 for breach of Buyem''s July 1 promise?', 'Bargained-for exchange.', 'Promissory estoppel.', 'Modification of contracts without consideration.', 'Unconscionability in the formation of contracts.', 'C', '“A modification of a contract is a change in the obligations of a party by a subsequent mutual agreement of the parties.” (West v. JPMorgan Chase Bank, N.A., supra, 214 Cal.App.4th at p. 798, 154 Cal.Rptr.3d 285.) The language in the contract, as modified, must be interpreted as a whole and in the circumstances of the case; it cannot be found ambiguous in the abstract. (Producers Dairy Delivery Co. v. Sentry Ins. Co. (1986) 41 Cal.3d 903, 916, fn. 7, 226 Cal.Rptr. 558, 718 P.2d 920.) “The proper interpretation of a contract is disputable if the contract is susceptible of more than one reasonable interpretation, that is, if the contract is ambiguous. An ambiguity may appear on the face of a contract, or extrinsic evidence may reveal a latent ambiguity.” (Fremont Indemnity Co. v. Fremont General Corp. (2007) 148 Cal.App.4th 97, 114, 55 Cal.Rptr.3d 621.) As our Supreme Court made clear in Pacific Gas & E. Co., however, “[a] court cannot determine based on only the four corners of a document, without provisionally considering any extrinsic evidence offered by the parties, that the meaning of the document is clear and unambiguous.” (Fremont Indemnity Co., at p. 114, 55 Cal.Rptr.3d 621 [discussing Pacific Gas & E. Co. v. G. W. Thomas Drayage etc. Co. (1968) 69 Cal.2d 33, 37, 69 Cal.Rptr. 561, 442 P.2d 641].)', 'mbe_580', 0, '198'),
('mbe_75', 'mbe', '75', '47', 'MBE-1972-78-part3', '', '26', 'Congress provides by statute that any state that fails to prohibit automobile speeds of over 55 miles per hour on highways within the state shall be denied all federal highway construction funding. The state of Atlantic, one of the richest and most highway-oriented states in the country, refuses to enact such a statute.', 'Which of the following potential plaintiffs is most likely to be able to obtain a judicial determination of the validity of this federal statute?', 'A taxpayer of the United States and the state of Atlantic who wants his state to get its fair share of federal tax monies for highways, and fears that, if it does not, his state taxes will be increased to pay for the highway construction in the state of Atlantic that federal funds would have financed.', 'Contractors who have been awarded contracts by the state of Atlantic for specified highway construction projects, which contracts are contingent on payment to the state of the federal highway construction funds to which it would otherwise be entitled.', 'An automobile owner who lives in the state of Atlantic and regularly uses its highway system', 'An organization dedicated to keeping the federal government within the powers granted it by the Constitution', 'B', 'This court has long held that to invoke the Uniform Declaratory Judgments Act, chapter 7.24 RCW (UDJA), a plaintiff must establish:
“(1) ... an actual, present and existing dispute, or the mature seeds of one, as distinguished from a possible, dormant, hypothetical, speculative, or moot disagreement, (2) between parties having genuine and opposing interests, (3) which involves interests that must be direct and substantial, rather than potential, theoretical, abstract or academic, and (4) a judicial determination of which will be final and conclusive.”
Id. quoting Diversified Indus. Dev. Corp. v. Ripley, 82 Wash.2d 811, 815, 514 P.2d 137 (1973).', 'mbe_60', 0, '26'),
('mbe_750', 'mbe', '750', '530', '1991-Feb', 'REAL PROP.', '200', '', 'Twenty years ago, Test, who owned Blackacre, a one-acre tract of land, duly delivered a deed of Blackacre "to School District so long as it is used for school purposes." The deed was promptly and properly recorded. Five years ago, Test died leaving Sonny as his only heir but, by his duly probated will, he left "all my Estate to my friend Fanny." Last month, School District closed its school on Blackacre and for valid consideration duly executed and delivered a quitclaim deed of Blackacre to Owner, who planned to use the land for commercial development. Owner has now brought an appropriate action to quiet title against Sonny, Fanny, and School District. The only applicable statute is a provision in the jurisdiction''s probate code which provides that any property interest which is descendible is devisable. In such action, the court should find that title is now in', 'Owner.', 'Sonny.', 'Fanny.', 'School District.', 'C', '“A quiet title action ‘is a suit brought to quiet an existing title against an adverse or hostile claim of another and the effect of a decree quieting title is not to vest title but rather is to perfect an existing title as against other claimants.’ ” Haynes Land & Livestock Co. v. Jacob Family Chalk Creek, LLC, 2010 UT App 112, ¶ 19, 233 P.3d 529 (quoting Nolan v. Hoopiiaina (In re Malualani B. Hoopiiaina Trust), 2006 UT 53, ¶ 26, 144 P.3d 1129). “To succeed in an action to quiet title to real estate, a plaintiff must prevail on the strength of his own claim to title and not on the weakness of a defendant''s title or even its total lack of title.” Church v. Meadow Springs Ranch Corp., 659 P.2d 1045, 1048–49 (Utah 1983).', 'mbe_581', 0, '200'),
('mbe_751', 'mbe', '751', '531', '1991-July', 'REAL PROP.', '1', '', 'By warranty deed, Marta conveyed Blackacre to Beth and Christine "as joint tenants with right of survivorship." Beth and Christine are not related. Beth conveyed all her interest to Eugenio by warranty deed and subsequently died intestate. Thereafter, Christine conveyed to Darin by warranty deed. There is no applicable statute, and the jurisdiction recognizes the common-law joint tenancy. Title to Blackacre is in', 'Darin.', 'Marta.', 'Darin and Eugenio.', 'Darin and the heirs of Beth.', 'C', 'However, a joint tenant may alienate or convey her interest in the property, and thereby **1218 defeat the right of survivorship. Boissonnault, 137 N.H. at 231, 625 A.2d 454; see also Mulvanity v. Nute, 95 N.H. 526, 528, 68 A.2d 536 (1949).', 'mbe_582', 0, '1'),
('mbe_752', 'mbe', '752', '532', '1991-July', 'TORTS', '2', '', 'Peavey was walking peacefully along a public street when he encountered Dorwin, whom he had never seen before. Without provocation or warning, Dorwin picked up a rock and struck Peavey with it. It was later established that Dorwin was mentally ill and suffered recurrent hallucinations. If Peavey asserts a claim against Dorwin based on battery, which of the following, if supported by evidence, will be Dorwin''s best defense?', 'Dorwin did not understand that his act was wrongful.', 'Dorwin did not desire to cause harm to Peavey.', 'Dorwin did not know that he was striking a person.', 'Dorwin thought Peavey was about to attack him.', 'C', '“The elements of civil battery are: (1) defendant intentionally performed an act that resulted in a harmful or offensive contact with the plaintiff’s person; (2) plaintiff did not consent to the contact; and (3) the harmful or offensive contact caused injury, damage, loss or harm to plaintiff.” Brown v. Ransweiler, 89 Cal. Rptr. 3d 801, 811 (Ct. App. 2009) (citing Piedra v. Dugan, 21 Cal. Rptr. 3d 36, 48 (Ct. App. 2004) ). “A harmful contact, intentionally done is the essence of a battery.” Ashcraft v. King, 278 Cal. Rptr. 900, 903 (Ct App. 1991).', 'mbe_583', 0, '2'),
('mbe_753', 'mbe', '753', '533', '1991-July', 'TORTS', '3', '', 'Penstock owned a large tract of land on the shore of a lake. Drury lived on a stream that ran along one boundary of Penstock''s land and into the lake. At some time in the past, a channel had been cut across Penstock''s land from the stream to the lake at a point some distance from the mouth of the stream. From where Drury lived, the channel served as a convenient shortcut to the lake. Erroneously believing that the channel was a public waterway, Drury made frequent trips through the channel in his motorboat. His use of the channel caused no harm to the land through which it passed. If Penstock asserts a claim for damages against Drury based on trespass, which of the following would be a correct disposition of the case?', 'Judgment for Penstock for nominal damages, because Drury intentionally used the channel.', 'Judgment for Drury, if he did not use the channel after learning of Penstock''s ownership claim.', 'Judgment for Drury, because he caused no harm to Penstock''s land.', 'Judgment for Drury, because when he used the channel he believed it was a public waterway.', 'A', 'The elements for a claim of intentional trespass are: “(1) an invasion affecting an interest in the exclusive possession of property; (2) an intentional doing of the act *401 which results in the invasion; (3) reasonable foreseeability that the act done could result in an invasion of plaintiff''s possessory interest; and (4) substantial damages to the res.” Seal v. Naches–Selah Irrigation Dist., 51 Wash.App. 1, 5, 751 P.2d 873 (1988) (citing Bradley v. Am. Smelting & Refining Co., 104 Wash.2d 677, 691, 709 P.2d 782 (1985)).', 'mbe_2685', 0, '3'),
('mbe_754', 'mbe', '754', '534', '1991-July', 'CONTRACTS', '4', 'Structo contracted with Bailey to construct for $500,000 a warehouse and an access driveway at highway level. Shortly after commencing work on the driveway, which required for the specified level some excavation and removal of surface material, Structo unexpectedly encountered a large mass of solid rock.', 'For this question only, assume the following facts. Structo informed Bailey (accurately) that because of the rock the driveway as specified would cost at least $20,000 more than figured, and demanded for that reason a total contract price of $520,000. Since Bailey was expecting warehousing customers immediately after the agreed completion date, he signed a writing promising to pay the additional $20,000. Following timely completion of the warehouse and driveway, which conformed to the contract in all respects, Bailey refused to pay Structo more than $500,000. What is the maximum amount to which Structo is entitled?', '$500,000, because there was no consideration for Bailey''s promise to pay the additional $20,000.', '$500,000, because Bailey''s promise to pay the additional $20,000 was exacted under duress.', '$520,000, because the modification was fair and was made in the light of circumstances not anticipated by the parties when the original contract was made.', '$520,000, provided that the reasonable value of Structo''s total performance was that much or more.', 'C', 'A contract is not substantively unconscionable unless the terms are grossly unfair under the circumstances that existed when the parties entered into the contract. Myers v. Nebraska Invest. Council, 272 Neb. 669, 724 N.W.2d 776 (2006).', 'mbe_584', 0, '4'),
('mbe_755', 'mbe', '755', '534', '1991-July', 'CONTRACTS', '5', 'Structo contracted with Bailey to construct for $500,000 a warehouse and an access driveway at highway level. Shortly after commencing work on the driveway, which required for the specified level some excavation and removal of surface material, Structo unexpectedly encountered a large mass of solid rock.', 'For this question only, assume the following facts. Upon encountering the rock formation, Structo, instead of incurring additional costs to remove it, built the access driveway over the rock with a steep grade down to the highway. Bailey, who was out of town for several days, was unaware of this nonconformity until the driveway had been finished. As built, it is too steep to be used safely by trucks or cars, particularly in the wet or icy weather frequently occurring in the area. It would cost $30,000 to tear out and rebuild the driveway at highway level. As built, the warehouse, including the driveway, has a fair market value of $550,000. Bailey has paid $470,000 to Structo, but refuses to pay more because of the nonconforming driveway, which Structo has refused to tear out and rebuild. If Structo sues Bailey for monetary relief, what is the maximum amount Structo is entitled to recover?', '$30,000, because the fair market value of the warehouse and driveway "as is" exceeds the contract price by $50,000 (more than the cost of correcting the driveway).', '$30,000, because Structo substantially performed and the cost of correcting the driveway would involve economic waste.', '$30,000, minus whatever amount Structo saved by not building the driveway at the specified level.', 'Nothing, because Bailey is entitled to damages for the cost of correcting the driveway.', 'D', 'The trial court held that the proper measure of damages applicable to the breach of a contract for the sale of real estate is as follows: “[T]he general rule and proper measure of damages available to a vendor as against a breaching vendee in a real estate transaction is that the vendor is entitled to the difference between the contract price and the fair market value of the property at the time of the breach.” Turner v. Benson, 672 S.W.2d 752, 754 (Tenn.1984);1 see also Massey v. Hardcastle, 753 S.W.2d 127, 140 (Tenn.Ct.App.1988); Lane v. Associated Hous. Developers, 767 S.W.2d 640, 644 (Tenn.Ct.App.1988); Yarbrough v. Stiles, 717 S.W.2d 886, 889 (Tenn.Ct.App.1986).', 'mbe_585', 0, '5'),
('mbe_756', 'mbe', '756', '535', '1991-July', 'CRIM. LAW', '6', '', 'Larson was charged with the murder of a man who had been strangled and whose body was found in some woods near his home. Larson suffers from a neurological problem that makes it impossible for him to remember an occurrence for longer than 48 hours. After Larson was charged, the police visited him and asked if they might search his home. Larson consented. The police found a diary written by Larson. An entry dated the same day as the victim''s disappearance read, "Indescribable excitement. Why did no one ever tell me that killing gave such pleasure to the master?" Larson was charged with murder. His attorney has moved to exclude the diary from evidence on the ground that its admission would violate Larson''s privilege against self-incrimination. Counsel has also argued that Larson could not give informed consent to the search because more than 48 hours had passed since the making of the entry and hence he could not remember the existence of the incriminating entry at the time he gave his consent. There is no evidence that the police officers who secured Larson''s consent to the search were aware of his memory impairment. With regard to the diary, the court should', 'admit it, because Larson''s consent was not obtained by intentional police misconduct and Larson was not compelled to make the diary entry.', 'admit it, pursuant to the good-faith exception to the exclusionary rule.', 'exclude it, because Larson was not competent to consent to a search.', 'exclude it, because use of the diary as evidence would violate Larson''s privilege against self-incrimination.', 'A', 'In determining whether exclusion is proper, a court must “evaluate the circumstances of this case in the light of the policy served by the exclusionary rule....” Brown v. Illinois, 422 U.S. 590, 604, 95 S.Ct. 2254, 45 L.Ed.2d 416 (1975). “ ‘The rule is calculated to prevent, not repair. Its purpose is to deter—to compel respect for the constitutional guaranty in the only effectively available way—by removing the incentive to disregard it.... [D]espite its broad deterrent purpose, the exclusionary rule has never been interpreted to proscribe the use of illegally seized evidence in all proceedings or against all persons.’ ” Id. at 599–600, 95 S.Ct. 2254 (citations omitted).
The exclusionary rule has its limitations ... as a tool of judicial control.... [In] some contexts the rule is ineffective as a deterrent.... Proper adjudication of cases in which the exclusionary rule is invoked demands a constant *636 awareness of these limitations.... [A] rigid and unthinking application of the ... rule ... may exact a high toll in human injury and frustration of efforts to prevent crime. [Terry v. Ohio, supra at 13–15, 88 S.Ct. 1868.]
As stated by this Court:
The exclusionary rule forbids the use of direct and indirect evidence acquired from governmental misconduct, such as evidence from an illegal police search.', 'mbe_586', 0, '6'),
('mbe_757', 'mbe', '757', '536', '1991-July', 'EVIDENCE', '7', '', 'In contract litigation between Pixley and Dill, a fact of consequence to the determination of the action is whether Pixley provided Dill with a required notice at Dill''s branch office "in the state capital." Pixley introduced evidence that he gave notice at Dill''s office in the city of Capitan. Although Capitan is the state''s capital, Pixley failed to offer proof of that fact. Which of the following statements is most clearly correct with respect to possible judicial notice of the fact that Capitan is the state''s capital?', 'The court may take judicial notice even though Pixley does not request it.', 'The court may take judicial notice only if Pixley provides the court with an authenticated copy of the statute that designates Capitan as the capital.', 'If the court takes judicial notice, the burden of persuasion on the issue of whether Capitan is the capital shifts to Dill.', 'If the court takes judicial notice, it should instruct the jury that it may, but is not required to, accept as conclusive the fact that Capitan is the capital.', 'A', '“ ‘A court may take judicial notice of the [e]xistence of each document in a court file, but can only take judicial notice of the truth of facts asserted in documents such as orders, findings of fact and conclusions of law, and judgments.’ ” (Day v. Sharp (1975) 50 Cal.App.3d 904, 914, 123 Cal.Rptr. 918, italics omitted; see Evid.Code § 452, subd. (d) [“Records of ... any court of this state” are among the matters that may be judicially noticed].) Because Franklin does not argue that the existence (as opposed to the content) of these briefs is relevant here, we deny his request for judicial notice.', 'mbe_587', 0, '7'),
('mbe_758', 'mbe', '758', '537', '1991-July', 'CONST. LAW', '8', '', 'A statute of the state of East Dakota requires each insurance company that offers burglary insurance policies in the state to charge a uniform rate for such insurance to all of its customers residing within the same county in that state. So long as it complies with this requirement, a company is free to charge whatever rate the market will bear for its burglary insurance policies. An insurance company located in the state of East Dakota files suit in federal district court against appropriate East Dakota state officials to challenge this statute on constitutional grounds. The insurance company wishes to charge customers residing within the same county in East Dakota rates for burglary insurance policies that will vary because they would be based on the specific nature of the customer''s business, on its precise location, and on its past claims record. In this suit, the court should', 'hold the statute unconstitutional, because the statute deprives the insurance company of its liberty or property without due process of law.', 'hold the statute unconstitutional, because the statute imposes an undue burden on interstate commerce.', 'hold the statute constitutional, because the statute is a reasonable exercise of the state''s police power.', 'abstain from ruling on the merits of this case until the state courts have had an opportunity to pass on the constitutionality of this state statute.', 'C', 'For a statute to be a proper exercise of police power, it must (i) be appropriate and reasonably necessary to accomplish a purpose within the scope of the police power and (ii) be reasonable and not arbitrary or unjust in the manner it seeks to accomplish the goal of the statute or so unduly harsh that it is out of proportion to the end sought to be accomplished. See, e.g., Mugler, 123 U.S. at 661, 8 S.Ct. 273; Martin v. Wholesome Dairy, Inc., 437 S.W.2d 586, 591 (Tex.Civ.App.-Austin 1969, writ ref''d n.r.e.); City of Coleman, 222 S.W.2d at 648–49.', 'mbe_588', 0, '8'),
('mbe_759', 'mbe', '759', '538', '1991-July', 'CRIM. LAW', '9', '', 'Dawson was charged with felony murder because of his involvement in a bank robbery. The evidence at trial disclosed that Smith invited Dawson to go for a ride in his new car, and after a while asked Dawson to drive. As Smith and Dawson drove around town, Smith explained to Dawson that he planned to rob the bank and that he needed Dawson to drive the getaway car. Dawson agreed to drive to the bank and to wait outside while Smith went in to rob it. As they approached the bank, Dawson began to regret his agreement to help with the robbery. Once there, Smith got out of the car. As Smith went out of sight inside the bank, Dawson drove away and went home. Inside the bank, Smith killed a bank guard who tried to prevent him from leaving with the money. Smith ran outside and, finding that his car and Dawson were gone, ran down an alley. He was apprehended a few blocks away. Dawson later turned himself in after hearing on the radio that Smith had killed the guard. The jurisdiction has a death penalty that applies to felony murder. Consistent with the law and the Constitution, the jury may convict Dawson of', 'felony murder and impose the death penalty.', 'felony murder but not impose the death penalty.', 'bank robbery only.', 'no crime.', 'B', 'Although the judgments of legislatures, juries, and prosecutors weigh heavily in the balance, it is for us ultimately to judge whether the Eighth Amendment permits imposition of the death penalty on one such as Enmund who aids and abets a felony in the course of which a murder is committed by others but who does not himself kill, attempt to kill, or intend that a killing take place or that lethal force will be employed. We have concluded, along with most legislatures and juries, that it does not.', 'mbe_589', 0, '9'),
('mbe_76', 'mbe', '76', '47', 'MBE-1972-78-part3', '', '27', 'Congress provides by statute that any state that fails to prohibit automobile speeds of over 55 miles per hour on highways within the state shall be denied all federal highway construction funding. The state of Atlantic, one of the richest and most highway-oriented states in the country, refuses to enact such a statute.', 'The strongest argument that can be made in support of the constitutionality of this federal statute is that', 'the states ceded their authority over highways to the national government when the states accepted federal grants to help finance their highways.', 'the federal government can regulate the use of state highways without limitation because the federal government paid for some of their construction costs', 'Congress could reasonably believe that the 55 mile-an-hour speed limit will assure that the federal money spent on highways results in greater benefit than harm to the public', 'a recent public opinion survey demonstrates that 90 per cert of the people in this country support a 55 mile-an-hour speed limit.', 'C', 'The Spending Clause of the Constitution of the United States empowers Congress “[t]o lay and collect Taxes, Duties, Imposts and Excises, to pay the Debts and provide for the common Defence and general Welfare of the United States.” U.S. Const., art. I, § 8, cl. 1. “The Clause provides Congress broad discretion to tax and spend for the ‘general Welfare,’ including by funding particular state or private programs or activities.” Agency for Int''l Dev. v. All. for Open Soc''y Int''l, Inc., 570 U.S. 205, ––––, 133 S.Ct. 2321, 2327–28, 186 L.Ed.2d 398 (2013). Incident to this power, Congress may “impose limits on the use of such funds to ensure they are used in the manner Congress intends.” Id. at –––, 133 S.Ct. at 2328.', 'mbe_61', 0, '27'),
('mbe_760', 'mbe', '760', '539', '1991-July', 'EVIDENCE', '10', '', 'In an automobile negligence action by Popkin against Dwyer, Juilliard testified for Popkin. Dwyer later called Watts, who testified that Juilliard''s reputation for truthfulness was bad. On cross-examination of Watts, Popkin''s counsel asks, "Isn''t it a fact that when you bought your new car last year, you made a false affidavit to escape paying the sales tax?" This question is', 'proper, because it will indicate Watts''s standard of judgment as to reputation for truthfulness.', 'proper, because it bears on Watts''s credibility.', 'improper, because character cannot be proved by specific instances of conduct.', 'improper, because one cannot impeach an impeaching witness.', 'B', 'Credibility determinations are to be made by the jury. “The courts of this State have long adhered to the cardinal principle that ‘[i]t is within the sole and exclusive province of the jury to determine the credibility of the testimony of a witness.’ ” Rodriguez v. Wal-Mart Stores, 449 N.J. Super. 577, 590, 159 A.3d 914 (App. Div. 2017) (quoting State v. Vandeweaghe, 351 N.J. Super. 467, 481, 799 A.2d 1 (App. Div. 2002), aff''d, 177 N.J. 229, 827 A.2d 1028 (2003) ), certif. granted, 230 N.J. 584, 170 A.3d 351 (2017). “[T]he jury is charged with making credibility determinations based on ordinary experiences of life and common knowledge about human nature, as well as upon observations of the demeanor and character of the witness.” Ibid. (citing State v. Jamerson, 153 N.J. 318, 341, 708 A.2d 1183 (1998) ). For these reasons, courts “do not allow one witness to comment upon the veracity of another witness.” Vandeweaghe, 351 N.J. Super. at 481-82, 799 A.2d 1. “This prohibition applies even if the witness proffered to render such a credibility opinion is an expert.” Rodriguez, 449 N.J. Super. at 591, 159 A.3d 914.', 'mbe_590', 0, '10'),
('mbe_761', 'mbe', '761', '540', '1991-July', 'TORTS', '11', '', 'David built in his backyard a garage that encroached two feet across the property line onto property owned by his neighbor, Prudence. Thereafter, David sold his property to Drake. Prudence was unaware, prior to David''s sale to Drake, of the encroachment of the garage onto her property. When she thereafter learned of the encroachment, she sued David for damages for trespass. In this action, will Prudence prevail?', 'No, unless David was aware of the encroachment when the garage was built.', 'No, because David no longer owns or possesses the garage.', 'Yes, because David knew where the garage was located, whether or not he knew where the property line was.', 'Yes, unless Drake was aware of the encroachment when he purchased the property.', 'C', 'We have defined a trespasser as “one who goes upon the property or premises of another without invitation, express or implied, and does so out of curiosity, or for his own purpose or convenience, and not in the performance of any duty to the owner.” Syl. pt. 1, Huffman v. Appalachian Power Co., 187 W.Va. 1, 415 S.E.2d 145 (1991). As Justice Starcher once noted, “a landowner doesn''t owe a trespasser the time of day.” Self v. Queen, 199 W. Va. 637, 642, 487 S.E.2d 295, 300 (1997) (Starcher, J., concurring). “Reasonable care does not require actions to protect or warn visitors whose coming is not known or reasonably foreseeable. Since trespassers ... are often unforeseeable visitors, the standard of reasonable care under the circumstances will not often result in any new liability.” Dan B. Dobbs, et al., The Law of Torts § 278 (2nd ed. 2015).', 'mbe_591', 0, '11'),
('mbe_762', 'mbe', '762', '541', '1991-July', 'EVIDENCE', '12', '', 'Poole sued Darrel for unlawfully using Poole''s idea for an animal robot as a character in Darrel''s science fiction movie. Darrel admitted that he had received a model of an animal robot from Poole, but he denied that it had any substantial similarity to the movie character. After the model had been returned to Poole, Poole destroyed it. In order for Poole to testify to the appearance of the model, Poole', 'must show that he did not destroy the model in bad faith.', 'must give advance notice of his intent to introduce the oral testimony.', 'must introduce a photograph of the model if one exists.', 'need do none of the above, because the "best evidence rule" applies only to writings, recordings, and photographs.', 'D', 'The best evidence rule provides that, where the contents of a document are to be proved, the party must either produce the original or show a sufficient excuse for its nonproduction.” Commonwealth v. Ocasio, 434 Mass. 1, 6, 746 N.E.2d 469 (2001). See Mass. G. Evid. § 1002.', 'mbe_592', 0, '12'),
('mbe_763', 'mbe', '763', '542', '1991-July', 'REAL PROP.', '13', '', 'Lanny, the owner of Whiteacre in fee simple, leased Whiteacre to Teri for a term of ten years by properly executed written instrument. The lease was promptly and properly recorded. It contained an option for Teri to purchase Whiteacre by tendering $250,000 as purchase price any time "during the term of this lease." One year later, Teri, by a properly executed written instrument, purported to assign the option to Oscar, expressly retaining all of the remaining term of the lease. The instrument of assignment was promptly and properly recorded. Two years later, Lanny contracted to sell Whiteacre to Jones and to convey a marketable title "subject to the rights of Teri under her lease." Jones refused to close because of the outstanding option assigned to Oscar. Lanny brought an appropriate action against Jones for specific performance. If judgment is rendered in favor of Lanny, it will be because the relevant jurisdiction has adopted a rule on a key issue as to which various state courts have split. Which of the following identifies the determinative rule or doctrine upon which the split occurs, and states the position favorable to Lanny?', 'In a contract to buy, any form of "subject to a lease" clause that fails to mention expressly an existing option means that the seller is agreeing to sell free and clear of any option originally included in the lease.', 'Marketable title can be conveyed so long as any outstanding option not mentioned in the purchase contract has not yet been exercised.', 'Options to purchase by lessees are subject to the Rule Against Perpetuities.', 'Options to purchase contained in a lease cannot be assigned separately from the lease.', 'D', '“ ‘An option in a lease, which gives the lessee the right to purchase the leased premises at any time before the expiration of the lease, is a continuing offer to sell on the terms set forth in the option, and may not be withdrawn by the lessor within the time limited. The lease is a sufficient consideration to support specific performance of the option to purchase granted therein.’ ” Reynolds v. Earley, 241 N.C. 521, 526, 85 S.E.2d 904, 907–08 (1955) (quoting Crotts v. Thomas, 226 N.C. 385, 387, 38 S.E.2d 158, 159 (1946)). It follows from this rule that termination of the lease terminates the option to purchase, but, where the lease is still in effect, the option to purchase is still valid. Indeed, the lease in the instant case indicates that the option is valid “during the term of the lease.” Thus, we must determine whether the lease was still valid when plaintiff attempted to exercise his option to purchase by letter dated 24 April 1998.', 'mbe_593', 0, '13'),
('mbe_764', 'mbe', '764', '543', '1991-July', 'TORTS', '14', '', 'Daniel and a group of his friends are fanatical basketball fans who regularly meet at each others'' homes to watch basketball games on television. Some of the group are fans of team A, and others are fans of team B. When the group has watched televised games between these two teams, fights sometimes have broken out among the group. Despite this fact, Daniel invited the group to his home to watch a championship game between teams A and B. During the game, Daniel''s guests became rowdy and antagonistic. Fearing that they would begin to fight, and that a fight would damage his possessions, Daniel asked his guests to leave. They refused to go and soon began to fight. Daniel called the police, and Officer was sent to Daniel''s home. Officer sustained a broken nose in his efforts to stop the fighting. Officer brought an action against Daniel alleging that Daniel was negligent in inviting the group to his house to watch this championship game. Daniel has moved to dismiss the complaint. The best argument in support of this motion would be that', 'a rescuer injured while attempting to avert a danger cannot recover damages from the endangered person.', 'a police officer is not entitled to a recovery based upon the negligent conduct that created the need for the officer''s professional intervention.', 'as a matter of law, Daniel''s conduct was not the proximate cause of Officer''s injury.', 'Daniel did not owe Officer a duty to use reasonable care, because Officer was a mere licensee on Daniel''s property.', 'B', 'The firefighter''s rule bars a police officer or firefighter from asserting a cause of action to recover damages for common-law negligence “where the performance of the police officer''s or firefighter''s duties increased the risk of the injury happening, and did not merely furnish the occasion for the injury” (Zanghi v. Niagara Frontier Transp. Commn., 85 N.Y.2d 423, 439, 626 N.Y.S.2d 23, 649 N.E.2d 1167; Byrnes v. City of New York, 249 A.D.2d 352, 671 N.Y.S.2d 483). *499 Recovery for damages for common-law negligence is precluded “where some act taken in furtherance of a specific police or firefighting function exposed the officer to a heightened risk of sustaining the particular injury” (Zanghi v. Niagara Frontier Transp. Commn., supra, at 439, 626 N.Y.S.2d 23, 649 N.E.2d 1167; Byrnes v. City of New York, supra, at 352, 671 N.Y.S.2d 483). Here, the plaintiff, who was a New York City Police Officer, was issuing a parking citation to an illegally-parked car when she fell because of a defect in a sidewalk. Common-law recovery is barred since the injury occurred while she was performing an act taken in “furtherance of a specific police * * * function [which] exposed [her] to a heightened risk of sustaining the particular injury” (Zanghi v. Niagara Frontier Transp. Commn., supra, at 439, 626 N.Y.S.2d 23, 649 N.E.2d 1167; Byrnes v. City of New York, supra, at 353, 671 N.Y.S.2d 483; cf., Olson v. City of New York, 233 A.D.2d 488, 650 N.Y.S.2d 291).', 'mbe_594', 0, '14'),
('mbe_765', 'mbe', '765', '544', '1991-July', 'EVIDENCE', '15', '', 'In a prosecution of Drew for forgery, the defense objects to the testimony of West, a government expert, on the ground of inadequate qualifications. The government seeks to introduce a letter from the expert''s former criminology professor, stating that West is generally acknowledged in his field as well qualified. On the issue of the expert''s qualifications, the letter may be considered by', 'the jury, without regard to the hearsay rule.', 'the judge, without regard to the hearsay rule.', 'neither the judge nor the jury, because it is hearsay not within any exception.', 'both the judge and the jury, because the letter is not offered for a hearsay purpose.', 'B', 'When a matter goes to trial, the specific training and experience of a potential expert witness can be explored on the record so that the trial court may ascertain whether that witness qualifies as an expert in the field at issue. See Rittenhouse v. Hanks, 2001 PA Super 153, 777 A.2d 1113 (2001) (qualification of expert witness at trial rests within the sound discretion of the trial judge). This also provides the jury with a basis on which to determine the expert''s credibility. In the present case, the matter has not yet gone to trial. Therefore, the correct opportunity for the trial court to evaluate fully the training and experience of Dr. Merikangas and Dr. Gramlich has not yet arisen. See Resolution Trust Corp. v. Urban Redevelopment Authority, 536 Pa. 219, 225, 638 A.2d 972, 975 (1994) (credibility of evidence is not a proper consideration at the summary judgment stage).', 'mbe_2686', 0, '15'),
('mbe_766', 'mbe', '766', '545', '1991-July', 'CONTRACTS', '16', 'Responding to County''s written advertisement for bids, Tyres was the successful bidder for the sale of tires to County for County''s vehicles. Tyres and County entered into a signed, written agreement that specified, "It is agreed that Tyres will deliver all tires required by this agreement to County, in accordance with the attached bid form and specifications, for a one-year period beginning September 1, 1990." Attached to the agreement was a copy of the bid form and specifications. In the written advertisement to which Tyres had responded, but not in the bid form, County had stated, "Multiple awards may be issued if they are in the best interests of County." No definite quantity of tires to be bought by County from Tyres was specified in any of these documents. In January 1991, Tyres learned that County was buying some of its tires from one of Tyres''s competitors. Contending that the Tyres-County agreement was a requirements contract, Tyres sued County for the damages caused by County''s buying some of its tires from the competitor.', 'If County defends by offering proof of the advertisement concerning the possibility of multiple awards, should the court admit the evidence?', 'Yes, because the provision in the written agreement, "all tires required by this agreement," is ambiguous.', 'Yes, because the advertisement was in writing.', 'No, because of the parol evidence rule.', 'No, because it would make the contract illusory.', 'A', 'If a contract provision''s meaning is uncertain or is subject to two or more reasonable interpretations after analyzing the language and considering extrinsic evidence (if appropriate), the provision is ambiguous. See Jensen v. Lake Jane Estates, 165 Wash.App. 100, 105, 267 P.3d 435 (2011).', 'mbe_2389', 0, '16'),
('mbe_767', 'mbe', '767', '545', '1991-July', 'CONTRACTS', '17', 'Responding to County''s written advertisement for bids, Tyres was the successful bidder for the sale of tires to County for County''s vehicles. Tyres and County entered into a signed, written agreement that specified, "It is agreed that Tyres will deliver all tires required by this agreement to County, in accordance with the attached bid form and specifications, for a one-year period beginning September 1, 1990." Attached to the agreement was a copy of the bid form and specifications. In the written advertisement to which Tyres had responded, but not in the bid form, County had stated, "Multiple awards may be issued if they are in the best interests of County." No definite quantity of tires to be bought by County from Tyres was specified in any of these documents. In January 1991, Tyres learned that County was buying some of its tires from one of Tyres''s competitors. Contending that the Tyres-County agreement was a requirements contract, Tyres sued County for the damages caused by County''s buying some of its tires from the competitor.', 'If the court concludes that the Tyres-County contract is an agreement by County to buy its tire requirements from Tyres, Tyres probably will', 'recover under the contracts clause of the United States Constitution.', 'recover under the provisions of the Uniform Commercial Code.', 'not recover, because the agreement lacks mutuality of obligation.', 'not recover, because the agreement is indefinite as to quantity.', 'B', 'In analyzing a contract clause claim, a court must consider the following four factors: whether a contractual obligation exists; whether governmental action has impaired that obligation; whether the impairment of the contract is substantial; and whether the government action serves an important public purpose. Kaufman, Litwin & Feinstein v. Edgar, 301 Ill.App.3d 826, 837, 235 Ill.Dec. 183, 704 N.E.2d 756 (1998). The contract clauses notwithstanding, contractual rights remain subject to the police power of the state. Lincoln Towers Insurance Agency, Inc. v. Boozell, 291 Ill.App.3d 965, 968–69, 225 Ill.Dec. 909, 684 N.E.2d 900 (1997). The state always retains the authority to safeguard the interests of its citizens. Sanelli v. Glenview State Bank, 108 Ill.2d 1, 23, 90 Ill.Dec. 908, 483 N.E.2d 226 (1985). Put differently, as Justice Oliver Wendell Holmes once observed: “One whose rights, such as they are, are subject to state restriction, cannot remove them from the power of the State by making a contract about them. The contract will carry with it the infirmity of the subject matter.” Hudson County Water Co. v. McCarter, 209 U.S. 349, 357, 28 S.Ct. 529, 531–32, 52 L.Ed. 828, 832 (1908). Furthermore, the police power “is not limited to health, morals and safety”; rather, it “extends to economic needs as well.” Veix v. Sixth Ward Building & Loan ***561 **1087 Ass''n of Newark, 310 U.S. 32, 38–39, 60 S.Ct. 792, 795, 84 L.Ed. 1061, 1066 (1940).', 'mbe_2390', 0, '17'),
('mbe_768', 'mbe', '768', '546', '1991-July', 'TORTS', '18', '', 'Supermarket is in a section of town where there are sometimes street fights and where pedestrians are occasionally the victims of pickpockets and muggers. In recognition of the unusual number of robberies in the area, the supermarket posted signs in the store and in its parking lot that read: Warning: There are pickpockets and muggers at work in this part of the city. Supermarket is not responsible for the acts of criminals. One evening, Lorner drove to Supermarket to see about a special on turkeys that Supermarket was advertising. She decided that the turkeys were too large and left the store without purchasing anything. In the parking lot, she was attacked by an unknown man who raped her and then ran away. If Lorner sues Supermarket, the result should be for the', 'plaintiff, if Supermarket failed to take reasonable steps to protect customers against criminal attack in its parking lot.', 'plaintiff, because Supermarket is liable for harm to business invitees on its premises.', 'defendant, if the warning signs were plainly visible to Lorner.', 'defendant, because the rapist was the proximate cause of Lorner''s injuries.', 'A', 'In Tennessee, while there is generally no duty for business to protect their customers from crimes occurring on their premises,
a duty to take reasonable steps to protect customers arises if the business knows, or has reason to know, either from what has been or should have been observed or from past experience, that criminal acts against its customers on its premises are reasonably foreseeable, either generally or at some particular time. In determining the duty that exists, the foreseeability of harm and the gravity of harm must be balanced against the commensurate burden imposed on the business to protect against that harm.
McClung v. Delta Square Ltd. P''ship, 937 S.W.2d 891, 902 (Tenn.1996).', 'mbe_2391', 0, '18'),
('mbe_769', 'mbe', '769', '547', '1991-July', 'CRIM. LAW', '19', '', 'Jones wanted to kill Adams because he believed Adams was having an affair with Jones''s wife. Early one morning, armed with a pistol, he crouched behind some bushes on a park hillside overlooking a path upon which Adams frequently jogged. On this morning, however, Jones saw Adams jogging on another path about a half mile away. Nonetheless, Jones fired five shots at Adams. None of the five shots came anywhere close to Adams as he was well out of the range of the pistol Jones was using. Jones is', 'guilty of attempted murder, if he was not aware of the limited range of his pistol.', 'guilty of attempted murder, if a reasonable person would not have been aware of the limited range of his pistol.', 'not guilty of attempted murder, or any lesser included offense, because, under the circumstances, it was impossible for him to have killed Adams.', 'not guilty of attempted murder, but guilty of assault.', 'A', 'The essential elements of attempted murder are that (1) the defendant (2) knowingly or intentionally (3) engaged in conduct that constituted a substantial step (4) toward killing another human being.', 'mbe_595', 0, '19'),
('mbe_77', 'mbe', '77', '47', 'MBE-1972-78-part3', '', '28', 'Congress provides by statute that any state that fails to prohibit automobile speeds of over 55 miles per hour on highways within the state shall be denied all federal highway construction funding. The state of Atlantic, one of the richest and most highway-oriented states in the country, refuses to enact such a statute.', 'The federal statute relating to disbursement of highway funds conditioned on the 55 mile-an-hour speed limit is probably', 'unconstitutional', 'constitutional only on the basis of the spending power', 'constitutional only on the basis of the commerce power', 'constitutional on the basis of both the spending power and the commerce power', 'D', 'The Constitution empowers Congress to “lay and collect Taxes, Duties, Imposts, and Excises, to pay the Debts and provide for the common Defence and general Welfare of the United States.” Art. I, § 8, cl. 1. Incident to this power, Congress may attach conditions on the receipt of **2796 federal funds, and has repeatedly employed the power “to further broad policy objectives by conditioning receipt of federal moneys upon compliance by the recipient with federal statutory and administrative directives.” Fullilove v. Klutznick, 448 U.S. 448, 474, 100 S.Ct. 2758, 2772, 65 L.Ed.2d 902 (1980) (opinion of Burger, C.J.).', 'mbe_62', 0, '28'),
('mbe_770', 'mbe', '770', '548', '1991-July', 'CONST. LAW', '20', '', 'Widgets are manufactured wholly from raw materials mined and processed in the state of Green. The only two manufacturers of widgets in the United States are also located in that state. However, their widgets are purchased by retailers located in every state. The legislature of the state of Green is considering the adoption of a statute that would impose a tax solely on the manufacture of widgets. The tax is to be calculated at 3% of their wholesale value. Which of the following arguments would be LEAST helpful to the state in defending the constitutionality of this proposed state tax on widgets?', 'At the time widgets are manufactured and taxed they have not yet entered the channels of interstate commerce.', 'The economic impact of this tax will be passed on to both in-state and out-ofstate purchasers of widgets and, therefore, it is wholly nondiscriminatory in its effect.', 'Because of the powers reserved to them by the Tenth Amendment, states have plenary authority to construct their tax system in any manner they choose.', 'A tax on the manufacture of widgets may be imposed only by the state in which the manufacturing occurs and, therefore, it is not likely to create the danger of a multiple tax burden on interstate commerce', 'C', 'Where Congress fails to legislate on a matter concerning interstate commerce, the courts recognize “that a dormant implication of the Commerce Clause prohibits state ... regulation ... that discriminates against or unduly burdens interstate commerce and thereby imped[es] free private trade in the national marketplace.” R & M Oil & Supply, Inc. v. Saunders, 307 F.3d 731, 734 (8th Cir.2002) (internal citations and quotations omitted).
*942 A statute may violate the dormant Commerce Clause in one of three ways: (1) the statute clearly discriminates against interstate commerce in favor of in-state commerce, Jones v. Gale, 470 F.3d 1261, 1267 (8th Cir.2006); (2) it imposes a burden on interstate commerce that outweighs any benefits received, Pike v. Bruce Church, Inc., 397 U.S. 137, 142, 90 S.Ct. 844, 25 L.Ed.2d 174 (1970); or (3) it has the practical effect of extraterritorial control of interstate commerce, see Healy v. Beer Inst., 491 U.S. 324, 336, 109 S.Ct. 2491, 105 L.Ed.2d 275 (1989).', 'mbe_596', 0, '20'),
('mbe_771', 'mbe', '771', '549', '1991-July', 'REAL PROP.', '21', '', 'Blackacre is a large tract of land owned by a religious order known as The Seekers. On Blackacre, The Seekers erected a large residential building where its members reside. Blackacre is surrounded by rural residential properties and its only access to a public way is afforded by an easement over a strip of land 30 feet wide. The easement was granted to The Seekers by deed from Sally, the owner of one of the adjacent residential properties. The Seekers built a driveway on the strip, and the easement was used for 20 years without incident or objection. Last year, as permitted by the applicable zoning ordinance, The Seekers constructed a 200-bed nursing home and a parking lot on Blackacre, using all of Blackacre that was available for such development. The nursing home was very successful, and on Sundays visitors to the nursing home overflowed the parking facilities on Blackacre and parked all along the driveway from early in the morning through the evening hours. After two Sundays of the resulting congestion and inconvenience, Sally erected a barrier across the driveway on Sundays preventing any use of the driveway by anyone seeking access to Blackacre. The Seekers objected. Sally brought an appropriate action to terminate the easement. The most likely result in this action is that the court will hold for', 'Sally, because The Seekers excessively expanded the use of the dominant tenement.', 'Sally, because the parking on the driveway exceeded the scope of the easement.', 'The Seekers, because expanded use of the easement does not terminate the easement.', 'The Seekers, because Sally''s use of selfhelp denies her the right to equitable relief.', 'C', 'An easement is a grant of only limited use of the land. Crane Hollow, Inc. v. Marathon Ashland Pipeline, LLC, 138 Ohio App.3d 57, 66, 740 N.E.2d 328 (2000), citations deleted. When interpreting the terms of a written easement, the court must follow the ordinary rules of contract construction so as to carry out the intent of the parties as demonstrated by the language in the contract. Lakewood Homes v. BP Oil, Inc. 11th District No. 5–98–29, 1999–Ohio–851 citing Skivoloski v. East Ohio Gas Company, 38 Ohio St.2d 244, 313 N.E.2d 374 (1974), syllabus, paragraph one. If the question is the scope of an easement, the court must look to the language of the easement to determine the extent. If there is no specific delineation of the easement, or if the document is ambiguous, then the court must look to the surrounding circumstances in order to determine the intent of the parties. Murray v. Lyon, 95 Ohio App.3d 215, 219, 642 N.E.2d 41 (1994). The language of the easement, coupled with the surrounding circumstances, is the best indication of the extent and limitations of the easement. Apel v. Katz, 83 Ohio St.3d 11, 17, 1998–Ohio420, 697 N.E.2d 600. In a case where the language of an easement is ambiguous, the use of the easement can be extended if the court finds the parties intended to allow an extension at the time they entered into the easement agreement. Cortland United Methodist Church v. Knowles, 11th District No. 2006–T–0110, 2007–Ohio–3383. Otherwise a court must determine whether an increased use or expansion unreasonably burdens the servient estate. Anspach v. Madden, 6th District No. S–84–40, 1985 WL 8215 (November 1, 1985).', 'mbe_597', 0, '21'),
('mbe_772', 'mbe', '772', '550', '1991-July', 'REAL PROP.', '23', '', 'Three months ago, Bert agreed in writing to buy Sam''s single-family residence, Liveacre, for $110,000. Bert paid Sam a $5,000 deposit to be applied to the purchase price. The contract stated that Sam had the right at his option to retain the deposit as liquidated damages in the event of Bert''s default. The closing was to have taken place last week. Six weeks ago, Bert was notified by his employer that he was to be transferred to another job 1,000 miles away. Bert immediately notified Sam that he could not close, and therefore he demanded the return of his $5,000. Sam refused, waited until after the contract closing date, listed with a broker, and then conveyed Liveacre for $108,000 to Conner, a purchaser found by the real estate broker. Conner paid the full purchase price and immediately recorded his deed. Conner knew of the prior contract with Bert. In an appropriate action, Bert seeks to recover the $5,000 deposit from Sam. The most probable result will be that Sam', 'must return the $5,000 to Bert, because Sam can no longer carry out his contract with Bert.', 'must return the $5,000 to Bert, because Bert was legally justified in not completing the contract.', 'must return $3,000 to Bert, because Sam''s damages were only $2,000.', 'may keep the $5,000 deposit, because Bert breached the contract.', 'D', 'To prevail in a breach of contract action, a plaintiff must prove: (1) a valid contract existed; (2) a material breach of the contract; and (3) damages. See Murciano v. Garcia, 958 So.2d 423 (Fla. 3d DCA 2007). Deauville contends that because the contract allowed it to reassign a space as needed and because “function space” was not defined as the Richelieu ballroom, the hotel did not breach the contract when it unilaterally moved the Wards'' reception to the lobby of the hotel. Deauville''s reading of the contract is an incomplete one.', 'mbe_598', 0, '23'),
('mbe_773', 'mbe', '773', '551', '1991-July', 'CONTRACTS', '24', '', 'Rollem, an automobile retailer, had an adult daughter, Betsy, who needed a car in her employment but had only $3,000 with which to buy one. Rollem wrote to her, "Give me your $3,000 and I''ll give you the car on our lot that we have been using as a demonstrator." Betsy thanked her father and paid him the $3,000. As both Rollem and Betsy knew, the demonstrator was reasonably worth $10,000. After Betsy had paid the $3,000, but before the car had been delivered to her, one of Rollem''s sales staff sold and delivered the same car to a customer for $10,000. Neither the salesperson nor the customer was aware of the transaction between Rollem and Betsy. Does Betsy, after rejecting a tendered return of the $3,000 by Rollem, have an action against him for breach of contract?', 'Yes, because Rollem''s promise was supported by bargained-for consideration.', 'Yes, because Rollem''s promise was supported by the moral obligation a father owes his child as to the necessities of modern life.', 'No, because the payment of $3,000 was inadequate consideration to support Rollem''s promise.', 'No, because the salesperson''s delivery of the car to the customer made it impossible for Rollem to perform.', 'A', 'Consideration, meaning that which is bargained for and given in exchange for a promise, is a necessary element of a binding contract, and the absence of consideration precludes the formation of a valid contract.” Harvest Land Co-Op, Inc. v. Hora, 2d Dist. Montgomery No. 25068, 2012-Ohio-5915, 2012 WL 6554728, ¶ 14, citing 17 Ohio Jurisprudence 3d, Contracts, Section 39.', 'mbe_599', 0, '24'),
('mbe_774', 'mbe', '774', '552', '1991-July', 'TORTS', '25', '', 'Peter, who was 20 years old, purchased a new, high-powered sports car that was marketed with an intended and recognized appeal to youthful drivers. The car was designed with the capability to attain speeds in excess of 100 miles per hour. It was equipped with tires designed and tested only for a maximum safe speed of 85 miles per hour. The owner''s manual that came with the car stated that "continuous driving over 90 miles per hour requires high-speed-capability tires," but the manual did not describe the speed capability of the tires sold with the car. Peter took his new car out for a spin on a straight, smooth country road where the posted speed limit was 55 miles per hour. Intending to test the car''s power, he drove for a considerable distance at over 100 miles per hour. While he was doing so, the tread separated from the left rear tire, causing the car to leave the road and hit a tree. Peter sustained severe injuries. Peter has brought a strict product liability action in tort against the manufacturer of the car. You should assume that pure comparative fault principles apply to this case. Will Peter prevail?', 'No, because Peter''s driving at an excessive speed constituted a misuse of the car.', 'No, because the car was not defective.', 'Yes, if the statement in the manual concerning the tires did not adequately warn of the danger of high-speed driving on the tires mounted on the car.', 'Yes, unless Peter''s driving at a speed in excess of the posted speed limit was negligence per se that, by the law of the jurisdiction, was not excusable.', 'C', 'The elements of a claim for failure to warn based in negligence are: (1) the defendant designed the product at issue; (2) the product did not contain an adequate warning of the alleged defect or hazard; (3) the defendant failed to use ordinary care to warn of the risk of harm from the alleged defect or hazard; and (4) as a direct result of the defendant''s failure to adequately warn, the plaintiff sustained damage. MAI 25.09.', 'mbe_600', 0, '25'),
('mbe_775', 'mbe', '775', '553', '1991-July', 'EVIDENCE', '26', '', 'In a federal court diversity action by Plant against Decord on an insurance claim, a question arose whether the court should apply a presumption that, where both husband and wife were killed in a common accident, the husband died last. Whether this presumption should be applied is to be determined according to', 'traditional common law.', 'federal statutory law.', 'the law of the state whose substantive law is applied.', 'the federal common law.', 'C', 'the principal location of the insured risk determines which state''s law applies when an insurance contract is at issue, unless some other state has a more significant relationship to the transaction and the parties.', 'mbe_601', 0, '26'),
('mbe_776', 'mbe', '776', '554', '1991-July', 'CRIM. LAW', '27', '', 'Plagued by neighborhood youths who had been stealing lawn furniture from his back yard, Armando remained awake nightly watching for them. One evening Armando heard noises in his backyard. He yelled out, warning intruders to leave. Receiving no answer, he fired a shotgun filled with nonlethal buckshot into bushes along his back fence where he believed the intruders might be hiding. A six-year-old child was hiding in the bushes and was struck in the eye by some of the pellets, causing loss of sight. If Armando is charged with second-degree assault, which is defined in the jurisdiction as "maliciously causing serious physical injury to another," he is', 'not guilty, because the child was trespassing and he was using what he believed was nondeadly force.', 'not guilty, because he did not intend to kill or to cause serious physical injury.', 'guilty, because he recklessly caused serious physical injury.', 'guilty, because there is no privilege to use force against a person who is too young to be criminally responsible.', 'C', 'The elements in a second degree assault proceeding include (1) reckless infliction of (2) substantial bodily harm.', 'mbe_602', 0, '27'),
('mbe_777', 'mbe', '777', '555', '1991-July', 'CONST. LAW', '28', '', 'Twenty percent of the residents of Green City are members of minority racial groups. These residents are evenly distributed among the many different residential areas of the city. The five city council members of Green City are elected from five single-member electoral districts that are nearly equally populated. No candidate has ever been elected to the city council who was a member of a minority racial group. A group of citizens who are members of minority racial groups file suit in federal district court seeking a declaratory judgment that the single-member districts in Green City are unconstitutional. They claim that the single-member districting system in that city diminishes the ability of voters who are members of minority racial groups to affect the outcome of city elections. They seek an order from the court forcing the city to adopt an at-large election system in which the five candidates with the greatest vote totals would be elected to the city council. No state or federal statutes are applicable to the resolution of this suit. Which of the following constitutional provisions provides the most obvious basis for plaintiffs'' claim in this suit?', 'The Thirteenth Amendment.', 'The due process clause of the Fourteenth Amendment.', 'The privileges and immunities clause of the Fourteenth Amendment.', 'The Fifteenth Amendment.', 'D', 'The Court''s early decisions under the Fifteenth Amendment established that it imposes but one limitation on the powers of the States. It forbids them to discriminate against Negroes in matters having to do with voting. See Ex parte **1497 Yarbrough, 110 U.S. 651, 665, 4 S.Ct. 152, 159, 28 L.Ed. 274; Neal v. Delaware, 103 U.S. 370, 389–390, 26 L.Ed. 567; United States v. Cruikshank, 92 U.S. 542, 555–556, 23 L.Ed. 588; United States v. Reese, 92 U.S. 214, 23 L.Ed. 563. The Amendment''scommand *62 and effect are wholly negative. “The Fifteenth Amendment does not confer the right of suffrage upon any one,” but has “invested the citizens of the United States with a new constitutional right which is within the protecting power of Congress. That right is exemption from discrimination in the exercise of the elective franchise on account of race, color, or previous condition of servitude.” Id., at 217–218.', 'mbe_603', 0, '28'),
('mbe_778', 'mbe', '778', '556', '1991-July', 'CONTRACTS', '29', '', 'Loomis, the owner and operator of a small business, encourages "wellness" on the part of his employees and supports various physicalfitness programs to that end. Learning that one of his employees, Graceful, was a dedicated jogger, Loomis promised to pay her a special award of $100 if she could and would run one mile in less than six minutes on the following Saturday. Graceful thanked him, and did in fact run a mile in less than six minutes on the day specified. Shortly thereafter, however, Loomis discovered that for more than a year Graceful had been running at least one mile in less than six minutes every day as a part of her personal fitness program. He refused to pay the $100. In an action by Graceful against Loomis for breach of contract, which of the following best summarizes the probable decision of the court?', 'Loomis wins, because it is a compelling inference that Loomis''s promise did not induce Graceful to run the specified mile.', 'Loomis wins, because Graceful''s running of the specified mile was beneficial, not detrimental, to her in any event.', 'Graceful wins, because running a mile in less than six minutes is a significantly demanding enterprise.', 'Graceful wins, because she ran the specified mile as requested, and her motives for doing so are irrelevant.', 'D', '“California law does not recognize a breach of contract as a ‘wrongful act’ predicate required for this claim.” “[A] breach of contract claim cannot be transmuted into tort liability by claiming that the breach interfered with the promisee''s business.”83 This is true even when a party breaches in order to put the non-breaching party out of business and rid itself of a competitor.84 “[M]otive, regardless of how malevolent, remains irrelevant to a breach of contract claim and does not convert a contract action into a tort claim....” To the extent that Templeton *1194 is alleging a breach of contract, it must pursue this claim under that theory.', 'mbe_2392', 0, '29'),
('mbe_779', 'mbe', '779', '557', '1991-July', 'REAL PROP.', '30', '', 'Able was the owner of Blackacre, an undeveloped city lot. Able and Baker executed a written document in which Able agreed to sell Blackacre to Baker and Baker agreed to buy Blackacre from Able for $100,000; the document did not provide for an earnest money down payment. Able recorded the document, as authorized by statute. Able orally gave Baker permission to park his car on Blackacre without charge prior to the closing. Thereafter, Baker frequently parked his car on Blackacre. Another property came on the market that Baker wanted more than Blackacre. Baker decided to try to escape any obligation to Able. Baker had been told that contracts for the purchase and sale of real property require consideration and concluded that because he had made no earnest money down payment, he could refuse to close and not be liable. Baker notified Able of his intention not to close and, in fact, did refuse to close on the date set for the closing. Able brought an appropriate action to compel specific performance by Baker. If Able wins, it will be because', 'Baker''s use of Blackacre for parking constitutes part performance.', 'general contract rules regarding consideration apply to real estate contracts.', 'the doctrine of equitable conversion applies.', 'the document was recorded.', 'B', '“Conversion is an intentional exercise of dominion or control over a chattel which so seriously interferes with the right of another to control it that the actor may justly be required to pay the other the full value of the chattel.” To establish a claim for conversion, the plaintiff must prove (1) that she had a possessory interest in the property; (2) that the defendant interfered with the plaintiff''s right to possess the property; (3) that the defendant intended to interfere with plaintiff''s possession; and (4) that the defendant''s act was the legal cause of the plaintiff''s loss of the property.30 Where the plaintiff voluntarily places her property with the defendant, the “defendant ordinarily is not required to do more than permit the plaintiff to come and get the chattel.”', 'mbe_2687', 0, '30'),
('mbe_78', 'mbe', '78', '48', 'MBE-1972-78-part3', '', '29', '', 'Detective received informal from Informant, who had given reliable information many times in the past, that Harry was a narcotics dealer. Specifically, Informant said that, two months before, he had visited Harry''s apartment with Bill and that on that occasion he saw Harry sell Bill some heroin. Detective knew that Informant, Harry, and Bill were friends. Thereafter, Detective put all this information into affidavit form, appeared before a magistrate, and secured a search warrant for Harry''s apartment. The search turned up a supply of heroin. Harry''s motion to suppress introduction of the heroin into evidence will most probably be', 'granted, because a search warrant cannot validly be issued solely on the basis of an informant''s information.', 'granted, because the information supplied to Detective concerned an occurrence too remote in time to justify a finding of probable cause at the time of the search', 'granted, because a search for "mere evidence" alone is improper and illegal', 'denied, because Informant had proven himself reliable in the past and the information he gave turned out to be correct', 'B', 'To establish probable cause, police officers must be able to point to objective circumstances leading them to believe that a suspect committed a crime. A police officer can''t establish probable cause by saying only something like, "I just had a hunch that the defendant was a burglar." Judges, not police officers, have the last word on whether probable cause exists. A police officer may be sincere in believing that the facts establish probable cause. But if a judge examines that same information and disagrees, then probable cause does not exist (or did not exist, if the question is being decided after an arrest). Note that probable cause may have existed at the time of an arrest even if the defendant didn''t actually do anything wrong. Put differently, an arrest is valid as long as it is based on probable cause, even if the arrested person is innocent.', 'mbe_63', 0, '29'),
('mbe_780', 'mbe', '780', '558', '1991-July', 'CONTRACTS', '31', 'Under the terms of a written contract, Karp agreed to construct for Manor a garage for $10,000. Nothing was said in the parties'' negotiations or in the contract about progress payments during the course of the work.', 'For this question only, assume the following facts. After completing 25% of the garage strictly according to Manor''s specifications, Karp demanded payment of $2,000 as a "reasonable progress payment." Manor refused, and Karp abandoned the job. If each party sues the other for breach of contract, which of the following will the court decide?', 'Both parties are in breach, and each is entitled to damages, if any, from the other.', 'Only Karp is in breach and liable for Manor''s damages, if any.', 'Only Manor is in breach and liable for Karp''s damages, if any.', 'Both parties took reasonable positions, and neither is in breach.', 'B', 'A material breach of contract “is a non-performance of a duty that is so material and important as to justify the injured party in regarding the whole transaction as at an end.” *6 Jenkins, Inc. v. Walsh Bros., Inc., 2001 ME 98, ¶ 13, 776 A.2d 1229, 1234 (quotation marks omitted); see also Forrest Assocs. v. Passamaquoddy Tribe, 2000 ME 195, ¶ 9, 760 A.2d 1041, 1044 (stating that “whether a breach has occurred ... [is a] question [ ] of fact”).', 'mbe_604', 0, '31'),
('mbe_781', 'mbe', '781', '558', '1991-July', 'CONTRACTS', '32', 'Under the terms of a written contract, Karp agreed to construct for Manor a garage for $10,000. Nothing was said in the parties'' negotiations or in the contract about progress payments during the course of the work.', 'For this question only, assume the following facts. After completing 25% of the garage strictly according to Manor''s specifications, Karp assigned his rights under the contract to Banquo as security for an $8,000 loan. Banquo immediately notified Manor of the assignment. Karp thereafter, without legal excuse, abandoned the job before it was half-complete. Karp subsequently defaulted on the loan from Banquo. Karp has no assets. It will cost Manor at least $8,000 to get the garage finished by another builder. If Banquo sues Manor for $8,000, which of the following will the court decide?', 'Banquo wins, because the Karp-Manor contract was in existence and Karp was not in breach when Banquo gave Manor notice of the assignment.', 'Banquo wins, because Banquo as a secured creditor over Karp is entitled to priority over Manor''s unsecured claim against Karp.', 'Manor wins, because his right to recoupment on account of Karp''s breach is available against Banquo as Karp''s assignee.', 'Manor wins, because his claim against Karp arose prior to Karp''s default on his loan from Banquo.', 'C', 'The assignee of rights under a contract stands in the shoes of the assignor and can assert any rights that the assignor could have asserted. Citimortgage, Inc. v. Barabas, 975 N.E.2d 805, 813 (Ind.2012). “A valid assignment gives the assignee neither greater nor lesser rights than those held by the assignor.” Indianapolis–Marion Cnty. Pub. Library v. Charlier Clark & Linard, PC, 929 N.E.2d 838, 848 (Ind.Ct.App.2010) (citation and quotation marks omitted), trans. denied.', 'mbe_605', 0, '32'),
('mbe_782', 'mbe', '782', '559', '1991-July', 'CONST. LAW', '33', '', 'The Sports Championship Revenue Enhancement Act is a federal statute that was enacted as part of a comprehensive program to eliminate the federal budget deficit. That act imposed, for a period of five years, a 50% excise tax on the price of tickets to championship sporting events. Such events included the World Series, the Super Bowl, major college bowl games, and similar championship sports events. This federal tax is probably', 'constitutional, because the compelling national interest in reducing the federal budget deficit justifies this tax as a temporary emergency measure.', 'constitutional, because an act of Congress that appears to be a revenue raising measure on its face is not rendered invalid because it may have adverse economic consequences for the activity taxed.', 'unconstitutional, because a 50% tax is likely to reduce attendance at championship sporting events and, therefore, is not rationally related to the legitimate interest of Congress in eliminating the budget deficit.', 'unconstitutional, because Congress violates the equal protection component of the Fifth Amendment by singling out championship sporting events for this tax while failing to tax other major sporting, artistic, or entertainment events to which tickets are sold.', 'B', 'It is conceded that a federal excise tax does not cease to be valid merely because it discourages or deters the activities taxed. Nor is the tax invalid because the revenue obtained its negligible. Appellee, however, argues that the sole purpose of the statute is to penalize only illegal gambling in the states through the guise of a tax measure. As with the above excise taxes which we have held to be valid, the instant tax has a regulatory effect. But regardless of its regulatory effect, the wagering tax produces revenue. As such it surpasses both the narcotics and firearms taxes which we have found valid.', 'mbe_2393', 0, '33'),
('mbe_783', 'mbe', '783', '560', '1991-July', 'CONTRACTS', '34', '', 'On June 1, Topline Wholesale, Inc., received a purchase-order form from Wonder-Good, Inc., a retailer and new customer, in which the latter ordered 1,000 anti-recoil widgets for delivery no later than August 30 at a delivered total price of $10,000, as quoted in Topline''s current catalog. Both parties are merchants with respect to widgets of all types. On June 2, Topline mailed to Wonder-Good its own form, across the top of which Topline''s president had written, "We are pleased to accept your order." This form contained the same terms as Wonder-Good''s form except for an additional printed clause in Topline''s form that provided for a maximum liability of $100 for any breach of contract by Topline. As of June 5, when Wonder-Good received Topline''s acceptance form, which of the following is an accurate statement concerning the legal relationship between Topline and Wonder-Good?', 'There is no contract, because the liability-limitation clause in Topline''s form is a material alteration of WonderGood''s offer.', 'There is no contract, because WonderGood did not consent to the liabilitylimitation clause in Topline''s form.', 'There is an enforceable contract whose terms include the liability-limitation clause in Topline''s form, because liquidation of damages is expressly authorized by the Uniform Commercial Code.', 'There is an enforceable contract whose terms do not include the liabilitylimitation clause in Topline''s form.', 'D', 'a material alteration will discharge a surety''s obligations. See Vastine v. Bank of Dallas, 808 S.W.2d 463, 464–65 (Tex.1991). Because a material alteration is an affirmative defense, the burden is on the surety to demonstrate that a material alteration occurred. See Sonne v. Federal Deposit Ins. Corp., 881 S.W.2d 789, 793 (Tex.App.—Houston [14th Dist.] 1994, writ denied) (citing Federal Deposit Ins. Corp. v. Attayi, 745 S.W.2d 939, 944 (Tex.App.—Houston [1st Dist.] 1988, no writ).
 To establish a material alteration, the following elements must be shown: (1) the existence of a material alteration to the underlying contract; (2) lack of consent to the alteration; and (3) harm resulting from the alteration. See Austin Hardwoods, Inc. v. Vanden Berghe, 917 S.W.2d 320, 326 (Tex.App.—El Paso 1995, writ denied) (citing Old Colony Ins. Co. v. City of Quitman, 163 Tex. 144, 352 S.W.2d 452, 455 (1961)); Sonne, 881 S.W.2d at 793; Attayi, 745 S.W.2d at 944.', 'mbe_606', 0, '34'),
('mbe_784', 'mbe', '784', '561', '1991-July', 'TORTS', '35', '', 'Electco operates a factory that requires the use of very high voltage electricity. Paul owns property adjacent to the Electco plant where he has attempted to carry on a business that requires the use of sensitive electronic equipment. The effectiveness of Paul''s electronic equipment is impaired by electrical interference arising from the high voltage currents used in Electco''s plant. Paul has complained to Electco several times, with no result. There is no way that Electco, by taking reasonable precautions, can avoid the interference with Paul''s operation that arises from the high voltage currents necessary to Electco''s operation. In Paul''s action against Electco to recover damages for the economic loss caused to him by the electrical interference, will Paul prevail?', 'Yes, because Electco''s activity is abnormally dangerous.', 'Yes, for loss suffered by Paul after Electco was made aware of the harm its activity was causing to Paul.', 'No, unless Electco caused a substantial and unreasonable interference with Paul''s business.', 'No, because Paul''s harm was purely economic and did not arise from physical harm to his person or property.', 'C', 'Idaho recognized the tort of interference with a prospective economic advantage in Idaho First National Bank v. Bliss Valley Foods, 121 Idaho 266, 284–85, 824 P.2d 841, 859–60 (1991). In adopting the cause of action, this Court stated that we agreed with the way in which the tort had been discussed by the Washington Supreme Court in Pleas v. City of Seattle, 112 Wash.2d 794, 774 P.2d 1158 (1989) and the Oregon Supreme Court in Top Service Body Shop, Inc. v. Allstate Ins. Co., 283 Or. 201, 582 P.2d 1365 (1978) and adopted the tort as outlined in those cases. Although in Bliss we did not precisely state each element of the tort and instead, focused mainly on the type of wrongful conduct necessary to establish a claim, our reference in Bliss to Barlow v. International Harvester, Co., 95 Idaho 881, 522 P.2d 1102 (1974), a case involving a nearly identical tort, interference with contract, combined with Pleas and Top Service, provides a clear picture of the elements of the tort of intentional interference with a prospective economic advantage.  Those elements are as follows: (1) The existence of a valid economic expectancy; (2) knowledge of the expectancy on the part of the interferer; (3) intentional interference inducing termination of the expectancy; (4) the interference was wrongful by some measure beyond the fact of the interference itself (i.e. that the defendant interfered for an improper purpose or improper means) and (5) resulting damage to the plaintiff whose expectancy has been disrupted. See Bliss, 121 Idaho at 285–86, 824 P.2d at 859–60; Barlow, 95 Idaho at 893, 522 P.2d at 1114; Pleas, 774 P.2d at 1161–63.', 'mbe_607', 0, '35'),
('mbe_785', 'mbe', '785', '562', '1991-July', 'REAL PROP.', '36', '', 'Les leased a barn to his neighbor, Tom, for a term of three years. Tom took possession of the barn and used it for his farming purposes. The lease made Les responsible for structural repairs to the barn, unless they were made necessary by actions of Tom. One year later, Les conveyed the barn and its associated land to Lottie "subject to the lease to Tom." Tom paid the next month''s rent to Lottie. The next day a portion of an exterior wall of the barn collapsed because of rot in the interior structure of the wall. The wall had appeared to be sound, but a competent engineer, on inspection, would have discovered its condition. Neither Lottie nor Tom had the barn inspected by an engineer. Tom was injured as a result of the collapse of the wall. Les had known that the wall was dangerously weakened by rot and needed immediate repairs, but had not told Tom or Lottie. There is no applicable statute. Tom brought an appropriate action against Les to recover damages for the injuries he sustained. Lottie was not a party. Which of the following is the most appropriate comment concerning the outcome of this action?', 'Tom should lose, because Lottie assumed all of Les''s obligations by reason of Tom''s attornment to her.', 'Tom should recover, because there is privity between lessor and lessee and it cannot be broken unilaterally.', 'Tom should recover, because Les knew of the danger but did not warn Tom.', 'Tom should lose, because he failed to inspect the barn.', 'C', 'Attornment is “[t]he agreement of a person to recognize a third party as a permissible successor party to a contract; most often, the agreement of a tenant to pay rent to a new landlord, especially a mortgagee who has foreclosed.” Black''s Law Dictionary (6th Ed.1990).', 'mbe_608', 0, '36'),
('mbe_786', 'mbe', '786', '563', '1991-July', 'EVIDENCE', '37', '', 'Dahle is charged with possession of heroin. Prosecution witness Walker, an experienced dog trainer, testified that he was in the airport with a dog trained to detect heroin. As Dahle approached, the dog immediately became alert and pawed and barked frantically at Dahle''s briefcase. Dahle managed to run outside and throw his briefcase into the river, from which it could not be recovered. After Walker''s experience is established, he is asked to testify as an expert that the dog''s reaction told him that Dahle''s briefcase contained heroin. Walker''s testimony is', 'admissible, as evidence of Dahle''s guilt.', 'admissible, because an expert may rely on hearsay.', 'inadmissible, because it is based on hearsay not within any exception.', 'inadmissible, because of the unreliability of the reactions of an animal.', 'A', 'the admissibility of opinion evidence under the strictures of Rule 701 is not without limit. Rule 701''s requirement that the opinion be “rationally based on the perception of the witness” demands more than that the witness have perceived something firsthand; rather, it requires that the witness''s perception provide a truly rational basis for his or her opinion. Similarly, the second requirement—that the opinion be “helpful to a clear understanding of the witness''s testimony or the determination of a fact in issue”—demands more than that the opinion have a bearing on the issues in the case; in order to be “helpful,” an opinion must be reasonably reliable. In other words, Rule 701 requires that a lay opinion witness have a reasonable basis grounded either in experience or specialized knowledge for arriving at the opinion that he or she expresses. See Paiva, 892 F.2d at 157 (“Individual experience and knowledge of a lay witness may establish his or her competence, without qualification as an expert, to express an opinion on a particular subject outside the realm of common knowledge.”).', 'mbe_609', 0, '37'),
('mbe_787', 'mbe', '787', '564', '1991-July', 'TORTS', '38', '', 'Doe negligently caused a fire in his house, and the house burned to the ground. As a result, the sun streamed into Peter''s yard next door, which previously had been shaded by Doe''s house. The sunshine destroyed some delicate and valuable trees in Peter''s yard that could grow only in the shade. Peter has brought a negligence action against Doe for the loss of Peter''s trees. Doe has moved to dismiss the complaint. The best argument in support of this motion would be that', 'Doe''s negligence was not the active cause of the loss of Peter''s trees.', 'Doe''s duty to avoid the risks created by a fire did not encompass the risk that sunshine would damage Peter''s trees.', 'the loss of the trees was not a natural and probable consequence of Doe''s negligence.', 'Peter suffered a purely economic loss, which is not compensable in a negligence action.', 'B', 'Proximate cause is the cause that “ ‘ “in natural and continuous sequence, unbroken by an efficient intervening cause, produces the injury and without which the injury would not have occurred, the injury being the natural and probable consequence of the wrongful act.” ’ ” Yount v. Deibert, 282 Kan. 619, 624-25, 147 P.3d 1065 (2006). Individuals are not responsible for all possible consequences arising from their negligence—just those that are probable according to ordinary and usual experience. Hale v. Brown, 287 Kan. 320, 322, 197 P.3d 438 (2008).', 'mbe_835', 0, '38'),
('mbe_788', 'mbe', '788', '565', '1991-July', 'CRIM. LAW', '39', '', 'Phillips bought a new rifle and wanted to try it out by doing some target shooting. He went out into the country to an area where he had previously hunted. Much to his surprise, he noticed that the area beyond a clearing contained several newly constructed houses that had not been there before. Between the houses there was a small playground where several children were playing. Nevertheless, Phillips nailed a paper target to a tree and went to a point where the tree was between himself and the playground. He then fired several shots at the target. One of the shots missed the target and the tree and hit and killed one of the children in the playground. Phillips was convicted of murder. He appealed, contending that the evidence was not sufficient to support a conviction of murder. The appellate court should', 'affirm the conviction, as the evidence is sufficient to support a conviction of murder.', 'reverse the conviction and remand for a new trial, because the evidence is not sufficient for murder but will support a conviction of voluntary manslaughter.', 'reverse the conviction and remand for a new trial, because the evidence is not sufficient for murder but will support a conviction of involuntary manslaughter.', 'reverse the conviction and order the case dismissed, because the evidence is sufficient only for a finding of negligence and negligence alone cannot support a criminal conviction.', 'A', 'In “reckless” or “universal malice” murder, “the defendant evinces a culpable mind, determined to act no matter what the consequences to others. He must have determined to follow a course of action which he knows, or should know, will, in all probability, lead to harm to another.” Napier v. State, 357 So.2d 1011, 1014 (Ala.1978). “The word ‘determines'' presupposes that some mental operation has taken place; the reasoning faculty must be called into play.” Langford v. State, 354 So.2d 313, 315 (Ala.1977).
“In providing that homicide committed ‘recklessly under circumstances manifesting extreme indifference to human life’ constitutes murder, the drafters of the model code were attempting to define a degree of recklessness ‘that cannot be fairly distinguished from homicides committed purposely or knowingly.’ Model Penal Code and Commentaries, § 210.02, Comment, 4 (1980).”
Ex parte Weems, 463 So.2d at 172. Consequently, a required element of “reckless” or “universal malice” murder involving the use of a firearm is that the defendant “determined” or intended to use the firearm.', 'mbe_2688', 0, '39'),
('mbe_789', 'mbe', '789', '566', '1991-July', 'CONTRACTS', '40', 'Dominique obtained a bid of $10,000 to tear down her old building and another bid of $90,000 to replace it with a new structure in which she planned to operate a sporting goods store. Having only limited cash available, Dominique asked Hardcash for a $100,000 loan. After reviewing the plans for the project, Hardcash in a signed writing promised to lend Dominique $100,000 secured by a mortgage on the property and repayable over ten years in equal monthly installments at 10% annual interest. Dominique promptly accepted the demolition bid and the old building was removed, but Hardcash thereafter refused to make the loan. Despite diligent efforts, Dominique was unable to obtain a loan from any other source.', 'Does Dominique have a cause of action against Hardcash?', 'Yes, because by having the building demolished, she accepted Hardcash''s offer to make the loan.', 'Yes, because her reliance on Hardcash''s promise was substantial, reasonable, and foreseeable.', 'No, because there was no bargained-for exchange of consideration for Hardcash''s promise to make the loan.', 'No, because Dominique''s inability to obtain a loan from any other source demonstrated that the project lacked the financial soundness that was a constructive condition to Hardcash''s performance.', 'B', 'Reliance damages entitle a plaintiff to be reimbursed for the out-of-pocket expenditures that were caused by his reliance on the contract, in order to put him in the same position he would have been in if the contract had not been made. Quigley, 227 S.W.3d at 56 n.1 (Brister, J., concurring in part & dissenting in part) (citing *516 Restatement (Second) of Contracts § 344 (1981)); Sharifi v. Steen Auto., LLC, 370 S.W.3d 126, 149 (Tex.App.—Dallas 2012, no pet.)', 'mbe_610', 0, '40'),
('mbe_79', 'mbe', '79', '49', 'MBE-1972-78-part3', '', '30', '', 'Defendant sold heroin to Morgan. Morgan was later stopped by police for speeding. The police searched Morgan''s car and found the heroin concealed under the rear seat. Defendant is charged with illegally selling heroin. Defendant''s motion to prevent introduction of the heroin into evidence will most probably be', 'granted, because the heroin was not in plain view', 'granted, because the scope of the search was excessive', 'denied, because Defendant has no standing to object to the search', 'denied, because the search was proper as incident to a valid full custodial arrest', 'C', 'only persons whose privacy or property interests are violated may object to a search on Fourth Amendment grounds; exerting control and oversight over property by virtue of participation in a criminal conspiracy does not alone establish such interests', 'mbe_64', 0, '30'),
('mbe_790', 'mbe', '790', '566', '1991-July', 'CONTRACTS', '41', 'Dominique obtained a bid of $10,000 to tear down her old building and another bid of $90,000 to replace it with a new structure in which she planned to operate a sporting goods store. Having only limited cash available, Dominique asked Hardcash for a $100,000 loan. After reviewing the plans for the project, Hardcash in a signed writing promised to lend Dominique $100,000 secured by a mortgage on the property and repayable over ten years in equal monthly installments at 10% annual interest. Dominique promptly accepted the demolition bid and the old building was removed, but Hardcash thereafter refused to make the loan. Despite diligent efforts, Dominique was unable to obtain a loan from any other source.', 'For this question only, assume that Dominique has a cause of action against Hardcash. If she sues him for monetary relief, what is the probable measure of her recovery?', 'Expectancy damages, measured by the difference between the value of the new building and the old building, less the amount of the proposed loan ($100,000).', 'Expectancy damages, measured by the estimated profits from operating the proposed sporting goods store for ten years, less the cost of repaying a $100,000 loan at 10% interest over ten years.', 'Reliance damages, measured by the $10,000 expense of removing the old building, adjusted by the decrease or increase in the market value of Dominique''s land immediately thereafter.', 'Nominal damages only, because both expectancy and reliance damages are speculative, and there is no legal or equitable basis for awarding restitution.', 'C', 'Expectation damages are recoverable where: (1) “damages were reasonably foreseeable by the breaching party at the time of contracting;” (2) damages were caused by the breach; and (3) “the damages are shown with reasonable certainty.” Ind. Mich. Power Co. v. United States, 422 F.3d 1369, 1373 (Fed.Cir.2005)(citing Energy Capital Corp. v. United States, 302 F.3d 1314, 1320 (Fed.Cir.2002)); see also Bluebonnet Savings Bank, FSB v. United States, 67 Fed.Cl. 231, 235 (2005). These factors, when applied in concert, ensure that a damages award may not be based on mere speculation. See Bluebonnet, 67 Fed.Cl. at 235.', 'mbe_611', 0, '41'),
('mbe_791', 'mbe', '791', '567', '1991-July', 'TORTS', '42', '', 'Dan, an eight-year-old, rode his bicycle down his driveway into a busy highway and Driver had to stop her car suddenly to avoid colliding with the bike. Because of the sudden stop, Driver''s two-year-old son, Peter, who was sitting on the seat without any restraint, was thrown into the dashboard and injured. Had Peter been properly restrained in a baby car seat, as required by a state safety statute of which his mother was aware, he would not have been injured. In an action brought on Peter''s behalf against Dan''s parents to recover for Peter''s injuries, Peter will', 'not prevail, because parents are not vicariously liable for the negligent acts of their children.', 'not prevail, because Peter''s injury was attributable to his mother''s knowing violation of a safety statute.', 'prevail, if Dan''s parents knew that he sometimes drove into the highway, and they took no steps to prevent it.', 'prevail, if Dan''s riding into the highway was negligent and the proximate cause of Peter''s injuries.', 'C', 'A duty of reasonable care generally encompasses a duty not to create an unreasonable risk of harm. See Reighard v. Yates, 2012 UT 45, ¶¶ 29–31, 285 P.3d 1168; B.R. ex rel. Jeffs v. West, 2012 UT 11, ¶ 21 & n. 11, 275 P.3d 228. What may be reasonable in one setting may not be reasonable in another. Ordinarily participants cannot reasonably expect instructors or coaches to insulate them from risks inherent in an activity in which they voluntarily engage. See, e.g., Kahn, 31 Cal.4th 990, 4 Cal.Rptr.3d 103, 75 P.3d at 38–43 (majority opinion). But whether, under the circumstances of this case, Instructor created an unreasonable risk of harm, increased the risk inherent in competitive ballroom dancing, or was otherwise unreasonable in his acts and omissions is a question for the trier of fact.', 'mbe_2394', 0, '42'),
('mbe_792', 'mbe', '792', '568', '1991-July', 'TORTS', '43', '', 'While Hill was in her kitchen, she heard the screech of automobile tires. She ran to the window and saw a tricycle flying through the air. The tricycle had been hit by a car driven by Weber, who had been speeding. She also saw a child''s body in the grass adjacent to the street. As a result of her shock from this experience, Hill suffered a heart attack. In a claim by Hill against Weber, the issue on which Hill''s right to recover will depend is whether', 'a person can recover damages based on the defendant''s breach of a duty owed to another.', 'it is foreseeable that a person may suffer physical harm caused solely by an injury inflicted on another.', 'a person can recover damages caused by shock unaccompanied by bodily impact.', 'a person can recover damages for harm resulting from shock caused solely by another''s peril or injury.', 'D', 'Proximate cause is “a ‘cause which in the natural and continuous sequence, unbroken by an efficient intervening cause, produces the result complained of and without which the result would not have occurred.’ ” Cruz-Mendez, 156 N.J. at 575, 722 A.2d 515 (quoting Daniel v. Dep''t of Transp., 239 N.J. Super. 563, 595, 571 A.2d 1329 (App. Div.), aff''d o.b., 79 N.J. 547, 401 A.2d 532 (1979) ). It is not enough that the injury would not have occurred but for the defendant''s negligence, where there are other contributing causes of the injury. A plaintiff must show that the negligence was a “substantial factor” contributing to the result. See Komlodi v. Picciano, 217 N.J. 387, 422, 89 A.3d 1234 (2014) (“[T]he ‘substantial factor’ test is given when there are concurrent causes potentially capable of producing the harm or injury.”); Verdicchio v. Ricca, 179 N.J. 1, 24-25, 843 A.2d 1042 (2004). “A substantial factor is one that is ‘not a remote, trivial or inconsequential cause.’ ” Komlodi, 217 N.J. at 423, 89 A.3d 1234 (quoting Model Jury Charge (Civil) § 6.13, “Proximate Cause – Where There is Claim that Concurrent Causes of Harm are Present and Claim that Specific Harm was Not Foreseeable” (approved May 1998) ).', 'mbe_612', 0, '43'),
('mbe_793', 'mbe', '793', '569', '1991-July', 'CRIM. LAW', '44', '', 'Suffering from painful and terminal cancer, Willa persuaded Harold, her husband, to kill her to end her misery. As they reminisced about their life together and reaffirmed their love for each other, Harold tried to discourage Willa from giving up. Willa insisted, however, and finally Harold held a gun to her head and killed her. The most serious degree of criminal homicide of which Harold can be legally convicted is', 'no degree of criminal homicide.', 'involuntary manslaughter.', 'voluntary manslaughter.', 'murder.', 'D', '(“[T]he difference between murder and aiding suicide generally hinges upon whether the defendant actively participates in the overt act directly causing death, or whether he merely provides the means of committing suicide.... This rule applies even where the victim has given his consent or requested the actual assistance provided.”).', 'mbe_613', 0, '44'),
('mbe_794', 'mbe', '794', '570', '1991-July', 'EVIDENCE', '45', '', 'Peterson sued Dylan for libel. After Peterson testified that Dylan wrote to Peterson''s employer that Peterson was a thief, Dylan offers evidence that Peterson once stole money from a former employer. The evidence of Peterson''s prior theft is', 'admissible, as substantive evidence to prove that Peterson is a thief.', 'admissible, but only to impeach Peterson''s credibility.', 'inadmissible, because character may not be shown by specific instances of conduct.', 'inadmissible, because such evidence is more unfairly prejudicial than probative.', 'A', 'Substantial evidence is evidence that a reasonable mind might accept as adequate to support a conclusion; it may be less than a preponderance of the evidence, but must be more than a “mere scintilla.” Upky v. Marshall Mountain, LLC, 2008 MT 90, ¶ 22, 342 Mont. 273, ¶ 22, 180 P.3d 651, ¶ 22 (citation omitted).', 'mbe_368', 0, '45'),
('mbe_795', 'mbe', '795', '571', '1991-July', 'CONST. LAW', '46', '', 'The Federal Computer Abuse Act establishes the Federal Computer Abuse Commission, authorizes the Commission to issue licenses for the possession of computers on terms that are consistent with the purposes of the act, and makes the unlicensed possession of a computer a crime. The provisions of the Federal Computer Abuse Act are inseverable. User applied to the Federal Computer Abuse Commission for a license to possess a computer. The Commission held, and User participated in, a trial-type proceeding on User''s license application. In that proceeding it was demonstrated that User repeatedly and intentionally used computers to introduce secret destructive computer programs (computer viruses) into electronic data banks without the consent of their owners. As a result, the Commission denied User''s application for a license. The license denial was based on a Commission rule authorized by the Computer Abuse Act that prohibited the issuance of computer licenses to persons who had engaged in such conduct. Nevertheless, User retained and continued to use his computer. He was subsequently convicted of the crime of unlicensed possession of a computer. On appeal, he challenges the constitutionality of the licensing provision of the Federal Computer Abuse Act. In this case, the reviewing court would probably hold that act to be', 'constitutional, because the Constitution generally authorizes Congress to enact all laws that are necessary and proper to advance the general welfare, and Congress could reasonably believe that possession of computers by people like User constitutes a threat to the general welfare.', 'constitutional, because Congress may use the authority vested in it by the commerce clause to regulate the possession of computers and the provisions of this act do not violate any prohibitory provision of the Constitution.', 'unconstitutional, because Congress may not impose a criminal penalty on action that is improper only because it is inconsistent with an agency rule.', 'unconstitutional, because the mere possession of a computer is a wholly local matter that is beyond the regulatory authority of Congress.', 'B', 'Where economic activity substantially affects interstate commerce, federal legislation regulating that activity will be sustained. U.S.C.A. Const. Art. 1, § 8, cl. 3.', 'mbe_614', 0, '46'),
('mbe_796', 'mbe', '796', '572', '1991-July', 'TORTS', '47', '', 'Defendant left her car parked on the side of a hill. Two minutes later, the car rolled down the hill and struck and injured Plaintiff. In Plaintiff''s negligence action against Defendant, Plaintiff introduced into evidence the facts stated above, which are undisputed. Defendant testified that, when she parked her car, she turned the front wheels into the curb and put on her emergency brakes, which were in good working order. She also introduced evidence that, in the weeks before this incident, juveniles had been seen tampering with cars in the neighborhood. The jury returned a verdict in favor of Defendant, and Plaintiff moved for a judgment notwithstanding the verdict. Plaintiff''s motion should be', 'granted, because it is more likely than not that Defendant''s negligent conduct was the legal cause of Plaintiff''s injuries.', 'granted, because the evidence does not support the verdict.', 'denied, because, given Defendant''s evidence, the jury was not required to draw an inference of negligence from the circumstances of the accident.', 'denied, if Defendant was in no better position than Plaintiff to explain the accident.', 'C', 'Res ipsa loquitur is a doctrine addressed to those situations where the facts or circumstances accompanying an injury by their very nature raise a presumption of negligence on the part of [the] defendant.” Bowlin v. Duke Univ., 108 N.C.App. 145, 149, 423 S.E.2d 320, 322 (1992). The doctrine of res ipsa loquitur, “ ‘in its distinctive sense, permits negligence to be inferred from the physical cause of an [injury], without the aid of circumstances pointing to the responsible human cause. Where this rule applies, evidence of the physical cause or causes of the [injury] is sufficient to carry the case to the jury on the bare question of negligence.’ ” Diehl v. Koffer, 140 N.C.App. 375, 377–78, 536 S.E.2d 359, 362 (2000) (quoting Harris v. Mangum, 183 N.C. 235, 237, 111 S.E. 177, 178 (1922)).', 'mbe_2689', 0, '47'),
('mbe_797', 'mbe', '797', '573', '1991-July', 'REAL PROP.', '48', '', 'Able conveyed Blackacre to Baker by a warranty deed. Baker recorded the deed four days later. After the conveyance but prior to Baker''s recording of the deed, Smollett properly filed a judgment against Able. The two pertinent statutes in the jurisdiction provide the following: 1) any judgment properly filed shall, for ten years from filing, be a lien on the real property then owned or subsequently acquired by any person against whom the judgment is rendered, and 2) no conveyance or mortgage of real property shall be good against subsequent purchasers for value and without notice unless the same be recorded according to law. The recording act has no provision for a grace period. Smollett joined both Able and Baker in an appropriate action to foreclose the judgment lien against Blackacre. If Smollett is unsuccessful, it will be because', 'Able''s warranty of title to Baker defeats Smollett''s claim.', 'Smollett is not a purchaser for value.', 'any deed is superior to a judgment lien.', 'four days is not an unreasonable delay in recording a deed.', 'B', '“A bona fide purchaser for value is one who without notice of another''s claim of right to, or equity in, the property prior to his acquisition of title, has paid the vendor a valuable consideration.” *661 Glaser v. Holdorf, 56 Wash.2d 204, 209, 352 P.2d 212 (1960). Where a purchaser has notice of facts sufficient to put an ordinarily prudent person on inquiry, the purchaser is on notice of all defects in title or equitable rights of others that the inquiry would have uncovered. Miebach v. Colasurdo, 102 Wash.2d 170, 175–76, 685 P.2d 1074 (1984).', 'mbe_49', 0, '48'),
('mbe_798', 'mbe', '798', '574', '1991-July', 'CONST. LAW', '49', '', 'The United States Department of Energy regularly transports nuclear materials through Centerville on the way to a nuclear weapons processing plant it operates in a nearby state. The city of Centerville recently adopted an ordinance prohibiting the transportation of any nuclear materials in or through the city. The ordinance declares that its purpose is to protect the health and safety of the residents of that city. May the Department of Energy continue to transport these nuclear materials through the city of Centerville?', 'No, because the ordinance is rationally related to the public health and safety of Centerville residents.', 'No, because the Tenth Amendment reserves to the states certain unenumerated sovereign powers.', 'Yes, because the Department of Energy is a federal agency engaged in a lawful federal function and, therefore, its activities may not be regulated by a local government without the consent of Congress.', 'Yes, because the ordinance enacted by Centerville is invalid because it denies persons transporting such materials the equal protection of the laws.', 'C', 'The Supremacy Clause restricts the power of state and local governments to regulate federal offices and officeholders. U.S. Const. art. 6, cl. 2.', 'mbe_2395', 0, '49'),
('mbe_799', 'mbe', '799', '575', '1991-July', 'CRIM. LAW', '50', '', 'Dart is charged with the statutory offense of "knowingly violating a regulation of the State Alcoholic Beverage Control Board" and specifically that he knowingly violated regulation number 345-90 issued by the State Alcoholic Beverage Control Board. That regulation prohibits the sale of alcoholic beverages to any person under the age of 18 and also prohibits the sale of any alcoholic beverage to a person over the age of 17 and under the age of 22 without the presentation of such person''s driver''s license or other identification showing the age of the purchaser to be 18 or older. The evidence showed that Dart was a bartender in a tavern and sold a bottle of beer to a person who was 17 years old and that Dart did not ask for or see the purchaser''s driver''s license or any other identification. Which of the following, if found by the jury, would be of the most help to Dart?', 'The purchaser had a driver''s license that falsely showed his age to be 21.', 'Dart had never been told he was supposed to check identification of persons over 17 and under 22 before selling them alcohol.', 'Dart did not know that the regulations classified beer as an alcoholic beverage.', 'Dart mistakenly believed the purchaser to be 24 years old.', 'D', 'Mistake of fact is a defense where the reasonable mistake of fact precludes the presence of any mental element required in that crime. La. R.S. 14:16; see State v. Converse, 529 So.2d 459, 465 (La.App. 1st Cir.), writ denied, 533 So.2d 355 (La.1988).', 'mbe_2396', 0, '50'),
('mbe_8', 'mbe', '8', '3', 'MBE-1972-78-part2', '', '9', 'A water pipe burst in the basement of Supermart, a grocery store, flooding the basement and damaging cases of canned goods on the floor. The Plumbing contractor''s workmen, in repairing the leak, knocked over several stacks of canned goods in cases, denting the cans. After settling its claims against the landlord for the water leak and against the plumbing contractor for the damage done by his workmen, Supermart put the goods on special sale. Four weeks later Dotty was shopping in Supermart. Several tables in the market were covered with assorted canned foods, all of which were dirty and dented. A sign on each of the tables read: "Damaged Cans-Half Price." Dotty was having Guest for dinner that evening and purchased two dented cans of tuna, packed by Canco, from one of the tables displaying the damaged cans. Before Guest arrived, Dotty prepared a tuna casserole which she and Guest ate. Both became ill and the medical testimony established that the illness was caused by the tuna''s being unfit for consumption. The tuna consumed by Dotty and Guest came from the case that was at the top of one of the stacks knocked over by the workmen. The tuna in undamaged cans from the same Canco shipment was fit for consumption.', 'If Guest asserts a claim against Dotty, Dotty most likely will', 'be held strictly liable in tort for serving spoiled tuna', 'be held liable only if she were negligent', 'not be held liable unless her conduct was in reckless disregard of the safety of Guest', 'not be held liable because Guest was a social visitor', 'B', 'The Indiana courts have apparently never squarely addressed the precise issue presented here.  But it has long been the rule in Indiana that the duty of care owed by a real-property owner to his social guests requires only that the host refrain from willfully, wantonly or intentionally injuring his social guests. Swanson v. Shroat, 169 Ind.App. 80, 345 N.E.2d 872 (1976); Pierce v. Walters, 152 Ind.App. 321, 283 N.E.2d 560 (1972); Fort Wayne National Bank v. Doctor, 149 Ind.App. 365, 272 N.E.2d 876 (1971).', 'mbe_5', 0, '9'),
('mbe_80', 'mbe', '80', '50', 'MBE-1972-78-part3', '', '31', '', 'Defendant visited a fellow college student, James, in James''s dormitory room. They drank some beer. James produced a box containing marijuana cigarettes and asked if Defendant wanted one. Defendant, afraid of being caught, declined and urged James to get rid of the marijuana. James refused. Shortly thereafter, both went out to get more beer, leaving the door to James''s room standing open. Making an excuse about having dropped his pen, Defendant went back into James''s room. Still apprehensive about their being caught with the marijuana cigarettes, he took the cigarettes and flushed them down the toilet. He was sure James was too drunk to notice that the cigarettes were missing. Defendant is charged with larceny and burglary (defined in the jurisdiction as breaking and entering the dwelling of another with intent to commit any felony or theft). He should be found guilty of', 'burglary only', 'larceny only', 'both burglary and larceny', 'neither burglary nor larceny', 'B', 'Despite the forgoing, the phrase “while acting in a fiduciary capacity” in section § 523(a)(4) does not qualify the terms “embezzlement” or “larceny.” In re Littleton, 942 F.2d 551, 555 (9th Cir.1991). Therefore, the elements of embezzlement or larceny must be satisfied, to find sufficient grounds for nondischargeability under § 523(a)(4). “Under federal law, embezzlement in the context of nondischargeability requires three elements: ‘(1) property rightfully in the possession of a nonowner; (2) nonowner''s appropriation of the property to a use other than which [it] was entrusted; and (3) circumstances indicating fraud.’ ” Id. (citations omitted). Larceny is the fraudulent and wrongful taking and carrying away the property of another with intent to convert such property to the taker''s use without the consent of the owner. Lucero v. Montes, 177 B.R. 325, 331 (Bankr.C.D.Cal.1994).', 'mbe_65', 0, '31'),
('mbe_800', 'mbe', '800', '576', '1991-July', 'CONTRACTS', '51', 'In a writing signed by both parties on December 1, Kranc agreed to buy from Schaff a gasoline engine for $1,000, delivery to be made on the following February 1. Through a secretarial error, the writing called for delivery on March 1, but neither party noticed the error until February 1. Before signing the agreement, Kranc and Schaff orally agreed that the contract of sale would be effective only if Kranc should notify Schaff in writing not later than January 2 that Kranc had arranged to resell the engine to a third person. Otherwise, they agreed orally, "There is no deal." On December 15, Kranc entered into a contract with Trimota to resell the engine to Trimota at a profit.', 'For this question only, assume the following facts. Kranc did not give Schaff notice of the resale until January 25, and Schaff received it by mail on January 26. Meantime, the value of the engine had unexpectedly increased about 75% since December 1, and Schaff renounced the agreement. If Kranc sues Schaff on February 2 for breach of contract, which of the following is Schaff''s best defense?', 'The secretarial error in the written delivery-term was a mutual mistake concerning a basic fact, and the agreement is voidable by either party.', 'Kranc''s not giving written notice by January 2 of his resale was a failure of a condition precedent to the existence of a contract.', 'In view of the unexpected 75% increase in value of the engine after December 1, Schaff''s performance is excused by the doctrine of commercial frustration.', 'The agreement, if any, is unenforceable because a material term was not included in the writing.', 'B', '“A condition precedent is something that is agreed must happen or be performed before a right can occur to enforce the main contract. It is one without the performance of which the contract entered into between the parties cannot be enforced.” Weinzirl v. Wells Grp., Inc., 234 Kan. 1016, 1020, 677 P.2d 1004 (1984).', 'mbe_615', 0, '51'),
('mbe_801', 'mbe', '801', '576', '1991-July', 'CONTRACTS', '52', 'In a writing signed by both parties on December 1, Kranc agreed to buy from Schaff a gasoline engine for $1,000, delivery to be made on the following February 1. Through a secretarial error, the writing called for delivery on March 1, but neither party noticed the error until February 1. Before signing the agreement, Kranc and Schaff orally agreed that the contract of sale would be effective only if Kranc should notify Schaff in writing not later than January 2 that Kranc had arranged to resell the engine to a third person. Otherwise, they agreed orally, "There is no deal." On December 15, Kranc entered into a contract with Trimota to resell the engine to Trimota at a profit.', 'For this question only, assume the following facts. On December 16, Kranc notified Schaff by telephone of Kranc''s resale agreement with Trimota, and explained that a written notice was unfeasible because Kranc''s secretary was ill. Schaff replied, "That''s okay. I''ll get the engine to you on February 1, as we agreed." Having learned, however, that the engine had increased in value about 75% since December 1, Schaff renounced the agreement on February 1. If Kranc sues Schaff on February 2 for breach of contract, which of the following concepts best supports Kranc''s claim?', 'Substantial performance.', 'Nonoccurrence of a condition subsequent.', 'Waiver of condition.', 'Novation of buyers.', 'C', 'A party may also waive a condition precedent after a breach by failing to assert its remedies for that breach. See Nat''l School Studios, Inc. v. Mealey, 211 Md. 116, 131, 126 A.2d 588, 596 (1956) (“It has been held in this State that one may waive the breach of the contract and later be bound by his election.”) (citing Key v. Dent, 6 Md. 142 (1854) and Orem v. Keelty, 85 Md. 337, 36 A. 1030 (1897)). A party''s inaction or silence is relevant, especially when that party is silent in response to a breach. See Jaworski v. Jaworski, 202 Md. 1, 10, 95 A.2d 95, 99 (1953) (“He who is silent when he ought to have spoken, will not be heard to speak when he ought to be silent.”).', 'mbe_616', 0, '52'),
('mbe_802', 'mbe', '802', '577', '1991-July', 'TORTS', '53', '', 'David owned a shotgun that he used for hunting. David knew that his old friend, Mark, had become involved with a violent gang that recently had a shoot-out with a rival gang. David, who was going to a farm to hunt quail, placed his loaded shotgun on the back seat of his car. On his way to the farm, David picked up Mark to give him a ride to a friend''s house. After dropping off Mark at the friend''s house, David proceeded to the farm, where he discovered that his shotgun was missing from his car. Mark had taken the shotgun and, later in the day, Mark used it to shoot Paul, a member of the rival gang. Paul was severely injured. Paul recovered a judgment for his damages against David, as well as Mark, on the ground that David was negligent in allowing Mark to obtain possession of the gun, and was therefore liable jointly and severally with Mark for Paul''s damages. The jurisdiction has a statute that allows contribution based upon proportionate fault and adheres to the traditional common-law rules on indemnity. If David fully satisfies the judgment, David then will have a right to recover from Mark', 'indemnity for the full amount of the judgment, because Mark was an intentional tortfeasor.', 'contribution only, based on comparative fault, because David himself was negligent.', 'one-half of the amount of the judgment.', 'nothing, because David''s negligence was a substantial proximate cause of the shooting.', 'A', 'Recognizing the correctness of these decisions, we hold that a negligent tortfeasor has a right to indemnity from an intentional joint tortfeasor. Were we to allow a negligent tortfeasor only a right to contribution from an intentional joint tortfeasor, the intentional tortfeasor effectively would receive the benefit of contribution from the negligent tortfeasor, in direct conflict with the established law in this state. While this approach allows a defendant who is causally negligent to escape from liability in some circumstances, we believe that shifting the full responsibility for the loss to the intentional tortfeasor serves the policy of deterring conduct which society considers to be substantially more egregious than negligence.', 'mbe_617', 0, '53'),
('mbe_803', 'mbe', '803', '578', '1991-July', 'CONST. LAW', '54', '', 'The legislature of the state of Chetopah enacted a statute requiring that all law enforcement officers in that state be citizens of the United States. Alien, lawfully admitted to permanent residency five years before the enactment of this statute, sought employment as a forensic pathologist in the Chetopah coroner''s office. He was denied such a job solely because he was not a citizen. Alien thereupon brought suit in federal district court against appropriate Chetopah officials seeking to invalidate this citizenship requirement on federal constitutional grounds. The strongest ground upon which to attack this citizenship requirement is that it', 'constitutes an ex postfJacto law as to previously admitted aliens.', 'deprives an alien of a fundamental right to employment without the due process of law guaranteed by the Fourteenth Amendment.', 'denies an alien a right to employment in violation of the privileges and immunities clause of the Fourteenth Amendment.', 'denies an alien the equal protection of the laws guaranteed by the Fourteenth Amendment.', 'D', 'The Court has ruled that classifications by a State that are based on alienage are “inherently suspect and subject to close judicial scrutiny.” Graham v. Richardson, 403 U.S. 365, 372, 91 S.Ct. 1848, 1852, 29 L.Ed.2d 534 (1971). See Examining Board v. Flores de Otero, 426 U.S. 572, 601-602, 96 S.Ct. 2264, 2281, 49 L.Ed.2d 65 (1976); In re Griffiths, 413 U.S., at 721, 93 S.Ct. at 2854, 37 L.Ed.2d 910; Sugarman v. Dougall, 413 U.S. 634, 642, 93 S.Ct. 2842, 2847, 37 L.Ed.2d 853 (1973). In undertaking this scrutiny, “the governmental interest claimed to justify the discrimination is to be carefully examined in order to determine whether that interest is legitimate and substantial, and inquiry must be made whether the means adopted to achieve the goal are necessary and precisely drawn.” Examining Board v. Flores de Otero, 426 U.S., at 605, 96 S.Ct., at 2283. See In re Griffths, 413 U.S., at 721-722, 93 S.Ct., at 2854-2855. Alienage classifications by a State that do not withstand this stringent examination cannot stand.8', 'mbe_2397', 0, '54'),
('mbe_804', 'mbe', '804', '579', '1991-July', 'REAL PROP.', '55', '', 'Olwen owned 80 acres of land, fronting on a town road. Two years ago, Olwen sold to Buck the back 40 acres. The 40 acres sold to Buck did not adjoin any public road. Olwen''s deed to Buck expressly granted a right-of-way over a specified strip of Olwen''s retained 40 acres, so Buck could reach the town road. The deed was promptly and properly recorded. Last year, Buck conveyed the back 40 acres to Sam. They had discussed the right-of-way over Olwen''s land to the road, but Buck''s deed to Sam made no mention of it. Sam began to use the right-of-way as Buck had, but Olwen sued to enjoin such use by Sam. The court should decide for', 'Sam, because he has an easement by implication.', 'Sam, because the easement appurtenant passed to him as a result of Buck''s deed to him.', 'Olwen, because Buck''s easement in gross was not transferable.', 'Olwen, because Buck''s deed failed expressly to transfer the right-of-way to Sam.', 'B', '“An appurtenant easement ‘is one where the land of one person, the servient [estate], is subjected to some use or burden for the benefit of the lands of another person, the dominant [estate].’ ” Id. at 399, 302 P.3d 812 (quoting Bloomfield, 224 Or.App. at 445, 199 P.3d 318). “ ‘The right is enjoyed by the owner of the dominant estate by virtue of his ownership of the land. If the dominant estate is sold or otherwise transferred to another, the easement over the servient land is transferred as well.’ ” Id. (quoting Braat v. Aylett, 278 Or. 549, 552, 564 P.2d 1030 (1977)).', 'mbe_618', 0, '55'),
('mbe_805', 'mbe', '805', '580', '1991-July', 'EVIDENCE', '56', '', 'Dickinson was charged with possession of cocaine. At Dickinson''s trial, the prosecution established that, when approached by police on a suburban residential street corner, Dickinson dropped a plastic bag and ran, and that when the police returned to the corner a few minutes later after catching Dickinson, they found a plastic bag containing white powder. Dickinson objects to introduction of this bag (the contents of which would later be established to be cocaine), citing lack of adequate identification. The objection should be\', 'overruled, because there is sufficient evidence to find that the bag was the one Dickinson dropped.', 'overruled, because the objection should have been made on the basis of incomplete chain of custody.', 'sustained, because Dickinson did not have possession of the bag at the time he was arrested.', 'sustained, unless the judge makes a finding by a preponderance of the evidence that the bag was the one dropped by Dickinson.', 'A', 'To satisfy the requirement under Rule 901(a) of the Federal Rules of Evidence that all evidence be authenticated or identified prior to admission, the proponent of the evidence must offer “evidence sufficient to support a finding that the item is what the proponent claims it is.” Rule 901(b), in turn, sets forth a non-exhaustive list of appropriate methods of authentication, including not only “[t]estimony that an item is what it is claimed to be,” Fed. R. Evid. 901(b)(1), but also “appearance, contents, substance, internal patterns, or other distinctive characteristics of the item, taken together with all the circumstances,” Fed. R. Evid. 901(b)(4), and “[e]vidence describing a process or system and showing that it produces an accurate result,” Fed. R. Evid. 901(b)(9).', 'mbe_619', 0, '56'),
('mbe_806', 'mbe', '806', '581', '1991-July', 'TORTS', '57', '', 'Chemco manufactured a liquid chemical product known as XRX. Some XRX leaked from a storage tank on Chemco''s property, seeped into the groundwater, flowed to Farmer''s adjacent property, and polluted Farmer''s well. Several of Farmer''s cows drank the polluted well water and died. If Farmer brings an action against Chemco to recover the value of the cows that died, Farmer will', 'prevail, because a manufacturer is strictly liable for harm caused by its products.', 'prevail, because the XRX escaped from Chemco''s premises.', 'not prevail, unless Farmer can establish that the storage tank was defective.', 'not prevail, unless Chemco failed to exercise reasonable care in storing the XRX.', 'B', 'The trial court''s finding that defendants knew or should have known the condition of their property was supported by evidence that they were informed in 1974 that motorcycles were trespassing on and damaging the property. The trial court''s finding on the question of causation was supported by evidence that prior to 1978 both properties possessed satisfactory drainage systems; at no time prior to 1978 did water from defendants'' property *415 drain onto plaintiffs'' property. Notwithstanding knowledge that the motorcycles were trespassing the defendants failed to take measures to stop the activity. The berms on defendants'' property broke down as a result of the trespassing.
 Defendants say the trial court erred in finding they were under a duty to inspect their property. They cite Kozloski v. Modern Litho, Inc., 182 Neb. 270, 154 N.W.2d 460, 463 (1967). A better characterization of the trial court''s holding would be that the defendants owed a duty to plaintiffs to take reasonable measures to maintain artificial conditions on their property and that, in the light of facts within their knowledge, inspection was one such reasonable measure. Kozloski held a landowner is under no independent duty to inspect property in the absence of knowledge suggesting an inspection. This seems to be consistent with the standard which the trial court here applied to defendants. Since defendants knew that motorcycle traffic was damaging their property it seems only reasonable that they should have inspected it to assess the situation and thereafter correct the damaged embankment. The trial court did not err in making this finding.', 'mbe_620', 0, '57'),
('mbe_807', 'mbe', '807', '582', '1991-July', 'EVIDENCE', '58', '', 'A threatening telephone call that purports to be from Defendant to Witness is most likely to be admitted against Defendant if', 'the caller identified himself as Defendant.', 'Witness had previously given damaging testimony against Defendant in another lawsuit.', 'Witness had given his unlisted number only to Defendant and a few other persons.', 'Witness believes that Defendant is capable of making such threats.', 'C', 'Demonstrative evidence is admissible if (1) a proper foundation is laid, by someone with personal knowledge of the thing to be demonstrated, that the demonstration is an accurate portrayal of what it purports to show, and (2) the probative value is not substantially outweighed by the danger of unfair prejudice. Id. at 342, 162 Ill.Dec. 59, 579 N.E.2d 873.', 'mbe_621', 0, '58'),
('mbe_808', 'mbe', '808', '583', '1991-July', 'CONST. LAW', '59', '', 'The open-air amphitheater in the city park of Rightville has been utilized for concerts and other entertainment programs. Until this year, each of the groups performing in that city facility was allowed to make its own arrangements for sound equipment and sound technicians. After recurring complaints from occupants of residential buildings adjacent to the city park about intrusive noise from some performances held in the amphitheater, the Rightville City Council passed an ordinance establishing city control over all sound amplification at all programs held there. The ordinance provided that Rightville''s Department of Parks would be the sole provider in the amphitheater of sound amplification equipment and of the technicians to operate the equipment "to ensure a proper balance between the quality of the sound at such performances and respect for the privacy of nearby residential neighbors." Which of the following standards should a court use to determine the constitutionality on its face of this content neutral ordinance?', 'The ordinance is narrowly tailored to serve a substantial government interest, and does not unreasonably limit alternative avenues of expression.', 'The ordinance is rationally related to a legitimate government interest, and does not unreasonably limit alternative avenues of expression.', 'The ordinance is rationally related to a legitimate government interest and restricts the expressive rights involved no more than is reasonable under the circumstances.', 'The ordinance is substantially related to a legitimate governmental interest and restricts the expressive rights involved no more than is reasonable in light of the surrounding circumstances.', 'A', '[E]ven in a public forum the government may impose reasonable restrictions on the time, place, or manner of protected speech, provided the restrictions “are justified without reference to the content of the regulated speech, that they are narrowly tailored to serve a significant governmental interest, and that they leave open ample alternative channels for communication of the information.” Clark v. Community for Creative Non–Violence, 468 U.S. 288, 293, 104 S.Ct. 3065, 3069, 82 L.Ed.2d 221 (1984); see Heffron v. International Society for Krishna Consciousness, Inc., 452 U.S. 640, 648, 101 S.Ct. 2559, 2564, 69 L.Ed.2d 298 (1981) (quoting Virginia Pharmacy Bd. v. Virginia **2754 Citizens Consumer Council, Inc., 425 U.S. 748, 771, 96 S.Ct. 1817, 1830, 48 L.Ed.2d 346 (1976)). We consider these requirements in turn.', 'mbe_622', 0, '59'),
('mbe_809', 'mbe', '809', '584', '1991-July', 'CRIM. LAW', '60', '', 'Smith and Penn were charged with murder. Each gave a confession to the police that implicated both of them. Smith later retracted her confession, claiming that it was coerced. Smith and Penn were tried together. The prosecutor offered both confessions into evidence. Smith and Penn objected. After a hearing, the trial judge found that both confessions were voluntary and admitted both into evidence. Smith testified at trial. She denied any involvement in the crime and claimed that her confession was false and the result of coercion. Both defendants were convicted. On appeal, Smith contends her conviction should be reversed because of the admission into evidence of Penn''s confession. Smith''s contention is', 'correct, unless Penn testified at trial.', 'correct, whether or not Penn testified at trial.', 'incorrect, because Smith testified in her own behalf.', 'incorrect, because Smith''s own confession was properly admitted into evidence.', 'A', 'The confession of an accomplice, made in the absence of the accused, is not competent evidence against the accused to prove their participation in the crime. Moreover, even if such a confession is made in the presence of the accused and the accused remains silent, it is still not competent unless the confession is made under such circumstances and conditions as to require the accused to speak. However, where a defendant acknowledges statements of an accomplice, the acknowledged statements become the defendant''s own confession by ratification or adoption and are admissible against the defendant, despite their claim that the inculpating remarks are hearsay.
A statement by a codefendant who is granted a separate trial may not be read into evidence at the trial of the other codefendant, where the party against whom it is offered has not had the opportunity and similar motive to develop the testimony by direct, cross, or redirect examination, to satisfy the right of confrontation.4 The United States Supreme Court has found that a nontestifying accomplice''s confession which inculpates a criminal defendant is not within a firmly rooted exception to the hearsay rule as that concept has been defined by Confrontation Clause jurisprudence. Thus, a nontestifying accomplice''s confession, in which they incriminate themselves as well as the defendant, is not sufficiently reliable to be admissible without allowing the defendant to cross-examine the accomplice, even though other evidence at trial corroborates portions of the accomplice''s statements, the police have informed the accomplice of their Miranda rights and have not promised them leniency in exchange for their statements, and the accomplice knows they are exposing themselves to criminal liability.5', 'mbe_623', 0, '60'),
('mbe_81', 'mbe', '81', '51', 'MBE-1972-78-part3', '', '32', '', 'Henry hated Wanda, his former wife, for divorcing him and marrying John a short time thereafter. About a month after Wanda married John. Henry secretly entered Wanda and John''s rented apartment during their absence by using a master key. Henry placed a microphone behind the bookstand in the bedroom of the apartment, drilled a hole in the nearby wall and poked the wires from the microphone through the hole into the space in the wall, with the result that the microphone appeared to be connected with wires going into the adjoining apartment. Actually, the microphone was not connected to anything. Henry anticipated that Wanda would discover the microphone in a few days and would be upset by the thought that someone had been listening to her conversations with John in their bedroom. Shortly thereafter, as he was putting a book on the stand, John noticed the wires behind the bookstand and discovered the hidden microphone. He then called Wanda and showed her the microphone and wires. Wanda fainted and, in falling, struck her head on the bookstand and suffered a mild concussion. The next day John telephone Henry and accused him of planting the microphone. Henry laughingly admitted it. Because of his concern about Wanda and his anger at Henry, John is emotionally upset and unable to go to work. If Wanda asserts a claim against Henry based on infliction of mental distress, the fact that John was the person who showed her the microphone will', 'relieve Henry of liability, because John was careless in so doing', 'relieve Henry of liability, because John''s conduct was the immediate cause of Wanda''s harm', 'not relieve Henry of liability, because Henry''s goal was achieved', 'not relieve Henry of liability, because the conduct of a third person is irrelevant in emotional distress cases', 'C', 'This court has previously recognized that contributory negligence is not a defense to an intentional tort. “ ‘[W]here the defendant''s conduct is actually intended to inflict *655 harm upon the plaintiff, there is a difference, not merely in degree but in the kind of fault; and the defense [contributory negligence] never has been extended to such intentional torts.’ ” **620 Omaha Nat. Bank v. Manufacturers Life Ins. Co., 213 Neb. 873, 881–82, 332 N.W.2d 196, 202 (1983), quoting William L. Prosser, Handbook of the Law of Torts § 65 (4th ed.1971).', 'mbe_2324', 0, '32'),
('mbe_810', 'mbe', '810', '585', '1991-July', 'CONST. LAW', '61', '', 'The state of Orrington wanted to prevent its only major league baseball team, the privately owned and operated Orrington Opossums, from moving to the rival state of Atrium. After a heated political debate in the legislature, Orrington enacted legislation providing for a one-time grant of $10 million in state funds to the Opossums to cover part of the projected income losses the team would suffer during the next five years if it remained in that state. The legislation required that the team remain in the state for at least ten years if it accepted the grant. After accepting the grant, the owners of the Opossums decided to build a new $150 million stadium in Orrington. As plans for the construction of the new stadium proceeded, it became evident that all of the contractors and subcontractors would be white males, and that they had been chosen by the owners of the Opossums without any public bids because these contractors and subcontractors had successfully built the only other new baseball stadium in the region. Several contractors who were females or members of minority racial groups filed suit against the owners of the Opossums in federal district court to compel public solicitation of bids for the construction of its new stadium on an equal opportunity basis, and to enjoin construction of the stadium until compliance was ensured. Their only claim was that the contracting practices of the owners of the Opossums denied them the equal protection of the laws in violation of the Fourteenth Amendment. In this suit, the court will probably rule that', 'the nexus between the actions of the owners of the Opossums and the onetime grant of monies to them by the state is sufficiently substantial to subject their actions to the limitations of the Fourteenth Amendment.', 'the intense public preoccupation with the activities of major league baseball teams coupled with the fact that baseball is considered to be our national pastime is sufficient to justify application of the Fourteenth Amendment to the activities of major league teams.', 'in the absence of additional evidence of state involvement in the operations or decisions of the owners of the Opossums, a onetime grant of state monies to them is insufficient to warrant treating their actions as subject to the limitations of the Fourteenth Amendment.', 'the issues presented by this case are nonjusticiable political questions because there is a lack of judicially manageable standards to resolve them and they are likely to be deeply involved in partisan politics.', 'C', 'Since the decision of this Court in the Civil Rights Cases, 1883, 109 U.S. 3, 3 S.Ct. 18, 27 L.Ed. 835, the principle has become firmly embedded in our constitutional law that the action inhibited by the first section of the Fourteenth Amendment is only such action as may fairly be said to be that of the States. That Amendment erects no shield against merely private conduct, however discriminatory or wrongful', 'mbe_624', 0, '61'),
('mbe_811', 'mbe', '811', '586', '1991-July', 'CONTRACTS', '62', 'Walker, who knew nothing about horses, inherited Aberlone, a thoroughbred colt whose disagreeable behavior made him a pest around the barn. Walker sold the colt for $1,500 to Sherwood, an experienced racehorse-trainer who knew of Walker''s ignorance about horses. At the time of sale, Walker said to Sherwood, "I hate to say it, but this horse is bad-tempered and nothing special."', 'For this question only, assume that soon after the sale, Aberlone won three races and earned $400,000 for Sherwood. Which of the following additional facts, if established by Walker, would best support his chance of obtaining rescission of the sale to Sherwood?', 'Walker did not know until after the sale that Sherwood was an experienced racehorse-trainer.', 'At a pre-sale exercise session of which Sherwood knew that Walker was not aware, Sherwood clocked Aberlone in record-setting time, far surpassing any previous performance.', 'Aberlone was the only thoroughbred that Walker owned, and Walker did not know how to evaluate young and untested racehorses.', 'At the time of the sale, Walker was angry and upset over an incident in which Aberlone had reared and thrown a rider.', 'B', 'rescission is a proper remedy when the breach of contract is so substantial and fundamental as to defeat the object of the parties in making the agreement', 'mbe_2398', 0, '62'),
('mbe_812', 'mbe', '812', '586', '1991-July', 'CONTRACTS', '63', 'Walker, who knew nothing about horses, inherited Aberlone, a thoroughbred colt whose disagreeable behavior made him a pest around the barn. Walker sold the colt for $1,500 to Sherwood, an experienced racehorse-trainer who knew of Walker''s ignorance about horses. At the time of sale, Walker said to Sherwood, "I hate to say it, but this horse is bad-tempered and nothing special."', 'Which one of the following scenarios would best support an action by Sherwood, rather than Walker, to rescind the sale?', 'In his first race after the sale, Aberlone galloped to a huge lead but dropped dead 100 yards from the finish line because of a rare congenital heart defect that was undiscoverable except by autopsy.', 'Aberlone won $5 million for Sherwood over a three-year racing career but upon being retired was found to be incurably sterile and useless as a breeder.', 'After Aberlone had won three races for Sherwood, it was discovered that by clerical error, unknown to either party, Aberlone''s official birth registration listed an undistinguished racehorse as the sire rather than the famous racehorse that in fact was the sire.', 'A week after the sale, Aberlone went berserk and inflicted injuries upon Sherwood that required his hospitalization for six months and a full year for his recovery.', 'A', 'It is also well settled that even if the owner proves the existence of the defects or omissions and the cost of repairing them, he is nevertheless barred from recovering the cost thereof if he accepted the work despite the patent defects or imperfections discoverable upon reasonable inspection. Acceptance, however, does not bar the owner from recovering for defects not readily discoverable by ordinary inspection, or for defects which manifest themselves subsequent to the acceptance, or for defects which are explicitly excluded from the terms of the acceptance.', 'mbe_2399', 0, '63'),
('mbe_813', 'mbe', '813', '587', '1991-July', 'REAL PROP.', '64', '', 'Sixty years ago by a properly executed and recorded deed, Albert conveyed Greenacre, a tract of land: "To Louis for life, then to Louis''s widow for her life, then to Louis''s child or children in equal shares." At that time, Louis, who was Albert''s grandson, was six years old. Shortly thereafter, Albert died testate. Louis was his only heir at law. Albert''s will left his entire estate to First Church. Twenty-five years ago, when he was 41, Louis married Maria who was then 20 years old; they had one child, Norman. Maria and Norman were killed in an automobile accident three years ago when Norman was 21. Norman died testate, leaving his entire estate to the American Red Cross. His father, Louis, was Norman''s sole heir at law. Two years ago, Louis married Zelda. They had no children. This year, Louis died testate, survived by his widow, Zelda, to whom he left his entire estate. The common-law Rule Against Perpetuities is unchanged by statute in the jurisdiction. In an appropriate action to determine the ownership of Greenacre, the court should find that title is vested in', 'First Church, because the widow of Louis was unborn at the time of conveyance and, hence, the remainder violated the Rule Against Perpetuities.', 'Zelda, because her life estate and her inheritance from Louis (who was Albert''s sole heir at law and who was Norman''s sole heir at law) merged the entire title in her.', 'the American Red Cross, because Norman had a vested remainder interest (as the only child of Louis) that it inherited, the life estate to Louis''s widow being of no force and effect.', 'Zelda for life under the terms of Albert''s deed, with the remainder to the American Red Cross as the successor in interest to Norman, Louis''s only child.', 'D', '“A life estate is a possessory estate of freehold in the real estate in which a vested remainder exists, and while the life estate continues the right to possession of the realty is in the life tenant. Present enjoyment is the very essence of a life estate. The tenant of an estate for life in real estate has the right to the full enjoyment and use of the land and of its profits during the continuance of the life estate.” Kanawha Banking & Trust Co. v. Alderson, 129 W.Va. at 517, 40 S.E.2d at 885. (Citations omitted.)', 'mbe_625', 0, '64'),
('mbe_814', 'mbe', '814', '588', '1991-July', 'EVIDENCE', '65', '', 'In an automobile collision case brought by Poe against Davies, Poe introduced evidence that Ellis made an excited utterance that Davies ran the red light. Davies called Witt to testify that later Ellis, a bystander, now deceased, told Witt that Davies went through a yellow light. Witt''s testimony should be', 'excluded, because it is hearsay not within any exception.', 'excluded, because Ellis is not available to explain or deny the inconsistency.', 'admitted only for the purpose of impeaching Ellis.', 'admitted as impeachment and as substantive evidence of the color of the light.', 'C', '“Impeachment evidence, on the other hand, is that which is offered to discredit a witness ... to reduce the effectiveness of [the] testimony by bringing forth evidence which explains why the jury should not put faith in [the] testimony.’ ” [Id.]', 'mbe_626', 0, '65'),
('mbe_815', 'mbe', '815', '589', '1991-July', 'TORTS', '66', '', 'Plaintiff, a jockey, was seriously injured in a race when another jockey, Daring, cut too sharply in front of her without adequate clearance. The two horses collided, causing Plaintiff to fall to the ground, sustaining injury. The State Racetrack Commission ruled that, by cutting in too sharply, Daring committed a foul in violation of racetrack rules requiring adequate clearance for crossing lanes. Plaintiff has brought an action against Daring for damages in which one count is based on battery. Will Plaintiff prevail on the battery claim?', 'Yes, if Daring was reckless in cutting across in front of Plaintiff''s horse.', 'Yes, because the State Racetrack Commission determined that Daring committed a foul in violation of rules applicable to racing.', 'No, unless Daring intended to cause impermissible contact between the two horses or apprehension of such contact by Plaintiff.', 'No, because Plaintiff assumed the risk of accidental injury inherent in riding as a jockey in a horse race.', 'C', 'Likewise, while allowing a recovery for a sports injury based on intentional tort, a Michigan court has stated that “[p]articipation in a game involves a manifestation of consent to those bodily contacts which are permitted by the rules of the game. Restatement of Torts, 2d, § 50, comment b. However, there is a general agreement that an intentional act causing injury, which goes beyond what is ordinarily permissible, is an assault and battery for which recovery may be had.” Overall v. Kadella (1984), 138 Mich.App. 351, 361 N.W.2d 352, 355. Thus, courts generally allow a cause of action for injuries sustained in recreational or sports activities only under reckless or intentional tort theories.', 'mbe_627', 0, '66'),
('mbe_816', 'mbe', '816', '590', '1991-July', 'REAL PROP.', '67', '', 'Able entered into a written contract with Baker to sell Greenacre. The contract was dated June 19 and called for a closing date on the following August 19. There was no other provision in the contract concerning the closing date. The contract contained the following clause: "subject to the purchaser, Baker, obtaining a satisfactory mortgage at the current rate." On the date provided for closing, Baker advised Able that he was unable to close because his mortgage application was still being processed by a bank. Able desired to declare the contract at an end and consulted his attorney in regard to his legal position. Which of the following are relevant in advising Able of his legal position? I. Is time of the essence? II. Parol evidence rule. III. Statute of Frauds. IV. Specific performance.', 'I and III only.', 'II and IV only.', 'II, III, and IV only.', 'I, II, III, and IV.', 'D', 'To regard a contract as “of the essence,” one of two conditions must be satisfied: either the contract must expressly state that time is of the essence or there must be a clear indication that the parties intended for time to be of the essence. Ferrara, 919 So.2d at 885(¶ 25).  In the absence of either condition, time will not ordinarily be considered of the essence in contract performance. Id. at (¶ 24).', 'mbe_267', 0, '67'),
('mbe_817', 'mbe', '817', '591', '1991-July', 'CRIM. LAW', '68', '', 'Lester was engaged to marry Sylvia. One evening, Lester became enraged at the comments of Sylvia''s eight-year-old daughter, Cynthia, who was complaining, in her usual fashion, that she did not want her mother to marry Lester. Lester, who had had too much to drink, began beating her. Cynthia suffered some bruises and a broken arm. Sylvia took Cynthia to the hospital. The police were notified by the hospital staff. Lester was indicted for felony child abuse. Lester pleaded with Sylvia to forgive him and to run away with him. She agreed. They moved out of state and took Cynthia with them. Without the testimony of the child, the prosecution was forced to dismiss the case. Some time later, Sylvia returned for a visit with her family and was arrested and indicted as an accessory-after-the-fact to child abuse. At her trial, the court should', 'dismiss the charge, because Lester had not been convicted.', 'dismiss the charge, because the evidence shows that any aid she rendered occurred after the crime was completed.', 'submit the case to the jury, on an instruction to convict only if Sylvia knew Lester had been indicted.', 'submit the case to the jury, on an instruction to convict only if her purpose in moving was to prevent Lester''s conviction.', 'D', '“An accessory after the fact is an offense where one knowing that an offense has been committed, receives, relieves, comforts or assists the offender in order to hinder his or her apprehension, trial or punishment.” United States v. Brown, 33 F.3d 1002, 1004 (8th Cir.1994) (internal quotations omitted).', 'mbe_628', 0, '68'),
('mbe_818', 'mbe', '818', '592', '1991-July', 'CONST. LAW', '69', '', 'In response to massive layoffs of employees of automobile assembly plants located in the state of Ames, the legislature of that state enacted a statute which prohibits the parking of automobiles manufactured outside of the United States in any parking lot or parking structure that is owned or operated by the state or any of its instrumentalities. This statute does not apply to parking on public streets. Which of the following is the strongest argument with which to challenge the constitutionality of this statute?', 'The statute imposes an undue burden on foreign commerce.', 'The statute denies the owners of foreignmade automobiles the equal protection of the laws.', 'The statute deprives the owners of foreign-made automobiles of liberty or property without due process of law.', 'The statute is inconsistent with the privileges and immunities clause of the Fourteenth Amendment.', 'A', 'The Constitution gives Congress the authority “[t]o regulate Commerce with foreign Nations, and among the several States.” U.S. Const. art. I, § 8, cl. 3. This affirmative grant of power has a negative aspect, known as the dormant Commerce Clause. See Grant''s Dairy–Me., LLC v. Comm''r of Me. Dep''t of Agric., Food & Rural Res., 232 F.3d 8, 18 (1st Cir.2000). In general, the dormant Commerce Clause “prevents state and local governments from impeding the free flow of goods from one state to another.” Houlton Citizens'' Coalition v. Town of Houlton, 175 F.3d 178, 184 (1st Cir.1999). As such, it “prohibits protectionist state regulation designed to benefit in-state economic interests by burdening out-of-state competitors.” Grant''s Dairy, 232 F.3d at 18. 
Although the language of dormant Commerce Clause jurisprudence most often concerns interstate commerce, essentially the same doctrine applies to international commerce. See Barclays Bank v. Franchise Tax Bd., 512 U.S. 298, 310 & n. 9, 114 S.Ct. 2268, 129 L.Ed.2d 244 (1994).', 'mbe_629', 0, '69'),
('mbe_819', 'mbe', '819', '593', '1991-July', 'EVIDENCE', '70', '', 'Pate sued Dr. Doke for psychiatric malpractice and called Dr. Will as an expert witness. During Will''s direct testimony, Will identified a text as a reliable authority in the field. He seeks to read to the jury passages from this book on which he had relied in forming his opinion on the proper standard of care. The passage is', 'admissible, as a basis for his opinion and as substantive evidence of the proper standard of care.', 'admissible, as a basis for his opinion but not as substantive evidence of the proper standard of care.', 'inadmissible, because a witness''s credibility cannot be supported unless attacked.', 'inadmissible, because the passage should be received as an exhibit and not read to the jury by the witness.', 'A', 'Expert testimony is necessary to establish the applicable standard of care “when the alleged negligence is of such a nature as not to be within the experience of the layman.” Id. at 90', 'mbe_630', 0, '70'),
('mbe_82', 'mbe', '82', '52', 'MBE-1972-78-part3', '', '33', 'Trease owned Hilltop in fee simple. By his will, he devised as follows: "Hilltop to such of my grandchildren who shall reach the age of_21; and by this provision I intend to include all grandchildren whenever born." At the time of his death, Trease had three children and two grandchildren.', 'Courts hold such a devise valid under the common-law Rule Against Perpetuities. What is the best explanation of that determination?', 'All of Trease''s children would be measuring lives.', 'The rule of convenience closes the class of beneficiaries when any grandchild reaches the age of 21.', 'There is a presumption that Trease intended to include only those grandchildren born prior to his death.', 'There is a subsidiary rule of construction that dispositive instruments are to be interpreted so as to uphold interests rather than to invalidate them under the Rule Against Perpetuities.', 'A', 'Rule of convenience:
Doctrine that specifies the class, as designated in a class gift, closes when a class member is entitled to a distribution of his share of the gift.', 'mbe_66', 0, '33'),
('mbe_820', 'mbe', '820', '594', '1991-July', 'TORTS', '71', '', 'The Daily Sun, a newspaper, printed an article that stated: Kitchen, the popular restaurant on the town square, has closed its doors. Kitchen employees have told the Daily Sun that the closing resulted from the owner''s belief that Kitchen''s general manager has embezzled thousands of dollars from the restaurant over the last several years. A decision on reopening the restaurant will be made after the completion of an audit of Kitchen''s books. Plaintiff, who is Kitchen''s general manager, brought a libel action against the Daily Sun based on the publication of this article. The parties stipulated that Plaintiff never embezzled any funds from Kitchen. They also stipulated that Plaintiff is well known among many people in the community because of his job with Kitchen. The case went to trial before a jury. The defendant''s motion for a directed verdict in its favor, made at the close of the evidence, should be granted if the', 'record contains no evidence that Plaintiff suffered special harm as a result of the publication.', 'record contains no evidence that the defendant was negligent as to the truth or falsity of the charge of embezzlement.', 'evidence is not clear and convincing that the defendant published the article with ''''actual malice."', 'record contains uncontradicted evidence that the article accurately reported what the employees told the Daily Sun.', 'B', 'Defendant argues that Plaintiff has failed to state a claim for defamation per se.  Under Florida law,1 to assert a claim for defamation—libel or slander—a plaintiff must establish that: “(1) the defendant published a false statement; (2) about the plaintiff; (3) to a third party; and (4) that the falsity of the statement caused injury to another.” Alan v. Wells Fargo Bank, N.A., 604 Fed. App''x 863, 865 (11th Cir. 2015)(applying Florida law). Libel (written defamation) may be proven in two ways: per se or per quod. Paulson v. Cosmetic Dermatology, Inc., Case No. 17-20094-CIV-Scola, 2017 U.S. Dist. LEXIS 88031, 2017 WL 2484197 (S.D. Fla. June 8, 2017)(citing Hoch v. Rissman, 742 So. 2d 451, 457 (Fla. 5th DA 1999) ).', 'mbe_631', 0, '71'),
('mbe_821', 'mbe', '821', '595', '1991-July', 'TORTS', '72', '', 'Surgeon performed a sterilization operation on Patient. After the surgery, Surgeon performed a test that showed that Patient''s fallopian tubes were not severed, as was necessary for sterilization. Surgeon did not reveal the failure of the operation to Patient, who three years later became pregnant and delivered a baby afflicted with a severe birth defect that will require substantial medical care throughout its life. The birth defect resulted from a genetic defect unknown to, and undiscoverable by, Surgeon. Patient brought an action on her own behalf against Surgeon, seeking to recover the cost of her medical care for the delivery of the baby, and the baby''s extraordinary future medical expenses for which Patient will be responsible. Which of the following questions is relevant to the lawsuit and currently most difficult to answer?', 'Did Surgeon owe a duty of care to the baby in respect to medical services rendered to Patient three years before the baby was conceived?', 'Can a person recover damages for a life burdened by a severe birth defect based on a physician''s wrongful failure to prevent that person''s birth from occurring?', 'Did Surgeon owe a duty to Patient to inform her that the sterilization operation had failed?', 'Is Patient entitled to recover damages for the baby''s extraordinary future medical expenses?', 'D', 'To place the issue presented in the certified question in proper context, we initially review some basic relevant concepts of compensatory damages.  Generally, a tort plaintiff is entitled to all damages proximately caused by a wrongdoer''s actions. “The basic goal in awarding damages is to fairly and adequately compensate the plaintiff for the injuries and losses sustained.” Flannery v. U.S., 171 W.Va. 27, 29, 297 S.E.2d 433, 435 (1982). Thus, “the aim of compensatory damages is to restore a plaintiff to the financial position he/she would presently enjoy but for the defendant''s injurious conduct.” Kessel v. Leavitt, 204 W.Va. 95, 187, 511 S.E.2d 720, 812 (1998).
To fulfill this overarching goal of making an injured party whole, compensatory damages include not only actual losses but also the anticipated losses due to the future effects of an injury caused by negligence. **463 *357 Future damages are “awarded to an injured party for, among other things: (1) Residuals or future effects of an injury which have reduced the capability of an individual to function as a whole man; (2) future pain and suffering; (3) loss or impairment of earning capacity; and (4) future medical expenses.” Syl. Pt. 10, Jordan v. Bero, 158 W.Va. 28, 210 S.E.2d 618 (1974). In syllabus point seven of Jordan we formally adopted the test, first articulated in Wilson v. Fleming, 89 W.Va. 553, 109 S.E. 810 (1921), for recovering future damages:
To form a legal basis for recovery of future permanent consequences of the negligent infliction of a personal injury, it must appear with reasonable certainty that such consequences will result from the injury; contingent or merely possible future injurious effects are too remote and speculative to support a lawful recovery.', 'mbe_632', 0, '72'),
('mbe_822', 'mbe', '822', '596', '1991-July', 'CRIM. LAW', '73', '', 'Robert walked into a store that had a checkcashing service and tried to cash a $550 check which was payable to him. The attendant on duty refused to cash the check because Robert did not have two forms of identification, which the store''s policies required. Robert, who had no money except for the check and who needed cash to pay for food and a place to sleep, became agitated. He put his hand into his pocket and growled, "Give me the money or I''ll start shooting." The attendant, who knew Robert as a neighborhood character, did not believe that he was violent or had a gun. However, because the attendant felt sorry for Robert, he handed over the cash. Robert left the check on the counter and departed. The attendant picked up the check and found that Robert had failed to endorse it. If Robert is guilty of any crime, he is most likely guilty of', 'robbery.', 'attempted robbery.', 'theft by false pretenses.', 'larceny by trick.', 'B', '“An attempt in criminal law is an unfinished crime and is composed of two elements, the intent to commit the *25 crime and the doing of some direct act toward its consummation, but falling short of the accomplishment of the ultimate design.” Johnson v. Commonwealth, 209 Va. 291, 293, 163 S.E.2d 570, 573 (1968).', 'mbe_633', 0, '73'),
('mbe_823', 'mbe', '823', '597', '1991-July', 'CONTRACTS', '74', 'Kabb, the owner of a fleet of taxis, contracted with Petrol, a dealer in petroleum products, for the purchase and sale of Kabb''s total requirements of gasoline and oil for one year. As part of that agreement, Petrol also agreed with Kabb that for one year Petrol would place all his advertising with Ada Artiste, Kabb''s wife, who owned her own small advertising agency. When Artiste was informed of the Kabb-Petrol contract, she declined to accept an advertising account from the Deturgid Soap Company because she could not handle both the Petrol and Deturgid accounts during the same year.', 'For this question only, assume the following facts. During the first month of the contract, Kabb purchased substantial amounts of his gasoline from a supplier other than Petrol, and Petrol thereupon notified Artiste that he would no longer place his advertising with her agency. In an action against Petrol for breach of contract, Artiste probably will', 'succeed, because she is a third-party beneficiary of the Kabb-Petrol contract.', 'succeed, because Kabb was acting as Artiste''s agent when he contracted with Petrol.', 'not succeed, because the failure of a constructive condition precedent excused Petrol''s duty to place his advertising with Artiste.', 'not succeed, because Artiste did not provide any consideration to support Petrol''s promise to place his advertising with her.', 'C', '“Conditions can be expressed or implied. Express conditions are those agreed to and imposed by the parties themselves.  Implied or constructive conditions are those ‘imposed by law to do justice’ (Calamari and Perillo, Contracts § 11–8, at 444 [3d ed.] ). Express conditions must be literally performed, whereas constructive conditions, which ordinarily arise from language of promise, are subject to the precept that substantial compliance is sufficient. The importance of the distinction has been explained by Professor Williston: ‘Since an express condition ... depends for its validity on the manifested intention of the parties, it has the same sanctity as the promise itself. Though the court may regret the harshness of such a condition, as it may regret the harshness of a promise, it must, nevertheless, generally enforce the will of the *297 parties unless to do so will violate public policy. Where, however, the law itself has imposed the condition, in absence of or irrespective of the manifested intention of the parties, it can deal with **540 its creation as it pleases, shaping the boundaries of the constructive condition in such a way as to do justice and avoid hardship’. (5 Williston, Contracts § 669, at 154 [3d ed.].)” Oppenheimer & Co. v. Oppenheim, Appel, Dixon & Co., 86 N.Y.2d 685, 690–691, 636 N.Y.S.2d 734, 660 N.E.2d 415 [1995].', 'mbe_634', 0, '74'),
('mbe_824', 'mbe', '824', '597', '1991-July', 'CONTRACTS', '75', 'Kabb, the owner of a fleet of taxis, contracted with Petrol, a dealer in petroleum products, for the purchase and sale of Kabb''s total requirements of gasoline and oil for one year. As part of that agreement, Petrol also agreed with Kabb that for one year Petrol would place all his advertising with Ada Artiste, Kabb''s wife, who owned her own small advertising agency. When Artiste was informed of the Kabb-Petrol contract, she declined to accept an advertising account from the Deturgid Soap Company because she could not handle both the Petrol and Deturgid accounts during the same year.', 'For this question only, make the following assumptions. Artiste was an intended beneficiary under the Kabb-Petrol contract. Kabb performed his contract with Petrol for six months, and during that time Petrol placed his advertising with Artiste. At the end of the six months, Kabb and Artiste were divorced, and Kabb then told Petrol that he had no further obligation to place his advertising with Artiste. Petrol thereupon notified Artiste that he would no longer place his advertising with her. In an action against Petrol for breach of contract, Artiste probably will', 'succeed, because, on the facts of this case, Petrol and Kabb could not, without Artiste''s consent, modify their contract so as to discharge Petrol''s duties to Artiste.', 'succeed, because Kabb acted in bad faith in releasing Petrol from his duty with respect to Artiste.', 'not succeed, because, absent a provision in the contract to the contrary, the promisor and promisee of a third-party beneficiary contract retain by law the right to modify or terminate the contract.', 'not succeed, because the agency relationship, if any, between Kabb and Artiste terminated upon their divorce.', 'A', 'Black letter law, as expressed in the Second Restatement, provides that a contract''s intended beneficiary may enforce the contract''s original terms even if the contractual parties agree to change those terms.  See *815 Restatement (Second) of Contracts § 304 (1981) (“A promise in a contract creates a duty in the promisor to any intended beneficiary to perform the promise, and the intended beneficiary may enforce the duty.”); id. § 311(1) (“Discharge or modification of a duty to an intended beneficiary by conduct of the promisee or by a subsequent agreement between promisor and promisee is ineffective if a term of the promise creating the duty so provides.”); id. §§ 311(2)–(3) (providing that the “power to discharge or modify the duty” to the intended beneficiary “terminates when the beneficiary ... materially changes his position in justifiable reliance on the promise”); see also Price v. Pierce, 823 F.2d 1114, 1121–22 (7th Cir.1987) (approvingly citing § 311 as reflecting the federal common law of contracts regarding third-party beneficiaries). The Second Restatement ''s view of a third-party beneficiary''s rights governs here.', 'mbe_635', 0, '75'),
('mbe_825', 'mbe', '825', '598', '1991-July', 'TORTS', '76', '', 'Drew, the owner of a truck leasing company, asked Pat, one of Drew''s employees, to deliver $1,000 to the dealership''s main office. The following week, as a result of a dispute over whether the money had been delivered, Drew instructed Pat to come to the office to submit to a lie detector test. When Pat reported to Drew''s office for the test, it was not administered. Instead, without hearing Pat''s story, Drew shouted at him, "You''re a thief!" and fired him. Drew''s shout was overheard by several other employees who were in another office, which was separated from Drew''s office by a thin partition. The next day, Pat accepted another job at a higher salary. Several weeks later, upon discovering that the money had not been stolen, Drew offered to rehire Pat. In a suit for slander by Pat against Drew, Pat will', 'prevail, because Pat was fraudulently induced to go to the office for a lie detector test, which was not, in fact, given.', 'prevail, if Drew should have foreseen that the statement would be overheard by other employees.', 'not prevail, if Drew made the charge in good faith, believing it to be true.', 'not prevail, because the statement was made to Pat alone and intended for his ears only.', 'B', 'Under New York Law, there are four elements necessary to establish a prima facie case of slander: “(1) an oral defamatory statement of fact, (2) regarding the plaintiff, (3) published to a third party by the defendant, and (4) injury to the plaintiff.” *415 See Weldy, 985 F.2d at 61.', 'mbe_636', 0, '76'),
('mbe_826', 'mbe', '826', '599', '1991-July', 'REAL PROP.', '77', '', 'Adam owns his home, Blackacre, which was mortgaged to Bank by a duly recorded purchase money mortgage. Last year, Adam replaced all of Blackacre''s old windows with new windows. Each new window consists of a window frame with three inserts: regular windows, storm windows, and screens. The windows are designed so that each insert can be easily inserted or removed from the window frame without tools to adjust to seasonal change and to facilitate the cleaning of the inserts. The new windows were expensive. Adam purchased them on credit, signed a financing statement, and granted a security interest in the windows to Vend, the supplier of the windows. Vend promptly and properly filed and recorded the financing statement before the windows were installed. Adam stored the old windows in the basement of Blackacre. This year, Adam has suffered severe financial reverses and has defaulted on his mortgage obligation to Bank and on his obligation to Vend. Bank brought an appropriate action to enjoin Vend from its proposed repossession of the window inserts. In the action, the court should rule for', 'Bank, because its mortgage was recorded first.', 'Bank, because windows and screens, no matter their characteristics, are an integral part of a house.', 'Vend, because the inserts are removable.', 'Vend, because the availability of the old windows enables Bank to return Blackacre to its original condition.', 'C', 'Accordingly, tenants are necessary parties to a foreclosure action (see 6820 Ridge Realty v. Goldman, 263 A.D.2d 22, 25, 701 N.Y.S.2d 69; Polish Natl. Alliance of Brooklyn v. White Eagle Hall Co., 98 A.D.2d 400, 404, 470 N.Y.S.2d 642).', 'mbe_2690', 0, '77'),
('mbe_827', 'mbe', '827', '600', '1991-July', 'EVIDENCE', '78', '', 'In a suit by Palmer against Denby, Palmer sought to subpoena an audiotape on which Denby had narrated his version of the dispute for his attorney. Counsel for Denby moves to quash the subpoena on the ground of privilege. The audiotape is most likely to be subject to subpoena if', 'Denby played the audiotape for his father to get his reactions.', 'the lawsuit involved alleged criminal behavior by Denby.', 'Denby has been deposed and there is good reason to believe that the audiotape may contain inconsistent statements.', 'Denby is deceased and thus unavailable to give testimony in person.', 'A', '(1) Where legal advice of any kind is sought (2) from a professional legal adviser in his capacity as such, (3) the communications relating to that purpose, (4) made in confidence (5) by the client, (6) are at his insistence permanently protected (7) from disclosure by himself or by the legal adviser, (8) unless the protection be waived.', 'mbe_637', 0, '78'),
('mbe_828', 'mbe', '828', '601', '1991-July', 'CONST. LAW', '79', '', 'The National Ecological Balance Act prohibits the destruction or removal of any wild animals located on lands owned by the United States without express permission from the Federal Bureau of Land Management. Violators are subject to fines of up to $1,000 per offense. After substantial property damage was inflicted on residents of the state of Arkota by hungry coyotes, the state legislature passed the Coyote Bounty Bill, which offers $25 for each coyote killed or captured within the state. The Kota National Forest, owned by the federal government, is located entirely within the state of Arkota. Many coyotes live in the Kota National Forest. Without seeking permission from the Bureau of Land Management, Hunter shot several coyotes in the Kota National Forest and collected the bounty from the state of Arkota. As a result, he was subsequently tried in federal district court, convicted, and fined $1,000 for violating the National Ecological Balance Act. Hunter appealed his conviction to the United States Court of Appeals. On appeal, the Court of Appeals should hold the National Ecological Balance Act, as applied to Hunter, to be', 'constitutional, because the property clause of Article IV, Section 3, of the Constitution authorizes such federal statutory controls and sanctions.', 'constitutional, because Article I, Section 8, of the Constitution authorizes Congress to enact all laws necessary and proper to advance the general welfare.', 'unconstitutional, because Congress may not use its delegated powers to override the Tenth Amendment right of the state of Arkota to legislate in areas of traditional state governmental functions, such as the protection of the property of its residents.', 'unconstitutional, because Congress violates the full faith and credit clause of Article IV when it punishes conduct that has been authorized by state action.', 'A', 'This failure is hardly surprising, for the Clause, in broad terms, gives Congress the power to determine what are “needful” rules “respecting” the public lands. United States v. San Francisco, 310 U.S., at 29-30, 60 S.Ct., at 756; Light v. United States, 220 U.S., at 537, 31 S.Ct., at 488; United States v. Gratiot, 14 Pet., at 537-538. And while the furthest reaches of the power granted by the Property Clause have not yet been definitively resolved, we have repeatedly observed that “(t)he power over the public land thus entrusted to Congress is without limitations.” United States v. San Francisco, supra, 310 U.S., at 29, 60 S.Ct., at 756. See Ivanhoe Irr. Dist. v. McCracken, 357 U.S. 275, 294-295, 78 S.Ct. 1174, 1185, 2 L.Ed.2d 1313 (1958); Alabama v. Texas, 347 U.S. 272, 273, 74 S.Ct. 481, 98 L.Ed. 689 (1954); FPC v. Idaho Power Co., 344 U.S. 17, 21, 73 S.Ct. 85, 87, 97 L.Ed. 15 (1952); United States v. California, 332 U.S. 19, 27, 67 S.Ct. 1658, 1662, 91 L.Ed. 1889 (1947); **2292 Gibson v. Chouteau, 13 Wall 92, 99, 20 L.Ed. 534 (1872); United States v. Gratiot, supra, 14 Pet., at 537.', 'mbe_2400', 0, '79'),
('mbe_829', 'mbe', '829', '602', '1991-July', 'CRIM. LAW', '80', '', 'A kidnapping statute in State A makes it a crime for a person, including a parent, to "take a child from the custody of his custodial parent, knowing he has no privilege to do so." After a bitter court battle Ann and Dave were divorced and Ann was given custody of their daughter, Maria. Dave later moved to State B where he brought an action to obtain custody of Maria. A local judge awarded him custody. His attorney incorrectly advised him that, under this award, he was entitled to take Maria away from Ann. Dave drove to State A, picked Maria up at her preschool, and took her back to State B with him. He was indicted for kidnapping in State A, extradited from State B, and tried. At trial, he testified that he had relied on his attorney''s advice in taking Maria, and that at the time he believed his conduct was not illegal. If the jury believes his testimony, Dave should be', 'acquitted, because he acted on the advice of an attorney.', 'acquitted, because he lacked a necessary mental element of the crime.', 'convicted, because reliance on an attorney''s advice is not a defense.', 'convicted, provided a reasonable person would have known that the attorney''s advice was erroneous.', 'B', 'While continuing to argue that the advice of defendant''s civil attorney was irrelevant, the state conceded that good-faith reliance on the advice of counsel could be relevant to the issue of intent when intent is an element of the charged crime. The state did argue that if defendant''s attorney''s advice was, for instance, “this is breaking the law but you can go ahead and do it as I think you can get away with it,” or something to that effect, the reliance would not be in good faith and not relevant on the issue of intent. The state conceded, however, that if defendant''s attorney had made a good-faith determination that defendant''s actions were legal and later it was determined that his research was flawed, his advice would be relevant on the issue of intent. However, the state still continues to claim that counsel''s advice is irrelevant because the state argues that “scienter” is an element of conspiracy on the two counts against defendant, but insisted that scienter goes to the “intent to commit the specific bad act that is an essential element of the crime,” not the conspiracy itself. The defense argues that scienter is an essential element of conspiracy on the two counts against defendant and that the state is required to prove “intent to conspire.” We conclude the state is required to prove “intent to conspire.” Thus, the attorney''s advice, if in good faith, is relevant on the issue of intent to conspire to procuring unlawful voting and to commit forgery.
We conclude that good-faith reliance on the advice of counsel is an available defense when intent is an element of the charged crime.', 'mbe_2691', 0, '80'),
('mbe_83', 'mbe', '83', '52', 'MBE-1972-78-part3', '', '34', 'Trease owned Hilltop in fee simple. By his will, he devised as follows: "Hilltop to such of my grandchildren who shall reach the age of_21; and by this provision I intend to include all grandchildren whenever born." At the time of his death, Trease had three children and two grandchildren.', 'Which of the following additions to or changes in the facts of the preceding question would produce a violation of the common-law Rule Against Perpetuities?', 'A posthumous child was born to Trease.', 'Trease''s will expressed the intention to include all afterborn grandchildren in the gift.', 'The instrument was an inter vivos conveyance rather than a will.', 'Trease had no grandchildren living at the time of his death.', 'C', 'An inter vivos transfer is a transfer of property made during a person''s lifetime. It can be contrasted with a testamentary transfer, which is a transfer made in a will after death.', 'mbe_67', 0, '34'),
('mbe_830', 'mbe', '830', '603', '1991-July', 'REAL PROP.', '81', '', 'Owen, the owner of Greenacre, a tract of land, mortgaged Greenacre to ABC Bank to secure his preexisting obligation to ABC Bank. The mortgage was promptly and properly recorded. Owen and Newton then entered into a valid written contract for the purchase and sale of Greenacre, which provided for the transfer of "a marketable title, free of encumbrances." The contract did not expressly refer to the mortgage. Shortly after entering into the contract, Newton found another property that much better suited her needs and decided to try to avoid her contract with Owen. When Newton discovered the existence of the mortgage, she asserted that the title was encumbered and that she would not close. Owen responded by offering to provide for payment and discharge of the mortgage at the closing from the proceeds of the closing. Newton refused to go forward, and Owen brought an appropriate action against her for specific performance. If the court holds for Owen in this action, it will most likely be because', 'the mortgage is not entitled to priority because it was granted for preexisting obligations.', 'the doctrine of equitable conversion supports the result.', 'Owen''s arrangements for the payment of the mortgage fully satisfied Owen''s obligation to deliver marketable title.', 'the existence of the mortgage was not Newton''s real reason for refusing to close.', 'C', '“The test of the marketability of a title is ‘whether there is an objection thereto such as would interfere with a sale or with the market value of the property.’ ” Id. at 571, 606 N.Y.S.2d 132, 626 N.E.2d 917 (quoting Regan v. Lanze, 40 N.Y.2d 475, 387 N.Y.S.2d 79, 354 N.E.2d 818 [1976] ). “A marketable title is ‘a title free from reasonable doubt, but not from every doubt.’ ” Id. (quoting same). The New York Court of Appeals explained in Voorheesville that a “ ‘purchaser ought not to be compelled to take property, the possession or title of which he may be obliged to defend by litigation. He should have a title that will enable him to hold his land free from probable claim by another, and one which, if he wishes to sell, would be reasonably free from any doubt which would interfere with its market value.’ ” (quoting Dyker Meadow Land & Improvement Co. v. Cook, 159 N.Y. 6, 15, 53 N.E. 690 [1899] ).', 'mbe_638', 0, '81'),
('mbe_831', 'mbe', '831', '604', '1991-July', 'EVIDENCE', '82', '', 'Pawn sued Dalton for injuries received when she fell down a stairway in Dalton''s apartment building. Pawn, a guest in the building, alleged that she caught the heel of her shoe in a tear in the stair carpet. Pawn calls Witt, a tenant, to testify that Young, another tenant, had said to him a week before Pawn''s fall: "When I paid my rent this morning, I told the manager he had better fix that torn carpet." Young''s statement, reported by Witt, is', 'admissible, to prove that the carpet was defective.', 'admissible, to prove that Dalton had notice of the defect.', 'admissible, to prove both that the carpet was defective and that Dalton had notice of the defect.', 'inadmissible, because it is hearsay not within any exception.', 'D', '“Hearsay is an assertion of fact or belief made out of court and offered to prove the truth of the matter asserted.” Mercer v. United States, 864 A.2d 110, 117 (D.C.2004).', 'mbe_2401', 0, '82'),
('mbe_832', 'mbe', '832', '605', '1991-July', 'CONST. LAW', '83', '', 'A law of the state of Wonatol imposed a generally applicable sales tax payable by the vendor. That law exempted from its provisions the sale of "all magazines, periodicals, newspapers, and books." In order to raise additional revenue, the state legislature eliminated that broad exemption and substituted a narrower exemption. The new, narrower exemption excluded from the state sales tax only the sale of those "magazines, periodicals, newspapers, and books that are published or distributed by a recognized religious faith and that consist wholly of writings sacred to such a religious faith." Magazine is a monthly publication devoted to history and politics. Magazine paid under protest the sales tax due on its sales according to the amended sales tax law. Magazine then filed suit against the state in an appropriate state court for a refund of the sales taxes paid. It contended that the state''s elimination of the earlier, broader exemption and adoption of the new, narrower exemption restricted to sacred writings of recognized religious faiths violates the First and Fourteenth Amendments to the Constitution. In this case, the court will probably rule that', 'Magazine lacks standing to sue for a refund of sales taxes imposed by a generally applicable state law because Article III of the Constitution precludes taxpayers from bringing such suits.', 'the Eleventh Amendment bars the state court from exercising jurisdiction over this suit in the absence of a law of Wonatol expressly waiving the state''s immunity.', 'the new, narrower exemption from the state sales tax law violates the establishment clause of the First and Fourteenth Amendments by granting preferential state support to recognized religious faiths for the communication of their religious beliefs.', 'the new, narrower exemption from the state sales tax law violates the freedom of the press guaranteed by the First and Fourteenth Amendments because it imposes a prior restraint on nonreligious publications that are required to pay the tax.', 'C', '[A] program violates the Establishment Clause when it allows or requires “the government itself ... through its own activities and influences” to advance or inhibit religion. Madison v. Riter, 355 F.3d 310, 318 (4th Cir.2003) (quoting Corporation of Presiding Bishop v. Amos, 483 U.S. 327, 337, 107 S.Ct. 2862, 97 L.Ed.2d 273 (1987)). Accordingly, when striking a balance between the call of duty and the strictures of the Establishment Clause, state officers must maintain a position of “benevolent neutrality which will permit religious exercise to exist without sponsorship and without interference.” Amos, 483 U.S. at 334, 107 S.Ct. 2862.', 'mbe_2692', 0, '83'),
('mbe_833', 'mbe', '833', '606', '1991-July', 'EVIDENCE', '85', '', 'Defendant was prosecuted for bankruptcy fraud. Defendant''s wife, now deceased, had testified adversely to Defendant during earlier bankruptcy proceedings that involved similar issues. Although the wife had been crossexamined, no serious effort was made to challenge her credibility despite the availability of significant impeachment information. At the fraud trial, the prosecutor offers into evidence the testimony given by Defendant''s wife at the bankruptcy proceeding. This evidence should be', 'admitted, under the hearsay exception for former testimony.', 'admitted, because it is a statement by a person identified with a party.', 'excluded, because it is hearsay not within any exception.', 'excluded, because Defendant has the right to prevent use of his spouse''s testimony against him in a criminal case.', 'A', 'If a witness who testified at a former trial or hearing of a criminal case is available to testify at a subsequent trial or hearing of that case, his or her testimony at the former proceeding is ordinarily inadmissible1 against the accused under the fundamental principle that the accused is constitutionally entitled to be confronted with the witnesses against him or her.
However, in criminal cases, if the declarant is unavailable as a witness, former testimony is admissible hearsay if given as a witness at another hearing of the same or a different proceeding, and if the party against whom the testimony is now offered had an opportunity and similar motive to develop the testimony by direct, cross, or redirect examination, or if the testimony was taken in a deposition and is offered in accordance with the governing provisions of the Code of Criminal Procedure.', 'mbe_639', 0, '85'),
('mbe_834', 'mbe', '834', '607', '1991-July', 'CONTRACTS', '86', 'Mermaid owns an exceptionally seaworthy boat that she charters for sport fishing at a $500 daily rate. The fee includes the use of the boat with Mermaid as the captain, and one other crew member, as well as fishing tackle and bait. On May 1, Phinney agreed with Mermaid that Phinney would have the full-day use of the boat on May 15 for himself and his family for $500. Phinney paid an advance deposit of $200 and signed an agreement that the deposit could be retained by Mermaid as liquidated damages in the event Phinney canceled or failed to appear.', 'For this question only, assume the following facts. At the time of contracting, Mermaid told Phinney to be at the dock at 5 a.m. on May 15. Phinney and his family, however, did not show up on May 15 until noon. Meantime, Mermaid agreed at 10 a.m. to take Tess and her family out fishing for the rest of the day. Tess had happened to come by and inquire about the possibility of such an outing. In view of the late hour, Mermaid charged Tess $400 and stayed out two hours beyond the customary return time. Phinney''s failure to appear until noon was due to the fact that he had been trying to charter another boat across the bay at a lower rate and had gotten lost after he was unsuccessful in getting such a charter. Which of the following is an accurate statement concerning the rights of the parties?', 'Mermaid can retain the $200 paid by Phinney, because it would be difficult for Mermaid to establish her actual damages and the sum appears to have been a reasonable forecast in light of anticipated loss of profit from the charter.', 'Mermaid is entitled to retain only $50 (10% of the contract price) and must return $150 to Phinney.', 'Mermaid must return $100 to Phinney in order to avoid her own unjust enrichment at Phinney''s expense.', 'Mermaid must return $100 to Phinney, because the liquidated-damage clause under the circumstances would operate as a penalty.', 'A', 'To be entitled to damages based upon an anticipatory breach, the nonbreaching party must establish its ability to perform at the time of the breach. Hosp. Mortg. Grp. v. First Prudential Dev. Corp., 411 So.2d 181, 182–83 (Fla.1982); see also Craigside, LLC v. GDC View, LLC, 74 So.3d 1087, 1090 (Fla. 1st DCA 2011) (quoting Restatement (Second) of Contracts § 253 (1979)). The rationale for this rule is that “[t]he holder of the duty based upon a condition precedent cannot profit from an anticipatory repudiation of a contract that he would have breached himself.” Hosp. Mortg. Grp., 411 So.2d at 183.', 'mbe_640', 0, '86'),
('mbe_835', 'mbe', '835', '607', '1991-July', 'CONTRACTS', '87', 'Mermaid owns an exceptionally seaworthy boat that she charters for sport fishing at a $500 daily rate. The fee includes the use of the boat with Mermaid as the captain, and one other crew member, as well as fishing tackle and bait. On May 1, Phinney agreed with Mermaid that Phinney would have the full-day use of the boat on May 15 for himself and his family for $500. Phinney paid an advance deposit of $200 and signed an agreement that the deposit could be retained by Mermaid as liquidated damages in the event Phinney canceled or failed to appear.', 'For this question only, assume the following facts. On May 15 at 1 a.m., the Coast Guard had issued offshore "heavy weather" warnings and prohibited all small vessels the size of Mermaid''s from leaving the harbor. This prohibition remained in effect throughout the day. Phinney did not appear at all on May 15, because he had heard the weather warnings on his radio. Which of the following is an accurate statement?', 'The contract is discharged because of impossibility, and Phinney is entitled to return of his deposit.', 'The contract is discharged because of mutual mistake concerning an essential fact, and Phinney is entitled to return of his deposit.', 'The contract is not discharged, because its performance was possible in view of the exceptional seaworthiness of Mermaid''s boat, and Phinney is not entitled to return of his deposit.', 'The contract is not discharged, and Phinney is not entitled to return of his deposit, because the liquidated-damage clause in effect allocated the risk of bad weather to Phinney.', 'A', '“Actual damages” are “[a]n amount awarded to a complainant to compensate for a proven injury or loss; damages that repay actual losses.—Also termed compensatory damages.” Black''s Law Dictionary (7th ed. 1999) (emphasis in original). In turn, “compensatory damages” are “[d]amages sufficient in *202 amount to indemnify the injured person for the loss suffered.” Id. Here, although defendant improperly deducted 6 percent from the pre-Measure 8 plaintiffs'' wages, the jury''s verdict indicates that those plaintiffs suffered actual damages in the amount of .3 percent of their wages.', 'mbe_641', 0, '87'),
('mbe_836', 'mbe', '836', '608', '1991-July', 'REAL PROP.', '88', '', 'Eight years ago, Orben, prior to moving to a distant city, conveyed Blackacre, an isolated farm, to his son, Sam, by a quitclaim deed. Sam paid no consideration. Sam, who was 19 years old, without formal education, and without experience in business, took possession of Blackacre and operated the farm but neglected to record his deed. Subsequently, Orben conveyed Blackacre to Fred by warranty deed. Fred, a substantial land and timber promoter, paid valuable consideration for the deed to him. He was unaware of Sam''s possession, his quitclaim deed, or his relationship to Orben. Fred promptly and properly recorded his deed and began removing timber from the land. Immediately upon learning of Fred''s actions, Sam recorded his deed and brought an appropriate action to enjoin Fred from removing the timber and to quiet title in Sam. The recording act of the jurisdiction provides: "No conveyance or mortgage of real property shall be good against subsequent purchasers for value and without notice unless the same be recorded according to law." In this action, Fred should', 'prevail, because a warranty deed for valuable consideration takes priority over a quitclaim deed without consideration.', 'prevail, because Orben''s subsequent conveyance to Fred revoked the gift to Sam.', 'lose, because Sam''s possession charged Fred with notice.', 'lose, because the equities favor Sam.', 'C', 'A quitclaim deed is, by definition, “[a] deed that conveys a grantor''s complete interest or claim in certain real property but that neither warrants nor professes *378 that the title is valid.” Again, then, the deed at issue in Epworth showed the grantor''s intent to convey all its interest in the property and lacked any language indicating that the grantor intended to convey merely an easement.', 'mbe_642', 0, '88'),
('mbe_837', 'mbe', '837', '609', '1991-July', 'REAL PROP.', '89', '', 'Brown owned Blackacre, a tract of undeveloped land. Blackacre abuts Whiteacre, a tract of land owned by Agency, the state''s governmental energy agency. At Whiteacre, Agency has operated a waste-to-electricity recycling facility for 12 years. Blackacre and Whiteacre are in a remote area and Whiteacre is the only developed parcel of real estate within a ten-mile radius. The boundary line between Blackacre and Whiteacre had never been surveyed or marked on the face of the earth. During the past 12 years, some of the trucks bringing waste to the Agency facility have dumped their loads so that the piles of waste extend from Whiteacre onto a portion of Blackacre. However, prior to the four-week period during each calendar year when the Agency facility is closed for inspection and repairs, the waste piles are reduced to minimal levels so that during each of the four-week closures no waste was, in fact, piled on Blackacre. Neither Brown nor any representative of Agency knew the facts about the relation of the boundary line to the waste piles. The time for acquiring title by adverse possession in the jurisdiction is ten years. Last year, Brown died, and his son, Silas, succeeded him as the owner of Blackacre. Silas became aware of the facts, demanded that Agency stop using Blackacre for the piling of waste, and, when Agency refused his demand, brought an appropriate action to enjoin any such use of Blackacre in the future. If Agency prevails in that action, it will be because', 'the facts constitute adverse possession and title to the portion of Blackacre concerned has vested in Agency.', 'Brown''s failure to keep himself informed as to Agency''s use of Blackacre and his failure to object constituted implied consent to the continuation of that use.', 'the interest of the public in the conversion of waste to energy overrides any entitlement of Silas to equitable remedies.', 'the power of eminent domain of the state makes the claim of Silas moot.', 'A', '“Adverse possession” is defined as “an actual and visible appropriation of real property, commenced and continued under a claim of right that is inconsistent with and is hostile to the claim of another person.” Terrill v. Tuckness, 985 S.W.2d 97, 107 (Tex.App.-San Antonio 1998, no pet.), quoting TEX.CIV.PRAC. & REM.CODE ANN. § 16.021(1). Possession must not only be actual, but also visible, continuous, notorious, distinct, *328 hostile (i.e., adverse), and of such a character as to indicate unmistakably an assertion of a claim of exclusive ownership in the occupant. Rhodes v. Cahill, 802 S.W.2d 643, 645 (Tex.1990); see also TEX.CIV.PRAC. & REM.CODE ANN. § 16.021(1). Exclusive possession of the land is required to support an adverse possession claim, and joint or common possession by the claimant and the property owner defeats the requisite exclusiveness. West End API Ltd. v. Rothpletz, 732 S.W.2d 371, 375–6 (Tex.App.-Dallas 1987, writ ref''d n.r.e.), citing Rick v. Grubbs, 147 Tex. 267, 214 S.W.2d 925, 927 (Tex.1948).', 'mbe_643', 0, '89'),
('mbe_838', 'mbe', '838', '610', '1991-July', 'EVIDENCE', '90', '', 'Defendant was charged with possession of cocaine with intent to distribute. He had been stopped while driving a car and several pounds of cocaine were found in the trunk. In his opening statement, defendant''s counsel asserted that his client had no key to the trunk and no knowledge of its contents. The prosecutor offers the state motor vehicle registration, shown to have been found in the glove compartment of the car, listing Defendant as the owner. The registration should be', 'admitted, as a statement against interest.', 'admitted, as evidence of Defendant''s close connection with the car and, therefore, knowledge of its contents.', 'excluded, unless authenticated by testimony of or certification by a state official charged with custody of vehicle registration records.', 'excluded, as hearsay not within any exception.', 'B', 'NRS 48.015  “Relevant evidence” defined.  As used in this chapter, “relevant evidence” means evidence having any tendency to make the existence of any fact that is of consequence to the determination of the action more or less probable than it would be without the evidence.', 'mbe_2693', 0, '90'),
('mbe_839', 'mbe', '839', '611', '1991-July', 'CRIM. LAW', '91', '', 'Donald was arrested in Marilyn''s apartment after her neighbors had reported sounds of a struggle and the police had arrived to find Donald bent over Marilyn''s prostrate body. Marilyn was rushed to the hospital where she lapsed into a coma. Despite the explanation that he was trying to revive Marilyn after she suddenly collapsed, Donald was charged with attempted rape and assault after a neighbor informed the police that she had heard Marilyn sobbing, "No, please no, let me alone." At trial, the forensic evidence was inconclusive. The jury acquitted Donald of attempted rape but convicted him of assault. While he was serving his sentence for assault, Marilyn, who had never recovered from the coma, died. Donald was then indicted and tried on a charge of felony murder. In this common-law jurisdiction, there is no statute that prevents a prosecutor from proceeding in this manner, but Donald argued that a second trial for felony murder after his original trial for attempted rape and assault would violate the double jeopardy clause. His claim is', 'correct, because he was acquitted of the attempted rape charge.', 'correct, because he was convicted of the assault charge.', 'incorrect, because Marilyn had not died at the time of the first trial and he was not placed in jeopardy for murder.', 'incorrect, because he was convicted of the assault charge.', 'A', 'The United States Constitution and the Washington State Constitution provide that the State may not put a criminal defendant in jeopardy twice for the same offense. U.S. Const. amend. V; Wash. Const. art. 1, § 9; State v. Corrado, 81 Wash.App. 640, 645, 915 P.2d 1121, (1996), review denied, 138 Wash.2d 1011, 989 P.2d 1138 (1999). “Generally, [double jeopardy] bars trial if three elements are met: (a) jeopardy previously attached, (b) jeopardy previously terminated, and (c) the defendant is again in jeopardy ‘for the same offense.‘” Corrado, 81 Wn. App. at 645 (quoting United States v. Dixon, 509 U.S. 688, 113 S. Ct. 2849, 125 L. Ed. 2d 556 (1993). The issue here is whether jeopardy terminated on the second degree intentional murder charge.', 'mbe_644', 0, '91'),
('mbe_84', 'mbe', '84', '53', 'MBE-1972-78-part3', '', '35', 'Victim, injured by Driver in an auto accident, employed attorney First to represent him in the matter. Victim was chronically insolvent and expressed doubt whether he could promptly get necessary medical treatment. Accordingly, First wrote into their contract his promise to Victim "to pay from any settlementtwith Driver compensation to any physician who provides professional services for Victim''s injuries." The contract also provided that First''s duties were "''nonassignable." First immediately filed suit against Driver. Victim then sought and received medical treatment, reasonably valued at S1,000, from Doctor, but failed to inform Doctor of First''s promise. After receiving a bill from Doctor for $1,000, Victim immediately wrote Doctor explaining that he was unable to pay and enclosing a copy of his contract with First. Victim then asked First about payment of this bill, but First requested a release from their employment contract. stating that he would like to refer Victim''s claim to attorney Second and that Second was willing to represent Victim in the pending lawsuit. Victim wrote a letter to First releasing him from their contract and agreeing to Second''s representation. A copy of this letter was sent to Doctor. Second subsequently promised First to represent Victim and soon negotiated a settlement of Victim''s claim against Driver which netted $1,000, all of which was paid by Victim to creditors other than Doctor. Victim remains insolvent.', 'In an action by Doctor against Victim to recover $1,000, Doctor''s best theory ofrecovery is that Doctor', 'is a creditor beneficiary of the employment contract between Victim and First', 'is a donee beneficiary of the employment contract between Victim and First', 'provided services essential to the preservation of Victim''s health', 'has a claim based upon an implied-in-fact contract with Victim', 'D', '“A person is a donee beneficiary if the purpose of the promisee in obtaining the promise of all or part of the performance thereof is to make a gift to the beneficiary or to confer upon him a right against the promisor to some performance neither due nor supposed nor asserted to be due from the promisee to the beneficiary.” Id. “A person is a creditor beneficiary if the performance of the promise will satisfy an actual or supposed or asserted duty of the promisee to the beneficiary.” Id. “Finally, if the person is neither a donee beneficiary nor a creditor beneficiary, he is an incidental beneficiary.”', 'mbe_68', 0, '35'),
('mbe_840', 'mbe', '840', '612', '1991-July', 'REAL PROP.', '92', '', 'Ogle owned Greenacre, a tract of land, in fee simple. Five years ago, he executed and delivered to Lilly an instrument in the proper form of a warranty deed that conveyed Greenacre to Lilly "for and during the term of her natural life." No other estate or interest or person taking an interest was mentioned. Lilly took possession of Greenacre and has remained in possession. Fifteen months ago, Ogle died, leaving a will that has been duly admitted to probate. The will, inter alia, had the following provision: "I devise Greenacre to Mina for her natural life and from and after Mina''s death to Rex, his heirs and assigns, forever." Administration of Ogle''s estate has been completed. Mina claims the immediate right to possession of Greenacre. Rex also asserts a right to immediate possession. In an appropriate lawsuit to which Lilly, Mina, and Rex are parties, who should be adjudged to have the right to immediate possession?', 'Lilly, because no subsequent act of Ogle would affect her life estate.', 'Mina, because Ogle''s will was the final and definitive expression of his intent.', 'Mina, because Lilly''s estate terminated with the death of Ogle.', 'Rex, because Lilly''s estate terminated with Ogle''s death and all that Ogle had was the right to transfer his reversion in fee simple.', 'A', 'To establish adverse possession, the claimant must prove: (1) possession under claim of right or color of title; (2) actual, open, and notorious occupation of *1033 the premises constituting reasonable notice to the true owner; (3) possession which is adverse and hostile to the true owner; (4) continuous possession for at least five years; and (5) payment of all taxes assessed against the property during the five-year period.” (Mehdizadeh, supra, 46 Cal.App.4th at p. 1305, 54 Cal.Rptr.2d 284.)', 'mbe_645', 0, '92'),
('mbe_841', 'mbe', '841', '613', '1991-July', 'CRIM. LAW', '93', '', 'Devlin was charged with murder. Several witnesses testified that the crime was committed by a person of Devlin''s general description who walked with a severe limp. Devlin in fact walks with a severe limp. He objected to a prosecution request that the court order him to walk across the courtroom in order to display his limp to the jury to assist it in determining whether Devlin was the person that the witnesses had seen. Devlin''s objection will most likely be', 'sustained, because the order sought by the prosecution would violate Devlin''s privilege against self-incrimination.', 'sustained, because the order sought by the prosecution would constitute an illegal search and seizure.', 'denied, because the order sought by the prosecution is a legitimate part of a proper courtroom identification process.', 'denied, because a criminal defendant has no legitimate expectation of privacy.', 'C', 'In determining whether identification procedures violate a defendant''s due process rights, the required inquiry is made on an ad hoc basis and is two-pronged: first, it must be determined whether the identification procedure was unnecessarily suggestive; and second, if it is found to have been so, it must be determined whether the identification was nevertheless reliable 148 based on examination of the totality of the circumstances. (Internal quotation marks omitted.) State v. Marquez, 291 Conn. 122, 141, 967 A.2d 56, cert. denied, 558 U.S. 895, 130 S.Ct. 237, 175 L.Ed.2d 163 (2009).
The first suggestiveness prong involves the circumstances of the identification procedure itself … and the critical question is whether the procedure was conducted in such a manner as to emphasize or highlight the individual whom the police believe is the suspect. … If the trial court determines that there was no unduly suggestive identification procedure, that is the end of the analysis, and the identification evidence is admissible. … If the court finds there was an unduly suggestive procedure, the court goes on to address the second reliability prong, under which the corruptive effect of the suggestive procedure is weighed against certain factors, such as the opportunity of the [eyewitness] to view the criminal at the time of the crime, the [eyewitness''] degree of attention, the accuracy of [the eyewitness''] prior description of the criminal, the level of certainty demonstrated at the [identification] and the time between the crime and the [identification]. (Citations omitted; internal quotation marks omitted.) State v. Dickson, supra, 322 Conn. at 421, 141 A.3d 810.', 'mbe_646', 0, '93'),
('mbe_842', 'mbe', '842', '614', '1991-July', 'CONST. LAW', '94', '', 'A statute of the state of Kiowa provided state monetary grants to private dance, theater, and opera groups located in that state. The statute required recipients of such grants to use the granted monies for the acquisition, construction, and maintenance of appropriate facilities for the public performance of their performing arts. The last section of the statute conditioned the award of each such grant on the recipient''s agreement to refrain from all kinds of political lobbying calculated to secure additional tax support for the performing arts. The strongest constitutional basis for an attack upon the validity of the last section of the statute would be based upon the', 'commerce clause.', 'obligation of contracts clause.', 'Fifth Amendment.', 'First and Fourteenth Amendments.', 'D', '[P]olitical activity is protected free speech under the First Amendment . . . . See Falco, 767 Fed. App''x at 305.', 'mbe_2402', 0, '94'),
('mbe_843', 'mbe', '843', '615', '1991-July', 'TORTS', '95', '', 'Penkov suffered a severe loss when his manufacturing plant, located in a shallow ravine, was flooded during a sustained rainfall. The flooding occurred because City had failed to maintain its storm drain, which was located on City land above Penkov''s premises, and because Railroad had failed to maintain its storm drain, which was located on Railroad land below Penkov''s premises. The flooding would not have occurred if either one of the two storm drains had been maintained properly. Penkov sued Railroad to recover compensation for his loss. The evidence in the case established that the failures of the two drains were caused by the respective negligence of City and Railroad. There is no special rule insulating City from liability. In his action against Railroad, Penkov should recover', 'nothing, because he should have joined City, without whose negligence he would have suffered no loss.', 'nothing, unless he introduces evidence that enables the court reasonably to apportion responsibility between City and Railroad.', 'one-half his loss, in the absence of evidence that enables the court to allocate responsibility fairly between City and Railroad.', 'all of his loss, because but for Railroad''s negligence none of the flooding would have occurred.', 'D', 'Causation as an element of any negligence action consists of two components, but-for causation and proximate cause. “But-for causation requires the existence of a direct, distinct, and identifiable nexus between the defendant’s breach of duty (negligence) and the plaintiff''s damages such that the event would not have occurred ‘but for’ the defendant’s negligent or wrongful conduct in breach of a duty.” Patton, 529 S.W.3d at 730.
The second component, proximate causation, “captures the notion that, although conduct in breach of an established duty may be an actual but-for cause of the plaintiff’s damages, it is nevertheless too attenuated from the damages in time, place, or foreseeability to reasonably impose liability upon the defendant.” Id. at 731. It is “bottomed on public policy as a limitation on how far society is willing to extend liability for a defendant''s actions[.]” Id. (quoting Ashley County, Arkansas v. Pfizer, Inc., 552 F.3d 659, 671 (8th Cir. 2009) ).', 'mbe_647', 0, '95'),
('mbe_844', 'mbe', '844', '616', '1991-July', 'CRIM. LAW', '96', '', 'Smith asked Jones if he would loan him $500, promising to repay the amount within two weeks. Jones loaned him the $500. The next day Smith took the money to the race track and lost all of it betting on horse races. He then left town for six months. He has not repaid Jones. Smith has committed', 'both larceny by trick and obtaining money by false pretenses (although he can only be convicted of one offense).', 'larceny by trick only.', 'obtaining money by false pretenses only.', 'neither larceny by trick nor obtaining money by false pretenses.', 'D', 'The elements of theft by trick and device are: “(1) the obtaining of the possession of the property of another by some trick or device; (2) the intent by the person so obtaining possession to convert it to his own use and to permanently deprive the owner of it; and (3) that the owner, although parting with possession to such person, does not intend to transfer his title to that person.”', 'mbe_648', 0, '96'),
('mbe_845', 'mbe', '845', '617', '1991-July', 'CONST. LAW', '97', '', 'Assume that Congress passed and the President signed the following statute: "The appellate jurisdiction of the United States Supreme Court shall not extend to any case involving the constitutionality of any state statute limiting the circumstances in which a woman may obtain an abortion, or involving the constitutionality of this statute." The strongest argument against the constitutionality of this statute is that', 'Congress may not exercise its authority over the appellate jurisdiction of the Supreme Court in a way that seriously interferes with the establishment of a supreme and uniform body of federal constitutional law.', 'Congress may only regulate the appellate jurisdiction of the Supreme Court over cases initially arising in federal courts.', 'the appellate jurisdiction of the Supreme Court may only be altered by constitutional amendment.', 'the statute violates the equal protection clause of the Fourteenth Amendment.', 'A', 'The Constitution provides that the judicial power of the United States shall be vested in one Supreme Court and such inferior courts as the Congress shall from time to time ordain and establish. The same instrument, in the last clause of the same article, provides that in all cases other than those of original jurisdiction, ‘the Supreme Court shall have appellate jurisdiction both as to law and fact, with such exceptions and under such regulations as the Congress shall make.’', 'mbe_2694', 0, '97'),
('mbe_846', 'mbe', '846', '618', '1991-July', 'CONST. LAW', '98', '', 'The federal statute admitting the state of Blue to the Union granted Blue certain public lands, and established some very ambiguous conditions on the subsequent disposition of these lands by Blue. This federal statute also required the new state to write those exact same conditions into its state constitution. One hundred years later, a statute of Blue dealing with the sale of these public lands was challenged in a state court lawsuit on the ground that it was inconsistent with the conditions contained in the federal statute, and with the provisions of the Blue Constitution that exactly copy the conditions contained in the federal statute. The trial court decision in this case was appealed to the Blue Supreme Court. In its opinion, the Blue Supreme Court dealt at length with the ambiguous language of the federal statute and with cases interpreting identical language in federal statutes admitting other states to the union. The Blue Supreme Court opinion did not discuss the similar provisions of the Blue Constitution, but it did hold that the challenged Blue statute is invalid because it is "inconsistent with the language of the federal statute and therefore is inconsistent with the identical provisions of our state constitution." If the losing party in the Blue Supreme Court seeks review of the decision of that court in the United States Supreme Court, the United States Supreme Court should', 'accept the case for review and determine the validity and interpretation of the federal statute if it is an important and substantial question.', 'ask the Blue Supreme Court to indicate more clearly whether it relied on the state constitutional provision in rendering its decision.', 'decline to review the case on the ground that the decision of the Blue Supreme Court rests on an adequate and independent state ground.', 'decline to review the case because a decision by a state supreme court concerning the proper disposition of state public lands is not reviewable by the United States Supreme Court.', 'A', 'Under that doctrine the Supreme Court “will not review a question of federal law decided by a state court if the decision of that court rests on a state law ground that is independent of the federal question and adequate to support the judgment.” Coleman v. Thompson, 501 U.S. 722, 729, 111 S.Ct. 2546, 115 L.Ed.2d 640 (1991).', 'mbe_649', 0, '98'),
('mbe_847', 'mbe', '847', '619', '1991-July', 'CONTRACTS', '99', '', 'Trawf, the manager of a state fair, contracted with Schweinebauch, a renowned hog breeder, to exhibit Schweinebauch''s world champion animal, Megahawg, for the three weeks of the annual fair, at the conclusion of which Schweinebauch would receive an honorarium of $300. Two days before the opening of the fair, Megahawg took sick with boarsitis, a communicable disease among swine, and, under the applicable state quarantine law, very probably could not be exhibited for at least a month. Upon learning this, Trawf can legally pursue which of the following courses of action with respect to his contract with Schweinebauch?', 'Suspend his own performance, demand assurances from Schweinebauch, and treat a failure by Schweinebauch to give them as an actionable repudiation.', 'Suspend his own performance and recover damages from Schweinebauch for breach of contract unless Schweinebauch at once supplies an undiseased hog of exhibition quality as a substitute for Megahawg.', 'Terminate his own performance and treat Megahawg''s illness as discharging all remaining duties under the contract.', 'Terminate the contract, but only if he (Trawf) seeks promptly to obtain for the exhibit a suitable substitute for Megahawg from another hog owner.', 'C', '“ ‘Under the contractual defense of impossibility, an obligation is deemed discharged if an unforeseen event occurs after formation of the contract and without fault of the obligated party, which event makes performance of the obligation impossible or highly impracticable.’ ” Robinson, 2010 UT App 96, ¶ 12, 232 P.3d 1081 (emphases omitted) (quoting Western Props., 776 P.2d at 658); see also Restatement (Second) of Contracts § 261 (1981) (“Where, after a contract is made, a party''s performance is made impracticable without his fault by the occurrence of an event the non-occurrence of which was a basic assumption on which the contract was made, his duty to render that performance is discharged, unless the language or the circumstances indicate the contrary.”).', 'mbe_2403', 0, '99'),
('mbe_848', 'mbe', '848', '620', '1991-July', 'TORTS', '100', '', 'The manager of a department store noticed that Paula was carrying a scarf with her as she examined various items in the blouse department. The manager recognized the scarf as an expensive one carried by the store. Paula was trying to find a blouse that matched a color in the scarf, and, after a while, found one. The manager then saw Paula put the scarf into her purse, pay for the blouse, and head for the door. The manager, who was eight inches taller than Paula, blocked Paula''s way to the door and asked to see the scarf in Paula''s purse. Paula produced the scarf, as well as a receipt for it, showing that it had been purchased from the store on the previous day. The manager then told Paula there was no problem, and stepped out of her way. If Paula brings a claim against the store based on false imprisonment, the store''s best defense would be that', 'by carrying the scarf in public view and then putting it into her purse, Paula assumed the risk of being detained.', 'the manager had a reasonable belief that Paula was shoplifting and detained her only briefly for a reasonable investigation of the facts.', 'Paula should have realized that her conduct would create a reasonable belief that facts existed warranting a privilege to detain.', 'Paula was not detained, but was merely questioned about the scarf.', 'B', 'A merchant may detain a suspected shoplifter without incurring liability if the storekeeper has reasonable cause to believe that the person shoplifted and if the detention is performed in a reasonable manner and for a reasonable length of time. A.R.S. § 13-1805; Gortarez v. Smitty''s Super Valu, Inc., 140 Ariz. 97, 103-05, 680 P.2d 807, 813-15 (1984). If the facts and reasonable inferences therefrom are not subject to material dispute, reasonable cause is a question of law to be determined by the court. Koepnick v. Sears Roebuck & Co., 158 Ariz. 322, 326, 762 P.2d 609, 613 (App.1988); see also Gortarez, 140 Ariz. at 104, 680 P.2d at 814.', 'mbe_650', 0, '100'),
('mbe_849', 'mbe', '849', '621', '1991-July', 'CONST. LAW', '101', '', 'A proposed federal statute would prohibit all types of discrimination against black persons on the basis of their race in every business transaction executed anywhere in the United States by any person or entity, governmental or private. Is this proposed federal statute likely to be constitutional?', 'Yes, because it could reasonably be viewed as an exercise of Congress''s authority to enact laws for the general welfare.', 'Yes, because it could reasonably be viewed as a means of enforcing the provisions of the Thirteenth Amendment.', 'No, because it would regulate purely local transactions that are not in interstate commerce.', 'No, because it would invade the powers reserved to the states by the Tenth Amendment.', 'B', 'Our case law firmly establishes Congress'' power to regulate purely local activities that are part of an economic “class of activities” that have a substantial effect on interstate commerce. See, e.g., Perez, 402 U.S., at 151, 91 S.Ct. 1357; Wickard v. Filburn, 317 U.S. 111, 128–129, 63 S.Ct. 82, 87 L.Ed. 122 (1942). As we stated in Wickard, “even if appellee''s activity be local and though it may not be regarded as commerce, it may still, whatever its nature, be reached by Congress if it exerts a substantial economic effect on interstate commerce.” Id., at 125, 63 S.Ct. 82. We have never required Congress to legislate with scientific exactitude. When Congress decides that the “ ‘total incidence’ ” of a practice poses a threat to a national market, it may regulate the entire class. See Perez, 402 U.S., at 154–155, 91 S.Ct. 1357 ( “ ‘[W]hen it is necessary in order to prevent an evil to make the law embrace more than the precise thing to be prevented it may do so’ ”(quoting Westfall v. United States, 274 U.S. 256, 259, 47 S.Ct. 629, 71 L.Ed. 1036 (1927))). In this vein, we have reiterated that when “ ‘a general regulatory statute bears a substantial relation to commerce, the de minimis character of individual instances arising under that statute is of no consequence.’ ” E.g., Lopez, 514 U.S., at 558, 115 S.Ct. 1624 (quoting Maryland v. Wirtz, 392 U.S. 183, 196, n. 27, 88 S.Ct. 2017, 20 L.Ed.2d 1020 (1968); emphasis deleted).', 'mbe_651', 0, '101'),
('mbe_85', 'mbe', '85', '53', 'MBE-1972-78-part3', '', '36', 'Victim, injured by Driver in an auto accident, employed attorney First to represent him in the matter. Victim was chronically insolvent and expressed doubt whether he could promptly get necessary medical treatment. Accordingly, First wrote into their contract his promise to Victim "to pay from any settlementtwith Driver compensation to any physician who provides professional services for Victim''s injuries." The contract also provided that First''s duties were "''nonassignable." First immediately filed suit against Driver. Victim then sought and received medical treatment, reasonably valued at S1,000, from Doctor, but failed to inform Doctor of First''s promise. After receiving a bill from Doctor for $1,000, Victim immediately wrote Doctor explaining that he was unable to pay and enclosing a copy of his contract with First. Victim then asked First about payment of this bill, but First requested a release from their employment contract. stating that he would like to refer Victim''s claim to attorney Second and that Second was willing to represent Victim in the pending lawsuit. Victim wrote a letter to First releasing him from their contract and agreeing to Second''s representation. A copy of this letter was sent to Doctor. Second subsequently promised First to represent Victim and soon negotiated a settlement of Victim''s claim against Driver which netted $1,000, all of which was paid by Victim to creditors other than Doctor. Victim remains insolvent.', 'In an action by Doctor against First upon First''s employment contract with Victim, First is likely to argue in defense that', 'the anti-assignment clause in First''s contract with Victim is void as against public policy', 'First has relied to his detriment on Victim''s letter of release', 'third parties cannot acquire valid claims under an attorney-client contract', 'Doctor has not materially changed his position in reliance upon First''s employment contract', 'D', 'Thus, in order to successfully assert a claim for detrimental reliance, a plaintiff must establish: “(1) a representation by conduct or word; (2) justifiable reliance; and (3) a change in position to one''s detriment because of the reliance.” **11 Luther v. IOM Co. LLC, 13–353, pp. 10–11 (La.10/15/13), 130 So.3d 817, 825.', 'mbe_69', 0, '36'),
('mbe_850', 'mbe', '850', '622', '1991-July', 'CRIM. LAW', '102', '', 'Sam told Horace, his neighbor, that he was going away for two weeks and asked Horace to keep an eye on his house. Horace agreed. Sam gave Horace a key to use to check on the house. Horace decided to have a party in Sam''s house. He invited a number of friends. One friend, Lewis, went into Sam''s bedroom, took some of Sam''s rings, and put them in his pocket. Which of the following is true?', 'Horace and Lewis are guilty of burglary.', 'Horace is guilty of burglary and Lewis is guilty of larceny.', 'Horace is guilty of trespass and Lewis is guilty of larceny.', 'Lewis is guilty of larceny and Horace is not guilty of any crime.', 'D', 'Larceny is the fraudulent and wrongful taking and carrying away the property of another with intent to convert such property to the taker''s use without the consent of the owner. Lucero v. Montes, 177 B.R. 325, 331 (Bankr.C.D.Cal.1994). ;  ‘[A]n accomplice is one who aids or promotes the perpetrator''s crime with knowledge of the perpetrator''s unlawful purpose and an intent to assist in the commission of the target crime....’ [Citation.] ‘In order to be an accomplice, the witness must be chargeable with the crime as a principal (§ 31) and not merely as an accessory after the fact (§§ 32, 33).’ [Citation.]” (People v. McKinzie (2012) 54 Cal.4th 1302, 1353, 144 Cal.Rptr.3d 427, 281 P.3d 412.)', 'mbe_2404', 0, '102'),
('mbe_851', 'mbe', '851', '623', '1991-July', 'TORTS', '103', '', 'John''s father, Jeremiah, died in Hospital. Hospital maintains a morgue with refrigerated drawers a bit larger than a human body. Jeremiah''s body was placed in such a drawer awaiting pickup by a mortician. Before the mortician called for the body, a Hospital orderly placed two opaque plastic bags in the drawer with Jeremiah''s body. One bag contained Jeremiah''s personal effects, and the other contained an amputated leg from some other Hospital patient. It is stipulated that Hospital was negligent to allow the amputated leg to get into Jeremiah''s drawer. The mortician delivered the two opaque plastic bags to John, assuming both contained personal effects. John was shocked when he opened the bag containing the amputated leg. John sued Hospital to recover for his emotional distress. At the trial, John testified that the experience had been extremely upsetting, that he had had recurring nightmares about it, and that his family and business relationships had been adversely affected for a period of several months. He did not seek medical or psychiatric treatment for his emotional distress. Who should prevail?', 'John, because of the sensitivity people have regarding the care of the bodies of deceased relatives.', 'John, because hospitals are strictly liable for mishandling dead bodies.', 'Hospital, because John did not require medical or psychiatric treatment.', 'Hospital, because John suffered no bodily harm.', 'A', 'The Court will address these various arguments in turn. First, the Court reaffirms its analysis found in its earlier Order denying the various Defendants'' Motions to Dismiss State Law Claims as it relates to the “Carney” exception to NIED under Ohio law (See doc. 283). The following is an extensive quote from this Court''s *953 previous Order (doc. 283), analyzing this issue:
“... Plaintiffs note that the Ohio Supreme Court in Heiner stated:
We note, in passing, that there does exist some case law in this state recognizing certain exceptions to the actual-peril requirement. See e.g., Carney v. Knollwood Cemetery Assn., 33 Ohio App.3d 31, 33–34, 514 N.E.2d 430, 432–33 (permitting recovery for negligent infliction of emotional distress where defendants were responsible for desecration of a grave.)”
Heiner at 670 n. 3. The court in Carney held that a claim for “abuse of a dead body has long been recognized in this country.” Carney at 432 citing Brownlee v. Pratt, 77 Ohio App. 533, 68 N.E.2d 798, 800–01 (1946). Carney notes that recognition of this claim has existed since “ancient times” and that the existence of “infliction of serious emotional distress” is a relatively new phenomenon Id. Mental anguish will undoubtedly result from the mishandling of a corpse, notes Carney. Id. at 433. Carney also states that:', 'mbe_652', 0, '103'),
('mbe_852', 'mbe', '852', '624', '1991-July', 'REAL PROP.', '104', '', 'Able was the owner of Greenacre, a large tract of land. Able entered into a binding written contract with Baker for the sale and purchase of Greenacre for $125,000. The contract required Able to convey marketable record title. Baker decided to protect his interest and promptly and properly recorded the contract. Thereafter, but before the date scheduled for the closing, Charlie obtained and properly filed a final judgment against Able in the amount of $1 million in a personal injury suit. A statute in the jurisdiction provides: "Any judgment properly filed shall, for ten years from filing, be a lien on the real property then owned or subsequently acquired by any person against whom the judgment is rendered." The recording act of the jurisdiction authorizes recording of contracts and also provides: "No conveyance or mortgage of real property shall be good against subsequent purchasers for value and without notice unless the same be recorded according to law." There are no other relevant statutory provisions. At the closing, Baker declined to accept the title of Able on the ground that Charlie''s judgment lien encumbered the title he would receive and rendered it unmarketable. Able brought an appropriate action against Baker for specific performance of the contract and joined Charlie as a party. In this action, the judgment should be for', 'Able, because in equity a purchaser takes free of judgment liens.', 'Able, because the contract had been recorded.', 'Baker, because Able cannot benefit from Baker''s action in recording the contract.', 'Baker, because the statute creating judgment liens takes precedence over the recording act.', 'B', '“[A] judgment lien can attach only to whatever interest the debtor has in the property. If he has no interest, then no lien can attach.” Romero v. State, 1982-NMSC-028, ¶ 15, 97 N.M. 569, 642 P.2d 172 (citing 2 A.C. Freeman, A Treatise of the Law of Judgments § 950 (5th ed. 1925)).', 'mbe_653', 0, '104'),
('mbe_853', 'mbe', '853', '625', '1991-July', 'EVIDENCE', '105', '', 'Post sued Dint for dissolution of their yearlong partnership. One issue concerned the amount of money Post had received in cash. It was customary for Dint to give Post money from the cash register as Post needed it for personal expenses. Post testified that, as he received money, he jotted down the amounts in the partnership ledger. Although Dint had access to the ledger, he made no changes in it. The ledger was admitted into evidence. Dint seeks to testify to his memory of much larger amounts he had given Post. Dint''s testimony is', 'admissible, because it is based on Dint''s firsthand knowledge.', 'admissible, because the ledger entries offered by a party opponent opened the door.', 'inadmissible, because the ledger is the best evidence of the amounts Post received.', 'inadmissible, because Dint''s failure to challenge the accuracy of the ledger constituted an adoptive admission.', 'A', '“Unlike an ordinary witness ... an expert is permitted wide latitude to offer opinions, including those that are not based on firsthand knowledge or observation.” Daubert, 509 U.S. at 592, 113 S.Ct. at 2796. “[T]his relaxation of the usual requirement of firsthand knowledge ... is premised on an assumption that the expert''s opinion will have a reliable basis in the knowledge and experience of his discipline.” Id. A trial court assessing the reliability of an expert''s evidence must therefore perform a “gatekeeping” function by conducting “a preliminary assessment of whether the reasoning or methodology underlying the testimony is scientifically valid and of whether that reasoning or methodology properly can be applied to the facts in issue.” Id. at 592–93, 113 S.Ct. at 2796. We have offered district courts the following general guidance in determining whether to admit scientific evidence under Daubert:', 'mbe_654', 0, '105'),
('mbe_854', 'mbe', '854', '626', '1991-July', 'CONTRACTS', '106', '', 'In a signed writing, Nimrod contracted to purchase a 25-foot travel trailer from Trailco for $15,000, cash on delivery no later than June 1. Nimrod arrived at the Trailco sales lot on Sunday, May 31, to pay for and take delivery of the trailer, but refused to do so when he discovered that the spare tire was missing. Trailco offered to install a spare tire on Monday when its service department would open, but Nimrod replied that he did not want the trailer and would purchase another one elsewhere. Which of the following is accurate?', 'Nimrod had a right to reject the trailer, but Trailco was entitled to a reasonable opportunity to cure the defect.', 'Nimrod had a right to reject the trailer and terminate the contract under the perfect tender rule.', 'Nimrod was required to accept the trailer, because the defect could be readily cured.', 'Nimrod was required to accept the trailer, because the defect did not substantially impair its value.', 'A', 'Generally, under the Uniform Commercial Code''s perfect tender rule, the buyer may reject a seller''s tender for any trivial defect, whether it be in the quality of the goods, the timing of performance, or the manner of delivery. Therefore, where the seller of a mobile home failed to perfectly perform his obligation under the plain terms of the parties'' contract to deliver title at closing, under the perfect tender rule, the buyer was entitled to reject the seller''s tender, where the contract unambiguously stated that title was due at closing, but instead of the title, the seller delivered the manufacturer''s certificate of origin. It was neither pretextual nor commercially unreasonable for buyer of mobile home to reject seller''s delivery of manufacturer''s certificate of origin at closing as imperfect tender, where parties'' contract unambiguously stated that title, not certificate, was due at closing, and seller''s delivery of certificate required buyer to pay sales tax, thereby adding $1,806 to buyer''s contractual obligation.', 'mbe_655', 0, '106'),
('mbe_855', 'mbe', '855', '627', '1991-July', 'REAL PROP.', '107', '', 'Oker owned in fee simple two adjoining lots, Lots 1 and 2. He conveyed in fee simple Lot 1 to Frank. The deed was in usual form of a warranty deed with the following provision inserted in the appropriate place: "Grantor, for himself, his heirs and assigns, does covenant and agree that any reasonable expense incurred by grantee, his heirs and assigns, as the result of having to repair the retaining wall presently situated on Lot 1 at the common boundary with Lot 2, shall be reimbursed one-half the costs of repairs; and by this provision the parties intend a covenant running with the land." Frank conveyed Lot 1 in fee simple to Sara by warranty deed in usual and regular form. The deed omitted any reference to the retaining wall or any covenant. Fifty years after Oker''s conveyance to Frank, Sara conveyed Lot 1 in fee simple to Tim by warranty deed in usual form; this deed omitted any reference to the retaining wall or the covenant. There is no statute that applies to any aspect of the problems presented except a recording act and a statute providing for acquisition of title after ten years of adverse possession. All conveyances by deeds were for a consideration equal to fair market value. The deed from Oker to Frank was never recorded. All other deeds were promptly and properly recorded. Lot 2 is now owned by Henry, who took by intestate succession from Oker, now dead. Tim expended $3,500 on the retaining wall. Then he obtained all of the original deeds in the chain from Oker to him. Shortly thereafter, Tim discovered the covenant in Oker''s deed to Frank. He demanded that Henry pay $1,750, and when Henry refused, Tim instituted an appropriate action to recover that sum from Henry. In such action, Henry asserted all defenses available to him. If judgment is for Henry, it will be because', 'Tim is barred by adverse possession.', 'Frank''s deed from Oker was never recorded.', 'Tim did not know about the covenant until after he had incurred the expenses and, hence, could not have relied on it.', 'Tim''s expenditures were not proved to be reasonable and customary.', 'D', 'An executory contract for the exchange of real property that is not recorded will be void against any person who subsequently purchases or acquires by exchange, or contracts to purchase or acquire by exchange, the same realty or any portion of the property, or acquires by assignment the rent to accrue from the property in good faith and for a valuable consideration, from the same vendor or assignor, his or her distributees or devisees, and whose conveyance, contract, or assignment is first duly recorded. An unrecorded contract is also void as against the lien on the same real property or a portion of the property arising from payments made on the execution of or pursuant to the terms of the contract with the same vendor, his or her distributees or devisees, if the contract is made in good faith and is first duly recorded.', 'mbe_656', 0, '107'),
('mbe_856', 'mbe', '856', '628', '1991-July', 'TORTS', '108', '', 'While Prudence was leaving an elevator, it suddenly dropped several inches, causing her to fall. An investigation of the accident revealed that the elevator dropped because it had been negligently maintained by the Acme Elevator Company. Acme had a contract with the owner of the building to inspect and maintain the elevator. Prudence''s fall severely aggravated a preexisting physical disability. If Prudence sues Acme Elevator Company for damages for her injuries, she should recover', 'nothing, if Acme could not reasonably have been expected to foresee the extent of the harm that Prudence suffered as a result of the accident.', 'nothing, if the accident would not have caused significant harm to an ordinarily prudent elevator passenger.', 'damages for the full amount of her disability, because a tortfeasor must take its victim as it finds her.', 'damages for the injury caused by the falling elevator, including the aggravation of her preexisting disability.', 'D', 'Finally, Covington attempts to counter this argument with the principle that “a tortfeasor takes his victim as he finds him”—the so-called “eggshell plaintiff” rule. Under this principle, the tortfeasor is responsible for the full extent of the plaintiff''s damages even if those injuries would not have occurred but for the plaintiff''s pre-existing physical condition, disease, or susceptibility to injury. Although her “pre-existing” condition is not a physical condition or illness as with the ordinary eggshell plaintiff, she argues that the same rule should apply. We disagree. The eggshell plaintiff principle concerns the amount or extent of damages recoverable from the defendant due to his negligence when the plaintiff has pre-existing injuries. It does not ease or lessen the plaintiff''s burden of showing that the defendant''s breach was a legal cause of her injury. Even if the eggshell plaintiff rule applied to NIED cases where there are no physical injuries, the defendant''s conduct is judged under an objective standard, i.e., the effect such conduct would have on a person of ordinary sensibilities, unless the defendant knew or should have known that the plaintiff is particularly susceptible to emotional distress. Knight''s negligence in this case would ordinarily result in little more than annoyance to the victim. Therefore, there is no “ease of association” between the harm claimed, i.e., severe emotional distress, and the conduct of Knight.', 'mbe_657', 0, '108'),
('mbe_857', 'mbe', '857', '629', '1991-July', 'EVIDENCE', '109', '', 'Dix is on trial for killing Vetter. The prosecutor calls Winn to testify that after being shot, Vetter said, "Dix did it." Before the testimony is given, Dix''s lawyer asks for a hearing on whether Vetter believed his death was imminent when he made the statement. Before permitting evidence of the dying declaration, the judge should hear evidence on the issue from', 'both sides, with the jury not present, and decide whether Winn may testify to Vetter''s statement.', 'both sides, with the jury present, and decide whether Winn may testify to Vetter''s statement.', 'both sides, with the jury present, and allow the jury to determine whether Winn may testify to Vetter''s statement.', 'the prosecutor only, with the jury not present, and if the judge believes a jury could reasonably find that Vetter knew he was dying, permit Winn to testify to the statement, with Dix allowed to offer evidence on the issue as a part of the defendant''s case.', 'A', '“ ‘A district court enjoys wide discretion in ruling on the admissibility of proffered evidence....’ “ Farrington v. Smith, 707 F.3d 963, 969 (8th Cir.2013) (quoting Quigley v. Winter, 598 F.3d 938, 946 (8th Cir.2010)). In this case, the parties have moved to exclude several pieces of evidence as irrelevant and prejudicial.  Under Federal Rule of Evidence 401, “[e]vidence is relevant if: (a) it has any tendency to make a fact more or less probable than it would be without the evidence; and (b) the fact is of consequence in determining the action.” Fed.R.Evid. 401. To determine whether evidence is relevant, the Court looks first to what must be proven at trial and then asks whether the evidence in question tends to support or refute one of those issues. See United States v. McCorkle, 688 F.3d 518, 521 (8th Cir.2012). Under Rule 402, evidence that is not relevant is not admissible. Fed.R.Evid. 402. And, Rule 403 provides that “[t]he court may exclude relevant evidence if its probative value is substantially outweighed by a danger of one or more of the following: unfair prejudice, confusing the issues, misleading the jury, undue delay, wasting time, or needlessly presenting cumulative evidence.” Fed.R.Evid. 403.', 'mbe_658', 0, '109'),
('mbe_858', 'mbe', '858', '630', '1991-July', 'CRIM. LAW', '110', '', 'Police received an anonymous tip that Tusitala was growing marijuana in her backyard, which was surrounded by a 15-foot high, solid wooden fence. Officer Boa was unable to view the yard from the street, so he used a police helicopter to fly over Tusitala''s house. Boa identified a large patch of marijuana plants growing right next to the house and used this observation to obtain a search warrant. Tusitala is prosecuted for possession of marijuana and moves to suppress use of the marijuana in evidence. The court should', 'grant the motion, because the only purpose of Boa''s flight was to observe the yard.', 'grant the motion, because Tusitala had a reasonable expectation of privacy in the curtilage around her house and the police did not have a warrant.', 'deny the motion, because a warrant is not required for a search of a residential yard.', 'deny the motion, because Tusitala had no reasonable expectation of privacy from aerial observation.', 'D', 'The Fourth Amendment protection of the home has never been extended to require law enforcement officers to shield their eyes when passing by a home on public thoroughfares. Nor does the mere fact that an individual has taken measures to restrict some views of his activities preclude an officer''s observations from a public vantage point where he has a right to be and which renders the activities clearly visible. E.g., United States v. Knotts, 460 U.S. 276, 282, 103 S.Ct. 1081, 1085–1086, 75 L.Ed.2d 55 (1983). “What a person knowingly exposes to the public, even in his own home or office, is not a subject of Fourth Amendment protection.” Katz, supra, 389 U.S., at 351, 88 S.Ct., at 511.
The observations by Officers Shutz and Rodriguez in this case took place within public navigable airspace, see 49 U.S.C.App. § 1304, in a physically nonintrusive manner; from this point they were able to observe plants readily discernible to the naked eye as marijuana. That the observation from aircraft was directed at identifying the plants and the officers were trained to recognize marijuana is irrelevant. Such observation is precisely what a judicial officer needs to provide a basis for a warrant. Any member of the public flying in this airspace who glanced down could have seen everything that these officers observed. On this record, we readily conclude that respondent''s expectation that his garden was protected from such observation is unreasonable and is not an expectation that society is prepared to honor.', 'mbe_659', 0, '110'),
('mbe_859', 'mbe', '859', '631', '1991-July', 'CONTRACTS', '111', '', 'Buyem faxed the following signed message to Zeller, his long-time widget supplier: "Urgently need blue widgets. Ship immediately three gross at your current list price of $600." Upon receipt of the fax, Zeller shipped three gross of red widgets to Buyem, and faxed to Buyem the following message: "Temporarily out of blue. In case red will help, am shipping three gross at the same price. Hope you can use them." Upon Buyem''s timely receipt of both the shipment and Zeller''s fax, which of the following best describes the rights and duties of Buyem and Zeller?', 'Buyem may accept the shipment, in which case he must pay Zeller the list price, or he must reject the shipment and recover from Zeller for total breach of contract.', 'Buyem may accept the shipment, in which case he must pay Zeller the list price, or he may reject the shipment, in which case he has no further rights against Zeller.', 'Buyem may accept the shipment, in which case he must pay Zeller the list price, less any damages sustained because of the nonconforming shipment, or he may reject the shipment and recover from Zeller for total breach of contract, subject to Zeller''s right to cure.', 'Buyem may accept the shipment, in which case he must pay Zeller the list price, less any damages sustained because of the nonconforming shipment, or he may reject the shipment provided that he promptly covers by obtaining conforming widgets from another supplier.', 'B', '“When performance of a duty under a contract is due, any nonperformance is a breach.” Restatement (Second) of Contracts § 235(2) (1981). See Barnes v. McKellar, 434 Pa.Super. 597, 644 A.2d 770 (1994); Camenisch v. Allen, 158 Pa.Super. 174, 44 A.2d 309 (1945).  If a breach constitutes a material failure of performance, then the non-breaching party is discharged from all liability under the contract. Oak Ridge Const. Co. v. Tolley, 351 Pa.Super. 32, 504 A.2d 1343 (1985). If, however, the breach is an immaterial failure of performance, and the contract was substantially performed, the contract remains effective. Cimina v. Bronich, 517 Pa. 378, 537 A.2d 1355 (1988); Borough of Greentree to Use of Castelli Const. Co. v. Tortorete, 205 Pa.Super. 532, 211 A.2d 76 (1965); *468 Schlein v. Gross, 186 Pa.Super. 618, 142 A.2d 329 (1958). Accord John D. Calamari & Joseph M. Perillo, The Law of Contracts § 11–22 (2d ed.1977). In other words, the non-breaching party does not have a right to suspend performance [if the breach is not material].
...“Whether a breach is so substantial as to justify an injured party''s regarding the whole transaction as at an end ‘is a question of degree; and it must be answered by weighing the consequences in the actual custom of men in the performance of contracts similar to the one that is involved in the specific case.’ ” Gray v. Gray, 448 Pa.Super. 456, 468, 671 A.2d 1166, 1172 (1996) (citing 2401 Pennsylvania Ave. Corp. v. Federation of Jewish Agencies, 319 Pa.Super. 228, 242–43, 466 A.2d 132, 139 (1983) (citations omitted)). In determining materiality for purposes of breaching a contract, we consider the following factors:
a) the extent to which the injured party will be deprived of the benefit which he reasonably expected;
b) the extent to which the injured party can be adequately compensated for that part of the benefit of which he will be deprived;
c) the extent to which the party failing to perform or to offer to perform will suffer forfeiture;
d) the likelihood that the party failing to perform or offer to perform will cure his failure, taking account of all the circumstances including any reasonable assurances;
e) the extent to which the behavior of the party failing to perform or offer to perform comports with standards of good faith and fair dealing.
Restatement (Second) of Contracts § 241 (1981). Accord Jennings v. League of Civic Organizations of Erie County, 180 Pa.Super. 398, 119 A.2d 608 (1956).', 'mbe_660', 0, '111'),
('mbe_86', 'mbe', '86', '53', 'MBE-1972-78-part3', '', '37', 'Victim, injured by Driver in an auto accident, employed attorney First to represent him in the matter. Victim was chronically insolvent and expressed doubt whether he could promptly get necessary medical treatment. Accordingly, First wrote into their contract his promise to Victim "to pay from any settlementtwith Driver compensation to any physician who provides professional services for Victim''s injuries." The contract also provided that First''s duties were "''nonassignable." First immediately filed suit against Driver. Victim then sought and received medical treatment, reasonably valued at S1,000, from Doctor, but failed to inform Doctor of First''s promise. After receiving a bill from Doctor for $1,000, Victim immediately wrote Doctor explaining that he was unable to pay and enclosing a copy of his contract with First. Victim then asked First about payment of this bill, but First requested a release from their employment contract. stating that he would like to refer Victim''s claim to attorney Second and that Second was willing to represent Victim in the pending lawsuit. Victim wrote a letter to First releasing him from their contract and agreeing to Second''s representation. A copy of this letter was sent to Doctor. Second subsequently promised First to represent Victim and soon negotiated a settlement of Victim''s claim against Driver which netted $1,000, all of which was paid by Victim to creditors other than Doctor. Victim remains insolvent.', 'In an action by Doctor against First upon First''s employment contract with Victim, if First attempted to use Victim''s release as a defense, Doctor is likely to argue that', 'the release was ineffective, because Doctor had impliedly assented to the Victim-First contract', 'the release was ineffective, because Victim would thereby be unjustly enriched', 'there was no consideration for Victim''s release of First', 'First''s contract duties were too personal to be effectively delegated to Second', 'A', 'Implied consent, compared to express consent (where consent is directly and clearly given with explicit words), is the agreement given by a person’s action (even just a gesture) or inaction, or can be inferred from certain circumstances by any reasonable person. The person who gives consent can withdraw the consent anytime and should have the capacity to make valid consent. The actor who gets the consent is bound by the consent and cannot exceed its scope.', 'mbe_70', 0, '37'),
('mbe_860', 'mbe', '860', '632', '1991-July', 'CONST. LAW', '112', '', 'Members of a religious group calling itself the Friends of Lucifer believe in Lucifer as their Supreme Being. The members of this group meet once a year on top of Mt. Snow, located in a U.S. National Park, to hold an overnight encampment and a midnight dance around a large campfire. They believe this overnight encampment and all of its rituals are required by Lucifer to be held on the top of Mt. Snow. U.S. National Park Service rules that have been consistently enforced prohibit all overnight camping and all campfires on Mt. Snow because of the very great dangers overnight camping and campfires would pose in that particular location. As a result, the park Superintendent denied a request by the Friends of Lucifer for a permit to conduct these activities on top of Mt. Snow. The park Superintendent, who was known to be violently opposed to cults and other unconventional groups had, in the past, issued permits to conventional religious groups to conduct sunrise services in other areas of that U.S. National Park. The Friends of Lucifer brought suit in Federal Court against the U.S. National Park Service and the Superintendent of the park to compel issuance of the requested permit. As a matter of constitutional law, the most appropriate result in this suit would be a decision that denial of the permit was', 'invalid, because the free exercise clause of the First Amendment prohibits the Park Service from knowingly interfering with religious conduct.', 'invalid, because these facts demonstrate that the action of the Park Service purposefully and invidiously discriminated against the Friends of Lucifer.', 'valid, because the establishment clause of the First Amendment prohibits the holding of religious ceremonies on federal land.', 'valid, because religiously motivated conduct may be subjected to nondiscriminatory time, place, and manner restrictions that advance important public interests.', 'D', 'Expression, whether oral or written or symbolized by conduct, is subject to reasonable time, place, or manner restrictions. We have often noted that restrictions of this kind are valid provided that they are justified without reference to the content of the regulated speech, that they are narrowly tailored to serve a significant governmental interest, and that they leave open ample alternative channels for communication of the information. City Council of Los Angeles v. Taxpayers for Vincent, 466 U.S. 789, 104 S.Ct. 2118, 80 L.Ed.2d 772 (1984); United States v. Grace, 461 U.S. 171, 103 S.Ct. 1702, 75 L.Ed.2d 736 (1983); Perry Education Assn. v. Perry Local Educators'' Assn., 460 U.S. 37, 45–46, 103 S.Ct. 948, 954–955, 74 L.Ed.2d 794 (1983); *294 Heffron v. International Society for Krishna Consciousness, Inc., 452 U.S. 640, 647–648, 101 S.Ct. 2559, 2563–2564, 69 L.Ed.2d 298 (1981); Virginia Pharmacy Board v. Virginia Citizens Consumer Council, Inc., 425 U.S. 748, 771, 96 S.Ct. 1817, 1830, 48 L.Ed.2d 346 (1976); Consolidated Edison Co. v. Public Service Comm''n of N.Y., 447 U.S. 530, 535, 100 S.Ct. 2326, 2332, 65 L.Ed.2d 319 (1980).', 'mbe_661', 0, '112'),
('mbe_861', 'mbe', '861', '633', '1991-July', 'EVIDENCE', '113', '', 'Park sued Davis Co. for injuries suffered in the crash of Park''s dune buggy, allegedly caused by a defective auto part manufactured by Davis Co. Davis Co. claims that the part was a fraudulent imitation, not produced by Davis Co. Which of the following is NOT admissible on the issue of whether the part was manufactured by Davis Co.?', 'The fact that the defective part bears Davis Co.''s insignia or trademark.', 'Testimony that the part was purchased from a parts house to which Davis Co. regularly sold parts.', 'The part itself and a concededly genuine part manufactured by Davis Co. (for the jury''s comparison).', 'A judgment for another plaintiff against Davis Co. in another case involving substantially similar facts.', 'D', 'Admissibility of evidence of other crimes or wrongs is guided by a four-prong test: (1) evidence of the other crime must be admissible as relevant to material issue; (2) it must be similar in kind and reasonably close in time to the offense charged; (3) evidence of the other crime must be clear and convincing; and (4) probative value of the evidence must not be outweighed by its apparent prejudice.', 'mbe_662', 0, '113'),
('mbe_862', 'mbe', '862', '634', '1991-July', 'REAL PROP.', '114', '', 'Anna entered into a valid written contract to purchase Blackacre, a large tract of land, from Jones for its fair market value of $50,000. The contract was assignable by Anna. Anna duly notified Jones to convey title to Anna and Charles, Charles being Anna''s friend whom Anna had not seen for many years. When Anna learned that Charles would have to sign certain documents in connection with the closing, she prevailed upon her brother, Donald, to attend the closing and pretend to be Charles. Anna and Donald attended the closing, and Jones executed an instrument in the proper form of a deed, purporting to convey Blackacre to Anna and Charles, as tenants in common. Donald pretended that he was Charles, and he signed Charles''s name to all the required documents. Anna provided the entire $50,000 consideration for the transaction. The deed was promptly and properly recorded. Unknown to Anna or Donald, Charles had died several months before the closing. Charles''s will, which was duly probated, devised "All my real estate to my nephew, Nelson" and the residue of his estate to Anna. Anna and Nelson have been unable to agree as to the status or disposition of Blackacre. Nelson brought an appropriate action against Jones and Anna to quiet legal title to an undivided one-half interest in Blackacre. The court should hold that legal title to Blackacre is vested', 'all in Jones.', 'all in Anna.', 'one-half in Anna and one-half in Jones.', 'one-half in Anna and one-half in Nelson.', 'C', 'Title to real property can only be conveyed by a valid, acknowledged deed.... RCW 64.04.010, .020.” Fid. Mut. Sav. Bank v. Mark, 112 Wash.2d 47, 53, 767 P.2d 1382 (1989). RCW 64.04.010 provides that “[e]very conveyance of real estate, or any interest therein ... shall be by deed.”', 'mbe_663', 0, '114'),
('mbe_863', 'mbe', '863', '635', '1991-July', 'CONTRACTS', '115', 'Staff, Inc., a flour wholesaler, contracted to deliver to Eclaire, a producer of fine baked goods, her flour requirements for a one-year period. Before delivery of the first scheduled installment, Staff sold its business and "assigned" all of its sale contracts to Miller, Inc., another reputable and long-time flour wholesaler. Staff informed Eclaire of this transaction.', 'For this question only, assume that when Miller tendered the first installment to Eclaire in compliance with the Staff-Eclaire contract, Eclaire refused to accept the goods. Which of the following arguments, if any, legally support(s) Eclaire''s rejection of the goods? I. Executory requirements contracts are nonassignable. II. Duties under an executory bilateral contract are assumable only by an express promise to perform on the part of the delegatee. III. Language of "assignment" in the transfer for value of a bilateral sale-of-goods contract affects only a transfer of rights, not a delegation of duties.', 'I only.', 'II and III only.', 'I and II and III.', 'Neither I nor II nor III.', 'D', '“[U]nder New York law, contracts are freely assignable in the absence of ‘clear language expressly prohibiting assignment.’ ” Elliott Assocs., L.P. v. Republic of Peru, 948 F.Supp. 1203, 1211 (S.D.N.Y.1996) (quoting Pravin Banker Assocs., Ltd. v. Banco Popular del Peru, 895 F.Supp. 660, 668 (S.D.N.Y.1995)); Stralem, 303 A.D.2d at 122, 758 N.Y.S.2d 345 (same).', 'mbe_346', 0, '115'),
('mbe_864', 'mbe', '864', '635', '1991-July', 'CONTRACTS', '116', 'Staff, Inc., a flour wholesaler, contracted to deliver to Eclaire, a producer of fine baked goods, her flour requirements for a one-year period. Before delivery of the first scheduled installment, Staff sold its business and "assigned" all of its sale contracts to Miller, Inc., another reputable and long-time flour wholesaler. Staff informed Eclaire of this transaction.', 'For this question only, assume that Eclaire accepted Miller''s delivery of the first installment under the Staff-Eclaire contract, but that Eclaire paid the contract price for that installment to Staff and refused to pay anything to Miller. In an action by Miller against Eclaire for the contractual amount of the first installment, which of the following, if any, will be an effective defense for Eclaire? I. Eclaire had not expressly agreed to accept Miller as her flour supplier. II. Eclaire''s payment of the contractual installment to Staff discharged her obligation. III. Staff remained obligated to Eclaire even though Staff had assigned the contract to Miller.', 'I only.', 'II only.', 'I and III only.', 'Neither I nor II nor III.', 'D', 'the injured party in a breach-of-contract action has a duty to mitigate damages, meaning that the injured party cannot recover damages “that it could have prevented by ‘reasonable affirmative action.’ ” Four Seasons Environmental, Inc. v. Westfield Cos., 93 Ohio App.3d 157, 159, 638 N.E.2d 91 (1st Dist.1994), quoting F. Ents. v. Kentucky Fried Chicken Corp., 47 Ohio St.2d 154, 351 N.E.2d 121 (1976), paragraph three of the syllabus. An injured party need only use “reasonable, practical care and diligence, not extraordinary measures to avoid excessive damages.” Provident Bank v. Barnhart, 3 Ohio App.3d 316, 320, 445 N.E.2d 746 (1st Dist.1982). The failure to mitigate damages is an affirmative defense, meaning that the burden of proof lies with the breaching party. Jindal Builders & Restoration Corp. v. Brown & Cris, 1st Dist. Hamilton Nos. C–970029 and C–970050, 1997 WL 674621, *1 (Oct. 31, 1997). Whether an injured party used reasonable care to avoid damages presents a question of fact. Pinnacle Mgt. v. Smith, 12th Dist. Butler No. CA2003–12–327, 2004-Ohio-6928, 2004 WL 2937535, ¶ 12.', 'mbe_664', 0, '116'),
('mbe_865', 'mbe', '865', '636', '1991-July', 'CRIM. LAW', '117', '', 'On October 22, Officer Jones submitted an application for a warrant to search 217 Elm Street for cocaine. In the application, Officer Jones stated under oath that he believed there was cocaine at that location because of information supplied to him on the morning of October 22 by Susie Schultz. He described Schultz as a cocaine user who had previously supplied accurate information concerning the use of cocaine in the community and summarized what Schultz had told him as follows: the previous night, October 21, Schultz was in Robert Redd''s house at 217 Elm Street. Redd gave her cocaine. She also saw three cellophane bags containing cocaine in his bedroom. The warrant was issued and a search of 217 Elm Street was conducted on October 22. The search turned up a quantity of marijuana but no cocaine. Robert Redd was arrested and charged with possession of marijuana. Redd moved to suppress the use of the marijuana as evidence contending that Susie Schultz was not in 217 Elm Street on October 21 or at any other time. If, after hearing evidence, the judge concludes that the statement in the application attributed to Susie Schultz is incorrect, the judge should grant the motion to suppress', 'because the application contains a material statement that is false.', 'because of the false statement and because no cocaine was found in the house.', 'only if he also finds that Susie Schultz''s statement was a deliberate lie.', 'only if he also finds that Officer Jones knew the statement was false.', 'D', 'To the extent that the defendant is arguing that the police informant provided inaccurate information, that fact, in and of itself, does not make the search warrant invalid. “The rule in this circuit is that as long as the applicant for the warrant accurately represents the information provided by an informant, probable cause is not defeated because the informant erred, or even lied, in his description of events.” See United States v. Smith, 9 F.3d 1007, 1014 (2d Cir.1993).', 'mbe_665', 0, '117'),
('mbe_866', 'mbe', '866', '637', '1991-July', 'CONST. LAW', '118', '', 'The Personnel Handbook of Green City contains all of that city''s personnel policies. One section of the handbook states that "where feasible and practicable supervisors are encouraged to follow the procedures specified in this Handbook before discharging a city employee." Those specified procedures include a communication to the employee of the reasons for the contemplated discharge and an opportunity for a pretermination trial-type hearing at which the employee may challenge those reasons. After a year of service, Baker, the secretary to the Green City Council, was discharged without receiving any communication of reasons for her contemplated discharge and without receiving an opportunity for a pretermination trial-type hearing. Baker files suit in federal district court to challenge her discharge solely on constitutional grounds. Which of the following best describes the initial burden of persuasion in that suit?', 'The Green City Council must demonstrate that its personnel handbook created no constitutionally protected interest in city employment or in the procedures by which such employment is terminated.', 'The Green City Council must demonstrate that Baker''s termination was for good cause.', 'Baker must demonstrate that state law creates a constitutionally protected interest in her employment or in the procedures by which her employment is terminated.', 'Baker must demonstrate that she reasonably believed that she could work for Green City for as long as she wished.', 'C', 'Property interests, of course, are not created by the Constitution. Rather they are created and their dimensions are defined by existing rules or understandings that stem from an independent source such as state law—rules or understandings that secure certain benefits and that support claims of entitlement to those benefits.', 'mbe_666', 0, '118'),
('mbe_867', 'mbe', '867', '638', '1991-July', 'EVIDENCE', '119', '', 'Dean was prosecuted in federal court for making threats against the President of the United States. Dean was a voluntary patient in a private psychiatric hospital and told a nurse, shortly before the President came to town, that Dean planned to shoot the President. The nurse reported the threat to FBI agents. Dean''s motion to prevent the nurse from testifying is likely to be', 'successful, because the statement was made in a medical setting.', 'successful, because the nurse violated a confidence in reporting the statement.', 'unsuccessful, because the statement was not within any privilege.', 'unsuccessful, because Dean had not been committed involuntarily by court order.', 'C', 'Information relating to medical or psychiatric examinations hospital required staff doctor to undergo prior to reappointment after suspension of privileges and specific information regarding doctor''s treating physicians and treatment received at hospital was privileged against disclosure in medical malpractice action, as record or communication made during or in connection with provision of mental health services.', 'mbe_667', 0, '119'),
('mbe_868', 'mbe', '868', '639', '1991-July', 'REAL PROP.', '120', '', 'Able, who owned Blackacre, a residential lot improved with a dwelling, conveyed it for a valuable consideration to Baker. The dwelling had been constructed by a prior owner. Baker had inspected Blackacre prior to the purchase and discovered no defects. After moving in, Baker became aware that sewage seeped into the basement when the toilets were flushed. Able said that this defect had been present for years and that he had taken no steps to hide the facts from Baker. Baker paid for the necessary repairs and brought an appropriate action against Able to recover his cost of repair. If Baker wins, it will be because', 'Able failed to disclose a latent defect.', 'Baker made a proper inspection.', 'the situation constitutes a health hazard.', 'Able breached the implied warranty of habitability and fitness for purpose.', 'A', 'A latent defect is defined as “[a] hidden or concealed defect. One which could not be discovered by reasonable and customary observation or inspection....” Black''s Law Dictionary 611 (Abridged 6th ed.1991). Nondisclosure to the purchaser of latent defects known to the vendor “impair[s] the right of the [purchaser] to receive the benefits” of the contract. Rawlings, 151 Ariz. at 153, 726 P.2d at 569.', 'mbe_668', 0, '120'),
('mbe_869', 'mbe', '869', '640', '1991-July', 'TORTS', '121', '', 'Gardner''s backyard, which is landscaped with expensive flowers and shrubs, is adjacent to a golf course. While Driver was playing golf on the course, a thunderstorm suddenly came up. As Driver was returning to the clubhouse in his golf cart, lightning struck a tree on the course, and the tree began to fall in Driver''s direction. In order to avoid being hit by the tree, Driver deliberately steered his cart onto Gardner''s property, causing substantial damage to Gardner''s expensive plantings. In an action by Gardner against Driver to recover damages for the harm to his plantings, Gardner will', 'prevail, because, although occasioned by necessity, Driver''s entry onto Gardner''s property was for Driver''s benefit.', 'prevail, for nominal damages only, because Driver was privileged to enter Gardner''s property.', 'not prevail, because the lightning was an act of God.', 'not prevail, because Driver''s entry onto Gardner''s property was occasioned by necessity and therefore privileged.', 'A', 'This Court has explained that “trespass is a tort involving ‘an intentional or negligent intrusion upon or to the possessory interest in property of another.’ ” Mitchell v. Baltimore Sun Co., 164 Md.App. 497, 508, 883 A.2d 1008 (2005) (quoting Ford v. Baltimore City Sheriff''s Office, 149 Md.App. 107, 129, 814 A.2d 127 (2002)), cert. denied, 390 Md. 501, 889 A.2d 418 (2006).  “In order to prevail on a cause of action for trespass, the plaintiff must establish: (1) an interference with a possessory interest in his property; (2) through the defendant''s physical act or force against that property; (3) which was executed without his consent.” Id. Royal Inv. Grp., LLC v. Wang, 183 Md.App. 406, 444–45, 961 A.2d 665 (2008) (alteration omitted).', 'mbe_669', 0, '121'),
('mbe_87', 'mbe', '87', '53', 'MBE-1972-78-part3', '', '38', 'Victim, injured by Driver in an auto accident, employed attorney First to represent him in the matter. Victim was chronically insolvent and expressed doubt whether he could promptly get necessary medical treatment. Accordingly, First wrote into their contract his promise to Victim "to pay from any settlementtwith Driver compensation to any physician who provides professional services for Victim''s injuries." The contract also provided that First''s duties were "''nonassignable." First immediately filed suit against Driver. Victim then sought and received medical treatment, reasonably valued at S1,000, from Doctor, but failed to inform Doctor of First''s promise. After receiving a bill from Doctor for $1,000, Victim immediately wrote Doctor explaining that he was unable to pay and enclosing a copy of his contract with First. Victim then asked First about payment of this bill, but First requested a release from their employment contract. stating that he would like to refer Victim''s claim to attorney Second and that Second was willing to represent Victim in the pending lawsuit. Victim wrote a letter to First releasing him from their contract and agreeing to Second''s representation. A copy of this letter was sent to Doctor. Second subsequently promised First to represent Victim and soon negotiated a settlement of Victim''s claim against Driver which netted $1,000, all of which was paid by Victim to creditors other than Doctor. Victim remains insolvent.', 'In an action by Doctor against Second, Second is most likely to argue on these facts that', 'Second made only a gratuitous promise to First', 'at the time Second promised to represent Victim, Doctor was only a member of an unidentified class of beneficiaries', 'there is insufficient evidence to support a finding that Doctor was either a creditor or donee beneficiary of Second''s promise to First', 'there is insufficient evidence to support a finding that Doctor substantially changed his position in reliance on Second''s promise', 'C', 'What Is a Donee Beneficiary?
A donee beneficiary receives the benefit of a contract between two other parties as a gift from one of the parties to the contract. While donee beneficiaries stand to benefit from the fulfillment of a contract, they are not technically party to the contract.

Who Is a Donee Beneficiary?
The donee beneficiary’s relationship to the parties in the contract distinguishes them from other types of third-party beneficiaries. Namely, a donee beneficiary’s claim to benefit from the contract amounts to a gift from one of the contractual parties. Donee beneficiaries are also allowed to include their promised property or estate into their own estate, as in the case of a 5 by 5 Power in Trust.

As with other situations involving third-party beneficiaries, donee beneficiaries have the legal right to demand benefits promised to them once their rights to the contract have vested. This makes them separate from creditor beneficiaries, who can only file suits once they have been made aware of the contracts or intended benefits. However, donee beneficiaries can only claim legal rights after the contract has been executed, per specified criteria.', 'mbe_71', 0, '38'),
('mbe_870', 'mbe', '870', '641', '1991-July', 'CRIM. LAW', '122', '', 'Steve, in desperate need of money, decided to hold up a local convenience store. Determined not to harm anyone, he carried a toy gun that resembled a real gun. In the store, he pointed the toy gun at the clerk and demanded money. A customer who entered the store and saw the robbery in progress pulled his own gun and fired at Steve. The bullet missed Steve but struck and killed the clerk. Steve was charged with felony murder. His best argument for being found NOT guilty is that he', 'did not intend to kill.', 'did not commit the robbery because he never acquired any money from the clerk.', 'did not intend to create any risk of harm.', 'is not responsible for the acts of the customer.', 'D', 'Felony-murder liability also extends to accidental deaths occurring during the course of an underlying felony so long as the death was a natural and probable consequence of the unlawful activity. For example, if the police officer in the hypothetical scenario above were to suffer a fatal heart attack from the stress of being confronted by armed robbers, the joint venturers could be found guilty of felony-murder. See Commonwealth v. Lucien, 440 Mass. 658, 668, 801 N.E.2d 247 (2004) (“If [the victim] had died of fright while the defendant was robbing him, the defendant would be responsible for murder”); Commonwealth v. Evans, 390 Mass. 144, 151–52, 454 N.E.2d 458 (1983) (felony-murder applies where victim was killed by accidental discharge of gun).', 'mbe_670', 0, '122'),
('mbe_871', 'mbe', '871', '642', '1991-July', 'CONTRACTS', '123', '', 'Client consulted Lawyer about handling the sale of Client''s building, and asked Lawyer what her legal fee would be. Lawyer replied that her usual charge was $100 per hour, and estimated that the legal work on behalf of Client would cost about $5,000 at that rate. Client said, "Okay; let''s proceed with it," and Lawyer timely and successfully completed the work. Because of unexpected title problems, Lawyer reasonably spent 75 hours on the matter and shortly thereafter mailed Client a bill for $7,500, with a letter itemizing the work performed and time spent. Client responded by a letter expressing his good-faith belief that Lawyer had agreed to a total fee of no more than $5,000. Client enclosed a check in the amount of $5,000 payable to Lawyer and conspicuously marked, "Payment in full for legal services in connection with the sale of Client''s building." Despite reading the "Payment in full..." language, Lawyer, without any notation of protest or reservation of rights, endorsed and deposited the check to her bank account. The check was duly paid by Client''s bank. A few days later, Lawyer unsuccessfully demanded payment from Client of the $2,500 difference between the amount of her bill and the check, and now sues Client for that difference. What, if anything, can Lawyer recover from Client?', 'Nothing, because the risk of unexpected title problems in a real-property transaction is properly allocable to the seller''s attorney and thus to Lawyer in this case.', 'Nothing, because the amount of Lawyer''s fee was disputed in good faith by Client, and Lawyer impliedly agreed to an accord and satisfaction.', '$2,500, because Client agreed to an hourly rate for as many hours as the work reasonably required, and the sum of $5,000 was merely an estimate.', 'The reasonable value of Lawyer''s services in excess of $5,000, if any, because there was no specific agreement on the total amount of Lawyer''s fee.', 'B', 'To succeed on an accord and satisfaction defense, Defendants must establish: (1) the existence of a disputed claim; (2) a specific and intentional agreement by the obligor to the tender of funds for less than the amount claimed; and (3) a specific and intentional agreement by the obligee to the acceptance of the tender and relinquishment of any claims. Hairston v. S. Methodist Univ., 441 S.W.3d 327, 336 (Tex. App.—Dallas 2013, pet. denied); accord United States v. Broussard, 102 F.3d 550, 551 (5th Cir. 1996) (citing Fischbach & Moore, Inc. v. Cajun Power Co-op, 799 F.2d 194, 198 (5th Cir. 1986) ); Westbank Riverboat Servs., Inc. v. Impala Warehousing US, LLC, No. 14-CV-1025, 2015 WL 5059998, at *4 (E.D. La. Aug. 25, 2015).', 'mbe_671', 0, '123'),
('mbe_872', 'mbe', '872', '643', '1991-July', 'REAL PROP.', '124', '', 'Pauline and Doris own adjacent parcels of land. On each of their parcels was a low-rise office building. The two office buildings were of the same height. Last year Doris decided to demolish the lowrise office building on her parcel and to erect a new high-rise office building of substantially greater height on the parcel as permitted by the zoning and building ordinances. She secured all the governmental approvals necessary to pursue her project. As Doris''s new building was in the course of construction, Pauline realized that the shadows it would create would place her (Pauline''s) building in such deep shade that the rent she could charge for space in her building would be substantially reduced. Pauline brought an appropriate action against Doris to enjoin the construction in order to eliminate the shadow problem and for damages. Pauline presented uncontroverted evidence that her evaluation as to the impact of the shadow on the fair rental value of her building was correct. There is no statute or ordinance (other than the building and zoning ordinances) that is applicable to the issues before the court. The court should', 'grant to Pauline the requested injunction.', 'award Pauline damages measured by the loss of rental value, but not an injunction.', 'grant judgment for Doris, because she had secured all the necessary governmental approvals for the new building.', 'grant judgment for Doris, because Pauline has no legal right to have sunshine continue to reach the windows of her building.', 'D', 'The owner of a piece of property has a right to shut off air and light from his neighbor''s windows by building on his own lots. This doctrine is too well settled in this country to require authorities. He cannot annoy his neighbor with the smell of his privy vaults, or with percolating sewer water, or other inconveniences which the law recognizes as injurious; but the free use of light and air by an owner of the soil are his, to any extent he pleases, without regard to his neighbor''s convenience or inconvenience. Pickard v. Collins, 23 Barb. 444; Letts v. Kessler, 54 Ohio St. 73, 42 N. E. 765; Judge Campbell''s opinion in Burke v. Smith, 69 Mich. 380, 37 N. W. 838. It makes no difference whether defendant''s motive in building the fence was one of malice towards her neighbor, or a desire to improve or ornament her property.', 'mbe_672', 0, '124'),
('mbe_873', 'mbe', '873', '644', '1991-July', 'TORTS', '125', 'Dumont, a real estate developer, was trying to purchase land on which he intended to build a large commercial development. Perkins, an elderly widow, had rejected all of Dumont''s offers to buy her ancestral home, where she had lived all her life and which was located in the middle of Dumont''s planned development. Finally, Dumont offered her $250,000. He told her that it was his last offer and that if she rejected it, state law authorized him to have her property condemned. Perkins then consulted her nephew, a law student, who researched the question and advised her that Dumont had no power of condemnation under state law. Perkins had been badly frightened by Dumont''s threat, and was outraged when she learned that Dumont had lied to her.', 'If Perkins sues Dumont for damages for emotional distress, will she prevail?', 'Yes, if Dumont''s action was extreme and outrageous.', 'Yes, because Perkins was frightened and outraged.', 'No, if Perkins did not suffer emotional distress that was severe.', 'No, if it was not Dumont''s purpose to cause emotional distress.', 'C', '“The elements of intentional infliction of emotional distress are (1) extreme and outrageous conduct; (2) the intent to cause, or the disregard of a substantial likelihood of causing, severe emotional distress; (3) causation; and (4) severe emotional distress” (Klein v. Metropolitan Child Servs., Inc., 100 A.D.3d 708, 710, 954 N.Y.S.2d 559; see Marmelstein v. Kehillat New Hempstead: Rav Aron Jofen Community Synagogue, 11 N.Y.3d 15, 22–23, 862 N.Y.S.2d 311, 892 N.E.2d 375; Howell v. New York Post Co., 81 N.Y.2d 115, 121, 596 N.Y.S.2d 350, 612 N.E.2d 699; Taggart v. Costabile, 131 A.D.3d 243, 249–250, 14 N.Y.S.3d 388).', 'mbe_2695', 0, '125'),
('mbe_874', 'mbe', '874', '644', '1991-July', 'TORTS', '126', 'Dumont, a real estate developer, was trying to purchase land on which he intended to build a large commercial development. Perkins, an elderly widow, had rejected all of Dumont''s offers to buy her ancestral home, where she had lived all her life and which was located in the middle of Dumont''s planned development. Finally, Dumont offered her $250,000. He told her that it was his last offer and that if she rejected it, state law authorized him to have her property condemned. Perkins then consulted her nephew, a law student, who researched the question and advised her that Dumont had no power of condemnation under state law. Perkins had been badly frightened by Dumont''s threat, and was outraged when she learned that Dumont had lied to her.', 'If Perkins asserts a claim based on misrepresentation against Dumont, will she prevail?', 'Yes, if Dumont knew he had no legal power of condemnation.', 'Yes, if Dumont tried to take unfair advantage of a gross difference between himself and Perkins in commercial knowledge and experience.', 'No, if Dumont''s offer of $250,000 equaled or exceeded the market value of Perkins''s property.', 'No, because Perkins suffered no pecuniary loss.', 'D', 'To prevail on an action for fraudulent misrepresentation, a plaintiff must establish: “(1) a false statement concerning a material fact; (2) the representer''s knowledge that the representation is false; (3) an intention that the representation induce another to act on it; and (4) consequent injury by the party acting in reliance on the representation.” Specialty Marine & Indus. Supplies, Inc. v. Venus, 66 So.3d 306, 310 (Fla. 1st DCA 2011).', 'mbe_2696', 0, '126'),
('mbe_875', 'mbe', '875', '645', '1991-July', 'CRIM. LAW', '127', '', 'State Y employs the Model Penal Code or American Law Institute test for insanity, and requires the state to prove sanity, when it is in issue, beyond a reasonable doubt. At Askew''s trial for murder, he pleaded insanity. The state put on an expert psychiatrist who had examined Askew. He testified that, in his opinion, Askew was sane at the time of the murder. Askew''s attorney did not introduce expert testimony on the question of sanity. Rather, he presented lay witnesses who testified that, in their opinion, Askew was insane at the time of the murder. At the end of the trial, each side moves for a directed verdict on the question of sanity. Which of the following correctly describes the judge''s situation?', 'She may grant a directed verdict for the defense if she believes that the jury could not find the prosecution to have proved sanity beyond a reasonable doubt.', 'She may grant a directed verdict for the prosecution if she believes that Askew''s witnesses on the insanity question are not believable.', 'She may not grant a directed verdict for the defense, because the state had expert testimony and the defense only lay witnesses.', 'She may grant a directed verdict for the prosecution if she is convinced by their experts that Askew was sane beyond a reasonable doubt.', 'A', 'This Court has previously announced this standard in our opinion in Ice v. Commonwealth, Ky., 667 S.W.2d 671 (1984), where we stated when “[i]t would not be clearly unreasonable for a jury to find against the defendant on the issue of insanity,” it may be submitted to the jury. The applicable standard in this case, therefore, is whether it would be clearly unreasonable for a jury to find against the defendant on the issue of insanity.', 'mbe_673', 0, '127'),
('mbe_876', 'mbe', '876', '646', '1991-July', 'CRIM. LAW', '128', '', 'Trelawney worked at a day-care center run by the Happy Faces Day Care Corporation. At the center, one of the young charges, Smith, often arrived with bruises and welts on his back and legs. A statute in the jurisdiction requires all day-care workers to report to the police cases where there is probable cause to suspect child abuse and provides for immediate removal from the home of any suspected child abuse victims. Trelawney was not aware of this statute. Nevertheless, he did report Smith''s condition to his supervisor, who advised him to keep quiet about it so the day-care center would not get into trouble for defaming a parent. About two weeks after Trelawney first noticed Smith''s condition, Smith was beaten to death by his father. Trelawney has been charged with murder in the death of Smith. The evidence at trial disclosed, in addition to the above, that the child had been the victim of beatings by the father for some time, and that these earlier beatings had been responsible for the marks that Trelawney had seen. Smith''s mother had been aware of the beatings but had not stopped them because she was herself afraid of Smith''s father. Trelawney''s best argument that he is NOT guilty of murder is', 'he was not aware of the duty-to-report statute.', 'he lacked the mental state necessary to the commission of the crime.', 'his omission was not the proximate cause of death.', 'the day-care corporation, rather than Trelawney, was guilty of the omission, which was sanctioned by its supervisorylevel agent.', 'B', 'Since the enactment of the revised Penal Law, however, we have recognized that in rare circumstances, depraved indifference murder can also be found in certain unintentional killings involving only a single individual. These limited cases are those in which—although the intent to kill is absent—the defendant''s utter depravity in causing the victim''s death warrants punishment in excess of that available for manslaughter. Such cases will arise only when the acts of the defendant are “marked by uncommon brutality—coupled not with an intent to kill ... but with depraved indifference to the victim''s plight” (Payne, 3 N.Y.3d at 271, 786 N.Y.S.2d 116, 819 N.E.2d 634). To constitute depraved indifference, the defendant''s “conduct must be ‘ “so wanton, so deficient in a moral sense of concern, so devoid of regard of the life or lives of others, and so blameworthy as to warrant the same criminal liability as that which the law imposes upon a person who intentionally causes the death of another” ’ ” (People v. Russell, 91 N.Y.2d 280, 287–288, 670 N.Y.S.2d 166, 693 N.E.2d 193 [1998], quoting People v. Fenner, 61 N.Y.2d 971, 973, 475 N.Y.S.2d 276, 463 N.E.2d 617 [1984] ).', 'mbe_674', 0, '128'),
('mbe_877', 'mbe', '877', '647', '1991-July', 'TORTS', '129', 'Perkins and Morton were passengers sitting in adjoining seats on a flight on Delval Airline. There were many empty seats on the aircraft. During the flight, a flight attendant served Morton nine drinks. As Morton became more and more obviously intoxicated and attempted to engage Perkins in a conversation, Perkins chose to ignore Morton. This angered Morton, who suddenly struck Perkins in the face, giving her a black eye.', 'If Perkins asserts a claim for damages against Delval Airline based on negligence, Perkins will', 'not recover, because a person is not required by law to come to the assistance of another who is imperiled by a third party.', 'not recover, if Perkins could easily have moved to another seat.', 'recover, because a common carrier is strictly liable for injuries suffered by a passenger while aboard the carrier.', 'recover, if the flight attendants should have perceived Morton''s condition and acted to protect Perkins before the blow was struck.', 'D', 'Generally, as the plaintiff claims, tort law requires that a duty of reasonable care be exercised to avoid injury to others.  Reasonable care is determined by the “standard of conduct demanded by the community for the protection of others against unreasonable risk.” Restatement (Second) of Torts § 283 comment (c) (1965).', 'mbe_675', 0, '129'),
('mbe_878', 'mbe', '878', '647', '1991-July', 'TORTS', '130', 'Perkins and Morton were passengers sitting in adjoining seats on a flight on Delval Airline. There were many empty seats on the aircraft. During the flight, a flight attendant served Morton nine drinks. As Morton became more and more obviously intoxicated and attempted to engage Perkins in a conversation, Perkins chose to ignore Morton. This angered Morton, who suddenly struck Perkins in the face, giving her a black eye.', 'If Perkins asserts a claim for damages against Delval Airline based on battery, she will', 'prevail, because she suffered an intentionally inflicted harmful or offensive contact.', 'prevail, if the flight attendant acted recklessly in continuing to serve liquor to Morton.', 'not prevail, because Morton was not acting as an agent or employee of Delval Airline.', 'not prevail, unless she can establish some permanent injury from the contact.', 'C', 'In Illinois, to establish a respondeat superior claim, a plaintiff is required to show; “(1) a principal/agent, master/servant, or employer/employee relationship existed; (2) the principle controlled ort has the right to control the conduct of the alleged employee or agent; and (3) the alleged conduct of the agent or employee fell within the scope of the agency or employment.” Wilson v. Edward Hosp., 981 N.E.2d 971, 978 (Ill.2012).', 'mbe_676', 0, '130'),
('mbe_879', 'mbe', '879', '648', '1991-July', 'CONST. LAW', '131', '', 'Terrorists in the foreign country of Ruritania kidnapped the United States ambassador to that country. They threatened to kill her unless the President of the United States secured the release of an identified person who was a citizen of Ruritania and was held in a prison of the state of Aurora in the United States pursuant to a valid conviction by that state. The President responded by entering into an agreement with Ruritania which provided that Ruritania would secure the release of the United States ambassador on a specified date in return for action by the President that would secure the release of the identified person held in the Aurora prison. The President then ordered the governor of Aurora to release the prisoner in question. The governor refused. No federal statutes are applicable. Which of the following is the strongest constitutional argument for the authority of the President to take action in these circumstances requiring the governor of Aurora to release the Aurora prisoner?', 'The power of the President to conduct the foreign affairs of the United States includes a plenary authority to take whatever action the President deems wise to protect the safety of our diplomatic agents.', 'The power of the President to appoint ambassadors authorizes him to take any action that he may think desirable to protect them from injury because, upon appointment, those officials become agents of the President.', 'The power of the President to negotiate with foreign nations impliedly authorizes the President to make executive agreements with them which prevail over state law.', 'The duty of the President to execute faithfully the laws authorizes him to resolve finally any conflicts between state and federal interests, making the determination of such matters wholly nonjusticiable.', 'C', 'If constitutional executive agreements conflict with state law, the executive agreement controls.', 'mbe_677', 0, '131'),
('mbe_88', 'mbe', '88', '54', 'MBE-1972-78-part3', '', '39', 'Peters sued Davis for $100,000 for injuries received in a traffic accident. Davis charges Peters with contributory negligence and alleges that Peters failed to have his lights on at a time when it was dark enough to require them.', 'Davis calls Bystander to testify that Passenger, who was riding in Peters'' automobile and who also was injured, confided to him at the scene of the accident that "we should have had our lights on." Bystander''s testimony is', 'admissible as an admission of a party opponent', 'admissible, as a declaration against interest', 'inadmissible, because it is hearsay, not within any exception', 'inadmissible, because it is opinion', 'C', 'A statement is against penal interest when it is so far contrary to the declarant''s penal interest that “a reasonable person in the declarant''s position would not have made the statement [without] believing it to be true.” See Torres, 1998–NMSC–052, ¶ 14, 126 N.M. 477, 971 P.2d 1267 (internal quotation marks omitted).', 'mbe_72', 0, '39'),
('mbe_880', 'mbe', '880', '649', '1991-July', 'EVIDENCE', '132', '', 'Damson was charged with murder, and Wagner testified for the prosecution. On crossexamination of Wagner, Damson seeks to elicit an admission that Wagner was also charged with the same murder and that the prosecutor told her, "If you testify against Damson, we will drop the charges against you after the conclusion of Damson''s trial." The evidence about the prosecutor''s promise is', 'admissible, as proper impeachment of Wagner.', 'admissible, as an admission by an agent of a party-opponent.', 'inadmissible, because the law encourages plea-bargaining.', 'inadmissible, because the evidence is hearsay not within any exception.', 'A', 'Cross-examination for accomplish impeachment is not limited to questions about prior crimes or like misconduct; rather, even where proof falls outside conventional category of immoral, vicious, or criminal acts, it may be proper subject for impeachment questioning where it demonstrates untruthful bent or significantly reveals willingness or disposition on part of particular defendant voluntarily to place advancement of his individual self-interest ahead of principle or of interest of society.', 'mbe_2697', 0, '132'),
('mbe_881', 'mbe', '881', '650', '1991-July', 'CONTRACTS', '133', 'On November 1, Debbit, an accountant, and Barrister, a lawyer, contracted for the sale by Debbit to Barrister of the law books Debbit had inherited from his father. Barrister agreed to pay the purchase price of $10,000 when Debbit delivered the books on December 1. On November 10, Barrister received a signed letter from Debbit that stated: "I have decided to dispose of the book stacks containing the law books you have already purchased. If you want the stacks, I will deliver them to you along with the books on December 1 at no additional cost to you. Let me know before November 15 whether you want them. I will not sell them to anyone else before then." On November 14, Barrister faxed and Debbit received the following message: "I accept your offer of the stacks." Debbit was not a merchant with respect to either law books or book stacks.', 'Debbit is contractually obligated to deliver the stacks because', 'Barrister provided a new bargained-for exchange by agreeing to take the stacks.', 'Debbit''s letter (received by Barrister on November 10) and Barrister''s faxmessage of November 14 constituted an effective modification of the original sale-of-books contract.', 'Barrister''s fax-message of November 14 operated to rescind unilaterally the original sale-of-books contract.', 'Debbit''s letter (received by Barrister on November 10) waived the bargained-for consideration that would otherwise be required.', 'B', 'A “modification” of a contract is a change in one or more respects which introduces new elements into the details of the contract, or cancels some of them, but leaves the general purpose and effect undisturbed. Hartwig Transit, Inc. v. Menolascino, 113 Ill.App.3d 165, 170, 68 Ill.Dec. 796, 446 N.E.2d 1193 (1983); International Business Lists, Inc. v. American Telephone & Telegraph Co., 147 F.3d 636, 640 (7th Cir.1998) (applying Illinois law); see Schwinder, 348 Ill.App.3d at 469, 284 Ill.Dec. 58, 809 N.E.2d 180 (“[t]he modified contract is regarded as creating a new single contract consisting of so many of the terms of the prior contract as the parties have not agreed to change, in addition to the new terms on which they have agreed”). Modification of a contract normally occurs when the parties agree to alter a contractual provision or to include additional obligations, while leaving intact the overall nature and obligations of the original agreement. See Hartwig, 113 Ill.App.3d at 170, 68 Ill.Dec. 796, 446 N.E.2d 1193.', 'mbe_678', 0, '133'),
('mbe_882', 'mbe', '882', '650', '1991-July', 'CONTRACTS', '134', 'On November 1, Debbit, an accountant, and Barrister, a lawyer, contracted for the sale by Debbit to Barrister of the law books Debbit had inherited from his father. Barrister agreed to pay the purchase price of $10,000 when Debbit delivered the books on December 1. On November 10, Barrister received a signed letter from Debbit that stated: "I have decided to dispose of the book stacks containing the law books you have already purchased. If you want the stacks, I will deliver them to you along with the books on December 1 at no additional cost to you. Let me know before November 15 whether you want them. I will not sell them to anyone else before then." On November 14, Barrister faxed and Debbit received the following message: "I accept your offer of the stacks." Debbit was not a merchant with respect to either law books or book stacks.', 'For this question only, assume that on November 12 Debbit told Barrister that he had decided not to part with the stacks. Will this communication operate as a legally effective revocation of his offer to deliver the stacks?', 'Yes, because Barrister had a pre-existing obligation to pay $10,000 for the law books.', 'Yes, because Debbit was not a merchant with respect to book stacks.', 'No, because Debbit had given a signed assurance that the offer would be held open until November 15.', 'No, because by delaying his acceptance until November 14, Barrister detrimentally relied on Debbit''s promise not to sell the stacks to anyone else in the meantime.', 'B', 'The concept of professionalism is heavy in determining who is a merchant under the statute. … The defined term “between merchants”, used in the exception proviso to the statute of frauds, contemplates the knowledge and skill of professionals on each side of the transaction. The transaction in question here was the sale of wheat. Appellee as a farmer undoubtedly had special knowledge or skill in raising wheat but we do not think this factor, coupled with annual sales of a wheat crop and purchases of seed wheat, qualified him as a merchant in that field.', 'mbe_679', 0, '134'),
('mbe_883', 'mbe', '883', '651', '1991-July', 'REAL PROP.', '135', '', 'Seller owned Blackacre, improved with an aging four-story warehouse. The warehouse was built to the lot lines on all four sides. On the street side, recessed loading docks permitted semi-trailers to be backed in. After the tractors were unhooked, the trailers extended into the street and occupied most of one lane of the street. Over the years, as trailers became larger, the blocking of the street became more severe. The municipality advised Seller that the loading docks could not continue to be used because the trailers blocked the street; it gave Seller 90 days to cease and desist. During the 90 days, Seller sold and conveyed Blackacre by warranty deed for a substantial consideration to Buyer. The problem of the loading docks was not discussed in the negotiations. Upon expiration of the 90 days, the municipality required Buyer to stop using the loading docks. This action substantially reduced the value of Blackacre. Buyer brought an appropriate action against Seller seeking cancellation of the deed and return of all monies paid. Such action should be based upon a claim of', 'misrepresentation.', 'breach of the covenant of warranty.', 'failure of consideration.', 'mutual mistake.', 'A', 'To succeed on a claim of fraudulent misrepresentation, a plaintiff must show: “ ‘(1) a false representation (2) concerning a material existing fact (3) [reasonably] relied upon by the plaintiff (4) who was damaged as a proximate result.’ ” Fisher v. Comer Plantation, Inc., 772 So.2d 455, 463 (Ala.2000) (quoting Baker v. Bennett, 603 So.2d 928, 935 (Ala.1992)).', 'mbe_680', 0, '135'),
('mbe_884', 'mbe', '884', '652', '1991-July', 'EVIDENCE', '136', '', 'Prescott sued Doxie for fraud. After verdict for Prescott, Doxie talked with juror Wall about the trial. Doxie''s motion for a new trial would be most likely granted if Wall is willing to testify that he voted for Prescott because he', 'misunderstood the judge''s instructions concerning the standard of proof in a fraud case.', 'was feeling ill and needed to get home quickly.', 'relied on testimony that the judge had stricken and ordered the jury to disregard.', 'learned from a court clerk that Doxie had been accused of fraud in several recent lawsuits.', 'D', '“ ‘To show probable injury, there must be some indication in the record that the alleged misconduct most likely caused a juror to vote differently than he ‘would otherwise have done on one or more issues vital to the judgment.’ ” Pharo, 922 S.W.2d at 950 (citations omitted). The record shows that when questioned about the verdict at the new trial hearing, each juror testified that he or she accepted the verdict as his or her verdict upon the conclusion of the deliberation process and that he or she still recognized the verdict as his or her verdict today.', 'mbe_681', 0, '136'),
('mbe_885', 'mbe', '885', '653', '1991-July', 'CRIM. LAW', '137', '', 'Despondent over losing his job, Wilmont drank all night at a bar. While driving home, he noticed a car following him and, in his intoxicated state, concluded he was being followed by robbers. In fact, a police car was following him on suspicion of drunk driving. In his effort to get away, Wilmont sped through a stop sign and struck and killed a pedestrian. He was arrested by the police. Wilmont is prosecuted for manslaughter. He should be', 'acquitted, because he honestly believed he faced an imminent threat of death or severe bodily injury.', 'acquitted, because his intoxication prevented him from appreciating the risk he created.', 'convicted, because he acted recklessly and in fact was in no danger.', 'convicted, because he acted recklessly and his apprehension of danger was not reasonable.', 'D', 'To convict for a violation of Code § 18.2-36.1(B), the Commonwealth must prove, inter alia, conduct by an accused “so gross, wanton and culpable as to show a reckless disregard for human life[.]” Code § 18.2-36.1(B). 1 Such conduct “has come to be known as ‘criminal negligence’ ” in the context of common law vehicular involuntary manslaughter and requires “ ‘acts of commission or omission of a wanton or willful nature, showing a reckless or indifferent disregard of the rights of others, under circumstances reasonably calculated to produce injury ... and the offender knows or is charged with the knowledge of, the probable results of his acts.’ ” Keech v. Commonwealth, 9 Va.App. 272, 277, 279, 386 S.E.2d 813, 816, 817 (1989) (emphasis omitted) (citations omitted).', 'mbe_2405', 0, '137'),
('mbe_886', 'mbe', '886', '654', '1991-July', 'REAL PROP.', '138', '', 'Ody, owner of Profitacre, executed an instrument in the proper form of a deed, purporting to convey Profitacre "to Leon for life, then to Ralph in fee simple." Leon, who is Ody''s brother and Ralph''s father, promptly began to manage Profitacre, which is valuable income-producing real estate. Leon collected all rents and paid all expenses, including real estate taxes. Ralph did not object, and this state of affairs continued for five years until 1987. In that year, Leon executed an instrument in the proper form of a deed, purporting to convey Profitacre to Mona. Ralph, no admirer of Mona, asserted his right to ownership of Profitacre. Mona asserted her ownership and said that if Ralph had any rights he was obligated to pay real estate taxes, even though Leon had been kind enough to pay them in the past. Income from Profitacre is ample to cover expenses, including real estate taxes. In an appropriate action to determine the rights of the parties, the court should decide', 'Leon''s purported deed forfeited his life estate, so Ralph owns Profitacre in fee simple.', 'Mona owns an estate for her life, is entitled to all income, and must pay real estate taxes; Ralph owns the remainder interest.', 'Mona owns an estate for the life of Leon, is entitled to all income, and must pay real estate taxes; Ralph owns the remainder interest.', 'Mona owns an estate for the life of Leon and is entitled to all income; Ralph owns the remainder interest, and must pay real estate taxes.', 'C', 'Contrary to plaintiffs'' contention, it is possible to waive a statutory right to partition, just as it is possible to waive other statutory rights. See, e.g., Sheldon v. Sheldon, 163 Or.App. 256, 265, 987 P.2d 1229 (1999) (waiver of a statutory right to take elective share); State v. Hunter, 316 Or. 192, 850 P.2d 366 (1993) (waiver of statutory right to speedy trial); Lane Education Service Dist. v. Swanson, 71 Or.App. 328, 692 P.2d 622 (1984) (waiver of statutory right of recall). As with contractual waiver, the waiver of a statutory right is an intentional relinquishment or abandonment of a known right or privilege. *155 State v. Rogers, 330 Or. 282, 4 P.3d 1261 (2000). “To make out a case of waiver of a legal right there must be a clear, unequivocal, and decisive act of the party showing such a purpose or acts amounting to an estoppel on his part.” McMillan v. Montgomery et al., 121 Or. 28, 32, 253 P. 879 (1927).', 'mbe_682', 0, '138'),
('mbe_887', 'mbe', '887', '655', '1991-July', 'REAL PROP.', '139', '', 'Homer and Ethel were jointly in possession of Greenacre in fee simple as tenants in common. They joined in a mortgage of Greenacre to Fortunoff Bank. Homer erected a fence along what he considered to be the true boundary between Greenacre and the adjoining property, owned by Mitchell. Shortly thereafter, Homer had an argument with Ethel and gave up his possession to Greenacre. The debt secured by the mortgage had not been paid. Mitchell surveyed his land and found that the fence erected a year earlier by Homer did not follow the true boundary. Part of the fence was within Greenacre. Part of the fence encroached on Mitchell''s land. Mitchell and Ethel executed an agreement fixing the boundary line in accordance with the fence constructed by Homer. The agreement, which met all the formalities required in the jurisdiction, was promptly and properly recorded. A year after the agreement was recorded, Homer temporarily reconciled his differences with Ethel and resumed joint possession of Greenacre. Thereafter, Homer repudiated the boundary line agreement and brought an appropriate action against Mitchell and Ethel to quiet title along the original true boundary. In such action, Homer will', 'win, because Fortunoff Bank was not a party to the agreement.', 'win, because one tenant in common cannot bind another tenant in common to a boundary line agreement.', 'lose, because the agreement, as a matter of law, was mutually beneficial to Ethel and Homer.', 'lose, because Ethel was in sole possession of said premises at the time the agreement was signed.', 'B', 'For there to be a valid boundary-line agreement, certain factors must be present: (1) there must be an uncertainty or dispute about the boundary line; (2) the agreement must be between the adjoining landowners; (3) the line fixed by the agreement must be definite and certain; (4) there must be possession following the agreement. Fields v. Griffen, 60 Ark.App. 186, 959 S.W.2d 759 (1998).', 'mbe_2698', 0, '139'),
('mbe_888', 'mbe', '888', '656', '1991-July', 'TORTS', '140', '', 'At the trial of an action against Grandmother on behalf of Patrick, the following evidence has been introduced. Grandson and his friend, Patrick, both aged eight, were visiting at Grandmother''s house when, while exploring the premises, they discovered a hunting rifle in an unlocked gun cabinet. They removed it from the cabinet and were examining it when the rifle, while in Grandson''s hands, somehow discharged. The bullet struck and injured Patrick. The gun cabinet was normally locked. Grandmother had opened it for dusting several days before the boys'' visit, and had then forgotten to relock it. She was not aware that it was unlocked when the boys arrived. If the defendant moves for a directed verdict in her favor at the end of the plaintiff''s case, that motion should be', 'granted, because Grandmother is not legally responsible for the acts of Grandson.', 'granted, because Grandmother did not recall that the gun cabinet was unlocked.', 'denied, because a firearm is an inherently dangerous instrumentality.', 'denied, because a jury could find that Grandmother breached a duty of care she owed to Patrick.', 'D', 'A duty of care arises when it is foreseeable that harm may result if care is not exercised. Lance, Inc. v. Ramanauskas, 731 So.2d 1204, 1208 (Ala.1999).', 'mbe_683', 0, '140'),
('mbe_889', 'mbe', '889', '657', '1991-July', 'CONTRACTS', '141', 'On November 15, Joiner in a signed writing contracted with Galley for an agreed price to personally remodel Galley''s kitchen according to specifications provided by Galley, and to start work on December 1. Joiner agreed to provide all materials for the job in addition to all of the labor required.', 'For this question only, assume that on November 26 Joiner without legal excuse repudiated the contract and that Galley, after a reasonable and prolonged effort, could not find anyone to remodel his kitchen for a price approximating the price agreed to by Joiner. If one year later Galley brings an action for specific performance against Joiner, which of the following will provide Joiner with the best defense?', 'An action for equitable relief not brought within a reasonable time is barred by laches.', 'Specific performance is generally not available as a remedy to enforce a contractual duty to perform personal services.', 'Specific performance is generally not available as a remedy in the case of an anticipatory repudiation.', 'Specific performance is not available as a remedy where even nominal damages could have been recovered as a remedy at law.', 'B', 'Courts of equity will not undertake to enforce the specific performance of a contract for personal services which are material or mechanical, and not peculiar or individual; but where the contract stipulates for special, unique, or extraordinary personal services, or where the services to be rendered are purely intellectual and individual in their character, the courts will grant an injunction in aid of a specific performance. William Rogers Mfg. Co. v. Rogers, 58 Conn. 356, 20 Atl. 467, 7 L. R. A. 779, 18 Am. St. Rep. 278. If a contract implies the performance of personal services requiring special skill, judgment, and discretion, a court of equity will not undertake its specific performance. South, etc., Alabama R. R. Co. v. Highland Ave., etc., R. R. Co., 98 Ala. 400, 13 South. 682, 39 Am. St. Rep. 74.', 'mbe_2406', 0, '141'),
('mbe_89', 'mbe', '89', '54', 'MBE-1972-78-part3', '', '40', 'Peters sued Davis for $100,000 for injuries received in a traffic accident. Davis charges Peters with contributory negligence and alleges that Peters failed to have his lights on at a time when it was dark enough to require them.', 'Davis offers to have Bystander testify that he was talking to Witness when he heard the crash and heard Witness, now deceased, exclaim, "That car doesn''t have any lights on." Bystander''s testimony is', 'admissible as a statement of present sense impression', 'admissible, because Witness is not available to testify', 'inadmissible as hearsay, not within any exception', 'inadmissible, because of the Dead Man''s Statute', 'A', 'Under the Federal Rules of Evidence, a present sense impression is defined as a statement that describes an event while it was occurring or immediately thereafter. A statement that qualifies as a present sense impression is admissible as an exception to the hearsay rule.', 'mbe_73', 0, '40')
ON CONFLICT (idx) DO NOTHING;
